INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('funfix/database/cats-effect-io', 'cats-effect-io', 'funfix', 'database', 'community', 'cats-effect-io funfix database community cats-effect-io is a database toolkit for the JVM, enabling developers to manage side effects and resources efficiently. It benefits developers working with Scala and Java. Cats Effect IO 是一个 JVM 数据库工具包，提供结构化并发和资源管理 Cats Effect IO は Java エージェントのための並行性ツールで、構造化された並行性とリソース管理を提供します Cats Effect IO는 JVM용 데이터베이스 툴킷으로 구조화된 并发과 리소스 관리를 제공합니다 Cats Effect IO es una herramienta de base de datos para JVM que simplifica la gestión de efectos laterales. Utiliza IO[A] y SyncIO[A] para controlar los efectos Cats Effect IO est un outil de base de données pour JVM qui simplifie la gestion des effets secondaires. Utilisez IO[A] et SyncIO[A] pour contrôler les effets Cats Effect IO ist ein Datenbank-Toolkit für die JVM, das die Verwaltung von Nebeneffekten vereinfacht. Verwenden Sie IO[A] und SyncIO[A], um die Effekte zu kontrollieren O Cats Effect IO é uma ferramenta de banco de dados para JVM que permite tratar efeitos colaterais como valores de efeito Cats Effect IO - это инструмент для работы с базами данных на JVM, который позволяет обрабатывать побочные эффекты как значения эффектов Cats Effect IO هو أداة قواعد البيانات للجافا التي تمكنك من التعامل مع الآثار الجانبية كقيم تأثير how to use cats-effect-io cats-effect-io vs monix cats-effect-io setup guide what is cats-effect-io cats-effect-io alternative cats-effect-io install scala cats-effect-io tutorial jvm database toolkit cats-effect-io resource management Cats Effect IO JVM 数据库工具包 结构化并发 资源管理 Java 阻塞调用 Sync 和 Async 并行性工具 Java 开发工具 Treats every side effect as an effect value using IO[A], SyncIO[A], or F[A] Wraps Java blocking calls with IO.blocking or IO.interruptible Provides Resource for acquiring and releasing resources Supports structured concurrency using parTraverse, parMapN, and background Utilizes Supervisor for program entry points and error handling cats-effect-io is a JVM database toolkit that provides a structured approach to handling side effects and resources using IO, SyncIO, and Resource.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('iheanyi/tasuku/tasuku', 'community', 'iheanyi', 'tasuku', 'iheanyi/tasuku', 'tasuku', 0, 0, 38, '2026-03-08T01:57:15.461Z', '2026-03-08T02:09:15.501Z', '9cc7df6a181c5034480529cb86c332c6d11cf349b1feac7cb9df18a0b8852d49', '{"id":"iheanyi/tasuku/tasuku","name":"tasuku","description":{"en":"Tasuku provides lightweight multi-agent task management for AI agents working on codebases, promoting agentic knowledge capture. It benefits developers by persisting tasks, learnings, and decisions across sessions.","zh":"Tasuku是一个轻量级的多代理任务管理工具，支持代码库和AI代理的任务管理","ja":"Tasukuは、コードベースでAIエージェントが共同作業するためのタスク管理ツールです","ko":"Tasuku는 코드베이스에서 AI 에이전트가 협업할 수 있는 태스크 관리 도구입니다","es":"Tasuku es una herramienta de gestión de tareas ligera y diseñada para agentes de IA que trabajan en codebases, con funcionalidades de persistencia y dependencias de tareas","fr":"Tasuku est un outil de gestion de tâches léger conçu pour les agents d''IA travaillant sur des codebases, avec des fonctionnalités de persistance et de dépendance de tâches","de":"Tasuku ist ein leichtes Taskmanagement-Tool, das für KI-Agents entwickelt wurde, die auf Codebases arbeiten, mit Funktionen wie Persistenz und Aufgabenabhängigkeiten","pt":"O Tasuku é uma ferramenta de gerenciamento de tarefas leve e multiagente para agentes de IA que trabalham em código aberto. Ele fornece gerenciamento de tarefas persistente e amigável ao Git.","ru":"Tasuku - это легкое и многоагентное средство управления задачами для ИИ Агентов, работающих с открытым исходным кодом. Он обеспечивает постоянное и дружественное к Git управление задачами.","ar":"Tasuku هو أداة إدارة المهام الخفيفة والمُتعددة الوكلاء للوكلاء الذكاء الاصطناعي الذين يعملون على الكود المفتوح. يوفر إدارة المهام المستدامة والصديقة لـ Git."},"seo":{"title":{"en":"Tasuku: Persistent Task Management for AI Agents | AI Age...","zh":"Tasuku Setup Guide: AIエージェント任务管理","ja":"Tasukuベストプラクティス: AIエージェントを使用したタスク管理","ko":"Tasuku 시작하기: AI 에이전트를 위한 멀티 에이전트 태스크 관리","es":"Guía de configuración de Tasuku para agentes de inteligen...","fr":"Guide de démarrage rapide de Tasuku pour les outils d''IA","de":"Einrichtungsleitfaden für Tasuku: Lightweight Multi-Agent...","pt":"Guia de Configuração do Tasuku - Gerenciamento de Tarefas...","ru":"Руководство по настройке Tasuku - Управление задачами для...","ar":"دليل إعداد Tasuku - إدارة المهام للوكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock efficient task management with Tasuku. Discover how to persist tasks, learnings, and decisions across sessions. Get started now!","zh":"了解Tasuku，一个轻量级的多代理任务管理工具，支持代码库和AI代理的任务管理","ja":"Tasukuは、AIエージェントがコードベースで共同作業するためのタスク管理ツールです","ko":"Tasuku는 코드베이스에서 AI 에이전트가 협업할 수 있는 태스크 관리 도구입니다","es":"Descubre cómo Tasuku facilita la gestión de tareas para agentes de IA con persistencia y dependencias de tareas","fr":"Découvrez comment Tasuku simplifie la gestion de tâches pour les outils d''IA avec des fonctionnalités de persistance et de dépendance de tâches","de":"Erfahren Sie, wie Tasuku die Aufgabenverwaltung für KI-Agents mit Persistenz und Aufgabenabhängigkeiten erleichtert","pt":"Aprenda a configurar o Tasuku para gerenciar tarefas de forma eficiente em projetos de código aberto com suporte a agentes de IA","ru":"Узнайте, как настроить Tasuku для эффективного управления задачами в проектах с открытым исходным кодом с поддержкой ИИ Агентов","ar":"تعلم كيفية إعداد Tasuku لإدارة المهام بفعالية في مشاريع الكود المفتوح مع دعم الوكلاء الذكاء الاصطناعي"},"definition":{"en":"Tasuku is a lightweight multi-agent task management system designed for AI agents, enabling persistent and git-friendly task management.","zh":"Tasuku是一种轻量级的多代理任务管理工具，用于捕获AI代理的知识","ja":"Tasukuは、AIエージェントの知識を取得するための軽量なマルチエージェントタスク管理ツールです","ko":"Tasuku는 AI 에이전트의 지식을 캡처하는 경량 다중 에이전트 태스크 관리 도구입니다","es":"Tasuku es un sistema de gestión de tareas multiagente que promueve la captura de conocimiento de los agentes","fr":"Tasuku est un système de gestion de tâches multi-agents qui favorise la capture de connaissances des agents","de":"Tasuku ist ein Multi-Agent-Taskmanagement-System, das die Erfassung von Agentenwissen fördert","pt":"O que é Tasuku? É uma ferramenta de gerenciamento de tarefas para agentes de IA que promove a captura de conhecimento agente.","ru":"Что такое Tasuku? Это средство управления задачами для ИИ Агентов, которое способствует захвату агентских знаний.","ar":"ما هو Tasuku؟ هو أداة إدارة المهام للوكلاء الذكاء الاصطناعي التي تعزز الحصول على المعرفة الوكيل."},"features":{"en":["Persistent task management across sessions","Supports task dependencies with block/unblock functionality","Enables knowledge capture through recording learnings and architectural decisions","Provides project context summaries","Designed for git-friendly task management"],"zh":["支持多会话工作","任务依赖管理","知识捕获和记录","项目上下文总结"],"ja":["マルチセッションワークのサポート","タスク依存関係の管理","知識の取得と記録","プロジェクトコンテキストのサマリー"],"ko":["멀티 세션 작업 지원","태스크 종속성 관리","지식 캡처 및 기록","프로젝트 컨텍스트 요약"],"es":["Gestión de tareas persistente a través de sesiones","Dependencias de tareas para bloquear o desbloquear tareas","Captura de conocimiento con registros de aprendizaje y decisiones","Resumen del estado del proyecto en cualquier momento"],"fr":["Gestion de tâches persistante à travers les sessions","Dépendances de tâches pour bloquer ou débloquer les tâches","Capture de connaissances avec des registres d''apprentissage et de décisions","Résumé de l''état du projet à tout moment"],"de":["Persistente Aufgabenverwaltung über Sitzungen hinweg","Aufgabenabhängigkeiten zum Blockieren oder Freigeben von Aufgaben","Erfassung von Wissen mit Lern- und Entscheidungsprotokollen","Projektzusammenfassung zu jedem Zeitpunkt"],"pt":["Gerenciamento de tarefas persistente em várias sessões","Dependências de tarefas para bloquear ou desbloquear tarefas","Captura de conhecimento para registrar aprendizados e decisões","Resumo do estado do projeto em qualquer momento","Integração com Git para gerenciamento de código"],"ru":["Постоянное управление задачами в нескольких сессиях","Зависимости задач для блокировки или разблокировки задач","Захват знаний для регистрации знаний и решений","Сводка состояния проекта в любой момент","Интеграция с Git для управления кодом"],"ar":["إدارة المهام المستدامة في جلسات متعددة","اعتماديات المهام لحظر أو إلغاء حظر المهام","الحصول على المعرفة لتسجيل التعلم والقرارات","ملخص حالة المشروع في أي وقت","التكامل مع Git لإدارة الكود"]},"keywords":{"en":["how to use tasuku","tasuku alternative","tasuku setup guide","what is tasuku","tasuku vs jira","tasuku install","tasuku for ai agents","git-friendly task management","persistent task management"],"zh":["AIエージェント任务管理","代码库任务管理","轻量级多代理任务管理","Tasuku Setup","Tasuku教程","AI代理知识捕获"],"ja":["AIエージェントタスク管理","コードベースタスク管理","軽量なマルチエージェントタスク管理","Tasukuセットアップ","Tasukuチュートリアル","AIエージェントの知識取得"],"ko":["AI 에이전트 태스크 관리","코드베이스 태스크 관리","경량 다중 에이전트 태스크 관리","Tasuku 시작하기","Tasuku 튜토리얼","AI 에이전트 지식 캡처"],"es":["agentes de inteligencia artificial","herramientas de IA","gestión de tareas","persistencia de tareas","dependencias de tareas","captura de conocimiento","codebases","desarrollo de software"],"fr":["outils d''IA","agents d''intelligence artificielle","gestion de tâches","persistance de tâches","dépendances de tâches","capture de connaissances","codebases","développement de logiciels"],"de":["KI-Agents","Künstliche Intelligenz","Aufgabenverwaltung","Persistenz von Aufgaben","Aufgabenabhängigkeiten","Erfassung von Wissen","Codebases","Softwareentwicklung"],"pt":["Tasuku","gerenciamento de tarefas","agentes de IA","código aberto","Git","captura de conhecimento","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Tasuku","управление задачами","ИИ Агенты","открытый исходный код","Git","захват знаний","разработка программного обеспечения","инструменты разработки"],"ar":["Tasuku","إدارة المهام","الوكلاء الذكاء الاصطناعي","الكود المفتوح","Git","الحصول على المعرفة","تطوير البرمجيات","أدوات التطوير"]}},"owner":"iheanyi","repo":"tasuku","repoPath":"iheanyi/tasuku","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.461Z","topics":[],"category":"community","skillMd":{"name":"tasuku","description":"Agent-first task management. Use when tracking multi-session work, recording learnings/decisions, managing task dependencies, or persisting context across sessions. Provides tk_list, tk_add, tk_done, tk_start, tk_learn, tk_decide, tk_note, tk_show, tk_find, tk_ready, tk_context, tk_stats, tk_block, tk_task, tk_metadata, tk_manage, tk_health, tk_suggest, tk_deps, and tk_help tools.","bodyPreview":"# Tasuku — Agent-First Task Management\n\nTasuku provides persistent, git-friendly task management designed for AI agents working on codebases.\n\n## When to Use Tasuku\n\n- **Multi-session work**: Tasks, learnings, and decisions persist across sessions\n- **Task dependencies**: Block/unblock tasks, track what''s ready to work on\n- **Knowledge capture**: Record learnings (\"Never X\", \"Always Y\") and architectural decisions\n- **Project context**: Get a summary of project state at any time\n\n## Quick Start","body":"# Tasuku — Agent-First Task Management\n\nTasuku provides persistent, git-friendly task management designed for AI agents working on codebases.\n\n## When to Use Tasuku\n\n- **Multi-session work**: Tasks, learnings, and decisions persist across sessions\n- **Task dependencies**: Block/unblock tasks, track what''s ready to work on\n- **Knowledge capture**: Record learnings (\"Never X\", \"Always Y\") and architectural decisions\n- **Project context**: Get a summary of project state at any time\n\n## Quick Start\n\n### Check project state\nUse `tk_context` to get a full overview of tasks, learnings, and decisions.\n\n### Pick up work\nUse `tk_ready` to see tasks ready to work on, then `tk_start` to begin.\n\n### Track progress\n- `tk_add` — Create new tasks\n- `tk_note` — Add progress notes to tasks\n- `tk_done` — Mark tasks complete\n\n### Capture knowledge\n- `tk_learn` — Record insights, gotchas, rules (\"Never manually edit ANSI strings\")\n- `tk_decide` — Record architectural decisions with alternatives and reasoning\n\n## Task vs Session Scope\n\nUse Tasuku for **project-level** work that spans sessions:\n- Features, bugs, milestones\n- Architectural decisions\n- Cross-cutting learnings\n\nUse your editor''s built-in task list for **session-level** steps:\n- Implementation steps within a single session\n- Temporary checklists\n\n## Workflow Commands\n\n### Starting a Session\n1. `tk_context` — See project overview\n2. `tk_ready` — Find next task to work on\n3. `tk_start` — Begin working on a task\n\n### During Work\n- `tk_note` — Record progress, blockers, or findings\n- `tk_learn` — Capture insights as you discover them\n- `tk_block` — Mark tasks blocked by other tasks\n\n### Completing Work\n1. `tk_done` — Mark task complete\n2. `tk_learn` — Capture what you learned (don''t skip this!)\n3. `tk_ready` — See what''s unblocked and ready next\n\n### Finding Information\n- `tk_find` — Search across tasks, learnings, and decisions\n- `tk_show` — Get full details on a specific task\n- `tk_deps` — See task dependency graph\n- `tk_stats` — Project health metrics\n"},"lastSynced":"2026-03-08T02:09:15.501Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Agent AI Systems needing persistent task management across sessions","zh":"非常适合需要跨会话进行持久任务管理的多智能体AI系统","ja":"セッション間での永続的なタスク管理を必要とするマルチエージェントAIシステムに最適","ko":"세션 간 지속적인 작업 관리가 필요한 다중 에이전트 AI 시스템에 완벽함","es":"Perfecto para sistemas de inteligencia artificial multiagente que necesitan una gestión de tareas persistente entre sesiones","fr":"Parfait pour les systèmes d''intelligence artificielle multi-agents nécessitant une gestion de tâches persistante entre sessions","de":"Perfekt für Multi-Agenten-KI-Systeme, die eine persistente Aufgabenverwaltung zwischen Sitzungen benötigen","pt":"Perfeito para Sistemas de IA Multi-Agente que necessitam de gestão persistente de tarefas entre sessões","ru":"Идеально подходит для многозадачных ИИ-систем, требующих постоянного управления задачами между сессиями","ar":"مثالي لأنظمة الذكاء الاصطناعي متعددة الوكلاء التي تحتاج إلى إدارة مهام مستمرة عبر الجلسات"},"recommendation":{"en":"Empowers agents to manage tasks, learnings, and decisions with git-friendly persistence, enabling seamless knowledge capture and project context summarization using task dependencies and architectural decision tracking","zh":"使智能体能够以支持git的持久性方式管理任务、学习和决策，利用任务依赖关系和架构决策跟踪，实现无缝的知识捕获和项目上下文摘要","ja":"タスクの依存関係とアーキテクチャ上の意思決定の追跡を使用して、シームレスな知識キャプチャとプロジェクトコンテキストの要約を可能にし、gitに適した永続性でエージェントがタスク、学習、意思決定を管理できるようにする","ko":"git 친화적인 지속성으로 에이전트가 작업, 학습 및 의사 결정을 관리할 수 있도록 하여, 작업 종속성 및 아키텍처 결정 추적을 사용한 원활한 지식 캡처 및 프로젝트 컨텍스트 요약 기능 제공","es":"Habilita a los agentes a gestionar tareas, aprendizajes y decisiones con persistencia amigable con git, lo que permite una captura de conocimiento y una resumen del contexto del proyecto sin problemas utilizando dependencias de tareas y seguimiento de decisiones arquitectónicas","fr":"Permet aux agents de gérer des tâches, des apprentissages et des décisions avec une persistance conviviale avec git, permettant ainsi une capture de connaissances et une synthèse du contexte du projet sans heurts en utilisant des dépendances de tâches et un suivi des décisions d''architecture","de":"Ermöglicht es Agenten, Aufgaben, Lernvorgänge und Entscheidungen mit git-freundlicher Persistenz zu verwalten, wodurch eine nahtlose Erfassung von Wissen und eine Zusammenfassung des Projektkontexts mithilfe von Aufgabenabhängigkeiten und Architektur-Entscheidungsverfolgung ermöglicht wird","pt":"Capacita os agentes a gerenciar tarefas, aprendizados e decisões com persistência compatível com git, permitindo uma captura de conhecimento contínua e sumarização de contexto de projeto usando dependências de tarefas e rastreamento de decisões arquiteturais","ru":"Позволяет агентам управлять задачами, обучением и решениями с git-совместимым постоянным хранением, обеспечивая беспрерывный сбор знаний и обобщение контекста проекта с использованием зависимостей задач и отслеживания архитектурных решений","ar":"يمكّن الوكلاء من إدارة المهام والتعلم والقرارات مع استمرارية متوافقة مع git، مما يتيح Capture سلس للمعرفة وتلخيص سياق المشروع باستخدام تبعيات المهام وتتبع القرارات المعمارية"},"useCases":{"en":["Persisting tasks and learnings across multi-session work","Managing task dependencies to track ready-to-work tasks","Capturing knowledge through recordings of learnings and architectural decisions"],"zh":["跨多个会话持久化任务和学习内容","管理工作任务依赖关系以跟踪可立即执行的任务","通过学习记录和架构决策记录来捕获知识"],"ja":["マルチセッション作業におけるタスクと学習内容の永続化","準備完了のタスクを追跡するためのタスク依存関係の管理","学習記録とアーキテクチャ上の意思決定を通じた知識の捕捉"],"ko":["다중 세션 작업에 걸친 작업 및 학습 내용의 지속화","실행 가능 작업을 추적하기 위한 작업 종속성 관리","학습 기록 및 아키텍처 결정 기록을 통한 지식 획득"],"es":["Permitir tareas y aprendizajes persistentes en trabajos de varias sesiones","Gestionar dependencias de tareas para realizar un seguimiento de tareas listas para trabajar","Capturar conocimiento a través de grabaciones de aprendizajes y decisiones arquitectónicas"],"fr":["Permettre des tâches et des apprentissages persistants dans les travaux de plusieurs sessions","Gérer les dépendances de tâches pour suivre les tâches prêtes à travailler","Capturer des connaissances via des enregistrements d''apprentissages et de décisions d''architecture"],"de":["Persistente Aufgaben und Lernvorgänge über mehrere Sitzungen hinweg ermöglichen","Aufgabenabhängigkeiten verwalten, um Aufgaben zu verfolgen, die bereit zum Arbeiten sind","Wissen durch Aufzeichnungen von Lernvorgängen und Architektur-Entscheidungen erfassen"],"pt":["Persistência de tarefas e aprendizados em trabalhos multi-sessão","Gestão de dependências de tarefas para monitorizar tarefas prontas para trabalhar","Captura de conhecimento através de gravações de aprendizados e decisões arquiteturais"],"ru":["Сохранение задач и обучения в ходе многосессионной работы","Управление зависимостями задач для отслеживания готовых к работе задач","Сбор знаний посредством записи процесса обучения и архитектурных решений"],"ar":["استمرارية المهام والتعلم عبر العمل متعدد الجلسات","إدارة تبعيات المهام لتتبع المهام الجاهزة للعمل","Capture المعرفة من خلال تسجيلات التعلم والقرارات المعمارية"]},"limitations":{"en":["Requires git integration","Designed specifically for AI agents working on codebases"],"zh":["需要集成git","专为处理代码库的AI智能体而设计"],"ja":["git連携が必要","コードベースを扱うAIエージェント向けに特別に設計されている"],"ko":["git 연동 필요","코드베이스를 작업하는 AI 에이전트를 위해 특별히 설계됨"],"es":["Requiere integración con git","Diseñado específicamente para agentes de inteligencia artificial que trabajan en codebases"],"fr":["Nécessite une intégration avec git","Conçu spécifiquement pour les agents d''intelligence artificielle travaillant sur des codebases"],"de":["Benötigt eine Integration mit git","Speziell für KI-Agents entwickelt, die auf Codebasen arbeiten"],"pt":["Requer integração com git","Projetado especificamente para agentes de IA que trabalham em bases de código"],"ru":["Требует интеграции с git","Специально разработан для ИИ-агентов, работающих с кодовая базами"],"ar":["يتطلب تكامل مع git","مصمم خصيصًا لوكلاء الذكاء الاصطناعي الذين يعملون على قواعد التعليمات البرمجية"]},"version":4},"contentHash":"9cc7df6a181c5034480529cb86c332c6d11cf349b1feac7cb9df18a0b8852d49","qualityScore":38}');
