INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('iheanyi/tasuku/tasuku', 'tasuku', 'iheanyi', 'tasuku', 'community', 'tasuku iheanyi tasuku community Tasuku provides lightweight multi-agent task management for AI agents working on codebases, promoting agentic knowledge capture. It benefits developers by persisting tasks, learnings, and decisions across sessions. Tasuku是一个轻量级的多代理任务管理工具，支持代码库和AI代理的任务管理 Tasukuは、コードベースでAIエージェントが共同作業するためのタスク管理ツールです Tasuku는 코드베이스에서 AI 에이전트가 협업할 수 있는 태스크 관리 도구입니다 Tasuku es una herramienta de gestión de tareas ligera y diseñada para agentes de IA que trabajan en codebases, con funcionalidades de persistencia y dependencias de tareas Tasuku est un outil de gestion de tâches léger conçu pour les agents d''IA travaillant sur des codebases, avec des fonctionnalités de persistance et de dépendance de tâches Tasuku ist ein leichtes Taskmanagement-Tool, das für KI-Agents entwickelt wurde, die auf Codebases arbeiten, mit Funktionen wie Persistenz und Aufgabenabhängigkeiten O Tasuku é uma ferramenta de gerenciamento de tarefas leve e multiagente para agentes de IA que trabalham em código aberto. Ele fornece gerenciamento de tarefas persistente e amigável ao Git. Tasuku - это легкое и многоагентное средство управления задачами для ИИ Агентов, работающих с открытым исходным кодом. Он обеспечивает постоянное и дружественное к Git управление задачами. Tasuku هو أداة إدارة المهام الخفيفة والمُتعددة الوكلاء للوكلاء الذكاء الاصطناعي الذين يعملون على الكود المفتوح. يوفر إدارة المهام المستدامة والصديقة لـ Git. how to use tasuku tasuku alternative tasuku setup guide what is tasuku tasuku vs jira tasuku install tasuku for ai agents git-friendly task management persistent task management AIエージェント任务管理 代码库任务管理 轻量级多代理任务管理 Tasuku Setup Tasuku教程 AI代理知识捕获 Persistent task management across sessions Supports task dependencies with block/unblock functionality Enables knowledge capture through recording learnings and architectural decisions Provides project context summaries Designed for git-friendly task management Tasuku is a lightweight multi-agent task management system designed for AI agents, enabling persistent and git-friendly task management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EmilyMacro/test/repo-bootstrap', 'community', 'EmilyMacro', 'test', 'EmilyMacro/test', 'repo-bootstrap', 0, 0, 38, '2026-03-08T01:57:15.467Z', '2026-03-08T02:09:29.293Z', 'd251d5a1b84e256e0817fb26e6b7df5b77fa05dde000fbc6e1bb9d595fb7428b', '{"id":"EmilyMacro/test/repo-bootstrap","name":"repo-bootstrap","description":{"en":"repo-bootstrap is a skill that helps developers set up a new repository from a template, providing a safe and fast path to a usable project setup. It benefits developers who want to quickly verify GitHub Actions permissions and run interactive tests","zh":"repo-bootstrap 是一个用于初始化 GitHub 仓库的工具，提供安全快速的项目设置。它包括 GitHub Actions 权限和 smoke 测试等功能","ja":"repo-bootstrap は GitHub リポジトリを初期化するためのツールで、セキュアで迅速なプロジェクト設定を提供します。GitHub Actions の権限と smoke テストなどの機能を含みます","ko":"repo-bootstrap는 GitHub 저장소를 초기화하는 도구로 안전하고 빠른 프로젝트 설정을 제공합니다. GitHub Actions 권한과 스모크 테스트 등의 기능을 포함합니다","es":"El repo-bootstrap es una herramienta para configurar proyectos de manera rápida y segura. Permite verificar permisos de GitHub Actions y ejecutar pruebas de humo.","fr":"Le repo-bootstrap est un outil pour configurer des projets de manière rapide et sécurisée. Il permet de vérifier les autorisations GitHub Actions et d''exécuter des tests de fumée.","de":"Der repo-bootstrap ist ein Tool zum Konfigurieren von Projekten in sicherer und schneller Weise. Es ermöglicht die Überprüfung von GitHub-Actions-Berechtigungen und die Ausführung von Rauchtests.","pt":"O repo-bootstrap é uma ferramenta para configurar projetos de forma segura e rápida. Siga nosso checklist para garantir um setup correto.","ru":"repo-bootstrap - это инструмент для настройки проектов безопасно и быстро. Следуйте нашему чек-листу, чтобы обеспечить правильную настройку - ИИ Агенты.","ar":"repo-bootstrap هو أداة لتهيئة المشاريع بسرعة وأمان. اتبع قائمة التحقق الخاصة بنا لضمان التهيئة الصحيحة - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"repo-bootstrap: Setup Guide for AI Agents | AI Agent Skill","zh":"repo-bootstrap 设置指南：GitHub 仓库初始化最佳实践","ja":"repo-bootstrap セットアップガイド：GitHub リポジトリ初期化のベストプラクティス","ko":"repo-bootstrap 설정 가이드: GitHub 저장소 초기화 최적화","es":"Guía de configuración de repo-bootstrap para un setup rápido","fr":"Guide de démarrage rapide pour repo-bootstrap","de":"Schnellstart-Anleitung für repo-bootstrap","pt":"Guia de Configuração do repo-bootstrap para Desenvolvedores","ru":"Руководство по настройке repo-bootstrap для разработчиков...","ar":"دليل إعداد repo-bootstrap لمنشئي التطبيقات - أدوات الذكاء..."},"description":{"en":"Get started with repo-bootstrap today and streamline your project setup! Learn how to verify GitHub Actions permissions and run interactive tests","zh":"使用 repo-bootstrap 初始化 GitHub 仓库，确保安全快速的项目设置。了解 GitHub Actions 权限和 smoke 测试","ja":"repo-bootstrap を使用して GitHub リポジトリを初期化し、セキュアで迅速なプロジェクト設定を実現します。GitHub Actions の権限と smoke テストについて学びます","ko":"repo-bootstrap를 사용하여 GitHub 저장소를 초기화하고 안전하고 빠른 프로젝트 설정을 구현합니다. GitHub Actions 권한과 스모크 테스트에 대해 알아보세요","es":"Aprende a configurar tu proyecto con repo-bootstrap de manera segura y rápida. Sigue nuestra guía paso a paso.","fr":"Configurez votre projet avec repo-bootstrap de manière sécurisée et rapide. Suivez notre guide étape par étape.","de":"Erfahren Sie, wie Sie Ihr Projekt mit repo-bootstrap sicher und schnell konfigurieren. Folgen Sie unserer Schritt-für-Schritt-Anleitung.","pt":"Aprenda a configurar o repo-bootstrap com segurança e eficiência. Siga nosso guia para desenvolvedores e otimize seu fluxo de trabalho.","ru":"Узнайте, как настроить repo-bootstrap безопасно и эффективно. Следуйте нашему руководству для разработчиков и оптимизируйте свой рабочий процесс - ИИ Агенты.","ar":"تعرف على كيفية إعداد repo-bootstrap بشكل آمن وموثوق. اتبع دليلنا المخصص لمنشئي التطبيقات وتحسين تدفق العمل - أدوات الذكاء الاصطناعي"},"definition":{"en":"repo-bootstrap is a skill that automates the initial setup of a new repository, ensuring proper GitHub Actions permissions and workflow configurations","zh":"repo-bootstrap 是一个 GitHub 仓库初始化工具，用于设置安全快速的项目环境","ja":"repo-bootstrap は GitHub リポジトリ初期化ツールで、セキュアで迅速なプロジェクト環境を設定するために使用されます","ko":"repo-bootstrap는 GitHub 저장소 초기화 도구로 안전하고 빠른 프로젝트 환경을 설정하기 위해 사용됩니다","es":"El repo-bootstrap es una herramienta de configuración de proyectos que facilita la verificación de permisos y la ejecución de pruebas.","fr":"Le repo-bootstrap est un outil de configuration de projets qui facilite la vérification des autorisations et l''exécution de tests.","de":"Der repo-bootstrap ist ein Konfigurations-Tool für Projekte, das die Überprüfung von Berechtigungen und die Ausführung von Tests erleichtert.","pt":"O repo-bootstrap é uma ferramenta de configuração de projetos que fornece um checklist para garantir um setup seguro e rápido.","ru":"repo-bootstrap - это инструмент настройки проектов, который предоставляет чек-лист для обеспечения безопасной и быстрой настройки - ИИ Агенты.","ar":"repo-bootstrap هو أداة لتهيئة المشاريع التي توفر قائمة تحقق لضمان التهيئة الآمنة والسريعة - أدوات الذكاء الاصطناعي"},"features":{"en":["Verifies GitHub Actions permissions with read and write access","Confirms workflow permissions to create and approve pull requests","Runs interactive tests, including the Smoke Test - GitHub Permissions","Creates a PR as part of the smoke test confirmation","Supports GitHub Actions setup documentation via docs/github-actions-setup.md","Enables developers to run the GitHub permissions smoke test"],"zh":["GitHub Actions 权限设置","Smoke 测试功能","交互式设置过程","Read 和 write 权限","自动创建和审批 pull 请求"],"ja":["GitHub Actions の権限設定","Smoke テスト機能","インタラクティブな設定プロセス","Read と write 権限","自動的な pull リクエストの作成と承認"],"ko":["GitHub Actions 권한 설정","스모크 테스트 기능","인터랙티브 설정 과정","Read 및 write 권한","자동 pull 요청 생성 및 승인"],"es":["Verificación de permisos de GitHub Actions","Ejecución de pruebas de humo para GitHub Permissions","Configuración interactiva para un setup rápido","Permisos de lectura y escritura para flujos de trabajo","Creación y aprobación de solicitudes de extracción"],"fr":["Vérification des autorisations GitHub Actions","Exécution de tests de fumée pour les autorisations GitHub","Configuration interactive pour un démarrage rapide","Autorisations de lecture et d''écriture pour les flux de travail","Création et approbation de demandes d''extraction"],"de":["Überprüfung von GitHub-Actions-Berechtigungen","Ausführung von Rauchtests für GitHub-Berechtigungen","Interaktive Konfiguration für einen schnellen Start","Lese- und Schreibberechtigungen für Arbeitsabläufe","Erstellung und Genehmigung von Pull-Requests"],"pt":["Verificação de permissões do GitHub Actions","Execução do teste de permissões do GitHub","Configuração interativa","Criação e aprovação de pull requests","Leitura e escrita de permissões de workflow"],"ru":["Проверка разрешений GitHub Actions","Выполнение теста разрешений GitHub","Интерактивная настройка","Создание и утверждение запросов на вытягивание","Чтение и запись разрешений рабочего процесса - ИИ Агенты"],"ar":["التحقق من صلاحيات إجراءات GitHub","تشغيل اختبار صلاحيات GitHub","التكوين التفاعلي","إنشاء واعتماد طلبات السحب","قراءة وكتابة صلاحيات سير العمل - أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use repo-bootstrap","repo-bootstrap setup guide","GitHub Actions permissions","repo-bootstrap alternative","repo-bootstrap vs other setup tools","what is repo-bootstrap","repo-bootstrap install","repo-bootstrap tutorial","GitHub repository setup"],"zh":["repo-bootstrap","GitHub 仓库初始化","AIエージェント","GitHub Actions","Smoke 测试","交互式设置","Read 和 write 权限","自动创建 pull 请求"],"ja":["repo-bootstrap","GitHub リポジトリ初期化","AIエージェント","GitHub Actions","Smoke テスト","インタラクティブな設定","Read と write 権限","自動的な pull リクエストの作成"],"ko":["repo-bootstrap","GitHub 저장소 초기화","AI 에이전트","GitHub Actions","스모크 테스트","인터랙티브 설정","Read 및 write 권한","자동 pull 요청 생성"],"es":["repo-bootstrap","configuración de proyectos","GitHub Actions","permisos de GitHub","pruebas de humo","setup rápido","herramientas de desarrollo","Herramientas de AI para desarrolladores","Inteligencia artificial para desarrolladores"],"fr":["repo-bootstrap","configuration de projets","GitHub Actions","autorisations GitHub","tests de fumée","démarrage rapide","outils de développement","Outils d''IA pour les développeurs","Intelligence artificielle pour les développeurs"],"de":["repo-bootstrap","Projektkonfiguration","GitHub-Actions","GitHub-Berechtigungen","Rauchtests","schneller Start","Entwicklungstools","KI-Tools für Entwickler","Künstliche Intelligenz für Entwickler"],"pt":["repo-bootstrap","configuração de projetos","segurança de projetos","GitHub Actions","permissões de workflow","teste de permissões do GitHub","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["repo-bootstrap","настройка проектов","безопасность проектов","GitHub Actions","разрешения рабочего процесса","тест разрешений GitHub","разработка программного обеспечения","инструменты разработки - ИИ Агенты"],"ar":["repo-bootstrap","تهيئة المشاريع","أمان المشاريع","إجراءات GitHub","صلاحيات سير العمل","اختبار صلاحيات GitHub","تطوير البرمجيات","أدوات التطوير - أدوات الذكاء الاصطناعي"]}},"owner":"EmilyMacro","repo":"test","repoPath":"EmilyMacro/test","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.467Z","topics":[],"category":"community","skillMd":{"name":"repo-bootstrap","description":"Bootstrap a new project repo created from this template (GitHub Actions permissions, init flow, and Windsurf copy-pack sync).","bodyPreview":"## When to use\n\nUse this when you just created a new repository from this template and want the safest, fastest path to a usable project setup.\n\n## Checklist\n\n1) Verify GitHub Actions permissions\n\n- See `docs/github-actions-setup.md`.\n- Confirm:\n  - Workflow permissions: **Read and write**\n  - Allow GitHub Actions to create and approve pull requests\n\n2) (Optional) Run the GitHub permissions smoke test\n\n- Run **Smoke Test - GitHub Permissions**.\n- Confirm that it creates a PR.\n\n3) Run interactive","body":"## When to use\n\nUse this when you just created a new repository from this template and want the safest, fastest path to a usable project setup.\n\n## Checklist\n\n1) Verify GitHub Actions permissions\n\n- See `docs/github-actions-setup.md`.\n- Confirm:\n  - Workflow permissions: **Read and write**\n  - Allow GitHub Actions to create and approve pull requests\n\n2) (Optional) Run the GitHub permissions smoke test\n\n- Run **Smoke Test - GitHub Permissions**.\n- Confirm that it creates a PR.\n\n3) Run interactive initialization in Windsurf\n\n- Run `/init-project`.\n- Ensure it creates/updates:\n  - `orga/domain/project-brief.md`\n  - baseline domain docs under `orga/domain/`\n  - project-specific Windsurf customizations under `docs/windsurf/`\n\n4) Apply the mechanical initialization PR\n\n- Run GitHub Actions workflow **Initialize Project**.\n- Merge the PR.\n\n5) Confirm Windsurf sync\n\n- Ensure `.windsurf/` reflects `docs/windsurf/` (rules, workflows, skills).\n- If you maintain multiple repos from this template, keep `docs/windsurf/` as the copy-pack.\n"},"lastSynced":"2026-03-08T02:09:29.293Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub-centric AI Agents needing streamlined repository setup and GitHub Actions permissions verification.","zh":"适用于需要简化仓库设置和GitHub Actions权限验证的GitHub中心AI代理。","ja":"GitHub Actionsの権限を検証し、リポジトリの設定を簡素化する必要があるGitHub中心のAIエージェントに最適です。","ko":"GitHub Actions 권한을 확인하고 저장소 설정을 간소화해야 하는 GitHub 중심의 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA centrados en GitHub que necesitan una configuración de repositorio optimizada y verificación de permisos de GitHub Actions.","fr":"Idéal pour les agents d''IA centrés sur GitHub nécessitant une configuration de référentiel simplifiée et une vérification des autorisations GitHub Actions.","de":"Ideal für GitHub-zentrierte KI-Agents, die eine optimierte Repository-Konfiguration und GitHub Actions-Berechtigungsüberprüfung benötigen.","pt":"Ideal para agentes de IA centrados no GitHub que necessitam de uma configuração de repositório simplificada e verificação de permissões do GitHub Actions.","ru":"Идеально для агентов ИИ, ориентированных на GitHub, которым требуется упрощенная настройка репозитория и проверка разрешений GitHub Actions.","ar":"مثالي لعميل الذكاء الاصطناعي المرتكز على جيت هاب الذي يحتاج إلى تركيب مستودع مبسط وتأكيد صلاحيات جيت هاب أكشنز."},"recommendation":{"en":"Empowers agents to verify GitHub Actions permissions and run interactive tests, providing a safe and fast path to a usable project setup using GitHub Actions and workflow permissions like read and write, and creating and approving pull requests via GitHub API.","zh":"赋予代理验证GitHub Actions权限并运行交互式测试的能力，提供了使用GitHub Actions和工作流权限（如读写权限）设置可用项目的安全快速路径，并通过GitHub API创建和批准拉取请求。","ja":"エージェントにGitHub Actionsの権限を検証し、インタラクティブなテストを実行する能力を付与し、GitHub Actionsとワークフローの権限（読み取りおよび書き込み権限など）を使用して、利用可能なプロジェクトを設定するための安全で迅速なパスを提供し、GitHub APIを介してプルリクエストを作成および承認します。","ko":"에이전트가 GitHub Actions 권한을 확인하고 상호 작용 테스트를 실행할 수 있는 능력을 부여하여 GitHub Actions와 워크플로 권한(읽기 및 쓰기 권한 등)을 사용하여 사용 가능한 프로젝트를 설정하는 안전하고 빠른 경로를 제공하며, GitHub API를 통해 풀 요청을 생성 및 승인합니다.","es":"Habilita a los agentes a verificar los permisos de GitHub Actions y ejecutar pruebas interactivas, proporcionando una ruta segura y rápida a una configuración de proyecto usable utilizando GitHub Actions y permisos de flujo de trabajo como lectura y escritura, y creando y aprobando solicitudes de extracción a través de GitHub API.","fr":"Permet aux agents de vérifier les autorisations GitHub Actions et d''exécuter des tests interactifs, offrant un chemin sûr et rapide vers une configuration de projet utilisable utilisant GitHub Actions et des autorisations de workflow comme lecture et écriture, et en créant et en approuvant des demandes d''extraction via l''API GitHub.","de":"Ermächtigt Agents, GitHub Actions-Berechtigungen zu überprüfen und interaktive Tests auszuführen, und bietet so einen sicheren und schnellen Weg zu einer verwendbaren Projekt-Konfiguration unter Verwendung von GitHub Actions und Workflow-Berechtigungen wie Lesen und Schreiben, sowie das Erstellen und Genehmigen von Pull-Requests über die GitHub-API.","pt":"Habilita os agentes a verificar permissões do GitHub Actions e executar testes interativos, fornecendo um caminho seguro e rápido para uma configuração de projeto utilizável usando GitHub Actions e permissões de fluxo de trabalho como leitura e escrita, e criando e aprovando solicitações de pull via API do GitHub.","ru":"Наделяет агентов возможностью проверять разрешения GitHub Actions и запускать интерактивные тесты, обеспечивая безопасный и быстрый путь к настройке проекта с помощью GitHub Actions и разрешений рабочего процесса, таких как чтение и запись, а также создание и утверждение запросов на включение через API GitHub.","ar":"يمنح العميل القدرة على التحقق من صلاحيات جيت هاب أكشنز و تشغيل الاختبارات التفاعلية، و يوفر مسارًا آمنًا وسريعًا لإعداد مشروع قابل للاستخدام باستخدام جيت هاب أكشنز و صلاحيات سير العمل مثل القراءة والكتابة، و إنشاء و موافقة طلبات السحب عبر واجهة برمجة تطبيقات جيت هاب."},"useCases":{"en":["Verifying GitHub Actions permissions","Running interactive tests for repository setup","Automating GitHub permissions smoke tests"],"zh":["验证GitHub Actions权限","运行交互式测试以设置仓库","自动化GitHub权限冒烟测试"],"ja":["GitHub Actionsの権限を検証する","リポジトリの設定のためのインタラクティブなテストを実行する","GitHubの権限の冒煙テストを自動化する"],"ko":["GitHub Actions 권한 확인","저장소 설정을 위한 상호 작용 테스트 실행","GitHub 권한冒烟 테스트 자동화"],"es":["Verificar permisos de GitHub Actions","Ejecutar pruebas interactivas para la configuración del repositorio","Automatizar pruebas de humo de permisos de GitHub"],"fr":["Vérifier les autorisations GitHub Actions","Exécuter des tests interactifs pour la configuration du référentiel","Automatiser les tests de fumée des autorisations GitHub"],"de":["GitHub Actions-Berechtigungen überprüfen","Interaktive Tests für die Repository-Konfiguration ausführen","GitHub-Berechtigungs-Smoke-Tests automatisieren"],"pt":["Verificar permissões do GitHub Actions","Executar testes interativos para configuração de repositório","Automatizar testes de fumaça de permissões do GitHub"],"ru":["Проверка разрешений GitHub Actions","Запуск интерактивных тестов для настройки репозитория","Автоматизация тестов разрешений GitHub"],"ar":["التحقق من صلاحيات جيت هاب أكشنز","تشغيل الاختبارات التفاعلية لتركيب المستودع","الاستفادة من اختبارات الدخان لصلاحيات جيت هاب"]},"limitations":{"en":["Requires GitHub repository access","GitHub Actions setup necessary","Limited to GitHub ecosystem"],"zh":["需要GitHub仓库访问","需要GitHub Actions设置","仅限GitHub生态系统"],"ja":["GitHubリポジトリへのアクセスが必要","GitHub Actionsの設定が必要","GitHubエコシステムに限定される"],"ko":["GitHub 저장소 액세스가 필요","GitHub Actions 설정이 필요","GitHub 생태계에만 제한"],"es":["Requiere acceso al repositorio de GitHub","Configuración de GitHub Actions necesaria","Limitado al ecosistema de GitHub"],"fr":["Nécessite un accès au référentiel GitHub","Configuration de GitHub Actions nécessaire","Limité à l''écosystème GitHub"],"de":["Benötigt Zugriff auf das GitHub-Repository","GitHub Actions-Setup erforderlich","Begrenzt auf das GitHub-Ökosystem"],"pt":["Requer acesso ao repositório do GitHub","Configuração do GitHub Actions necessária","Limitado ao ecossistema do GitHub"],"ru":["Требуется доступ к репозиторию GitHub","Необходимо настроить GitHub Actions","Ограничен экосистемой GitHub"],"ar":["يتطلب الوصول إلى مستودع جيت هاب","إعداد جيت هاب أكشنز ضروري","محدود بنظام جيت هاب"]},"version":4},"contentHash":"d251d5a1b84e256e0817fb26e6b7df5b77fa05dde000fbc6e1bb9d595fb7428b","qualityScore":38}');
