INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EmilyMacro/test/repo-bootstrap', 'repo-bootstrap', 'EmilyMacro', 'test', 'community', 'repo-bootstrap EmilyMacro test community repo-bootstrap is a skill that helps developers set up a new repository from a template, providing a safe and fast path to a usable project setup. It benefits developers who want to quickly verify GitHub Actions permissions and run interactive tests repo-bootstrap 是一个用于初始化 GitHub 仓库的工具，提供安全快速的项目设置。它包括 GitHub Actions 权限和 smoke 测试等功能 repo-bootstrap は GitHub リポジトリを初期化するためのツールで、セキュアで迅速なプロジェクト設定を提供します。GitHub Actions の権限と smoke テストなどの機能を含みます repo-bootstrap는 GitHub 저장소를 초기화하는 도구로 안전하고 빠른 프로젝트 설정을 제공합니다. GitHub Actions 권한과 스모크 테스트 등의 기능을 포함합니다 El repo-bootstrap es una herramienta para configurar proyectos de manera rápida y segura. Permite verificar permisos de GitHub Actions y ejecutar pruebas de humo. Le repo-bootstrap est un outil pour configurer des projets de manière rapide et sécurisée. Il permet de vérifier les autorisations GitHub Actions et d''exécuter des tests de fumée. Der repo-bootstrap ist ein Tool zum Konfigurieren von Projekten in sicherer und schneller Weise. Es ermöglicht die Überprüfung von GitHub-Actions-Berechtigungen und die Ausführung von Rauchtests. O repo-bootstrap é uma ferramenta para configurar projetos de forma segura e rápida. Siga nosso checklist para garantir um setup correto. repo-bootstrap - это инструмент для настройки проектов безопасно и быстро. Следуйте нашему чек-листу, чтобы обеспечить правильную настройку - ИИ Агенты. repo-bootstrap هو أداة لتهيئة المشاريع بسرعة وأمان. اتبع قائمة التحقق الخاصة بنا لضمان التهيئة الصحيحة - أدوات الذكاء الاصطناعي how to use repo-bootstrap repo-bootstrap setup guide GitHub Actions permissions repo-bootstrap alternative repo-bootstrap vs other setup tools what is repo-bootstrap repo-bootstrap install repo-bootstrap tutorial GitHub repository setup repo-bootstrap GitHub 仓库初始化 AIエージェント GitHub Actions Smoke 测试 交互式设置 Read 和 write 权限 自动创建 pull 请求 Verifies GitHub Actions permissions with read and write access Confirms workflow permissions to create and approve pull requests Runs interactive tests, including the Smoke Test - GitHub Permissions Creates a PR as part of the smoke test confirmation Supports GitHub Actions setup documentation via docs/github-actions-setup.md Enables developers to run the GitHub permissions smoke test repo-bootstrap is a skill that automates the initial setup of a new repository, ensuring proper GitHub Actions permissions and workflow configurations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HKTITAN/FediChess/fedichess-design', 'community', 'HKTITAN', 'FediChess', 'HKTITAN/FediChess', 'fedichess-design', 0, 0, 38, '2026-03-08T01:57:15.473Z', '2026-03-08T02:09:38.357Z', '664c381d6a4c4094e3e95a94fcf4194488ca9c24ee537161ee89e323d6d6dd7b', '{"id":"HKTITAN/FediChess/fedichess-design","name":"fedichess-design","description":{"en":"FediChess-design enables decentralized P2P chess in the browser, benefiting developers who want to create seamless user interactions. It applies principles of simplicity, fluidity, and delight to UI design.","zh":"FediChess 设计遵循简洁、流畅、愉悦的原则，实现无缝的 UI 体验。主要关注点包括使用 tray/overlay 进行次要操作和实现平滑的视图转换","ja":"FediChess デザインはシンプルさ、流動性、驚きの原則に基づいています。シームレスな UI 体験を実現するために、トレイ/オーバーレイを使用して二次的な操作を行うことができます","ko":"FediChess 디자인은 심플함, 유연함, 즐거움의 원칙을 따릅니다. 무중단의 UI 경험을 구현하기 위해 트레이/오버레이를 사용하여 부가적인 동작을 수행","es":"FediChess es un juego de ajedrez descentralizado que sigue principios de simplicidad y fluididad para ofrecer una experiencia de usuario intuitiva","fr":"FediChess est un jeu d''échecs décentralisé qui suit des principes de simplicité et de fluidité pour offrir une expérience utilisateur intuitive","de":"FediChess ist ein dezentrales Schachspiel, das Prinzipien der Einfachheit und Flüssigkeit verfolgt, um eine benutzerfreundliche Oberfläche zu bieten","pt":"O design do FediChess segue princípios de simplicidade, fluididade e deleite para criar uma experiência de usuário agradável","ru":"Дизайн FediChess основан на принципах простоты, жидкости и удовольствия для создания приятного пользовательского опыта","ar":"يتبع تصميم FediChess مبادئ البساطة والسلاسة والمتعة لإنشاء تجربة مستخدم لطيفة"},"seo":{"title":{"en":"fedichess-design: Decentralized P2P Chess Setup Guide | A...","zh":"FediChess 设计指南：简洁、流畅、愉悦的 UI 设计","ja":"FediChess デザインガイド：シンプルさ、流動性、驚きを実現する UI 設計","ko":"FediChess 디자인 가이드: 심플하고 유연하며 즐거운 UI 디자인","es":"Guía de diseño de FediChess: principios de simplicidad y ...","fr":"Conception de FediChess : meilleures pratiques pour une e...","de":"FediChess-Design-Leitfaden: Prinzipien für einfache und f...","pt":"Guia de Design do FediChess: Princípios de Simplicidade e...","ru":"ИИ Агенты: FediChess Design Руководство по Простоте и Жид...","ar":"دليل تصميم FediChess: مبادئ البساطة والسلاسة"},"description":{"en":"Discover how to implement smooth transitions and delightful UI in FediChess. Learn the principles of simplicity, fluidity, and polish for a better user exper...","zh":"了解 FediChess 设计的核心原则：简洁、流畅、愉悦。实现无缝的 UI 体验","ja":"FediChess デザインの核心原則：シンプルさ、流動性、驚きを学ぶ。シームレスな UI 体験を実現する","ko":"FediChess 디자인의 핵심 원칙: 심플함, 유연함, 즐거움. 無斷의 UI 경험을 구현","es":"Aprende a diseñar experiencias de usuario intuitivas con FediChess, el ajedrez descentralizado en el navegador, utilizando principios de simplicidad y fluididad","fr":"Découvrez comment concevoir des expériences utilisateur intuitives avec FediChess, le jeu d''échecs décentralisé dans le navigateur, en utilisant des principe...","de":"Erfahren Sie, wie Sie mit FediChess, dem dezentralen Schachspiel im Browser, benutzerfreundliche Oberflächen gestalten, indem Sie Prinzipien der Einfachheit ...","pt":"Aprenda sobre os princípios de design do FediChess, incluindo simplicidade, fluididade e deleite, para criar experiências de usuário agradáveis","ru":"Узнайте о принципах дизайна FediChess, включая простоту, жидкость и удовольствие, для создания приятных пользовательских опытов","ar":"تعرف على مبادئ تصميم FediChess، بما في ذلك البساطة والسلاسة والمتعة، لإنشاء تجارب مستخدم لطيفة"},"definition":{"en":"fedichess-design is a set of principles for designing intuitive and engaging user interfaces for decentralized P2P chess applications, focusing on simplicity, fluidity, and delight.","zh":"FediChess 设计是指一种遵循简洁、流畅、愉悦的原则的 UI 设计方法","ja":"FediChess デザインとは、シンプルさ、流動性、驚きの原則に基づいた UI 設計方法のこと","ko":"FediChess 디자인은 심플함, 유연함, 즐거움의 원칙을 따르는 UI 디자인 방법","es":"FediChess es un juego de ajedrez descentralizado que utiliza principios de diseño para ofrecer una experiencia de usuario simple y fluida","fr":"FediChess est un jeu d''échecs décentralisé qui utilise des principes de conception pour offrir une expérience utilisateur simple et fluide","de":"FediChess ist ein dezentrales Schachspiel, das Prinzipien des Designs verwendet, um eine einfache und flüssige Benutzeroberfläche zu bieten","pt":"O que é FediChess Design? É um conjunto de princípios de design para criar experiências de usuário agradáveis em aplicativos de xadrez","ru":"Что такое FediChess Design? Это набор принципов дизайна для создания приятных пользовательских опытов в шахматных приложениях","ar":"ما هو تصميم FediChess؟ هو مجموعة من مبادئ تصميم لتجارب مستخدم لطيفة في تطبيقات الشطرنج"},"features":{"en":["Applies simplicity principle for one primary focus per view","Utilizes tray/overlay for secondary actions like settings and copy link","Employs progressive disclosure to avoid crowding the main screen","Enables smooth transitions and modals for fluidity","Reuses or morphs elements for continuity and avoids static jumps","Adds polish and small surprises in high-impact moments like landing CTA"],"zh":["简洁的 UI 设计","平滑的视图转换","使用 tray/overlay 进行次要操作","实现进度式披露","避免静态跳转和冗余动画"],"ja":["シンプルな UI デザイン","スムーズなビューの切り替え","トレイ/オーバーレイを使用した二次的な操作","進度式の開示を実現","静的なジャンプや冗余なアニメーションを避ける"],"ko":["심플한 UI 디자인","무중단의 뷰 전환","트레이/오버레이를 사용한 부가적인 동작","진행식 공개를 구현","정적인 점프나 중복된 애니메이션을 피함"],"es":["Diseño simple y minimalista","Transiciones fluidas y sin saltos","Uso de trays y overlays para acciones secundarias","Divulgación progresiva para evitar la sobrecarga de la pantalla principal","Animaciones suaves y con propósito","Reutilización de elementos para mantener la continuidad"],"fr":["Conception simple et minimaliste","Transitions fluides et sans sauts","Utilisation de trays et d''overlays pour les actions secondaires","Divulgation progressive pour éviter l''encombrement de l''écran principal","Animations douces et à dessein","Réutilisation d''éléments pour maintenir la continuité"],"de":["Einfaches und minimalistisches Design","Flüssige Übergänge ohne Sprünge","Verwendung von Trays und Overlays für sekundäre Aktionen","Schrittweise Offenlegung, um die Überlastung des Hauptbildschirms zu vermeiden","Sanfte und zweckmäßige Animationen","Wiederverwendung von Elementen, um die Kontinuität zu wahren"],"pt":["Princípio de simplicidade para interfaces de usuário intuitivas","Transições suaves e purposeful para uma experiência de usuário fluida","Reutilização de elementos para continuidade visual","Efeitos de deleite para momentos de alta impacto","Design responsivo para uma experiência de usuário ótima em diferentes dispositivos"],"ru":["Принцип простоты для интуитивных интерфейсов пользователя","Гладкие и осмысленные переходы для жидкого пользовательского опыта","Переиспользование элементов для визуальной непрерывности","Эффекты удовольствия для моментов высокого воздействия","Отзывчивый дизайн для оптимального пользовательского опыта на разных устройствах"],"ar":["مبدأ البساطة لواجهات المستخدم البسيطة","انتقالات سلسة وغرضية لتحقيق تجربة مستخدم سلسة","إعادة استخدام العناصر للاستمرارية البصرية","أffects المتعة لأوقات التأثير العالي","تصميم مرن لتحقيق تجربة مستخدم ممتازة على أجهزة مختلفة"]},"keywords":{"en":["how to use fedichess-design","what is fedichess-design","fedichess-design alternative","fedichess-design vs chess.com","fedichess-design install","fedichess-design setup guide","decentralized P2P chess","smooth transitions in UI design","delightful user experience in chess apps"],"zh":["FediChess 设计","UI 设计","简洁设计","流畅设计","愉悦设计","进度式披露","tray/overlay","平滑视图转换"],"ja":["FediChess デザイン","UI デザイン","シンプル デザイン","流動性 デザイン","驚き デザイン","進度式の開示","トレイ/オーバーレイ","スムーズなビューの切り替え"],"ko":["FediChess 디자인","UI 디자인","심플 디자인","유연한 디자인","즐거운 디자인","진행식 공개","트레이/오버레이","무중단의 뷰 전환"],"es":["diseño de FediChess","ajedrez descentralizado","principios de diseño","experiencia de usuario","simplicidad","fluididad","Herramientas de diseño de UI","desarrollo de aplicaciones web","tecnologías de diseño"],"fr":["conception de FediChess","jeu d''échecs décentralisé","principes de conception","expérience utilisateur","simplicité","fluidité","Outils de conception d''UI","développement d''applications web","technologies de conception"],"de":["FediChess-Design","dezentrales Schachspiel","Designprinzipien","Benutzeroberfläche","Einfachheit","Flüssigkeit","UI-Design-Tools","Webanwendungs-Entwicklung","Design-Technologien"],"pt":["FediChess design","princípios de design","simplicidade","fluididade","deleite","design de aplicativos","experiência de usuário","interfaces de usuário","transições suaves","reutilização de elementos"],"ru":["FediChess дизайн","принципы дизайна","простота","жидкость","удовольствие","дизайн приложений","пользовательский опыт","интерфейсы пользователя","гладкие переходы","переиспользование элементов"],"ar":["تصميم FediChess","مبادئ التصميم","البساطة","السلاسة","المتعة","تصميم التطبيقات","تجربة المستخدم","واجهات المستخدم","انتقالات سلسة","إعادة استخدام العناصر"]}},"owner":"HKTITAN","repo":"FediChess","repoPath":"HKTITAN/FediChess","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.473Z","topics":[],"category":"community","skillMd":{"name":"fedichess-design","description":"Use when designing or changing UI, layout, or motion in FediChess.","bodyPreview":"# FediChess design\n\nApply when changing UI, layout, or motion in the app.\n\n## Principles\n\n- **Simplicity**: One primary focus per view. Use tray/overlay for secondary actions (settings, copy link). Progressive disclosure; avoid crowding the main screen.\n- **Fluidity**: Smooth, purposeful transitions (view changes, modals). Reuse or morph elements for continuity. Avoid static jumps and redundant or decorative animation.\n- **Delight**: Polish and small surprises in high-impact moments (landing CTA","body":"# FediChess design\n\nApply when changing UI, layout, or motion in the app.\n\n## Principles\n\n- **Simplicity**: One primary focus per view. Use tray/overlay for secondary actions (settings, copy link). Progressive disclosure; avoid crowding the main screen.\n- **Fluidity**: Smooth, purposeful transitions (view changes, modals). Reuse or morph elements for continuity. Avoid static jumps and redundant or decorative animation.\n- **Delight**: Polish and small surprises in high-impact moments (landing CTA, move confirmation, game end). Avoid sprinkling motion everywhere; follow a delight–impact curve.\n\n## Typography and brand\n\n- **Instrument Serif** for brand and headings (e.g. main \"FediChess\" title, section headings).\n- Body text: neutral sans for readability.\n- Reference `.agents/skills/frontend-design/SKILL.md` for typography, color, and motion details. FediChess design principles are the project design language.\n\n## When to use\n\nUse this skill when the user asks to change or add UI, layout, animations, or styling in FediChess (landing, lobby, game, or shared components).\n"},"lastSynced":"2026-03-08T02:09:38.357Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX Agent Architects designing fluid, minimalist browser-based applications.","zh":"非常适合设计流畅、极简的基于浏览器的应用程序的UI/UX Agent架构师。","ja":"流暢でミニマリストなブラウザベースのアプリケーションを設計するUI/UXエージェントアーキテクトに最適です。","ko":"유연하고 미니멀한 브라우저 기반 애플리케이션을 설계하는 UI/UX 에이전트 아키텍트에게 완벽합니다.","es":"Ideal para arquitectos de Agentes de UI/UX que diseñan aplicaciones basadas en navegador minimalistas y fluidas.","fr":"Parfait pour les architectes d''agents UI/UX conçuant des applications basées sur navigateur fluides et minimalistes.","de":"Perfekt für UI/UX-Agenten-Architekten, die flüssige, minimalistische browserbasierte Anwendungen entwerfen.","pt":"Perfeito para Arquitetos de Agentes UI/UX que projetam aplicações baseadas em navegador fluidas e minimalistas.","ru":"Идеально подходит для архитекторов UI/UX агентов, разрабатывающих жидкие, минималистические приложения на основе браузера.","ar":"مثالي لعمارة واجهة المستخدم وتجربة المستخدم التي تصمم تطبيقات متصفح الإنترنت السلسة والبسيطة."},"recommendation":{"en":"Enables agents to implement decentralized P2P chess interfaces with smooth view transitions, tray/overlay systems for secondary actions, and progressive disclosure patterns that avoid screen crowding. Applies principles of simplicity, fluidity, and delight to create seamless user interactions in browser environments.","zh":"使智能体能够实现具有流畅视图转换的去中心化P2P象棋界面、用于次要操作的托盘/覆盖系统，以及避免屏幕拥挤的渐进式披露模式。应用简洁性、流畅性和愉悦性原则，在浏览器环境中创建无缝的用户交互体验。","ja":"エージェントが、スムーズなビュートランジションを備えた分散型P2Pチェスインターフェース、二次アクションのためのトレイ/オーバーレイシステム、画面の混雑を避ける段階的開示パターンを実装できるようにします。シンプルさ、流動性、喜びの原則を適用し、ブラウザ環境でシームレスなユーザーインタラクションを作成します。","ko":"에이전트가 매끄러운 뷰 전환, 보조 작업을 위한 트레이/오버레이 시스템, 화면 혼잡을 피하는 점진적 공개 패턴을 갖춘 분산형 P2P 체스 인터페이스를 구현할 수 있도록 합니다. 단순성, 유연성, 즐거움의 원칙을 적용하여 브라우저 환경에서 원활한 사용자 상호 작용을 생성합니다.","es":"Permite a los agentes implementar interfaces de ajedrez P2P descentralizadas con transiciones de vista suaves, sistemas de bandeja/sobreposición para acciones secundarias y patrones de divulgación progresiva que evitan la congestión de la pantalla. Aplica principios de simplicidad, fluidez y deleite para crear interacciones de usuario sin problemas en entornos de navegador.","fr":"Permet aux agents de mettre en œuvre des interfaces d''échecs P2P décentralisées avec des transitions de vue fluides, des systèmes de bac/surimpression pour des actions secondaires et des modèles de divulgation progressive qui évitent l''encombrement de l''écran. Applique des principes de simplicité, de fluidité et de délice pour créer des interactions utilisateur sans accroc dans les environnements de navigateur.","de":"Ermöglicht es Agenten, dezentrale P2P-Schachinterfaces mit sanften Blickübergängen, Tray/Überlagerungssystemen für sekundäre Aktionen und progressiven Offenlegungsmustern zu implementieren, die eine Bildschirmüberlastung vermeiden. Wendet Prinzipien der Einfachheit, Flüssigkeit und Freude an, um nahtlose Benutzerinteraktionen in Browserumgebungen zu schaffen.","pt":"Permite que os agentes implementem interfaces de xadrez P2P descentralizadas com transições de visualização suaves, sistemas de bandeja/sobreposição para ações secundárias e padrões de divulgação progressiva que evitam o congestionamento da tela. Aplica princípios de simplicidade, fluidez e prazer para criar interações de usuário sem interrupções em ambientes de navegador.","ru":"Позволяет агентам реализовывать децентрализованные интерфейсы шахмат P2P с плавными переходами вида, системами поддон/наложения для второстепенных действий и шаблонами постепенного раскрытия, которые избегают загромождения экрана. Применяет принципы простоты, плавности и удовольствия для создания бесперебойных взаимодействий пользователя в средах браузера.","ar":"يسمح للوكلاء بتنفيذ واجهات شطرنج منتشرة مع عمليات انتقال اتجاهات سلسة، ونظم سلة/تغطية لإجراءات ثانوية، وأنماط الكشف التدريجي التي تتجنب الازدحام الشاشات. يطبق مبادئ البساطة والسيولة والمتعة لإنشاء تفاعلات مستخدم لامعة في بيئات المتصفح."},"useCases":{"en":["Designing minimalist chess game interfaces","Implementing smooth modal transitions for game actions","Creating progressive disclosure systems for settings and controls","Developing tray/overlay systems for secondary game functions"],"zh":["设计极简主义象棋游戏界面","为游戏操作实现流畅的模态转换","为设置和控制创建渐进式披露系统","为次要游戏功能开发托盘/覆盖系统"],"ja":["ミニマリストなチェスゲームインターフェースの設計","ゲームアクションのためのスムーズなモーダルトランジションの実装","設定と制御のための段階的開示システムの作成","二次的なゲーム機能のためのトレイ/オーバーレイシステムの開発"],"ko":["미니멀리스트 체스 게임 인터페이스 설계","게임 작업을 위한 매끄러운 모달 전환 구현","설정 및 컨트롤을 위한 점진적 공개 시스템 생성","보조 게임 기능을 위한 트레이/오버레이 시스템 개발"],"es":["Diseñar interfaces de juegos de ajedrez minimalistas","Implementar transiciones modales suaves para acciones de juego","Crear sistemas de divulgación progresiva para configuraciones y controles","Desarrollar sistemas de bandeja/sobreposición para funciones de juego secundarias"],"fr":["Concevoir des interfaces de jeux d''échecs minimalistes","Mettre en œuvre des transitions modales fluides pour les actions de jeu","Créer des systèmes de divulgation progressive pour les paramètres et les commandes","Développer des systèmes de bac/surimpression pour les fonctions de jeu secondaires"],"de":["Minimalistische Schachspielf Schnittstellen entwerfen","Sanfte Modallübergänge für Spielaktionen implementieren","Progressive Offenlegungssysteme für Einstellungen und Steuerungen erstellen","Tray/Überlagerungssysteme für sekundäre Spielbereiche entwickeln"],"pt":["Projetar interfaces de jogo de xadrez minimalistas","Implementar transições modais suaves para ações de jogo","Criar sistemas de divulgação progressiva para configurações e controles","Desenvolver sistemas de bandeja/sobreposição para funções de jogo secundárias"],"ru":["Проектировать минималистические интерфейсы шахматных игр","Реализовывать плавные модальные переходы для действий игры","Создавать системы постепенного раскрытия для настроек и контролей","Разрабатывать системы поддон/наложения для второстепенных функций игры"],"ar":["تصميم واجهات لعبة الشطرنج البسيطة","تنفيذ عمليات انتقال مودال سلسة لإجراءات اللعبة","إنشاء أنظمة الكشف التدريجي للإعدادات والضوابط","تطوير أنظمة سلة/تغطية لبعض وظائف اللعبة"]},"limitations":{"en":["Browser-based implementation only","Focuses exclusively on UI/UX design patterns","Requires existing chess game logic integration"],"zh":["仅限基于浏览器的实现","完全专注于UI/UX设计模式","需要集成现有的象棋游戏逻辑"],"ja":["ブラウザベースの実装のみ","UI/UXデザインパターンにのみ焦点を当てる","既存のチェスゲームロジックの統合が必要"],"ko":["브라우저 기반 구현만 해당","UI/UX 디자인 패턴에만 집중","기존 체스 게임 로직 통합 필요"],"es":["Implementación basada en navegador solo","Se centra exclusivamente en patrones de diseño de UI/UX","Requiere la integración existente de la lógica del juego de ajedrez"],"fr":["Mise en œuvre basée sur navigateur uniquement","Se concentre exclusivement sur les modèles de conception UI/UX","Nécessite l''intégration existante de la logique du jeu d''échecs"],"de":["Nur browserbasierte Implementierung","Konzentriert sich ausschließlich auf UI/UX-Designtrends","Benötigt die bestehende Integration der Schachspielloigik"],"pt":["Implementação baseada em navegador apenas","Concentra-se exclusivamente em padrões de design UI/UX","Requer integração de lógica de jogo de xadrez existente"],"ru":["Реализация только на основе браузера","Фокусируется исключительно на шаблонах дизайна UI/UX","Требует интеграции существующей логики шахматной игры"],"ar":["تنفيذ المتصفح فقط","يركز حصريا على أنماط تصميم واجهة المستخدم وتجربة المستخدم","يتطلب تكامل منطق لعبة الشطرنج الحالية"]},"version":4},"contentHash":"664c381d6a4c4094e3e95a94fcf4194488ca9c24ee537161ee89e323d6d6dd7b","qualityScore":38}');
