INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HKTITAN/FediChess/fedichess-design', 'fedichess-design', 'HKTITAN', 'FediChess', 'community', 'fedichess-design HKTITAN FediChess community FediChess-design enables decentralized P2P chess in the browser, benefiting developers who want to create seamless user interactions. It applies principles of simplicity, fluidity, and delight to UI design. FediChess 设计遵循简洁、流畅、愉悦的原则，实现无缝的 UI 体验。主要关注点包括使用 tray/overlay 进行次要操作和实现平滑的视图转换 FediChess デザインはシンプルさ、流動性、驚きの原則に基づいています。シームレスな UI 体験を実現するために、トレイ/オーバーレイを使用して二次的な操作を行うことができます FediChess 디자인은 심플함, 유연함, 즐거움의 원칙을 따릅니다. 무중단의 UI 경험을 구현하기 위해 트레이/오버레이를 사용하여 부가적인 동작을 수행 FediChess es un juego de ajedrez descentralizado que sigue principios de simplicidad y fluididad para ofrecer una experiencia de usuario intuitiva FediChess est un jeu d''échecs décentralisé qui suit des principes de simplicité et de fluidité pour offrir une expérience utilisateur intuitive FediChess ist ein dezentrales Schachspiel, das Prinzipien der Einfachheit und Flüssigkeit verfolgt, um eine benutzerfreundliche Oberfläche zu bieten O design do FediChess segue princípios de simplicidade, fluididade e deleite para criar uma experiência de usuário agradável Дизайн FediChess основан на принципах простоты, жидкости и удовольствия для создания приятного пользовательского опыта يتبع تصميم FediChess مبادئ البساطة والسلاسة والمتعة لإنشاء تجربة مستخدم لطيفة how to use fedichess-design what is fedichess-design fedichess-design alternative fedichess-design vs chess.com fedichess-design install fedichess-design setup guide decentralized P2P chess smooth transitions in UI design delightful user experience in chess apps FediChess 设计 UI 设计 简洁设计 流畅设计 愉悦设计 进度式披露 tray/overlay 平滑视图转换 Applies simplicity principle for one primary focus per view Utilizes tray/overlay for secondary actions like settings and copy link Employs progressive disclosure to avoid crowding the main screen Enables smooth transitions and modals for fluidity Reuses or morphs elements for continuity and avoids static jumps Adds polish and small surprises in high-impact moments like landing CTA fedichess-design is a set of principles for designing intuitive and engaging user interfaces for decentralized P2P chess applications, focusing on simplicity, fluidity, and delight.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hutchic/.cursor/ensure-feature-branch', 'community', 'hutchic', '.cursor', 'hutchic/.cursor', 'ensure-feature-branch', 0, 0, 38, '2026-03-08T01:57:15.475Z', '2026-03-08T02:09:44.877Z', 'f40d627d738cf2ff67e96a58127f02ee6c149facfdc3d0bdbb74896c65796aef', '{"id":"hutchic/.cursor/ensure-feature-branch","name":"ensure-feature-branch","description":{"en":"The ensure-feature-branch skill automates branch management, ensuring that commits are made on feature or bug branches. This skill benefits developers working on mainline or release branches","zh":"Ensure Feature Branch Skill 是一个自动化工具，确保代码提交到正确的分支，防止直接提交到主线或发布分支","ja":"Ensure Feature Branch Skill は、コードのコミットを正しいブランチに確実にする自動化ツールです","ko":"Ensure Feature Branch Skill은 코드를 올바른 분기에 커밋하도록 하는 자동화 도구입니다","es":"La habilidad ensure-feature-branch garantiza que los commits se realicen en una rama de función o error, evitando así modificaciones en mainline o release.","fr":"L''agent ensure-feature-branch assure que les commits sont effectués sur une branche de fonction ou de correction, évitant ainsi les modifications sur mainline ou release.","de":"Die Fähigkeit ensure-feature-branch stellt sicher, dass Commits auf einem Feature- oder Fehlerbranch durchgeführt werden, um so Änderungen an mainline oder release zu vermeiden.","pt":"O Ensure Feature Branch é uma habilidade que garante que o trabalho seja feito em uma branch de recurso ou bug, evitando ainsi commits diretos na mainline ou release.","ru":"ИИ Агент Ensure Feature Branch - это функция, которая гарантирует, что работа выполняется в функциональной или ошибочной ветке, тем самым избегая прямых коммитов в mainline или release.","ar":"Ensure Feature Branch هو ميزة تضمن أن يتم العمل في فرع ميزة أو خطأ، وبذلك يتم تجنب الالتزامات المباشرة في الخط الرئيسي أو الإصدار"},"seo":{"title":{"en":"ensure-feature-branch: Automated Branch Management for AI...","zh":"Ensure Feature Branch Setup Guide - AIエージェント","ja":"Ensure Feature Branch ベストプラクティス - AIエージェント","ko":"Ensure Feature Branch 설정 가이드 - AI 에이전트","es":"Configuración de la habilidad ensure-feature-branch para ...","fr":"Guide d''installation de l''agent ensure-feature-branch pou...","de":"Einrichtung der ensure-feature-branch-Fähigkeit für KI-Tools","pt":"Guia de Configuração do Ensure Feature Branch para Desenv...","ru":"Настройка ИИ Агента Ensure Feature Branch для разработчиков","ar":"إعداد وتثبيت Ensure Feature Branch لمنصة التطوير"},"description":{"en":"Prevent accidental commits to mainline or release branches with ensure-feature-branch. Learn how to set up and use this skill for seamless automation","zh":"使用 Ensure Feature Branch Skill 确保代码提交到正确的分支，避免直接提交到主线或发布分支","ja":"Ensure Feature Branch Skill を使用して、コードのコミットを正しいブランチに確実にします","ko":"Ensure Feature Branch Skill을 사용하여 코드를 올바른 분기에 커밋하도록 하세요","es":"Aprende a configurar la habilidad ensure-feature-branch para evitar commits en mainline o release. ¡Descubre cómo proteger tu código con esta herramienta de IA!","fr":"Découvrez comment configurer l''agent ensure-feature-branch pour éviter les commits sur mainline ou release. Protégez votre code avec cet outil d''IA !","de":"Erfahren Sie, wie Sie die Fähigkeit ensure-feature-branch einrichten, um Commits auf mainline oder release zu vermeiden. Schützen Sie Ihren Code mit diesem K...","pt":"Aprenda a configurar o Ensure Feature Branch para evitar commits diretos na mainline ou release. Descubra como usar essa habilidade em hooks de pré-commit ou...","ru":"Узнайте, как настроить ИИ Агент Ensure Feature Branch, чтобы избежать прямых коммитов в mainline или release. Откройте для себя, как использовать эту функцию...","ar":"تعرف على كيفية تثبيت Ensure Feature Branch لتجنب الالتزامات المباشرة في الخط الرئيسي أو الإصدار. اكتشف كيفية استخدام هذه الميزة في-hooks pre-commit أو أوامر"},"definition":{"en":"ensure-feature-branch is a skill that ensures the current branch is a feature or bug branch, preventing commits on mainline or release branches","zh":"Ensure Feature Branch Skill 是一种自动化工具，用于确保代码提交到正确的分支","ja":"Ensure Feature Branch Skill は、コードのコミットを正しいブランチに確実にするための自動化ツールです","ko":"Ensure Feature Branch Skill은 코드를 올바른 분기에 커밋하도록 하는 자동화 도구입니다","es":"La habilidad ensure-feature-branch es una herramienta de IA que garantiza que los commits se realicen en una rama de función o error.","fr":"L''agent ensure-feature-branch est un outil d''IA qui assure que les commits sont effectués sur une branche de fonction ou de correction.","de":"Die Fähigkeit ensure-feature-branch ist ein KI-Tool, das sicherstellt, dass Commits auf einem Feature- oder Fehlerbranch durchgeführt werden.","pt":"O que é Ensure Feature Branch? É uma habilidade que garante o trabalho em branches de recurso ou bug.","ru":"Что такое ИИ Агент Ensure Feature Branch? Это функция, которая гарантирует выполнение работы в функциональных или ошибочных ветках.","ar":"ما هو Ensure Feature Branch؟ هو ميزة تضمن العمل في فروع الميزة أو الخطأ"},"features":{"en":["Automatically creates and checks out a new branch if the current branch is mainline or release","Prevents commits from being made directly to mainline or release branches","Supports use as a pre-commit hook, command, or manual request","Ensures work is not committed or pushed directly to mainline or release","Compatible with various branch names, including ''main'' and ''master''"],"zh":["自动检测当前分支","防止直接提交到主线或发布分支","支持 pre-commit hook 和命令行调用","确保代码提交到正确的分支"],"ja":["現在のブランチを自動で検出","メインラインやリリースブランチへの直接コミットを防止","pre-commit hook とコマンドライン呼び出しをサポート","コードを正しいブランチにコミットすることを保証"],"ko":["현재 분기를 자동으로 감지","메인 라인 또는 릴리즈 분기에 대한 직접 커밋을 방지","pre-commit hook 및 명령줄 호출을 지원","코드를 올바른 분기에 커밋하도록 보장"],"es":["Evita commits en mainline o release","Crea y cambia a una nueva rama si es necesario","Se puede utilizar como hook de pre-compromiso o como comando manual","Protege el código evitando modificaciones no deseadas","Se integra con herramientas de automatización","Es compatible con Git"],"fr":["Évite les commits sur mainline ou release","Crée et bascule sur une nouvelle branche si nécessaire","Peut être utilisé comme hook de pré-compromis ou comme commande manuelle","Protège le code en évitant les modifications non désirées","S''intègre avec des outils d''automatisation","Est compatible avec Git"],"de":["Vermeidet Commits auf mainline oder release","Erstellt und wechselt zu einem neuen Branch, wenn erforderlich","Kann als Pre-Commit-Hook oder als manueller Befehl verwendet werden","Schützt den Code, indem unerwünschte Änderungen vermieden werden","Integriert sich mit Automatisierungstools","Ist mit Git kompatibel"],"pt":["Evita commits diretos na mainline ou release","Cria e verifica uma nova branch se necessário","Pode ser usado em hooks de pré-commit ou comandos","Garante que o trabalho seja feito em uma branch de recurso ou bug","Compatível com automação de tarefas","Integração com CLI para comandos personalizados"],"ru":["Избегает прямых коммитов в mainline или release","Создаёт и проверяет новую ветку, если необходимо","Может быть использована в хуках предкоммита или командах","Гарантирует, что работа выполняется в функциональной или ошибочной ветке","Компатибельно с автоматизацией задач","Интегрируется с CLI для пользовательских команд"],"ar":["يتجنب الالتزامات المباشرة في الخط الرئيسي أو الإصدار","ينشئ ويفحص فرعًا جديدًا عند الحاجة","يمكن استخدامه في-hooks pre-commit أو أوامر","يضمن أن يتم العمل في فرع ميزة أو خطأ","متوافق مع ت자동ية المهام","يتوافق مع CLI لأوامر مخصصة"]},"keywords":{"en":["how to use ensure-feature-branch","what is ensure-feature-branch","ensure-feature-branch alternative","ensure-feature-branch vs git flow","ensure-feature-branch install","ensure-feature-branch setup guide","automated branch management","pre-commit hook","git branch management"],"zh":["AIエージェント","自动化工具","代码提交","分支管理","pre-commit hook","命令行调用","Ensure Feature Branch Skill"],"ja":["AIエージェント","自動化ツール","コードのコミット","ブランチ管理","pre-commit hook","コマンドライン呼び出し","Ensure Feature Branch Skill"],"ko":["AI 에이전트","자동화 도구","코드 커밋","분기 관리","pre-commit hook","명령줄 호출","Ensure Feature Branch Skill"],"es":["agentes de IA para desarrollo","herramientas de IA para Git","ensure-feature-branch","ramas de función","ramas de error","pre-compromiso","automatización de código"],"fr":["outils d''IA pour le développement","outils d''IA pour Git","ensure-feature-branch","branches de fonction","branches de correction","pré-compromis","automatisation de code"],"de":["KI-Tools für Entwicklung","KI-Tools für Git","ensure-feature-branch","Feature-Branches","Fehlerbranches","Pre-Commit","Code-Automatisierung"],"pt":["ensure feature branch","desenvolvimento de software","controle de versão","git","hooks de pré-commit","automatização de tarefas","CLI","desenvolvedores","programação"],"ru":["ИИ Агент Ensure Feature Branch","разработка программного обеспечения","контроль версий","git","хуки предкоммита","автоматизация задач","CLI","разработчики","программирование"],"ar":["Ensure Feature Branch","تطوير البرمجيات","مراقبة الإصدار","git","hooks pre-commit","ت자동ية المهام","CLI","مطوّرون","برمجة"]}},"owner":"hutchic","repo":".cursor","repoPath":"hutchic/.cursor","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.475Z","topics":[],"category":"community","skillMd":{"name":"ensure-feature-branch","description":"Ensure were on a feature or bug branch. If current branch is mainline (main, master, dev) or a release branch (release/*), create and checkout a new branch. Use when a workflow or user request should avoid committing or pushing directly to mainline or release.","bodyPreview":"# Ensure Feature Branch Skill\n\nEnsure the current branch is a feature or bug branch. If it is a mainline or release branch, create and checkout a new branch so commits are not made on mainline/release. Use this skill on its own or as part of any automation (e.g. pre-commit hook, command, or manual request).\n\n## When to Use\n\n- Use when you need to ensure work is not committed or pushed directly to mainline or release\n- Use when the user asks to commit/push and the current branch is main, master,","body":"# Ensure Feature Branch Skill\n\nEnsure the current branch is a feature or bug branch. If it is a mainline or release branch, create and checkout a new branch so commits are not made on mainline/release. Use this skill on its own or as part of any automation (e.g. pre-commit hook, command, or manual request).\n\n## When to Use\n\n- Use when you need to ensure work is not committed or pushed directly to mainline or release\n- Use when the user asks to commit/push and the current branch is main, master, dev, or release/*\n- Use in any workflow that requires a feature/bug branch before subsequent steps (e.g. stage, commit, push)\n\n## Mainline and Release Branches\n\nTreat these as **not** feature/bug branches; create a new branch if current branch is one of:\n\n- **Mainline**: `main`, `master`, `dev`\n- **Release**: Any branch matching `release/*` (e.g. `release/1.0`, `release/2.x`)\n\nRepos may use different default branch names (e.g. `trunk`, `development`). If the repo clearly uses another name as the primary integration branch, treat it as mainline.\n\n## Steps\n\n1. Get current branch: `git branch --show-current`\n2. If it is a mainline or release branch (as above), create a new branch and checkout:\n   - **Branch name**: Infer from the changes (files/diff) a short kebab-case description. Use `feat/<description>` for features or `fix/<description>` for fixes. If the change type is unclear, use `feat/<description>` or a neutral `chore/<description>`.\n   - Run: `git checkout -b <branch-name>`\n3. If already on a feature/bug branch (e.g. `feat/...`, `fix/...`, or any branch not mainline/release), do nothing and proceed.\n\n## Notes\n\n- When used in a multi-step flow (e.g. before stage → commit → push), run this first so the first commit lands on the new branch.\n- Do not create a branch if already on a non-mainline, non-release branch (e.g. existing `feat/xyz` or an updatecli branch).\n\n## Related Artifacts\n\n- [Shipit Command](.cursor/commands/shipit.md)\n- [Stage Related Files Skill](.cursor/skills/git/stage-related-files/SKILL.md)\n- [Terse Semantic Commits Skill](.cursor/skills/git/terse-semantic-commits/SKILL.md)\n"},"lastSynced":"2026-03-08T02:09:44.877Z","agentAnalysis":{"suitability":{"en":"Ideal for Git-based AI Agents requiring automated branch management and pre-commit hook integration.","zh":"适用于需要自动化分支管理和预提交钩子集成的基于 Git 的 AI 代理。","ja":"Git ベースの AI エージェントが自動化されたブランチ管理と事前コミットフック統合を必要とする場合に最適です。","ko":"자동화된 브랜치 관리 및 커밋 전 후크 통합이 필요한 Git 기반 AI 에이전트에 적합합니다.","es":"Ideal para Agentes de IA basados en Git que requieren una gestión de ramas automatizada y una integración de ganchos pre-commit.","fr":"Idéal pour les agents d''IA basés sur Git nécessitant une gestion de branches automatisée et une intégration de hooks de pré-validation.","de":"Ideal für Git-basierte KI-Agents, die eine automatisierte Verwaltung von Zweigen und eine Integration von Pre-Commit-Hooks erfordern.","pt":"Ideal para Agentes de IA baseados em Git que exigem gerenciamento de branch automatizado e integração de hook pré-commit.","ru":"Идеально для агентов ИИ на основе Git, требующих автоматизированного управления ветками и интеграции с хуками предкоммита.","ar":"مثالي للوكلاء الذكاء الاصطناعي القائمين على Git الذين يتطلبون إدارة فرع أوتوماتيكي وتكامل hook ما قبل الإلتزام."},"recommendation":{"en":"Empowers agents to enforce branch protocols, preventing direct commits to mainline or release branches and ensuring compliance with Git workflows using feature and bug branches, thereby streamlining development and reducing errors.","zh":"赋予代理人执行分支协议的能力，防止直接提交到主线或发布分支，并确保遵守使用功能和 bug 分支的 Git 工作流，从而简化开发并减少错误。","ja":"エージェントがブランチプロトコルを強制し、メインラインやリリースブランチへの直接コミットを防ぎ、機能ブランチとバグブランチを使用する Git ワークフローに従って、開発を簡素化し、エラーを削減する。","ko":"에이전트가 브랜치 프로토콜을 시행하고 메인라인 또는 릴리스 브랜치에 대한 직접 커밋을 방지하여 기능 브랜치와 버그 브랜치를 사용하는 Git 워크플로우를 준수하도록 하여 개발을 단순화하고 오류를 줄입니다.","es":"Habilita a los agentes a hacer cumplir los protocolos de ramas, evitando los commits directos a las ramas principales o de lanzamiento y asegurando el cumplimiento de los flujos de trabajo de Git utilizando ramas de características y errores, lo que simplifica el desarrollo y reduce los errores.","fr":"Permet aux agents d''appliquer les protocoles de branches, empêchant les commits directs sur les branches principales ou de publication et assurant le respect des flux de travail Git en utilisant des branches de fonctionnalités et de bogues, ce qui rationalise le développement et réduit les erreurs.","de":"Ermächtigt die Agents, die Verzweigungsprotokolle durchzusetzen, indem direkte Commits an Haupt- oder Release-Zweige verhindert und die Einhaltung von Git-Workflows mit Hilfe von Feature- und Bug-Zweigen sichergestellt wird, wodurch die Entwicklung vereinfacht und die Fehler reduziert werden.","pt":"Habilita os agentes a impor protocolos de branch, impedindo commits diretos para branches principais ou de lançamento e garantindo a conformidade com fluxos de trabalho Git usando branches de recursos e bugs, simplificando assim o desenvolvimento e reduzindo erros.","ru":"Наделяет агентов возможностью обеспечивать соблюдение протоколов веток, предотвращая прямые коммиты в основные или релизные ветки и гарантируя соответствие рабочим процессам Git с использованием функциональных и баг-веток, тем самым оптимизируя разработку и снижая ошибки.","ar":"يمكن الوكلاء من فرض بروتوكولات الفرع، ومنع الالتزامات المباشرة للفروع الرئيسية أو الإصدار وضمان الامتثال لتدفقات العمل Git باستخدام فروع الميزات والعيوب، وبالتالي تبسيط التطوير وتقليل الأخطاء."},"useCases":{"en":["Automating branch creation for new features","Validating branch types before commit","Integrating with pre-commit hooks for enhanced workflow control"],"zh":["自动化新功能的分支创建","提交前验证分支类型","集成预提交钩子以增强工作流控制"],"ja":["新機能のブランチ作成を自動化する","コミット前にブランチタイプを検証する","事前コミットフックを統合してワークフロー制御を強化する"],"ko":["새 기능에 대한 브랜치 생성 자동화","커밋 전 분기 유형 확인","사전 커밋 후크와의 통합을 통해 워크플ロー 제어 강화"],"es":["Automatizar la creación de ramas para nuevas características","Validar los tipos de ramas antes del commit","Integrar con ganchos pre-commit para un control de flujo de trabajo mejorado"],"fr":["Automatiser la création de branches pour de nouvelles fonctionnalités","Valider les types de branches avant le commit","Intégrer avec des hooks de pré-validation pour un contrôle amélioré du flux de travail"],"de":["Automatisieren der Erstellung von Zweigen für neue Funktionen","Validieren der Zweigtypen vor dem Commit","Integrieren mit Pre-Commit-Hooks für eine verbesserte Workflow-Kontrolle"],"pt":["Automatizar a criação de branch para novos recursos","Validar os tipos de branch antes do commit","Integrar com hooks pré-commit para controle de fluxo de trabalho aprimorado"],"ru":["Автоматизировать создание веток для новых функций","Проверять типы веток перед коммитом","Интегрироваться с хуками предкоммита для расширенного контроля рабочего процесса"],"ar":["أتمتة إنشاء الفرع للسمات الجديدة","التحقق من أنواع الفرع قبل الالتزام","التكامل مع hooks ما قبل الالتزام لتحكم متقدم في تدفق العمل"]},"limitations":{"en":["Requires Git repository access","Limited to feature and bug branch management"],"zh":["需要 Git 存储库访问","仅限功能和 bug 分支管理"],"ja":["Git リポジトリへのアクセスが必要","機能とバグブランチ管理のみ"],"ko":["Git 저장소 액세스가 필요함","기능 및 버그 브랜치 관리에만 제한"],"es":["Requiere acceso al repositorio de Git","Limitado a la gestión de ramas de características y errores"],"fr":["Nécessite un accès au référentiel Git","Limité à la gestion des branches de fonctionnalités et de bogues"],"de":["Benötigt Zugriff auf das Git-Repository","Begrenzt auf die Verwaltung von Feature- und Bug-Zweigen"],"pt":["Exige acesso ao repositório Git","Limitado ao gerenciamento de branch de recursos e bugs"],"ru":["Требует доступа к репозиторию Git","Ограничен управлением ветками функций и багов"],"ar":["يتطلب الوصول إلى مستودع Git","محدود لإدارة فروع الميزات والعيوب"]},"version":4},"contentHash":"f40d627d738cf2ff67e96a58127f02ee6c149facfdc3d0bdbb74896c65796aef","qualityScore":38}');
