INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hutchic/.cursor/ensure-feature-branch', 'ensure-feature-branch', 'hutchic', '.cursor', 'community', 'ensure-feature-branch hutchic .cursor community The ensure-feature-branch skill automates branch management, ensuring that commits are made on feature or bug branches. This skill benefits developers working on mainline or release branches Ensure Feature Branch Skill 是一个自动化工具，确保代码提交到正确的分支，防止直接提交到主线或发布分支 Ensure Feature Branch Skill は、コードのコミットを正しいブランチに確実にする自動化ツールです Ensure Feature Branch Skill은 코드를 올바른 분기에 커밋하도록 하는 자동화 도구입니다 La habilidad ensure-feature-branch garantiza que los commits se realicen en una rama de función o error, evitando así modificaciones en mainline o release. L''agent ensure-feature-branch assure que les commits sont effectués sur une branche de fonction ou de correction, évitant ainsi les modifications sur mainline ou release. Die Fähigkeit ensure-feature-branch stellt sicher, dass Commits auf einem Feature- oder Fehlerbranch durchgeführt werden, um so Änderungen an mainline oder release zu vermeiden. O Ensure Feature Branch é uma habilidade que garante que o trabalho seja feito em uma branch de recurso ou bug, evitando ainsi commits diretos na mainline ou release. ИИ Агент Ensure Feature Branch - это функция, которая гарантирует, что работа выполняется в функциональной или ошибочной ветке, тем самым избегая прямых коммитов в mainline или release. Ensure Feature Branch هو ميزة تضمن أن يتم العمل في فرع ميزة أو خطأ، وبذلك يتم تجنب الالتزامات المباشرة في الخط الرئيسي أو الإصدار how to use ensure-feature-branch what is ensure-feature-branch ensure-feature-branch alternative ensure-feature-branch vs git flow ensure-feature-branch install ensure-feature-branch setup guide automated branch management pre-commit hook git branch management AIエージェント 自动化工具 代码提交 分支管理 pre-commit hook 命令行调用 Ensure Feature Branch Skill Automatically creates and checks out a new branch if the current branch is mainline or release Prevents commits from being made directly to mainline or release branches Supports use as a pre-commit hook, command, or manual request Ensures work is not committed or pushed directly to mainline or release Compatible with various branch names, including ''main'' and ''master'' ensure-feature-branch is a skill that ensures the current branch is a feature or bug branch, preventing commits on mainline or release branches');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Jeduardo622/AllIincompassing/staging-deployment-operation', 'community', 'Jeduardo622', 'AllIincompassing', 'Jeduardo622/AllIincompassing', 'staging-deployment-operation', 0, 0, 38, '2026-03-08T01:57:15.477Z', '2026-03-08T02:09:49.514Z', '6d2e39dcabfab8c8810abc7fe3fac78587e04cb51ad449fcca9bd44ef2e4eb19', '{"id":"Jeduardo622/AllIincompassing/staging-deployment-operation","name":"staging-deployment-operation","description":{"en":"The staging-deployment-operation skill automates deployment workflows for developers, providing a quick start guide and validation checks for seamless staging deployment operations.","zh":"预发布部署操作是一种确保代码部署到预发布环境的过程，包括验证检查和状态汇总","ja":"ステージングデプロイ操作は、コードをステージング環境にデプロイするためのプロセスです - バリデーションチェックとステータスサマリー","ko":"스테이징 배포 운영은 코드를 스테이징 환경에 배포하는 프로세스입니다 - 유효성 검사 및 상태 요약","es":"La operación de despliegue de staging es un proceso crucial para validar y probar aplicaciones antes de su lanzamiento. Nuestra guía cubre los pasos clave para una implementación exitosa.","fr":"L''opération de déploiement de staging est un processus crucial pour valider et tester des applications avant leur lancement. Notre guide couvre les étapes clés pour une mise en place réussie.","de":"Die Staging-Deploy-Operation ist ein entscheidender Prozess, um Anwendungen vor ihrem Release zu validieren und zu testen. Unser Leitfaden behandelt die wichtigsten Schritte für eine erfolgreiche Implementierung.","pt":"A operação de implantação em staging é um processo que envolve a validação e o resumo de status para garantir a implantação correta","ru":"Операция развертывания в стадии - это процесс, включающий проверку и сводку статуса для обеспечения правильного развертывания","ar":"عملية النشر في مرحلة الاستضافة هي عملية تتضمن التحقق والملخص الإحصائي لضمان نشر صحيح"},"seo":{"title":{"en":"staging-deployment-operation: Automated Deployment Setup ...","zh":"预发布部署操作 Setup Guide","ja":"ステージングデプロイ操作ベストプラクティス - AIエージェント","ko":"스테이징 배포 운영 가이드 - AI Tools","es":"Guía de configuración de operaciones de despliegue de sta...","fr":"Guide de mise en place de l''opération de déploiement de s...","de":"Einrichtungsleitfaden für Staging-Deploy-Operationen mit ...","pt":"Guia de Configuração de Operação de Implantação em Stagin...","ru":"Настройка операции развертывания в стадии с помощью ИИ Аг...","ar":"دليل إعداد عملية النشر في مرحلة الاستضافة باستخدام أدوات ..."},"description":{"en":"Streamline your staging deployment workflow with our expert guide - learn how to validate, summarize, and automate your deployment operations today!","zh":"了解预发布部署操作的步骤和技术要求，包括验证检查和状态汇总","ja":"ステージングデプロイ操作の手順と技術要件を確認する - バリデーションチェックとステータスサマリー","ko":"스테이징 배포 운영의 단계와 기술 요구 사항을 확인하세요 - 유효성 검사 및 상태 요약","es":"Aprende a implementar operaciones de despliegue de staging de manera efectiva con nuestra guía paso a paso y mejora tus flujos de trabajo de CI/CD","fr":"Découvrez comment mettre en place des opérations de déploiement de staging de manière efficace avec notre guide étape par étape et améliorez vos flux de trav...","de":"Erfahren Sie, wie Sie Staging-Deploy-Operationen effektiv implementieren können, mit unserem Schritt-für-Schritt-Leitfaden und verbessern Sie Ihre CI/CD-Work...","pt":"Aprenda a configurar a operação de implantação em staging com validação e resumo de status para desenvolvedores","ru":"Узнайте, как настроить операцию развертывания в стадии с проверкой и сводкой статуса для разработчиков","ar":"تعرف على كيفية إعداد عملية النشر في مرحلة الاستضافة مع التحقق والملخص الإحصائي لل مطورين"},"definition":{"en":"staging-deployment-operation is a technical process that automates deployment workflows, confirming targets, running validation checks, and summarizing status and blockers.","zh":"预发布部署操作是一种自动化流程，确保代码正确部署到预发布环境","ja":"ステージングデプロイ操作は、コードをステージング環境に自動デプロイするためのプロセス","ko":"스테이징 배포 운영은 코드를 스테이징 환경에 자동으로 배포하는 프로세스","es":"La operación de despliegue de staging es un proceso que involucra la validación y prueba de aplicaciones en un entorno de staging antes de su despliegue en producción","fr":"L''opération de déploiement de staging est un processus qui implique la validation et le test d''applications dans un environnement de staging avant leur déploiement en production","de":"Die Staging-Deploy-Operation ist ein Prozess, der die Validierung und das Testen von Anwendungen in einer Staging-Umgebung vor ihrem Release in die Produktion beinhaltet","pt":"Operação de implantação em staging é uma sequência de etapas para validar e resumir o status de implantação","ru":"Операция развертывания в стадии - это последовательность шагов для проверки и сводки статуса развертывания","ar":"عملية النشر في مرحلة الاستضافة هي سلسلة من الخطوات للتحقق والملخص الإحصائي لنشر"},"features":{"en":["Follows documentation in `docs/STAGING_OPERATIONs.md` for standardized deployment operations","References CI deploy job in `.github/workflows/ci.yml` for expected deployment steps","Runs validation checks to ensure smooth staging deployment","Summarizes status and blockers for efficient issue resolution","Provides a quick start guide for rapid deployment setup","Outputs staging status summary and required follow-ups for informed decision-making"],"zh":["验证检查","状态汇总","CI deploy job 集成","多环境支持","自动化部署","GitHub Workflows 集成"],"ja":["バリデーションチェック","ステータスサマリー","CI デプロイジョブ統合","マルチ環境サポート","自動デプロイ","GitHub Workflows 統合"],"ko":["유효성 검사","상태 요약","CI 배포 작업 통합","다중 환경 지원","자동 배포","GitHub Workflows 통합"],"es":["Validación de objetivos de despliegue de staging","Ejecución de comprobaciones de validación","Resumen del estado y bloqueadores","Integración con flujos de trabajo de CI/CD","Uso de archivos de configuración como .github/workflows/ci.yml","Seguimiento de la documentación en docs/STAGING_OPERATIONs.md"],"fr":["Validation des objectifs de déploiement de staging","Exécution de contrôles de validation","Résumé de l''état et des bloqueurs","Intégration avec les flux de travail CI/CD","Utilisation de fichiers de configuration tels que .github/workflows/ci.yml","Suivi de la documentation dans docs/STAGING_OPERATIONs.md"],"de":["Validierung der Ziele für die Staging-Deploy-Operation","Ausführung von Validierungschecks","Zusammenfassung des Status und der Blockierungen","Integration mit CI/CD-Workflows","Verwendung von Konfigurationsdateien wie .github/workflows/ci.yml","Verfolgung der Dokumentation in docs/STAGING_OPERATIONs.md"],"pt":["Confirmação do alvo de implantação em staging","Execução de verificações de validação","Resumo de status e bloqueadores","Integração com CI deploy job em .github/workflows/ci.yml","Acesso a documentação em docs/STAGING_OPERATIONs.md"],"ru":["Подтверждение цели развертывания в стадии","Выполнение проверок валидации","Сводка статуса и блокировщиков","Интеграция с CI deploy job в .github/workflows/ci.yml","Доступ к документации в docs/STAGING_OPERATIONs.md"],"ar":["التأكد من هدف النشر في مرحلة الاستضافة","تشغيل عمليات التحقق","ملخص الحالة والمعوقات","التكامل مع وظيفة النشر CI في .github/workflows/ci.yml","الوصول إلى الوثائق في docs/STAGING_OPERATIONs.md"]},"keywords":{"en":["how to use staging-deployment-operation","staging-deployment-operation setup guide","automated deployment workflows","CI deploy job configuration","staging deployment best practices","what is staging-deployment-operation","staging-deployment-operation vs manual deployment","staging-deployment-operation install and setup","staging deployment operation tutorial"],"zh":["预发布部署","自动化部署","CI deploy job","GitHub Workflows","代码部署","预发布环境","AI工具","预发布部署操作","代码验证"],"ja":["ステージングデプロイ","自動デプロイ","CI デプロイジョブ","GitHub Workflows","コードデプロイ","ステージング環境","AIエージェント","ステージングデプロイ操作","コードバリデーション"],"ko":["스테이징 배포","자동 배포","CI 배포 작업","GitHub Workflows","コード 배포","스테이징 환경","AI Tools","스테이징 배포 운영","코드 유효성 검사"],"es":["despliegue de staging","operaciones de despliegue","validación de aplicaciones","pruebas de aplicaciones","CI/CD","herramientas de AI","desarrollo de software","implementación de staging","guía de configuración"],"fr":["déploiement de staging","opérations de déploiement","validation d''applications","tests d''applications","CI/CD","outils d''AI","développement de logiciels","mise en place de staging","guide de configuration"],"de":["Staging-Deploy","Deploy-Operationen","Validierung von Anwendungen","Tests von Anwendungen","CI/CD","KI-Tools","Software-Entwicklung","Staging-Implementierung","Einrichtungsleitfaden"],"pt":["operação de implantação em staging","ferramentas de inteligência artificial para desenvolvedores","validação de implantação","resumo de status de implantação","CI deploy job","github workflows","documentação de operação de implantação"],"ru":["операция развертывания в стадии","ИИ Агенты для разработчиков","проверка развертывания","сводка статуса развертывания","CI deploy job","github workflows","документация операции развертывания"],"ar":["عملية النشر في مرحلة الاستضافة","أدوات الذكاء الاصطناعي للمطورين","التحقق من النشر","ملخص حالة النشر","وظيفة النشر CI","github workflows","وثائق عملية النشر"]}},"owner":"Jeduardo622","repo":"AllIincompassing","repoPath":"Jeduardo622/AllIincompassing","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.477Z","topics":[],"category":"community","skillMd":{"name":"staging-deployment-operation","description":"Deploy and validate staging environment workflows. Use when the user mentions staging deploys, staging validation, or environment checks.","bodyPreview":"# Staging Deployment Operation\n\n## Quick Start\n\n1. Confirm staging deployment target.\n2. Run validation checks.\n3. Summarize status and blockers.\n\n## Steps\n\n- Follow `docs/STAGING_OPERATIONs.md`.\n- Reference CI deploy job in `.github/workflows/ci.yml` for expected steps.\n\n## Output\n\n- Staging status summary and required follow-ups.","body":"# Staging Deployment Operation\n\n## Quick Start\n\n1. Confirm staging deployment target.\n2. Run valida