INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jeduardo622/AllIincompassing/staging-deployment-operation', 'staging-deployment-operation', 'Jeduardo622', 'AllIincompassing', 'community', 'staging-deployment-operation Jeduardo622 AllIincompassing community The staging-deployment-operation skill automates deployment workflows for developers, providing a quick start guide and validation checks for seamless staging deployment operations. 预发布部署操作是一种确保代码部署到预发布环境的过程，包括验证检查和状态汇总 ステージングデプロイ操作は、コードをステージング環境にデプロイするためのプロセスです - バリデーションチェックとステータスサマリー 스테이징 배포 운영은 코드를 스테이징 환경에 배포하는 프로세스입니다 - 유효성 검사 및 상태 요약 La operación de despliegue de staging es un proceso crucial para validar y probar aplicaciones antes de su lanzamiento. Nuestra guía cubre los pasos clave para una implementación exitosa. L''opération de déploiement de staging est un processus crucial pour valider et tester des applications avant leur lancement. Notre guide couvre les étapes clés pour une mise en place réussie. Die Staging-Deploy-Operation ist ein entscheidender Prozess, um Anwendungen vor ihrem Release zu validieren und zu testen. Unser Leitfaden behandelt die wichtigsten Schritte für eine erfolgreiche Implementierung. A operação de implantação em staging é um processo que envolve a validação e o resumo de status para garantir a implantação correta Операция развертывания в стадии - это процесс, включающий проверку и сводку статуса для обеспечения правильного развертывания عملية النشر في مرحلة الاستضافة هي عملية تتضمن التحقق والملخص الإحصائي لضمان نشر صحيح how to use staging-deployment-operation staging-deployment-operation setup guide automated deployment workflows CI deploy job configuration staging deployment best practices what is staging-deployment-operation staging-deployment-operation vs manual deployment staging-deployment-operation install and setup staging deployment operation tutorial 预发布部署 自动化部署 CI deploy job GitHub Workflows 代码部署 预发布环境 AI工具 预发布部署操作 代码验证 Follows documentation in `docs/STAGING_OPERATIONs.md` for standardized deployment operations References CI deploy job in `.github/workflows/ci.yml` for expected deployment steps Runs validation checks to ensure smooth staging deployment Summarizes status and blockers for efficient issue resolution Provides a quick start guide for rapid deployment setup Outputs staging status summary and required follow-ups for informed decision-making staging-deployment-operation is a technical process that automates deployment workflows, confirming targets, running validation checks, and summarizing status and blockers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sooom1627/linkcache/expo-deployment', 'community', 'sooom1627', 'linkcache', 'sooom1627/linkcache', 'expo-deployment', 0, 0, 38, '2026-03-08T01:57:15.481Z', '2026-03-08T02:09:56.011Z', '81b700b0cfe12ac175d4f64d052464db5f7ddc40e8a29cba52c642d87acee0dd', '{"id":"sooom1627/linkcache/expo-deployment","name":"expo-deployment","description":{"en":"The expo-deployment skill enables developers to deploy Expo applications across all platforms using Expo Application Services (EAS). It benefits developers by simplifying the deployment process.","zh":"Expo 部署技能涵盖使用 EAS 在所有平台上部署 Expo 应用程序","ja":"Expo デプロイメントスキルは、EAS を使用してすべてのプラットフォームで Expo アプリケーションをデプロイすることをカバーしています","ko":"Expo 배포 스킬은 EAS를 사용하여 모든 플랫폼에서 Expo 애플리케이션을 배포하는 것을 다룹니다","es":"El skill de expo-deployment te permite desplegar aplicaciones Expo en todas las plataformas con EAS. Consulta nuestros recursos para más información.","fr":"Le skill de expo-deployment vous permet de déployer des applications Expo sur toutes les plateformes avec EAS. Consultez nos ressources pour plus d''informations.","de":"Das expo-deployment-Skill ermöglicht es Ihnen, Expo-Anwendungen auf allen Plattformen mit EAS bereitzustellen. Besuchen Sie unsere Ressourcen für weitere Informationen.","pt":"O expo-deployment é uma habilidade que cobre a implantação de aplicativos Expo em todas as plataformas usando EAS","ru":"ИИ Агент expo-deployment - это навык, который охватывает развертывание приложений Expo на всех платформах с помощью EAS","ar":"expo-deployment هو مهارة تغطي نشر تطبيقات Expo على جميع المنصات باستخدام EAS"},"seo":{"title":{"en":"expo-deployment: EAS Deployment Setup Guide | AI Agent Skill","zh":"Expo 部署最佳实践 - AIエージェント","ja":"Expo デプロイメントガイド - AIエージェント","ko":"Expo 배포 설정 가이드 - AI 에이전트","es":"Guía de configuración de expo-deployment para aplicacione...","fr":"Déploiement d''applications Expo avec EAS - Guide de démar...","de":"Expo-Deployment-Setup für mobile Anwendungen mit EAS","pt":"Guia de Configuração do Expo-Deployment","ru":"Настройка ИИ Агента Expo-Deployment","ar":"دليل إعداد expo-deployment"},"description":{"en":"Streamline your Expo app deployment with EAS. Learn how to automate deployments, submit to TestFlight, and optimize App Store metadata with our expert guide.","zh":"了解 Expo 应用程序的自动化部署和 PR 预览，使用 EAS 提高效率","ja":"Expo アプリケーションの自動化デプロイと PR プレビューを使用して効率を高める","ko":"Expo 애플리케이션의 자동화 배포 및 PR预览를 사용하여 효율성을 높여보세요","es":"Aprende a desplegar aplicaciones Expo en todas las plataformas con EAS. Consulta nuestros recursos para flujos de trabajo de CI/CD y optimización de metadato...","fr":"Découvrez comment déployer des applications Expo sur toutes les plateformes avec EAS. Consultez nos ressources pour les flux de travail CI/CD et l''optimisati...","de":"Erfahren Sie, wie Sie Expo-Anwendungen auf allen Plattformen mit EAS bereitstellen. Besuchen Sie unsere Ressourcen für CI/CD-Workflows und App-Store-Metadate...","pt":"Aprenda a configurar o expo-deployment para implantar aplicativos Expo em todas as plataformas com EAS","ru":"Узнайте, как настроить expo-deployment для развертывания приложений Expo на всех платформах с помощью EAS","ar":"تعرف على كيفية إعداد expo-deployment لنشر تطبيقات Expo على جميع المنصات باستخدام EAS"},"definition":{"en":"expo-deployment is a skill that covers deploying Expo applications using EAS, including automated deployments, PR previews, and submissions to TestFlight and the App Store.","zh":"Expo 部署是使用 EAS 在所有平台上自动化部署 Expo 应用程序的过程","ja":"Expo デプロイメントとは、EAS を使用してすべてのプラットフォームで Expo アプリケーションを自動化デプロイするプロセスです","ko":"Expo 배포는 EAS를 사용하여 모든 플랫폼에서 Expo 애플리케이션을 자동화 배포하는 과정입니다","es":"Expo-deployment es un skill que permite desplegar aplicaciones Expo en todas las plataformas con EAS","fr":"Expo-deployment est un skill qui permet de déployer des applications Expo sur toutes les plateformes avec EAS","de":"Expo-Deployment ist ein Skill, der es ermöglicht, Expo-Anwendungen auf allen Plattformen mit EAS bereitzustellen","pt":"O que é expo-deployment? É uma habilidade para implantar aplicativos Expo em todas as plataformas","ru":"Что такое expo-deployment? Это навык для развертывания приложений Expo на всех платформах","ar":"ما هو expo-deployment? هو مهارة لنشر تطبيقات Expo على جميع المنصات"},"features":{"en":["Automates deployments using EAS (Expo Application Services)","Supports CI/CD workflows for automated deployments and PR previews","Enables submissions to TestFlight for iOS beta testing","Manages App Store metadata for ASO optimization","Facilitates submissions to the Google Play Store for Android builds"],"zh":["使用 EAS 自动化部署 Expo 应用程序","支持 CI/CD 工作流和 PR 预览","提交 iOS 构建到 TestFlight 进行 beta 测试","管理 App Store 元数据和 ASO 优化","提交 Android 构建到 Google Play"],"ja":["EAS を使用して Expo アプリケーションを自動化デプロイする","CI/CD ワークフローと PR プレビューをサポートする","iOS ビルドを TestFlight に提出してベータテストを行う","App Store メタデータと ASO 最適化を管理する","Android ビルドを Google Play に提出する"],"ko":["EAS를 사용하여 Expo 애플리케이션을 자동화 배포하는","CI/CD 워크플ロー와 PR 프리뷰를 지원하는","iOS 빌드를 TestFlight에 제출하여 베타 테스트를 수행하는","App Store 메타데이터와 ASO 최적화를 관리하는","Android 빌드를 Google Play에 제출하는"],"es":["Despliegue de aplicaciones Expo en todas las plataformas con EAS","Flujos de trabajo de CI/CD para despliegues automatizados y previsualizaciones de PR","Optimización de metadatos de la App Store y ASO","Envío de builds de iOS a TestFlight para pruebas beta","Envío de builds de Android a la Play Store"],"fr":["Déploiement d''applications Expo sur toutes les plateformes avec EAS","Flux de travail CI/CD pour des déploiements automatisés et des prévisualisations de PR","Optimisation des métadonnées de l''App Store et ASO","Envoi de builds iOS à TestFlight pour des tests bêta","Envoi de builds Android à la Play Store"],"de":["Bereitstellung von Expo-Anwendungen auf allen Plattformen mit EAS","CI/CD-Workflows für automatisierte Bereitstellungen und PR-Vorschauen","Optimierung von App-Store-Metadaten und ASO","Übermittlung von iOS-Builds an TestFlight für Betatests","Übermittlung von Android-Builds an die Play Store"],"pt":["Implantação de aplicativos Expo em todas as plataformas com EAS","CI/CD workflows para implantações automatizadas e pré-visualizações de PR","Envio de builds iOS para TestFlight para teste beta","Gerenciamento de metadados da App Store e otimização do ASO","Envio de builds Android para a Play Store"],"ru":["Развертывание приложений Expo на всех платформах с помощью EAS","CI/CD workflows для автоматизированных развертываний и предварительных просмотров PR","Отправка сборок iOS в TestFlight для бета-тестирования","Управление метаданными App Store и оптимизация ASO","Отправка сборок Android в Play Store"],"ar":["نشر تطبيقات Expo على جميع المنصات باستخدام EAS","CI/CD workflows للنشر التلقائي وتحديثات(PR) المسبقة","إرسال بناء iOS إلى TestFlight لاختبار البيتا","إدارة بيانات متجر التطبيقات وتحسين ASO","إرسال بناء Android إلى متجر Play"]},"keywords":{"en":["how to use expo-deployment","expo-deployment setup guide","EAS deployment tutorial","expo-deployment vs traditional deployment","expo-deployment install","automating deployments with EAS","expo-deployment best practices","what is expo-deployment","expo-deployment documentation"],"zh":["Expo 部署","EAS","CI/CD","PR 预览","TestFlight","App Store","ASO 优化","Google Play","AIエージェント"],"ja":["Expo デプロイメント","EAS","CI/CD","PR プレビュー","TestFlight","App Store","ASO 最適化","Google Play","AIエージェント"],"ko":["Expo 배포","EAS","CI/CD","PR 프리뷰","TestFlight","App Store","ASO 최적화","Google Play","AI 에이전트"],"es":["expo-deployment","EAS","despliegue de aplicaciones móviles","CI/CD","TestFlight","App Store","Play Store","ASO","optimización de metadatos"],"fr":["expo-deployment","EAS","déploiement d''applications mobiles","CI/CD","TestFlight","App Store","Play Store","ASO","optimisation des métadonnées"],"de":["expo-deployment","EAS","Bereitstellung von mobilen Anwendungen","CI/CD","TestFlight","App Store","Play Store","ASO","Optimierung von Metadaten"],"pt":["expo-deployment","implantação de aplicativos Expo","EAS","CI/CD workflows","TestFlight","App Store","ASO","Play Store"],"ru":["expo-deployment","развертывание приложений Expo","EAS","CI/CD workflows","TestFlight","App Store","ASO","Play Store","ИИ Агенты"],"ar":["expo-deployment","نشر تطبيقات Expo","EAS","CI/CD workflows","TestFlight","متجر التطبيقات","ASO","متجر Play","أدوات الذكاء الاصطناعي"]}},"owner":"sooom1627","repo":"linkcache","repoPath":"sooom1627/linkcache","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.481Z","topics":[],"category":"community","skillMd":{"name":"expo-deployment","description":"Deploying Expo apps to iOS App Store, Android Play Store, web hosting, and API routes","version":"1.0.0","bodyPreview":"# Deployment\n\nThis skill covers deploying Expo applications across all platforms using EAS (Expo Application Services).\n\n## References\n\nConsult these resources as needed:\n\n- ./references/workflows.md -- CI/CD workflows for automated deployments and PR previews\n- ./references/testflight.md -- Submitting iOS builds to TestFlight for beta testing\n- ./references/app-store-metadata.md -- Managing App Store metadata and ASO optimization\n- ./references/play-store.md -- Submitting Android builds to Goog","body":"# Deployment\n\nThis skill covers deploying Expo applications across all platforms using EAS (Expo Application Services).\n\n## References\n\nConsult these resources as needed:\n\n- ./references/workflows.md -- CI/CD workflows for automated deployments and PR previews\n- ./references/testflight.md -- Submitting iOS builds to TestFlight for beta testing\n- ./references/app-store-metadata.md -- Managing App Store metadata and ASO optimization\n- ./references/play-store.md -- Submitting Android builds to Google Play Store\n- ./references/ios-app-store.md -- iOS App Store submission and review process\n\n## Quick Start\n\n### Install EAS CLI\n\n```bash\nnpm install -g eas-cli\neas login\n```\n\n### Initialize EAS\n\n```bash\nnpx eas-cli@latest init\n```\n\nThis creates `eas.json` with build profiles.\n\n## Build Commands\n\n### Production Builds\n\n```bash\n# iOS App Store build\nnpx eas-cli@latest build -p ios --profile production\n\n# Android Play Store build\nnpx eas-cli@latest build -p android --profile production\n\n# Both platforms\nnpx eas-cli@latest build --profile production\n```\n\n### Submit to Stores\n\n```bash\n# iOS: Build and submit to App Store Connect\nnpx eas-cli@latest build -p ios --profile production --submit\n\n# Android: Build and submit to Play Store\nnpx eas-cli@latest build -p android --profile production --submit\n\n# Shortcut for iOS TestFlight\nnpx testflight\n```\n\n## Web Deployment\n\nDeploy web apps using EAS Hosting:\n\n```bash\n# Deploy to production\nnpx expo export -p web\nnpx eas-cli@latest deploy --prod\n\n# Deploy PR preview\nnpx eas-cli@latest deploy\n```\n\n## EAS Configuration\n\nStandard `eas.json` for production deployments:\n\n```json\n{\n  \"cli\": {\n    \"version\": \">= 16.0.1\",\n    \"appVersionSource\": \"remote\"\n  },\n  \"build\": {\n    \"production\": {\n      \"autoIncrement\": true,\n      \"ios\": {\n        \"resourceClass\": \"m-medium\"\n      }\n    },\n    \"development\": {\n      \"developmentClient\": true,\n      \"distribution\": \"internal\"\n    }\n  },\n  \"submit\": {\n    \"production\": {\n      \"ios\": {\n        \"appleId\": \"your@email.com\",\n        \"ascAppId\": \"1234567890\"\n      },\n      \"android\": {\n        \"serviceAccountKeyPath\": \"./google-service-account.json\",\n        \"track\": \"internal\"\n      }\n    }\n  }\n}\n```\n\n## Platform-Specific Guides\n\n### iOS\n\n- Use `npx testflight` for quick TestFlight submissions\n- Configure Apple credentials via `eas credentials`\n- See ./reference/testflight.md for credential setup\n- See ./reference/ios-app-store.md for App Store submission\n\n### Android\n\n- Set up Google Play Console service account\n- Configure tracks: internal → closed → open → production\n- See ./reference/play-store.md for detailed setup\n\n### Web\n\n- EAS Hosting provides preview URLs for PRs\n- Production deploys to your custom domain\n- See ./reference/workflows.md for CI/CD automation\n\n## Automated Deployments\n\nUse EAS Workflows for CI/CD:\n\n```yaml\n# .eas/workflows/release.yml\nname: Release\n\non:\n  push:\n    branches: [main]\n\njobs:\n  build-ios:\n    type: build\n    params:\n      platform: ios\n      profile: production\n\n  submit-ios:\n    type: submit\n    needs: [build-ios]\n    params:\n      platform: ios\n      profile: production\n```\n\nSee ./reference/workflows.md for more workflow examples.\n\n## Version Management\n\nEAS manages version numbers automatically with `appVersionSource: \"remote\"`:\n\n```bash\n# Check current versions\neas build:version:get\n\n# Manually set version\neas build:version:set -p ios --build-number 42\n```\n\n## Monitoring\n\n```bash\n# List recent builds\neas build:list\n\n# Check build status\neas build:view\n\n# View submission status\neas submit:list\n```\n"},"lastSynced":"2026-03-08T02:09:56.011Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile Agents requiring streamlined Expo application deployment across all platforms using Expo Application Services (EAS).","zh":"适用于需要使用Expo Application Services (EAS)跨所有平台简化Expo应用程序部署的移动代理。","ja":"Expo Application Services (EAS)を使用してすべてのプラットフォームでExpoアプリケーションのデプロイを簡素化する必要があるモバイルエージェントに最適です。","ko":"Expo Application Services (EAS)를 사용하여 모든 플랫폼에서 Expo 애플리케이션 배포를 간소화해야 하는 모바일 에이전트에 적합합니다.","es":"Ideal para Agentes Móviles que requieren una implementación de aplicaciones Expo optimizada en todas las plataformas utilizando los Servicios de Aplicación Expo (EAS).","fr":"Idéal pour les agents mobiles nécessitant un déploiement d''applications Expo rationalisé sur toutes les plateformes en utilisant les Services d''Application Expo (EAS).","de":"Ideal für Mobile Agents, die eine optimierte Expo-Anwendungsbereitstellung auf allen Plattformen mit Expo Application Services (EAS) benötigen.","pt":"Ideal para Agentes Móveis que exigem implantação de aplicativos Expo simplificada em todas as plataformas usando os Serviços de Aplicativos Expo (EAS).","ru":"Идеально для Мобильных Агентов, требующих упрощенную установку приложений Expo на все платформы с помощью Сервисов Приложений Expo (EAS).","ar":"مثالية لعميل المحمول الذين يتطلبون نشر تطبيقات Expo مبسط عبر جميع المنصات باستخدام خدمات تطبيقات Expo (EAS)."},"recommendation":{"en":"Empowers agents to automate deployments and PR previews using CI/CD workflows, submit iOS builds to TestFlight for beta testing, and manage App Store metadata for ASO optimization, all while leveraging EAS for seamless cross-platform deployment.","zh":"赋予代理人自动化部署和PR预览使用CI/CD工作流、将iOS构建提交到TestFlight进行beta测试，并管理App Store元数据以进行ASO优化的能力，同时利用EAS进行无缝的跨平台部署。","ja":"CI/CDワークフローを使用した自動化されたデプロイとPRプレビュー、TestFlightへのiOSビルドの提出、ASO最適化のためのApp Storeメタデータの管理などを行い、EASを使用したシームレスなクロスプラットフォームデプロイを可能にします。","ko":"CI/CD 워크플로를 사용한 자동화된 배포 및 PR预览, TestFlight에 대한 iOS 빌드 제출, ASO 최적화를 위한 App Store 메타데이터 관리 등과 같은 기능을 제공하며, EAS를 사용한 무결점의 크로스 플랫폼 배포를 가능하게 합니다.","es":"Permite a los agentes automatizar implementaciones y vistas previas de PR utilizando flujos de trabajo de CI/CD, enviar compilaciones de iOS a TestFlight para pruebas beta y administrar metadatos de la App Store para la optimización de ASO, todo mientras aprovecha EAS para una implementación transversal sin problemas.","fr":"Permet aux agents d''automatiser les déploiements et les aperçus de PR en utilisant des flux de travail CI/CD, de soumettre des builds iOS à TestFlight pour des tests bêta et de gérer les métadonnées de l''App Store pour l''optimisation ASO, le tout en exploitant EAS pour un déploiement transversal sans accroc.","de":"Ermächtigt Agenten, Bereitstellungen und PR-Vorschauen mithilfe von CI/CD-Workflows zu automatisieren, iOS-Builds an TestFlight für Betatests zu senden und App-Store-Metadaten für ASO-Optimierung zu verwalten, alles bei gleichzeitiger Nutzung von EAS für eine nahtlose Bereitstellung über alle Plattformen hinweg.","pt":"Habilita os agentes a automatizar implantações e visualizações de PR usando fluxos de trabalho de CI/CD, enviar compilações do iOS para o TestFlight para testes beta e gerenciar metadados da App Store para otimização do ASO, tudo isso aproveitando os EAS para implantação cross-plataforma sem interrupções.","ru":"Наделяет агентов возможностью автоматизировать развертывания и предварительные просмотры PR с помощью рабочих процессов CI/CD, отправлять сборки iOS в TestFlight для бета-тестирования и управлять метаданными App Store для оптимизации ASO, все это при помощи EAS для бесперебойной cross-платформенной развертки.","ar":"تمكّن الوكلاء من تutomation نشر الإصدارات ومعاينة PR باستخدام سير عمل CI/CD، وإرسال عمليات بناء iOS إلى TestFlight للاختبار التجريبي وإدارة بيانات App Store من أجل تحسين ASO، كل ذلك مع الاستفادة من EAS لنشر متوافق عبر المنصات."},"useCases":{"en":["Automating Expo application deployments across iOS and Android platforms","Submitting builds to TestFlight for beta testing and managing App Store metadata","Configuring CI/CD workflows for automated deployments and PR previews","Optimizing App Store presence through ASO metadata management"],"zh":["自动化Expo应用程序在iOS和Android平台上的部署","将构建提交到TestFlight进行beta测试并管理App Store元数据","配置CI/CD工作流以实现自动化部署和PR预览","通过ASO元数据管理优化App Store存在感"],"ja":["iOSおよびAndroidプラットフォームでExpoアプリケーションのデプロイを自動化する","TestFlightへのビルド提出およびApp Storeメタデータの管理","自動化されたデプロイおよびPRプレビューのためのCI/CDワークフローの構成","ASOメタデータ管理によるApp Store存在感の最適化"],"ko":["iOS와 Android 플랫폼에서 Expo 애플리케이션 배포를 자동화하는 것","TestFlight에 빌드를 제출하고 App Store 메타데이터를 관리하는 것","자동화된 배포 및 PR预览을 위한 CI/CD 워크플로의 구성","ASO 메타데이터 관리를 통해 App Store 존재감을 최적화하는 것"],"es":["Automatizar implementaciones de aplicaciones Expo en plataformas iOS y Android","Enviar compilaciones a TestFlight para pruebas beta y administrar metadatos de la App Store","Configurar flujos de trabajo de CI/CD para implementaciones y vistas previas automatizadas","Optimizar la presencia en la App Store a través de la administración de metadatos ASO"],"fr":["Automatiser les déploiements d''applications Expo sur les plateformes iOS et Android","Soumettre des builds à TestFlight pour des tests bêta et gérer les métadonnées de l''App Store","Configurer des flux de travail CI/CD pour des déploiements et des aperçus automatisés","Optimiser la présence sur l''App Store via la gestion des métadonnées ASO"],"de":["Automatisieren von Expo-Anwendungsbereitstellungen auf iOS- und Android-Plattformen","Senden von iOS-Builds an TestFlight für Betatests und Verwalten von App-Store-Metadaten","Konfigurieren von CI/CD-Workflows für automatisierte Bereitstellungen und PR-Vorschauen","Optimieren des App-Store-Auftritts durch Verwalten von ASO-Metadaten"],"pt":["Automatizar implantações de aplicativos Expo em plataformas iOS e Android","Enviar compilações para o TestFlight para testes beta e gerenciar metadados da App Store","Configurar fluxos de trabalho de CI/CD para implantações automatizadas e visualizações de PR","Otimizar presença na App Store por meio da gestão de metadados ASO"],"ru":["Автоматизировать развертывания приложений Expo на платформах iOS и Android","Отправлять сборки в TestFlight для бета-тестирования и управлять метаданными App Store","Настроить рабочие процессы CI/CD для автоматизированных развертываний и предварительных просмотров PR","Оптимизировать присутствие в App Store за счет управления метаданными ASO"],"ar":["توسيط نشر تطبيقات Expo عبر منصات iOS و Android","إرسال عمليات بناء إلى TestFlight للاختبار التجريبي وإدارة بيانات App Store","تكوين سير عمل CI/CD لنشر تلقائي ومعاينة PR","تحسين وجود تطبيق في App Store من خلال إدارة بيانات ASO"]},"limitations":{"en":["Requires Expo Application Services (EAS) setup","Limited to Expo applications","Needs access to App Store and Google Play Store for submission"],"zh":["需要设置Expo Application Services (EAS)","仅限Expo应用程序","需要访问App Store和Google Play Store以进行提交"],"ja":["Expo Application Services (EAS)の設定が必要","Expoアプリケーションに限定される","提出のためのApp StoreおよびGoogle Play Storeへのアクセスが必要"],"ko":["Expo Application Services (EAS) 설정이 필요함","Expo 애플리케이션에만 제한됨","제출을 위한 App Store 및 Google Play Store에 대한 액세스가 필요함"],"es":["Requiere configuración de Servicios de Aplicación Expo (EAS)","Limitado a aplicaciones Expo","Necesita acceso a la App Store y Google Play Store para la presentación"],"fr":["Nécessite une configuration des Services d''Application Expo (EAS)","Limité aux applications Expo","Nécessite un accès à l''App Store et Google Play Store pour la soumission"],"de":["Benötigt eine Einrichtung von Expo Application Services (EAS)","Begrenzt auf Expo-Anwendungen","Benötigt Zugriff auf den App Store und Google Play Store für die Einreichung"],"pt":["Exige configuração dos Serviços de Aplicativos Expo (EAS)","Limitado a aplicativos Expo","Necessita acesso à App Store e Google Play Store para envio"],"ru":["Требует настройки Сервисов Приложений Expo (EAS)","Ограничен приложениями Expo","Требует доступа к App Store и Google Play Store для отправки"],"ar":["يتطلب إعداد خدمات تطبيقات Expo (EAS)","محدود بتطبيقات Expo","يحتاج إلى وصول إلى App Store و Google Play Store للنشر"]},"version":4},"contentHash":"81b700b0cfe12ac175d4f64d052464db5f7ddc40e8a29cba52c642d87acee0dd","qualityScore":38}');
