INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sooom1627/linkcache/expo-deployment', 'expo-deployment', 'sooom1627', 'linkcache', 'community', 'expo-deployment sooom1627 linkcache community The expo-deployment skill enables developers to deploy Expo applications across all platforms using Expo Application Services (EAS). It benefits developers by simplifying the deployment process. Expo 部署技能涵盖使用 EAS 在所有平台上部署 Expo 应用程序 Expo デプロイメントスキルは、EAS を使用してすべてのプラットフォームで Expo アプリケーションをデプロイすることをカバーしています Expo 배포 스킬은 EAS를 사용하여 모든 플랫폼에서 Expo 애플리케이션을 배포하는 것을 다룹니다 El skill de expo-deployment te permite desplegar aplicaciones Expo en todas las plataformas con EAS. Consulta nuestros recursos para más información. Le skill de expo-deployment vous permet de déployer des applications Expo sur toutes les plateformes avec EAS. Consultez nos ressources pour plus d''informations. Das expo-deployment-Skill ermöglicht es Ihnen, Expo-Anwendungen auf allen Plattformen mit EAS bereitzustellen. Besuchen Sie unsere Ressourcen für weitere Informationen. O expo-deployment é uma habilidade que cobre a implantação de aplicativos Expo em todas as plataformas usando EAS ИИ Агент expo-deployment - это навык, который охватывает развертывание приложений Expo на всех платформах с помощью EAS expo-deployment هو مهارة تغطي نشر تطبيقات Expo على جميع المنصات باستخدام EAS how to use expo-deployment expo-deployment setup guide EAS deployment tutorial expo-deployment vs traditional deployment expo-deployment install automating deployments with EAS expo-deployment best practices what is expo-deployment expo-deployment documentation Expo 部署 EAS CI/CD PR 预览 TestFlight App Store ASO 优化 Google Play AIエージェント Automates deployments using EAS (Expo Application Services) Supports CI/CD workflows for automated deployments and PR previews Enables submissions to TestFlight for iOS beta testing Manages App Store metadata for ASO optimization Facilitates submissions to the Google Play Store for Android builds expo-deployment is a skill that covers deploying Expo applications using EAS, including automated deployments, PR previews, and submissions to TestFlight and the App Store.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LucasSantana-Dev/LukBot/music-queue-player', 'community', 'LucasSantana-Dev', 'LukBot', 'LucasSantana-Dev/LukBot', 'music-queue-player', 0, 0, 38, '2026-03-08T01:57:15.475Z', '2026-03-08T02:10:08.549Z', 'c5d93f643473aa8c900c756ff8ab22d025c5aac4d4fabf2b3e55afceba49fbe2', '{"id":"LucasSantana-Dev/LukBot/music-queue-player","name":"music-queue-player","description":{"en":"The music-queue-player skill is a Discord bot developed with Typescript, providing moderation and music tools for efficient server management. It benefits developers and server administrators seeking to streamline music playback and queue management.","zh":"music-queue-player 是一个使用 TypeScript 开发的 Discord 机器人，提供音乐和队列管理工具","ja":"music-queue-player は、TypeScript で開発された Discord ボットであり、音楽とキュー管理ツールを提供します","ko":"music-queue-player는 TypeScript로 개발된 디스코드 봇으로 음악 및 큐 관리 도구를 제공합니다","es":"Music-queue-player es un bot de Discord creado con Typescript que ofrece herramientas de moderación y música","fr":"Music-queue-player est un bot Discord créé avec Typescript qui propose des outils de modération et de musique","de":"Music-queue-player ist ein Discord-Bot, der mit Typescript erstellt wurde und Moderations- und Musiktools bietet","pt":"O music-queue-player é um bot de música e moderação para Discord desenvolvido em Typescript, oferecendo ferramentas de música e controle","ru":"Music-queue-player - это бот для музыки и модерации в Discord, созданный на Typescript, предлагающий музыкальные и контролирующие инструменты","ar":"music-queue-player هو بوت موسيقي وتنظيمي لديسكورد مصمم بلغة Typescript، يقدم أدوات موسيقية ومراقبة"},"seo":{"title":{"en":"music-queue-player: Discord Bot Setup Guide | AI Agent Skill","zh":"music-queue-player 入门指南：Discord 机器人音乐工具","ja":"music-queue-player のセットアップガイド：Discord ボットの音楽ツール","ko":"music-queue-player 시작하기: 디스코드 봇 음악 도구","es":"Guía de configuración de music-queue-player para Discord","fr":"Configurer music-queue-player pour Discord : Guide étape ...","de":"Music-Queue-Player für Discord einrichten: Eine Anleitung","pt":"Guia de Configuração do music-queue-player: Ferramentas d...","ru":"Настройка music-queue-player: Лучшие Практики для Музыки ...","ar":"دليل إعداد music-queue-player: أدوات الموسيقى والتحكم في ..."},"description":{"en":"Discover how to use music-queue-player, a Discord bot built with Typescript, to manage music and moderation tools - learn more and get started today!","zh":"了解 music-queue-player 的功能和特点，包括 Discord 机器人音乐工具和队列管理","ja":"music-queue-player の機能と特徴を紹介します。Discord ボットの音楽ツールとキュー管理をご覧ください","ko":"music-queue-player의 기능과 특징을 알아보세요. 디스코드 봇 음악 도구와 큐 관리를 지원합니다","es":"Aprende a configurar music-queue-player para Discord con Typescript y herramientas de moderación y música","fr":"Découvrez comment configurer music-queue-player pour Discord avec Typescript et des outils de modération et de musique","de":"Erfahren Sie, wie Sie music-queue-player für Discord mit Typescript und Moderations- und Musiktools einrichten","pt":"Aprenda a configurar o music-queue-player, um bot de música e moderação para Discord feito com Typescript, e descubra suas funcionalidades","ru":"Узнайте, как настроить music-queue-player, бота для музыки и модерации в Discord, созданного на Typescript, и его возможности","ar":"إكتشف كيفية إعداد music-queue-player، بوت موسيقي وتنظيمي لديسكورد مصمم بلغة Typescript، واكتشف ميزاته"},"definition":{"en":"music-queue-player is a Typescript-based Discord bot that offers music and moderation tools, enabling features like play, queue, skip, pause, and volume control.","zh":"music-queue-player 是一个 Discord 机器人，用于管理音乐和队列","ja":"music-queue-player は、音楽とキューを管理する Discord ボットです","ko":"music-queue-player는 음악과 큐를 관리하는 디스코드 봇입니다","es":"Music-queue-player es un bot de Discord que permite la reproducción de música y la gestión de colas","fr":"Music-queue-player est un bot Discord qui permet la lecture de musique et la gestion de files d''attente","de":"Music-queue-player ist ein Discord-Bot, der die Wiedergabe von Musik und die Verwaltung von Warteschlangen ermöglicht","pt":"O music-queue-player é um bot de Discord que fornece ferramentas de música e moderação, incluindo reprodução e controle de filas","ru":"Music-queue-player - это бот для Discord, который предоставляет музыкальные и модерационные инструменты, включая воспроизведение и контроль очередей","ar":"music-queue-player هو بوت ديسكورد يقدم أدوات موسيقية وتنظيمية، بما في ذلك تشغيل ومراقبة الطوابير"},"features":{"en":["Utilizes discord-player for player access and management","Supports play, queue, skip, pause, and volume control via specific commands","Enables search functionality via player.search(query, { requestedBy })","Provides autoplay, repeat, and shuffle features for enhanced music playback","Manages player lifecycle, errors, and extractors for seamless performance"],"zh":["使用 discord-player 库管理音乐和队列","支持播放、暂停、跳过和重复播放","提供队列管理和错误处理功能","使用 TypeScript 开发，确保代码的可维护性和安全性","支持多种音乐来源和搜索功能"],"ja":["discord-player ライブラリを使用して音楽とキューを管理","再生、停止、スキップ、繰り返し再生をサポート","キュー管理とエラー処理機能を提供","TypeScript で開発されており、コードの保守性とセキュリティを確保","複数の音楽ソースと検索機能をサポート"],"ko":["discord-player 라이브러리를 사용하여 음악과 큐를 관리","재생, 일시정지, 스킵, 반복재생을 지원","큐 관리와 에러 처리 기능을 제공","TypeScript로 개발되어 코드의 유지보수성과 보안성을 đảm보","다양한 음악 소스와 검색 기능을 지원"],"es":["Reproducción de música con Typescript","Herramientas de moderación para Discord","Gestión de colas con `useMainPlayer()`","Búsqueda de música con `player.search()`","Control de volumen y reproducción automática"],"fr":["Lecture de musique avec Typescript","Outils de modération pour Discord","Gestion de files d''attente avec `useMainPlayer()`","Recherche de musique avec `player.search()`","Contrôle du volume et de la lecture automatique"],"de":["Musikwiedergabe mit Typescript","Moderations-Tools für Discord","Verwaltung von Warteschlangen mit `useMainPlayer()`","Musiksuche mit `player.search()`","Lautstärke- und Autoplay-Steuerung"],"pt":["Reprodução de música com Typescript","Controle de filas e reprodução de faixas","Funções de moderação para gerenciar o bot","Integração com o discord-player para acesso ao player","Suporte a busca e reprodução de músicas","Gerenciamento de volume, autoplay, repeat e shuffle"],"ru":["Воспроизведение музыки с помощью Typescript","Контроль очередей и воспроизведение треков","Функции модерации для управления ботом","Интеграция с discord-player для доступа к плееру","Поддержка поиска и воспроизведения музыки","Управление громкостью, autoplay, повтором и перемешиванием"],"ar":["تشغيل الموسيقى باستخدام Typescript","مراقبة الطوابير و تشغيل المسارات","وظائف التحكم لدارة البوت","التكامل مع discord-player للوصول إلى اللاعب","دعم البحث و تشغيل الموسيقى","إدارة الصوت، التشغيل التلقائي، التكرار و الخلط"]},"keywords":{"en":["how to use music-queue-player","music-queue-player setup guide","discord bot music player","music-queue-player alternative","music-queue-player vs discord.js","typescript discord bot development","music-queue-player install","discord music bot tutorial"],"zh":["music-queue-player","Discord 机器人","音乐工具","队列管理","TypeScript","discord-player","AI エージェント","音乐管理"],"ja":["music-queue-player","Discord ボット","音楽ツール","キュー管理","TypeScript","discord-player","AIエージェント","音楽管理"],"ko":["music-queue-player","디스코드 봇","음악 도구","큐 관리","TypeScript","discord-player","AI 에이전트","음악 관리"],"es":["music-queue-player","bot de Discord","Typescript","herramientas de moderación","reproducción de música","gestión de colas","discord-player","bot de música para Discord"],"fr":["music-queue-player","bot Discord","Typescript","outils de modération","lecture de musique","gestion de files d''attente","discord-player","bot de musique pour Discord"],"de":["music-queue-player","Discord-Bot","Typescript","Moderations-Tools","Musikwiedergabe","Verwaltung von Warteschlangen","discord-player","Musikbot für Discord"],"pt":["music-queue-player","bot de música para Discord","ferramentas de moderação","Typescript","discord-player","reprodução de música","controle de filas","moderação de bots"],"ru":["music-queue-player","бот для музыки в Discord","инструменты модерации","Typescript","discord-player","воспроизведение музыки","контроль очередей","модерация ботов"],"ar":["music-queue-player","بوت موسيقي لديسكورد","أدوات التحكم","Typescript","discord-player","تشغيل الموسيقى","مراقبة الطوابير","تنظيم البوتات"]}},"owner":"LucasSantana-Dev","repo":"LukBot","repoPath":"LucasSantana-Dev/LukBot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.475Z","topics":[],"category":"community","skillMd":{"name":"music-queue-player","description":"Work with Discord Player, queue, and music commands in Nexus. Use when changing play/queue/skip/volume, track handling, or player lifecycle.","bodyPreview":"# Nexus Music & Queue\n\n## When to use\n\n- Changing play, queue, skip, pause, volume, autoplay, repeat, shuffle\n- Fixing track or queue display\n- Player lifecycle, errors, or extractors\n\n## Player access\n\n- Use `useMainPlayer()` from `discord-player` where the player is available (e.g. after client ready).\n- Play: `player.play(voiceChannel, searchResult, { nodeOptions: { metadata } })`. Search via `player.search(query, { requestedBy })`.\n\n## Command locations\n\n- **Play**: `packages/bot/src/functio","body":"# Nexus Music & Queue\n\n## When to use\n\n- Changing play, queue, skip, pause, volume, autoplay, repeat, shuffle\n- Fixing track or queue display\n- Player lifecycle, errors, or extractors\n\n## Player access\n\n- Use `useMainPlayer()` from `discord-player` where the player is available (e.g. after client ready).\n- Play: `player.play(voiceChannel, searchResult, { nodeOptions: { metadata } })`. Search via `player.search(query, { requestedBy })`.\n\n## Command locations\n\n- **Play**: `packages/bot/src/functions/music/commands/play/` — processor, queryDetector, queueManager, spotify/youtube handlers\n- **Queue**: `packages/bot/src/functions/music/commands/queue/` — formatter, embed, grouping, stats\n- **Control**: `packages/bot/src/functions/music/commands/` — skip, pause, resume, remove, clear, volume, repeat, shuffle, leave, stop\n\n## Handlers\n\n- **Player**: `packages/bot/src/handlers/player/` — trackHandlers, errorHandlers, lifecycleHandlers, playerFactory\n- **Events**: `packages/bot/src/handlers/player/trackHandlers.ts` and related — wire player events to replies and history\n\n## Shared state\n\n- Track history and recommendations: use services from `@nexus/shared` (e.g. TrackHistoryService, recommendation) when persisting; do not duplicate queue state in Redis/DB beyond what shared exposes.\n\n## Validations\n\n- Ensure user is in a voice channel; bot has join permissions. Use existing queue/voice validators before touching queue or player.\n"},"lastSynced":"2026-03-08T02:10:08.549Z","agentAnalysis":{"suitability":{"en":"Perfect for Discord Agents needing advanced music queue management and playback control.","zh":"非常适合需要高级音乐队列管理和播放控制的Discord Agents。","ja":"Discordエージェントが高度な音楽キュー管理と再生制御を必要とする場合に最適です。","ko":"고급 음악 큐 관리 및 재생 제어가 필요한 Discord 에이전트에게 적합합니다.","es":"Perfecto para agentes de Discord que necesitan una gestión avanzada de cola de música y control de reproducción.","fr":"Parfait pour les agents Discord ayant besoin d''une gestion avancée de file d''attente de musique et de contrôle de lecture.","de":"Perfekt für Discord-Agenten, die eine erweiterte Musikwarteschlangenverwaltung und Wiedergabekontrolle benötigen.","pt":"Perfeito para Agentes do Discord que precisam de gerenciamento avançado de fila de música e controle de reprodução.","ru":"Идеально подходит для агентов Discord, которым требуется продвинутый менеджер очереди музыки и управление воспроизведением.","ar":"مثالي لعميل ديسكورد الذين يحتاجون إلى إدارة متقدمة لترتيب الموسيقى وسيطرة التشغيل."},"recommendation":{"en":"Empowers agents to manage music playback using discord-player, enabling features like autoplay, repeat, shuffle, and volume control through voice channel interactions and search queries with metadata.","zh":"赋予代理管理音乐播放的能力，使用discord-player实现自动播放、重复、随机播放和通过语音频道交互和带有元数据的搜索查询来控制音量。","ja":"discord-playerを使用して、自動再生、リピート、シャッフル、音量コントロールなどの機能を実現し、ボイスチャンネルのやり取りやメタデータを含む検索クエリを介して音楽の再生を管理するエージェントを可能にします。","ko":"discord-player를 사용하여 자동 재생, 반복, 셔플, 볼륨 제어 등의 기능을 구현하고, 음성 채널 상호 작용 및 메타데이터가 포함된 검색 쿼리를 통해 음악 재생을 관리하는 에이전트를 가능하게 합니다.","es":"Habilita a los agentes a gestionar la reproducción de música utilizando discord-player, lo que permite características como autoplay, repetir, barajar y control de volumen a través de interacciones de canales de voz y consultas de búsqueda con metadatos.","fr":"Permet aux agents de gérer la lecture de musique en utilisant discord-player, permettant des fonctionnalités comme l''autoplay, la répétition, le mélange et le contrôle du volume via les interactions de canaux vocaux et les requêtes de recherche avec des métadonnées.","de":"Ermächtigt Agenten, die Musikwiedergabe mit discord-player zu verwalten, wodurch Funktionen wie Autoplay, Wiederholung, Shuffle und Lautstärkenkontrolle über Voice-Channel-Interaktionen und Suchanfragen mit Metadaten ermöglicht werden.","pt":"Habilita agentes a gerenciar a reprodução de música usando discord-player, habilitando recursos como autoplay, repetir, embaralhar e controle de volume por meio de interações de canal de voz e consultas de pesquisa com metadados.","ru":"Наделяет агентов возможностью управлять воспроизведением музыки с помощью discord-player, обеспечивая функции, такие как автопроигрывание, повтор, перемешивание и контроль громкости через взаимодействия голосового канала и поисковые запросы с метаданными.","ar":"يمنح الوكلاء إمكانية إدارة تشغيل الموسيقى باستخدام discord-player، وتمكين الميزات مثل التشغيل التلقائي وإعادة التشغيل وخلط الأغاني وسيطرة الحجم من خلال التفاعلات القناة الصوتية والاستفسارات البحثية مع البيانات الوصفية."},"useCases":{"en":["Managing music queues with skip, pause, and play functionality","Fixing track or queue display issues","Handling player lifecycle, errors, or extractors"],"zh":["使用跳过、暂停和播放功能管理音乐队列","修复音轨或队列显示问题","处理播放器生命周期、错误或提取器"],"ja":["スキップ、ポーズ、再生機能を使用して音楽キューを管理する","トラックまたはキューの表示の問題を修正する","プレイヤーのライフサイクル、エラー、またはエクストラクターを処理する"],"ko":["스킵, 일시 중지, 재생 기능을 사용하여 음악 큐를 관리하는 것","트랙 또는 큐 표시 문제를 수정하는 것","플레이어 수명 주기, 오류 또는 추출기를 처리하는 것"],"es":["Gestionar colas de música con funcionalidad de salto, pausa y reproducción","Solucionar problemas de visualización de pistas o colas","Gestionar el ciclo de vida del reproductor, errores o extractores"],"fr":["Gérer les files d''attente de musique avec des fonctionnalités de saut, de pause et de lecture","Résoudre les problèmes d''affichage de pistes ou de files d''attente","Gérer le cycle de vie du lecteur, les erreurs ou les extracteurs"],"de":["Musikwarteschlangen mit Skip-, Pause- und Play-Funktion verwalten","Probleme mit der Anzeige von Tracks oder Warteschlangen beheben","Lebenszyklus des Players, Fehler oder Extractor verwalten"],"pt":["Gerenciar filas de música com funcionalidades de pular, pausar e reproduzir","Corrigir problemas de exibição de faixas ou filas","Lidar com ciclo de vida do player, erros ou extratores"],"ru":["Управление очередями музыки с функциями пропуска, паузы и воспроизведения","Исправление проблем отображения треков или очередей","Обработка жизненного цикла плеера, ошибок или экстракторов"],"ar":["إدارة ترتيب الموسيقى مع وظائف التخطي والتعليق والتشغيل","تصحيح مشاكل عرض المسارات أو الترتيب","التعامل مع دورة حياة اللاعب، والأخطاء أو المستخرجات"]},"limitations":{"en":["Requires Discord bot setup with Typescript","Needs discord-player library integration","Limited to Discord server management"],"zh":["需要使用Typescript设置Discord机器人","需要集成discord-player库","仅限Discord服务器管理"],"ja":["Typescriptを使用してDiscordボットを設定する必要がある","discord-playerライブラリの統合が必要","Discordサーバー管理のみ"],"ko":["Typescript를 사용하여 Discord 봇을 설정해야 함","discord-player 라이브러리를 통합해야 함","Discord 서버 관리만 가능"],"es":["Requiere configuración de bot de Discord con Typescript","Necesita integración de la biblioteca discord-player","Limitado a la gestión de servidores de Discord"],"fr":["Nécessite une configuration de bot Discord avec Typescript","Nécessite une intégration de la bibliothèque discord-player","Limité à la gestion de serveurs Discord"],"de":["Benötigt Discord-Bot-Konfiguration mit Typescript","Benötigt discord-player-Bibliotheksintegration","Begrenzt auf Discord-Serververwaltung"],"pt":["Exige configuração de bot do Discord com Typescript","Necessita de integração da biblioteca discord-player","Limitado à gestão do servidor do Discord"],"ru":["Требует настройки бота Discord с Typescript","Требует интеграции библиотеки discord-player","Ограничен управлением сервером Discord"],"ar":["يتطلب إعداد.bot ديسكورد مع Typescript","يحتاج إلى دمج مكتبة discord-player","محدود بإدارة خادم ديسكورد"]},"version":4},"contentHash":"c5d93f643473aa8c900c756ff8ab22d025c5aac4d4fabf2b3e55afceba49fbe2","qualityScore":38}');
