INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('theonizs/my-pearl-page/vercel-react-native-skills', 'vercel-react-native-skills', 'theonizs', 'my-pearl-page', 'community', 'vercel-react-native-skills theonizs my-pearl-page community Vercel React Native Skills provides comprehensive best practices for React Native and Expo applications, covering performance, animations, and platform-specific optimizations for developers. Vercel React Native 技能提供了 React Native 和 Expo 应用的综合最佳实践，涵盖性能、动画、UI 模式和平台特定优化等多个类别 Vercel React Native スキルは、React Native と Expo アプリケーションの包括的なベストプラクティスを提供し、パフォーマンス、動画、UI パターン、プラットフォーム特有の最適化など複数のカテゴリをカバーする Vercel React Native 스킬은 React Native 및 Expo 애플리케이션의 종합적인 최적화 방법을 제공하며, 성능, 애니메이션, UI 패턴 및 플랫폼 특정 최적화 등 여러 카테고리를 다룹니다 Optimiza tus aplicaciones React Native y Expo con las mejores prácticas de Vercel, incluyendo rendimiento, animaciones y optimizaciones de plataforma Optimisez vos applications React Native et Expo avec les meilleures pratiques de Vercel, y compris les performances, les animations et les optimisations de plateforme Optimieren Sie Ihre React Native- und Expo-Anwendungen mit den bewährten Methoden von Vercel, einschließlich Leistung, Animationen und Plattformoptimierungen O Vercel React Native é uma ferramenta que fornece diretrizes abrangentes para otimizar o desempenho e a experiência do usuário em aplicações React Native e Expo Vercel React Native - это инструмент, который предоставляет комплексные рекомендации для оптимизации производительности и пользовательского опыта в приложениях React Native и Expo أداة Vercel React Native هي أداة توفر إرشادات شاملة لتحسين الأداء وتجربة المستخدم في تطبيقات React Native و Expo how to use vercel-react-native-skills what is vercel-react-native-skills vercel-react-native-skills setup guide vercel-react-native-skills vs react native cli react native performance optimization expo app development best practices vercel-react-native-skills install react native animations with reanimated vercel-react-native-skills alternative Vercel React Native React Native 优化 Expo 项目结构 Reanimated 动画 UI 模式 平台特定优化 AI エージェント React Native 最佳实践 Provides rules for optimizing list and scroll performance in React Native apps Supports implementing animations with Reanimated Offers guidelines for working with images and media in Expo applications Includes best practices for configuring native modules or fonts Helps with structuring monorepo projects with native code Vercel-react-native-skills is a set of guidelines for building and optimizing React Native and Expo applications with best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('paruma/atcoder_rust/symmetry-syncer', 'community', 'paruma', 'atcoder_rust', 'paruma/atcoder_rust', 'symmetry-syncer', 0, 0, 38, '2026-03-08T01:57:15.567Z', '2026-03-08T02:11:42.646Z', 'bd76f0fe975a3cf6f0ceacd282f70788c96b242fa967c79a6d57ef9567c2b735', '{"id":"paruma/atcoder_rust/symmetry-syncer","name":"symmetry-syncer","description":{"en":"The symmetry-syncer skill maintains structural integrity in paired files, ensuring consistency across symmetric implementations. It benefits developers working with paired files like ext_int.rs and neg_ext_int.rs","zh":"Symmetry Syncer 是一种保持代码对称性的专家，自动同步代码结构，确保代码的一致性","ja":"Symmetry Syncer はコードの対称性を維持するスペシャリストで、コード構造を自動同期してコードの一貫性を確保します","ko":"대칭성 동기화기는 코드 대칭성을 유지하는 전문가로, 코드 구조를 자동으로 동기화하여 코드 일관성을 보장합니다","es":"Symmetry Syncer es una herramienta especializada para mantener la integridad estructural de archivos simétricos. Sincroniza la estructura de archivos como ext_int.rs y neg_ext_int.rs","fr":"Symmetry Syncer est un outil spécialisé pour maintenir l''intégrité structurelle des fichiers symétriques. Il synchronise la structure de fichiers tels que ext_int.rs et neg_ext_int.rs","de":"Symmetry Syncer ist ein spezialisiertes Tool zur Erhaltung der Strukturintegrität symmetrischer Dateien. Es synchronisiert die Struktur von Dateien wie ext_int.rs und neg_ext_int.rs","pt":"O Symmetry Syncer é uma ferramenta especializada que mantém a integridade estrutural de arquivos simétricos, como ext_int.rs e neg_ext_int.rs. Ele garante a sincronização completa dos arquivos, incluindo o número de linhas.","ru":"ИИ Агент Symmetry Syncer - это специализированный инструмент, который поддерживает структуальную целостность симметричных файлов, таких как ext_int.rs и neg_ext_int.rs. Он обеспечивает полную синхронизацию файлов, включая количество строк.","ar":"Symmetry Syncer هو أداة متخصصة