INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('paruma/atcoder_rust/symmetry-syncer', 'symmetry-syncer', 'paruma', 'atcoder_rust', 'community', 'symmetry-syncer paruma atcoder_rust community The symmetry-syncer skill maintains structural integrity in paired files, ensuring consistency across symmetric implementations. It benefits developers working with paired files like ext_int.rs and neg_ext_int.rs Symmetry Syncer 是一种保持代码对称性的专家，自动同步代码结构，确保代码的一致性 Symmetry Syncer はコードの対称性を維持するスペシャリストで、コード構造を自動同期してコードの一貫性を確保します 대칭성 동기화기는 코드 대칭성을 유지하는 전문가로, 코드 구조를 자동으로 동기화하여 코드 일관성을 보장합니다 Symmetry Syncer es una herramienta especializada para mantener la integridad estructural de archivos simétricos. Sincroniza la estructura de archivos como ext_int.rs y neg_ext_int.rs Symmetry Syncer est un outil spécialisé pour maintenir l''intégrité structurelle des fichiers symétriques. Il synchronise la structure de fichiers tels que ext_int.rs et neg_ext_int.rs Symmetry Syncer ist ein spezialisiertes Tool zur Erhaltung der Strukturintegrität symmetrischer Dateien. Es synchronisiert die Struktur von Dateien wie ext_int.rs und neg_ext_int.rs O Symmetry Syncer é uma ferramenta especializada que mantém a integridade estrutural de arquivos simétricos, como ext_int.rs e neg_ext_int.rs. Ele garante a sincronização completa dos arquivos, incluindo o número de linhas. ИИ Агент Symmetry Syncer - это специализированный инструмент, который поддерживает структуальную целостность симметричных файлов, таких как ext_int.rs и neg_ext_int.rs. Он обеспечивает полную синхронизацию файлов, включая количество строк. Symmetry Syncer هو أداة متخصصة تحافظ على السلامة الهيكلية للملفات المتماثلة، مثل ext_int.rs و neg_ext_int.rs. يحقق التزامن الكامل للملفات، بما في ذلك عدد الأسطر. how to use symmetry-syncer symmetry-syncer setup guide symmetry-syncer alternative symmetry-syncer vs file comparison tools automated file synchronization symmetry-syncer install what is symmetry-syncer 代码对称性 自动同步 代码结构 对称性同步器 AIエージェント 代码工具 代码一致性 代码可维护性 代码开发 Automates file synchronization for paired files like ext_int.rs and neg_ext_int.rs Maintains structural integrity using The Symmetry Sync Flow Performs diff comparisons to identify symmetry discrepancies Supports synchronization of files with maximum/minimum implementations Ensures line number consistency across synchronized files symmetry-syncer is a specialist that maintains the structural completeness of symmetric files, ensuring consistency across paired implementations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('macho715/cursor_openclaw/decision-router', 'community', 'macho715', 'cursor_openclaw', 'macho715/cursor_openclaw', 'decision-router', 0, 0, 38, '2026-03-08T01:57:15.625Z', '2026-03-08T02:13:32.113Z', '27139ad1ca32a41e0d0f254cea2d83fba0942c02f80e10b0bc50c656725c121b', '{"id":"macho715/cursor_openclaw/decision-router","name":"decision-router","description":{"en":"The decision-router skill applies SSOT Decision Rules to determine next actions, benefiting developers who need to automate decision-making processes. It evaluates conditions and outputs decisions based on predefined rules.","zh":"决策路由器应用SSOT Decision Rules决定下一步行动，包括最小决定规则和输出分支","ja":"デシジョンルーターはSSOT Decision Rulesを適用して次のアクションを決定し、最小決定ルールと出力ブランチを提供する","ko":"의사결정 라우터는 SSOT Decision Rules를 적용하여 다음 행동을 결정하며 최소 결정 규칙과 출력 분기를 포함한다","es":"El decision-router aplica reglas de decisión para determinar la próxima acción en tus flujos de trabajo de Agentes de IA","fr":"Le decision-router applique des règles de décision pour déterminer la prochaine action dans vos flux de travail d''Outils d''IA","de":"Der decision-router wendet Entscheidungsregeln an, um die nächste Aktion in Ihren KI-Agents-Workflows zu bestimmen","pt":"O Decision-Router é uma ferramenta que aplica regras de SSOT para determinar a próxima ação. Ele é capaz de automatizar decisões com base em condições pré-definidas","ru":"ИИ Агент Decision-Router применяет правила SSOT для определения следующего действия. Он может автоматизировать принятие решений на основе предварительно определенных условий","ar":"Decision-Router هو أداة تطبيق قواعد SSOT لتحديد الإجراء التالي. يمكنه تautomatize القرارات بناءً على الشروط المحددة مسبقا"},"seo":{"title":{"en":"decision-router: Setup Guide for AI Agents | AI Agent Skill","zh":"决策路由器 Setup Guide - AI工具","ja":"デシジョンルーター ベストプラクティス - AIエージェント","ko":"의사결정 라우터 설정 가이드 