INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('macho715/cursor_openclaw/decision-router', 'decision-router', 'macho715', 'cursor_openclaw', 'community', 'decision-router macho715 cursor_openclaw community The decision-router skill applies SSOT Decision Rules to determine next actions, benefiting developers who need to automate decision-making processes. It evaluates conditions and outputs decisions based on predefined rules. 决策路由器应用SSOT Decision Rules决定下一步行动，包括最小决定规则和输出分支 デシジョンルーターはSSOT Decision Rulesを適用して次のアクションを決定し、最小決定ルールと出力ブランチを提供する 의사결정 라우터는 SSOT Decision Rules를 적용하여 다음 행동을 결정하며 최소 결정 규칙과 출력 분기를 포함한다 El decision-router aplica reglas de decisión para determinar la próxima acción en tus flujos de trabajo de Agentes de IA Le decision-router applique des règles de décision pour déterminer la prochaine action dans vos flux de travail d''Outils d''IA Der decision-router wendet Entscheidungsregeln an, um die nächste Aktion in Ihren KI-Agents-Workflows zu bestimmen O Decision-Router é uma ferramenta que aplica regras de SSOT para determinar a próxima ação. Ele é capaz de automatizar decisões com base em condições pré-definidas ИИ Агент Decision-Router применяет правила SSOT для определения следующего действия. Он может автоматизировать принятие решений на основе предварительно определенных условий Decision-Router هو أداة تطبيق قواعد SSOT لتحديد الإجراء التالي. يمكنه تautomatize القرارات بناءً على الشروط المحددة مسبقا how to use decision-router what is decision-router decision-router setup guide decision-router alternative decision-router vs pr-merge-orchestrator decision-router install SSOT Decision Rules AI agent decision-making automated decision-making 决策路由器 AI工具 SSOT Decision Rules 最小决定规则 输出分支 AI开发 自动化决策 条件重置 pr-merge-orchestrator Applies SSOT Decision Rules to determine next actions Evaluates conditions such as STOP detection, allowlist violations, and gate failures Outputs decisions based on predefined rules, including ZERO_STOP and PR_ONLY Integrates with pr-merge-orchestrator for conditional re-evaluation Supports automatic merge candidate generation decision-router is a skill that applies Single Source of Truth (SSOT) Decision Rules to determine the next course of action based on predefined conditions and rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nicenonecb/RepoMap/repomap', 'community', 'Nicenonecb', 'RepoMap', 'Nicenonecb/RepoMap', 'repomap', 0, 0, 38, '2026-03-08T01:57:15.652Z', '2026-03-08T02:13:53.432Z', 'e373052725a4d6105e09c2b5730fea3364bd169c54f775bd38ef3d41124105e4', '{"id":"Nicenonecb/RepoMap/repomap","name":"repomap","description":{"en":"repomap helps developers locate relevant modules, entry points, and keywords in large repositories, providing a repeatable workflow for building and updating .repomap/ and querying it.","zh":"Repomap是一个用于仓库映射的工具，帮助开发者快速定位模块和入口文件","ja":"Repomapはリポジトリマッピングツールで、開発者がモジュールやエントリファイルを迅速に特定するのに役立ちます","ko":"Repomap은 리포지토리 맵핑을 위한 도구로 개발자가 모듈과 엔트리 파일을 신속히 식별하는 데 도움이 됩니다","es":"RepoMap es una herramienta para localizar módulos y puntos de entrada en grandes repositorios. Proporciona un flujo de trabajo repetible para construir y actualizar la salida de RepoMap","fr":"RepoMap est un outil pour localiser les modules et les points d''entrée dans les grands référentiels. Il fournit un flux de travail répétitif pour construire et mettre à jour la sortie de RepoMap","de":"RepoMap ist ein Tool zum Auffinden von Modulen und Einstiegspunkten in großen Repositorien. Es bietet einen wiederholbaren Arbeitsablauf zur Erstellung und Aktualisierung der RepoMap-Ausgabe","pt":"O Repomap é uma ferramenta que ajuda a localizar módulos e pontos de entrada em grandes repositórios, melhorando a eficiência do desenvolvimento.","ru":"Repomap - это инструмент, который помогает найти необходимые модули и точки входа в больших репозиториях, повышая эффективность разработки с помощью ИИ Агентов.","ar":"Repomap هو أداة تساعد في تحديد الوحدات والنقاط الرئيسية في المستودعات الكبيرة، وتحسين كفاءة التطوير."},"seo":{"title":{"en":"repomap: Efficient Repository Mapping for AI Agents | AI ...","zh":"Repomap Setup Guide - AI工具用于仓库映射","ja":"Repomap ベストプラクティス - AIエージェントによるリポジトリマッピング","ko":"Repomap 가이드 - AI 에이전트를 사용한 리포지토리 맵핑","es":"Guía de Configuración de RepoMap para Desarrolladores","fr":"Guide de Mise en Place de RepoMap pour les Développeurs","de":"Einrichtungs-Leitfaden für RepoMap-Entwickler","pt":"Guia de Configuração do Repomap: Localizando Módulos e Po...","ru":"ИИ Агенты: Руководство по Настройке Repomap для Оптимизац...","ar":"دليل إعداد Repomap: تحديد الوحدات والنقاط الرئيسية في الم..."},"description":{"en":"Unlock efficient repository navigation with repomap! Learn how to build, update, and query .repomap/ for streamlined development workflows","zh":"了解Repomap的用途、工作流程和功能，提高开发效率","ja":"Repomapの目的、ワークフロー、機能を学び、開発の生産性を向上させる","ko":"Repomap의 목적, 워크플로우, 기능을 학습하고 개발 생산성을 향상시키세요","es":"Aprende a utilizar RepoMap para localizar módulos y puntos de entrada en grandes repositorios. Mejora tu flujo de trabajo con nuestra guía","fr":"Découvrez comment utiliser RepoMap pour localiser les modules et les points d''entrée dans les grands référentiels. Améliorez votre flux de travail avec notre...","de":"Erfahren Sie, wie Sie RepoMap verwenden, um Module und Einstiegspunkte in großen Repositorien zu finden. Verbessern Sie Ihren Arbeitsablauf mit unserem Leitf...","pt":"Aprenda a usar o Repomap para localizar módulos e pontos de entrada em grandes repositórios, otimizando seu fluxo de trabalho de desenvolvimento.","ru":"Узнайте, как использовать Repomap для оптимизации репозиториев и поиска необходимых модулей и точек входа, используя ИИ Агенты.","ar":"تعلم كيفية استخدام Repomap لتحديد الوحدات والنقاط الرئيسية في المستودعات الكبيرة، وتحسين تدفق عمل التطوير الخاص بك."},"definition":{"en":"repomap is a tool for mapping and navigating large repositories, enabling developers to efficiently locate modules, entry points, and keywords","zh":"Repomap是一种AI工具，用于生成仓库映射以便快速定位模块和入口文件","ja":"RepomapはAIエージェントの一種で、リポジトリマッピングを生成し、モジュールやエントリファイルを迅速に特定するのに役立ちます","ko":"Repomap은 리포지토리 맵핑을 생성하여 모듈과 엔트리 파일을 신속히 식별하는 데 도움이 되는 AI 에이전트입니다","es":"RepoMap es una herramienta de línea de comandos (CLI) que ayuda a los desarrolladores a localizar módulos y puntos de entrada en grandes repositorios","fr":"RepoMap est un outil en ligne de commande (CLI) qui aide les développeurs à localiser les modules et les points d''entrée dans les grands référentiels","de":"RepoMap ist ein Command-Line-Interface-Tool (CLI), das Entwicklern hilft, Module und Einstiegspunkte in großen Repositorien zu finden","pt":"O que é Repomap? É uma ferramenta que fornece uma saída para localizar módulos e pontos de entrada em repositórios.","ru":"Что такое Repomap? Это инструмент, который предоставляет вывод для поиска модулей и точек входа в репозиториях с помощью ИИ Агентов.","ar":"ما هو Repomap؟ هو أداة توفر مخرجات لتحديد الوحدات والنقاط الرئيسية في المستودعات."},"features":{"en":["Builds and updates .repomap/ using the `repomap build --out .repomap` command","Provides a repeatable workflow for querying and analyzing repository structures","Locates modules or entry files for specific features or bugfixes","Summarizes repository structure and entry points","Refreshes RepoMap outputs for up-to-date analysis"],"zh":["生成仓库映射以便快速定位模块和入口文件","提供可重复的工作流程以构建和更新仓库映射","支持CLI命令，如`repomap build --out .repomap`","能够根据需要刷新仓库映射输出","帮助开发者快速定位特定功能或bugfix的模块和入口文件"],"ja":["リポジトリマッピングを生成し、モジュールやエントリファイルを迅速に特定する","リポジトリマッピングの構築と更新のための再現可能なワークフローを提供する","CLIコマンドをサポートし、例えば`repomap build --out .repomap`","リポジトリマッピングの出力を必要に応じて更新する","開発者が特定の機能またはバグフィックスのモジュールとエントリファイルを迅速に特定するのに役立つ"],"ko":["리포지토리 맵핑을 생성하여 모듈과 엔트리 파일을 신속히 식별하는 데 도움이 됩니다","리포지토리 맵핑을 빌드하고 업데이트 하는데 필요한 워크플로우를 제공합니다","CLI 명령어를 지원하며 예를 들어 `repomap build --out .repomap`","리포지토리 맵핑 출력을 필요에 따라 새로 고침","개발자가 특정 기능이나 버그 픽스의 모듈과 엔트리 파일을 신속히 식별하는 데 도움이 됩니다"],"es":["Localiza módulos y puntos de entrada en grandes repositorios","Proporciona un flujo de trabajo repetible para construir y actualizar la salida de RepoMap","Permite la actualización de la salida de RepoMap antes del análisis","Utiliza comandos como `repomap build --out .repomap` para construir la salida","Utiliza comandos como `repomap update` para actualizar la salida","Ayuda a resumir la estructura del repositorio y los puntos de entrada"],"fr":["Localise les modules et les points d''entrée dans les grands référentiels","Fournit un flux de travail répétitif pour construire et mettre à jour la sortie de RepoMap","Permet la mise à jour de la sortie de RepoMap avant l''analyse","Utilise des commandes comme `repomap build --out .repomap` pour construire la sortie","Utilise des commandes comme `repomap update` pour mettre à jour la sortie","Aide à résumer la structure du référentiel et les points d''entrée"],"de":["Findet Module und Einstiegspunkte in großen Repositorien","Bietet einen wiederholbaren Arbeitsablauf zur Erstellung und Aktualisierung der RepoMap-Ausgabe","Ermöglicht die Aktualisierung der RepoMap-Ausgabe vor der Analyse","Verwendet Befehle wie `repomap build --out .repomap` zur Erstellung der Ausgabe","Verwendet Befehle wie `repomap update` zur Aktualisierung der Ausgabe","Hilft bei der Zusammenfassung der Repositorien-Struktur und der Einstiegspunkte"],"pt":["Localização de módulos e pontos de entrada em repositórios grandes","Otimização do fluxo de trabalho de desenvolvimento","Saída personalizada para análise de repositórios","Comando CLI para construir e atualizar a saída do Repomap","Integração com fluxos de trabalho de desenvolvimento existentes"],"ru":["Поиск модулей и точек входа в больших репозиториях с помощью ИИ Агентов","Оптимизация потока разработки","Пользовательский вывод для анализа репозиториев","Команда CLI для построения и обновления вывода Repomap","Интеграция с существующими потоками разработки"],"ar":["تحديد الوحدات والنقاط الرئيسية في المستودعات الكبيرة","تحسين تدفق عمل التطوير","مخرجات مخصصة لتحليل المستودعات","أمر CLI لبناء وتحديث مخرجات Repomap","التكامل مع تدفقات عمل التطوير الحالية"]},"keywords":{"en":["how to use repomap","repomap setup guide","what is repomap","repomap alternative","repomap vs repository mapping tools","repomap install","repomap workflow","repository mapping best practices","efficient repository navigation"],"zh":["Repomap","AI工具","仓库映射","CLI命令","开发效率","模块定位","入口文件","代码分析","开发工具"],"ja":["Repomap","AIエージェント","リポジトリマッピング","CLIコマンド","開発の生産性","モジュールの特定","エントリファイル","コード分析","開発ツール"],"ko":["Repomap","AI 에이전트","리포지토리 맵핑","CLI 명령어","개발 생산성","모듈 식별","엔트리 파일","코드 분석","개발 도구"],"es":["RepoMap","herramienta de línea de comandos","localizar módulos","puntos de entrada","grandes repositorios","flujo de trabajo repetible","construir y actualizar","análisis de repositorios","desarrollo de software"],"fr":["RepoMap","outil en ligne de commande","localiser les modules","points d''entrée","grands référentiels","flux de travail répétitif","construire et mettre à jour","analyse de référentiels","développement de logiciels"],"de":["RepoMap","Command-Line-Interface-Tool","Module finden","Einstiegspunkte","große Repositorien","wiederholbarer Arbeitsablauf","Erstellung und Aktualisierung","Repositorien-Analyse","Software-Entwicklung"],"pt":["repomap","localizar módulos","pontos de entrada","repositórios grandes","otimizar desenvolvimento","ferramenta de desenvolvimento","CLI","análise de repositórios"],"ru":["repomap","поиск модулей","точки входа","большие репозитории","оптимизировать разработку","инструмент разработки","CLI","анализ репозиториев","ИИ Агенты"],"ar":["repomap","تحديد الوحدات","نقاط الدخول","مستودعات كبيرة","تحسين التطوير","أداة التطوير","CLI","تحليل المستودعات","أدوات الذكاء الاصطناعي"]}},"owner":"Nicenonecb","repo":"RepoMap","repoPath":"Nicenonecb/RepoMap","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.652Z","topics":[],"category":"community","skillMd":{"name":"repomap","description":"Guide for using RepoMap outputs and CLI to locate modules, entry files, and keywords. This skill should be used when users ask to navigate a large repository, find relevant modules/files, or run RepoMap build/update/query.","bodyPreview":"# RepoMap\n\n## Purpose\n\n- Use RepoMap outputs to locate relevant modules, entry points, and keywords in large repositories.\n- Provide a repeatable workflow for building/updating `.repomap/` and querying it.\n\n## When To Use\n\n- Locate modules or entry files for a feature or bugfix.\n- Summarize repo structure or entry points.\n- Refresh RepoMap outputs before analysis.\n\n## Workflow\n\n1. Confirm `.repomap/` exists; if missing or stale, build/update.\n   - Build: `repomap build --out .repomap`\n   - Updat","body":"# RepoMap\n\n## Purpose\n\n- Use RepoMap outputs to locate relevant modules, entry points, and keywords in large repositories.\n- Provide a repeatable workflow for building/updating `.repomap/` and querying it.\n\n## When To Use\n\n- Locate modules or entry files for a feature or bugfix.\n- Summarize repo structure or entry points.\n- Refresh RepoMap outputs before analysis.\n\n## Workflow\n\n1. Confirm `.repomap/` exists; if missing or stale, build/update.\n   - Build: `repomap build --out .repomap`\n   - Update: `repomap update --out .repomap`\n   - If the CLI is not installed, run `pnpm -r build` first and use:\n     `node packages/cli/dist/index.js build --out .repomap`\n2. Read `.repomap/summary.md` for the high-level layout.\n3. Query candidates by keywords:\n   - `repomap query \"refresh token\" --out .repomap`\n   - Use `--format json` when structured output is required.\n4. Inspect `.repomap/module_index.json` and `.repomap/entry_map.json` to locate\n   modules and entry files; join on `path`.\n5. Broaden keywords or rerun `update` after changes if results are empty.\n6. Report top modules with paths and entry files; include tokens and matches\n   when returning JSON results.\n\n## Notes\n\n- Treat output paths as POSIX; resolve against repo root if needed.\n- Ignore output directories when rebuilding examples (use `--ignore \"output/**\"`).\n- Include ignored paths by using negate patterns (example:\n  `--ignore ''!node_modules/**''`).\n"},"lastSynced":"2026-03-08T02:13:53.432Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing efficient repository navigation and module location capabilities.","zh":"非常适合需要高效的仓库导航和模块定位能力的代码分析代理。","ja":"コード分析エージェントが効率的なリポジトリナビゲーションとモジュールの位置特定能力を必要とする場合に最適です。","ko":"코드 분석 에이전트가 효율적인 저장소 탐색 및 모듈 위치 지정 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan una navegación eficiente por repositorios y capacidades de localización de módulos.","fr":"Parfait pour les Agents d''Analyse de Code nécessitant une navigation de référentiel efficace et des capacités de localisation de modules.","de":"Perfekt für Code-Analyse-Agents, die eine effiziente Repository-Navigation und Modulortungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de navegação eficiente de repositórios e capacidades de localização de módulos.","ru":"Идеально подходит для агентов анализа кода, которым необходима эффективная навигация по репозиториям и возможности поиска модулей.","ar":"مثالي للوكلاء تحليل الشفرة التي تحتاج إلى التنقل الفعال في المستودعات وقدرات تحديد الموقع من الوحدات"},"recommendation":{"en":"Empowers agents to locate relevant modules, entry points, and keywords in large repositories using repeatable workflows and querying .repomap/ outputs, streamlining development and bugfixing processes with precise repository structure summaries.","zh":"赋予代理定位大型仓库中相关模块、入口点和关键字的能力，使用可重复的工作流和查询 .repomap/ 输出，通过精确的仓库结构摘要来简化开发和调试过程。","ja":"エージェントに、大規模リポジトリ内の関連モジュール、エントリポイント、およびキーワードを特定する機能を提供します。リピータブルなワークフローと .repomap/ 出力を照会することで、開発とバグ修正プロセスを精確なリポジトリ構造のサマリーで効率化します。","ko":"에이전트가 대형 저장소 내 관련 모듈, 진입점 및 키워드를 찾을 수 있는 기능을 제공하여 반복 가능한 워크플로 및 .repomap/ 출력을 쿼리하여 개발 및 버그 수정 프로세스를 정확한 저장소 구조 요약으로 간소화합니다.","es":"Habilita a los agentes a localizar módulos relevantes, puntos de entrada y palabras clave en grandes repositorios utilizando flujos de trabajo repetibles y consultando salidas de .repomap/, lo que agiliza los procesos de desarrollo y depuración con resúmenes precisos de la estructura del repositorio.","fr":"Permet aux agents de localiser des modules pertinents, des points d''entrée et des mots clés dans de grands référentiels en utilisant des flux de travail répétitifs et en interrogeant les sorties de .repomap/, ce qui rationalise les processus de développement et de débogage avec des résumés précis de la structure du référentiel.","de":"Ermächtigt Agents, relevante Module, Einstiegspunkte und Schlüsselwörter in großen Repositorien zu lokalisieren, indem sie wiederholbare Workflows und .repomap/-Ausgaben abfragen, wodurch die Entwicklungs- und Fehlersuchprozesse mit präzisen Repository-Strukturzusammenfassungen rationalisiert werden.","pt":"Habilita os agentes a localizar módulos relevantes, pontos de entrada e palavras-chave em repositórios grandes usando fluxos de trabalho repetíveis e consultando saídas .repomap/, otimizando os processos de desenvolvimento e depuração com resumos precisos da estrutura do repositório.","ru":"Позволяет агентам находить релевантные модули, точки входа и ключевые слова в больших репозиториях, используя повторяемые рабочие процессы и запросы вывода .repomap/, оптимизируя процессы разработки и исправления ошибок с точными резюме структуры репозитория.","ar":"تمكّن الوكلاء من تحديد الوحدات ذات الصلة ونقاط الدخول والكلمات الرئيسية في المستودعات الكبيرة باستخدام سير عمل قابلة للتكرار واستعلام مخرجات .repomap/، وتحسين عمليات التطوير وإصلاح العيوب مع ملخصات دقيقة لهيكل المستودع"},"useCases":{"en":["Locating modules for feature development","Summarizing repository structures for entry points","Refreshing RepoMap outputs for stale data analysis"],"zh":["用于功能开发的模块定位","用于入口点的仓库结构摘要","用于过时数据分析的RepoMap输出刷新"],"ja":["機能開発のためのモジュールの位置特定","エントリポイントのためのリポジトリ構造のサマリー","古いデータ分析のためのRepoMap出力の更新"],"ko":["기능 개발을 위한 모듈 위치 지정","진입점을 위한 저장소 구조 요약","陳旧한 데이터 분석을 위한 RepoMap 출력 갱신"],"es":["Localización de módulos para el desarrollo de características","Resumen de estructuras de repositorio para puntos de entrada","Actualización de salidas de RepoMap para análisis de datos obsoletos"],"fr":["Localisation de modules pour le développement de fonctionnalités","Résumé des structures de référentiel pour les points d''entrée","Actualisation des sorties de RepoMap pour l''analyse de données obsolètes"],"de":["Lokalisierung von Modulen für die Entwicklung von Funktionen","Zusammenfassung von Repository-Strukturen für Einstiegspunkte","Aktualisierung von RepoMap-Ausgaben für die Analyse veralteter Daten"],"pt":["Localizar módulos para desenvolvimento de recursos","Resumir estruturas de repositório para pontos de entrada","Atualizar saídas RepoMap para análise de dados obsoletos"],"ru":["Найти модули для разработки функций","Суммировать структуры репозитория для точек входа","Обновить выводы RepoMap для анализа устаревших данных"],"ar":["تحديد الوحدات لتنمية الميزات","تجميع هيكل المستودع لنقاط الدخول","تحديث مخرجات RepoMap لتحليل البيانات المتقادمة"]},"limitations":{"en":["Requires .repomap/ directory presence","Needs periodic updates for accuracy","Limited to repository analysis"],"zh":[".repomap/ 目录存在的要求","需要周期性的更新以确保准确性","仅限于仓库分析"],"ja":[".repomap/ ディレクトリの存在の要件","精度を確保するための周期的な更新の必要性","リポジトリ分析のみに限定"],"ko":[".repomap/ 디렉토리 존재 요구","정확성을 보장하기 위한 주기적인 업데이트의 필요성","저장소 분석에만 제한"],"es":["Requiere la presencia del directorio .repomap/","Necesita actualizaciones periódicas para garantizar la precisión","Limitado al análisis de repositorios"],"fr":["Nécessite la présence du répertoire .repomap/","A besoin de mises à jour périodiques pour l''exactitude","Limité à l''analyse de référentiels"],"de":["Erfordert die Anwesenheit des .repomap/-Verzeichnisses","Benötigt regelmäßige Updates für die Genauigkeit","Begrenzt auf die Analyse von Repositorien"],"pt":["Exige a presença do diretório .repomap/","Necessita de atualizações periódicas para precisão","Limitado à análise de repositórios"],"ru":["Требует наличия директории .repomap/","Требует периодических обновлений для точности","Ограничен анализом репозиториев"],"ar":["يتطلب وجود دليل .repomap/","يحتاج إلى تحديثات دورية لضمان الدقة","محدود بتحليل المستودعات"]},"version":4},"contentHash":"e373052725a4d6105e09c2b5730fea3364bd169c54f775bd38ef3d41124105e4","qualityScore":38}');
