INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nicenonecb/RepoMap/repomap', 'repomap', 'Nicenonecb', 'RepoMap', 'community', 'repomap Nicenonecb RepoMap community repomap helps developers locate relevant modules, entry points, and keywords in large repositories, providing a repeatable workflow for building and updating .repomap/ and querying it. Repomap是一个用于仓库映射的工具，帮助开发者快速定位模块和入口文件 Repomapはリポジトリマッピングツールで、開発者がモジュールやエントリファイルを迅速に特定するのに役立ちます Repomap은 리포지토리 맵핑을 위한 도구로 개발자가 모듈과 엔트리 파일을 신속히 식별하는 데 도움이 됩니다 RepoMap es una herramienta para localizar módulos y puntos de entrada en grandes repositorios. Proporciona un flujo de trabajo repetible para construir y actualizar la salida de RepoMap RepoMap est un outil pour localiser les modules et les points d''entrée dans les grands référentiels. Il fournit un flux de travail répétitif pour construire et mettre à jour la sortie de RepoMap RepoMap ist ein Tool zum Auffinden von Modulen und Einstiegspunkten in großen Repositorien. Es bietet einen wiederholbaren Arbeitsablauf zur Erstellung und Aktualisierung der RepoMap-Ausgabe O Repomap é uma ferramenta que ajuda a localizar módulos e pontos de entrada em grandes repositórios, melhorando a eficiência do desenvolvimento. Repomap - это инструмент, который помогает найти необходимые модули и точки входа в больших репозиториях, повышая эффективность разработки с помощью ИИ Агентов. Repomap هو أداة تساعد في تحديد الوحدات والنقاط الرئيسية في المستودعات الكبيرة، وتحسين كفاءة التطوير. how to use repomap repomap setup guide what is repomap repomap alternative repomap vs repository mapping tools repomap install repomap workflow repository mapping best practices efficient repository navigation Repomap AI工具 仓库映射 CLI命令 开发效率 模块定位 入口文件 代码分析 开发工具 Builds and updates .repomap/ using the `repomap build --out .repomap` command Provides a repeatable workflow for querying and analyzing repository structures Locates modules or entry files for specific features or bugfixes Summarizes repository structure and entry points Refreshes RepoMap outputs for up-to-date analysis repomap is a tool for mapping and navigating large repositories, enabling developers to efficiently locate modules, entry points, and keywords');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mihaicrisan04/zalem/clerk-custom-ui', 'community', 'mihaicrisan04', 'zalem', 'mihaicrisan04/zalem', 'clerk-custom-ui', 0, 0, 38, '2026-03-07T22:03:44Z', '2026-03-08T02:18:48.547Z', 'edf74eede00053b2155da19b770cb28d69972a195745abae81006fd8e25e4434', '{"id":"mihaicrisan04/zalem/clerk-custom-ui","name":"clerk-custom-ui","description":{"en":"The clerk-custom-ui skill enables developers to create custom authentication flows and customize the appearance of Clerk''s pre-built components. It benefits developers who want to tailor their app''s UI to their brand.","zh":"Clerk 自定义 UI 允许您构建自定义的身份验证流程和外观定制，使用 React 和 JavaScript","ja":"Clerk カスタム UI では、独自の認証フローと外観カスタマイズを構築できます。React と JavaScript を使用します","ko":"Clerk Custom UI를 사용하여 사용자 지정 인증 흐름과 외관을 구축할 수 있습니다. React와 JavaScript를 사용합니다","es":"clerk-custom-ui permite personalizar la interfaz de usuario de Clerk y crear flujos de autenticación personalizados con hooks","fr":"clerk-custom-ui permet de personnaliser l''interface utilisateur de Clerk et de créer des flux d''authentification personnalisés avec des hooks","de":"clerk-custom-ui ermöglicht die Anpassung der Benutzeroberfläche von Clerk und die Erstellung von benutzerdefinierten Authentifizierungsflüssen mit Hooks","pt":"O skill Clerk Custom UI permite criar fluxos de autenticação personalizados e customizar a aparência do Clerk. Saiba como configurar.","ru":"Умение Clerk Custom UI позволяет создать пользовательские потоки аутентификации и настроить внешний вид Clerk. Узнайте, как настроить ИИ Агентов.","ar":"المهارة Clerk Custom UI تمكن من إنشاء تدفقات مصادقة مخصصة وتخصيص المظهر في Clerk. اعرف كيفية التثبيت لمنصة الإي آي أدوات"},"seo":{"title":{"en":"clerk-custom-ui: Custom Authentication Flow Setup Guide |...","zh":"Clerk 自定义 UI 设置指南","ja":"Clerk カスタム UI のベストプラクティス","ko":"Clerk Custom UI 시작하기","es":"Guía de conf