INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mihaicrisan04/zalem/clerk-custom-ui', 'clerk-custom-ui', 'mihaicrisan04', 'zalem', 'community', 'clerk-custom-ui mihaicrisan04 zalem community The clerk-custom-ui skill enables developers to create custom authentication flows and customize the appearance of Clerk''s pre-built components. It benefits developers who want to tailor their app''s UI to their brand. Clerk 自定义 UI 允许您构建自定义的身份验证流程和外观定制，使用 React 和 JavaScript Clerk カスタム UI では、独自の認証フローと外観カスタマイズを構築できます。React と JavaScript を使用します Clerk Custom UI를 사용하여 사용자 지정 인증 흐름과 외관을 구축할 수 있습니다. React와 JavaScript를 사용합니다 clerk-custom-ui permite personalizar la interfaz de usuario de Clerk y crear flujos de autenticación personalizados con hooks clerk-custom-ui permet de personnaliser l''interface utilisateur de Clerk et de créer des flux d''authentification personnalisés avec des hooks clerk-custom-ui ermöglicht die Anpassung der Benutzeroberfläche von Clerk und die Erstellung von benutzerdefinierten Authentifizierungsflüssen mit Hooks O skill Clerk Custom UI permite criar fluxos de autenticação personalizados e customizar a aparência do Clerk. Saiba como configurar. Умение Clerk Custom UI позволяет создать пользовательские потоки аутентификации и настроить внешний вид Clerk. Узнайте, как настроить ИИ Агентов. المهارة Clerk Custom UI تمكن من إنشاء تدفقات مصادقة مخصصة وتخصيص المظهر في Clerk. اعرف كيفية التثبيت لمنصة الإي آي أدوات how to use clerk-custom-ui clerk-custom-ui setup guide custom authentication flow examples clerk-custom-ui vs competing UI libraries clerk-custom-ui install what is clerk-custom-ui clerk-custom-ui documentation clerk-custom-ui tutorial clerk-custom-ui alternative Clerk 自定义 UI AIエージェント 身份验证流程 外观定制 React JavaScript ClerkProvider 版本检查 Build custom authentication flows using hooks Customize the appearance of Clerk''s pre-built components Theme and style Clerk''s components to match your brand Use the ClerkProvider to wrap your app Check package.json for the SDK version Reference custom flow tables for setup clerk-custom-ui is a skill that allows developers to build custom sign-in/sign-up UI with hooks and customize the theme, style, and branding of Clerk''s pre-built components.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('carrizoja/Nest-Dating-Backend/Project Guidelines', 'community', 'carrizoja', 'Nest-Dating-Backend', 'carrizoja/Nest-Dating-Backend', 'Project Guidelines', 0, 0, 38, '2026-03-07T01:33:50Z', '2026-03-08T02:18:56.934Z', '6532105588aa59594aa6d796188e8a27182295b02516c97eb4323ca8614edad7', '{"id":"carrizoja/Nest-Dating-Backend/Project Guidelines","name":"Project Guidelines","description":{"en":"Project Guidelines is a Backend App made with Nest Js and Typescript, providing a foundation for custom instructions and strict typing. It benefits developers working with Nest Js and Typescript.","zh":"Project Guidelines是一套使用Nest Js和Typescript的后端应用开发指南，帮助开发者高效构建应用","ja":"Project Guidelinesは、Nest JsとTypescriptを使用してバックエンドアプリを開発するためのガイドラインです","ko":"Project Guidelines는 Nest Js와 Typescript를 사용하여 백엔드 애플리케이션을 개발하기 위한 가이드라인입니다","es":"Project Guidelines es una aplicación de backend creada con Nest Js y Typescript que sigue instrucciones personalizadas","fr":"Project Guidelines est une application backend créée avec Nest Js et Typescript qui suit des instructions personnalisées","de":"Project Guidelines ist eine Backend-Anwendung, die mit Nest Js und Typescript erstellt wurde und benutzerdefinierte Anweisungen befolgt","pt":"Um aplicativo de backend feito com Nest Js e Typescript, com diretrizes de projeto personalizadas","ru":"Бэкенд-приложение, созданное с помощью Nest Js и Typescript, с настраиваемыми проектными рекомендациями","ar":"تطبيق خلفي مصنوع مع Nest Js و Typescript ، مع إرشادات مشروع مخصصة"},"seo":{"title":{"en":"Project Guidelines: Setup Guide for Nest Js and Typescrip...","zh":"Project Guidelines Setup Guide - 使用Nest Js和Typescript","ja":"プロジェクトガイドライン Setup Guide - Nest JsとTypescriptを使用","ko":"프로젝트 가이드라인 Setup Guide - Nest Js와 Typescript 사용","es":"Guía de configuración para Project Guidelines con Nest Js...","fr":"Guide de mise en place pour Project Guidelines avec Nest ...","de":"Einrichtungsleitfaden für Project Guidelines mit Nest Js ...","pt":"Guia de Configuração do Projeto com Nest Js e Typescript","ru":"Настройка Проекта с помощью Nest Js и Typescript: ИИ Агенты","ar":"إعداد مشروع مع Nest Js و Typescript: أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement custom instructions with Project Guidelines, a Backend App built with Nest Js and Typescript. Get started with setup and configurat...","zh":"了解如何创建一个使用Nest Js和Typescript的后端应用，按照Project Guidelines实现高效开发","ja":"Nest JsとTypescriptを使用してバックエンドアプリを作成する方法について学び、Project Guidelinesに従って効率的な開発を実現する","ko":"Nest Js와 Typescript를 사용하여 백엔드 애플리케이션을 생성하는 방법에 대해 알아보고 Project Guidelines를 따라 효율적인 개발을 구현합니다","es":"Descubre cómo configurar Project Guidelines con Nest Js y Typescript para mejorar tu desarrollo backend","fr":"Découvrez comment configurer Project Guidelines avec Nest Js et Typescript pour améliorer votre développement backend","de":"Erfahren Sie, wie Sie Project Guidelines mit Nest Js und Typescript einrichten, um Ihr Backend-Entwicklung zu verbessern","pt":"Descubra como criar um aplicativo de backend robusto com Nest Js e Typescript, seguindo diretrizes de projeto claras","ru":"Узнайте, как создать надежное 백енд-приложение с помощью Nest Js и Typescript, следуя проектным рекомендациям","ar":"اكتشف كيفية إنشاء تطبيق خلفي قوي مع Nest Js و Typescript ، متبوعًا بإرشادات مشروع واضحة"},"definition":{"en":"Project Guidelines is a technical framework for Backend Apps, utilizing Nest Js and Typescript for custom instruction implementation.","zh":"Project Guidelines是指使用Nest Js和Typescript开发后端应用的技术指南","ja":"Project Guidelinesとは、Nest JsとTypescriptを使用してバックエンドアプリを開発するための技術ガイドラインです","ko":"Project Guidelines는 Nest Js와 Typescript를 사용하여 백엔드 애플리케이션을 개발하기 위한 기술 가이드라인입니다","es":"Project Guidelines es una herramienta de AI que proporciona instrucciones personalizadas para desarrollar aplicaciones de backend con Nest Js y Typescript","fr":"Project Guidelines est un outil d''IA qui fournit des instructions personnalisées pour développer des applications backend avec Nest Js et Typescript","de":"Project Guidelines ist ein AI-Tool, das benutzerdefinierte Anweisungen für die Entwicklung von Backend-Anwendungen mit Nest Js und Typescript bereitstellt","pt":"O que é um projeto com diretrizes personalizadas em Nest Js e Typescript?","ru":"Что такое проект с настраиваемыми рекомендациями в Nest Js и Typescript?","ar":"ما هو مشروع مع إرشادات مخصصة في Nest Js و Typescript؟"},"features":{"en":["Utilizes Nest Js for Backend App development","Leverages Typescript for strict typing and code quality","Allows for custom instructions and naming conventions","Supports adherence to specific coding standards","Enables developers to follow best practices with Typescript"],"zh":["使用Nest Js构建后端应用","使用Typescript实现严格类型检查","自定义项目指南","遵循特定的命名约定","高效开发和构建应用"],"ja":["Nest Jsを使用してバックエンドアプリを構築","Typescriptを使用して厳密な型チェックを実現","カスタムプロジェクトガイドライン","特定の命名規則に従って開発","効率的な開発とアプリの構築"],"ko":["Nest Js를 사용하여 백엔드 애플리케이션을 구축","Typescript를 사용하여 엄격한 타입 체크를 구현","사용자 정의 프로젝트 가이드라인","특정한 명명 규칙을 따르는 개발","효율적인 개발과 애플리케이션 구축"],"es":["Desarrollo de aplicaciones de backend con Nest Js","Uso de Typescript para un desarrollo más seguro","Instrucciones personalizadas para mejorar la productividad","Integración con herramientas de desarrollo de backend","Compatibilidad con diferentes versiones de Nest Js y Typescript"],"fr":["Développement d''applications backend avec Nest Js","Utilisation de Typescript pour un développement plus sécurisé","Instructions personnalisées pour améliorer la productivité","Intégration avec des outils de développement de backend","Compatibilité avec différentes versions de Nest Js et Typescript"],"de":["Entwicklung von Backend-Anwendungen mit Nest Js","Verwendung von Typescript für eine sicherere Entwicklung","Benutzerdefinierte Anweisungen für eine verbesserte Produktivität","Integration mit Entwicklungstools für Backend","Kompatibilität mit verschiedenen Versionen von Nest Js und Typescript"],"pt":["Desenvolvimento de aplicativos de backend com Nest Js","Utilização de Typescript para tipagem estrita","Criação de projetos personalizados com instruções claras","Integração com tecnologias de backend","Suporte a padrões de naming convention"],"ru":["Разработка бэкенд-приложений с помощью Nest Js","Использование Typescript для строгой типизации","Создание проектов с настраиваемыми инструкциями","Интеграция с бэкенд-технологиями","Поддержка именованных конвенций"],"ar":["تطوير تطبيقات الخلفية مع Nest Js","استخدام Typescript لتحديد أنواع صارمة","إنشاء مشاريع مخصصة مع إرشادات واضحة","التكامل مع تقنيات الخلفية","دعم Naming Convention"]},"keywords":{"en":["how to use Project Guidelines","what is Project Guidelines","Project Guidelines alternative","Project Guidelines vs Nest Js","Project Guidelines install","Project Guidelines setup guide","Nest Js and Typescript development","custom instruction implementation","strict typing with Typescript"],"zh":["Project Guidelines","Nest Js","Typescript","后端应用开发","技术指南","严格类型检查","自定义项目指南","命名约定","高效开发"],"ja":["プロジェクトガイドライン","Nest Js","Typescript","バックエンドアプリ開発","技術ガイドライン","厳密な型チェック","カスタムプロジェクトガイドライン","命名規則","効率的な開発"],"ko":["프로젝트 가이드라인","Nest Js","Typescript","백엔드 애플리케이션 개발","기술 가이드라인","엄격한 타입 체크","사용자 정의 프로젝트 가이드라인","명명 규칙","효율적인 개발"],"es":["Project Guidelines","Nest Js","Typescript","desarrollo de backend","herramientas de AI","instrucciones personalizadas","desarrollo de aplicaciones","integración con herramientas de desarrollo","compatibilidad con versiones de Nest Js y Typescript"],"fr":["Project Guidelines","Nest Js","Typescript","développement de backend","outils d''IA","instructions personnalisées","développement d''applications","intégration avec des outils de développement","compatibilité avec des versions de Nest Js et Typescript"],"de":["Project Guidelines","Nest Js","Typescript","Entwicklung von Backend-Anwendungen","AI-Tools","benutzerdefinierte Anweisungen","Entwicklung von Anwendungen","Integration mit Entwicklungstools","Kompatibilität mit Versionen von Nest Js und Typescript"],"pt":["Nest Js","Typescript","Desenvolvimento de backend","Projetos personalizados","Diretrizes de projeto","Tipagem estrita","Naming convention"],"ru":["Nest Js","Typescript","Разработка бэкенда","Настраиваемые проекты","Проектные рекомендации","Строгая типизация","Именованные конвенции"],"ar":["Nest Js","Typescript","تطوير الخلفية","مشاريع مخصصة","إرشادات المشروع","تحديد أنواع صارمة","Naming Convention"]}},"owner":"carrizoja","repo":"Nest-Dating-Backend","repoPath":"carrizoja/Nest-Dating-Backend","stars":0,"forks":0,"updatedAt":"2026-03-07T01:33:50Z","topics":[],"category":"community","skillMd":{"name":"Project Guidelines","description":"General instructions and guidelines for this NestJS project.","bodyPreview":"# Instructions\n\n1. Add your custom instructions here.\n2. For example: \"Always use strict typing.\" or \"Follow these specific naming conventions.\"","body":"# Instructions\n\n1. Add your custom instructions here.\n2. For example: \"Always use strict typing.\" or \"Follow these specific naming conventions.\"\n"},"lastSynced":"2026-03-08T02:18:56.934Z","agentAnalysis":{"suitability":{"en":"Ideal for TypeScript-focused AI Agents seeking structured project management with strict typing and custom instructions.","zh":"适合专注于TypeScript的AI代理，寻求结构化的项目管理、严格的类型检查和自定义指令。","ja":"TypeScriptに焦点を当てたAIエージェントが、構造化されたプロジェクト管理、厳格な型付け、およびカスタム指令を求める場合に適しています。","ko":"TypeScript에 중점을 둔 AI 에이전트가 구조화된 프로젝트 관리, 엄격한 타이핑 및 사용자 지정 지침을 찾는 경우 적합합니다.","es":"Ideal para agentes de IA enfocados en TypeScript que buscan una gestión de proyectos estructurada con tipificación estricta y instrucciones personalizadas.","fr":"Idéal pour les agents d''IA axés sur TypeScript qui recherchent une gestion de projet structurée avec une typification stricte et des instructions personnalisées.","de":"Ideal für TypeScript-fokussierte KI-Agents, die eine strukturierte Projektverwaltung mit strenger Typisierung und benutzerdefinierten Anweisungen suchen.","pt":"Ideal para Agentes de IA focados em TypeScript que buscam gerenciamento de projeto estruturado com digitação estrita e instruções personalizadas.","ru":"Идеально для агентов ИИ, ориентированных на TypeScript, которые стремятся к структурированному управлению проектами с жесткой типизацией и пользовательскими инструкциями.","ar":"مثالية للوكلاء الذكاء الاصطناعي الذين يركزون على TypeScript والذين يبحثون عن إدارة مشروع منظم مع كتابة مشددة وتعليمات مخصصة."},"recommendation":{"en":"Empowers agents to enforce consistent coding standards and best practices using Nest Js and TypeScript, providing a solid foundation for custom project guidelines and strict typing protocols.","zh":"使代理能够使用Nest Js和TypeScript强制执行一致的编码标准和最佳实践，为自定义项目指南和严格的类型协议提供了坚实的基础。","ja":"Nest JsとTypeScriptを使用して、一貫したコード規約とベストプラクティスをエージェントが実施できるようにし、カスタムプロジェクトガイドラインと厳格な型付けプロトコルに堅実な基盤を提供します。","ko":"Nest Js와 TypeScript를 사용하여 에이전트가 일관된 코딩 표준 및 모범 사례를 시행할 수 있도록 하여 사용자 지정 프로젝트 지침 및 엄격한 타이핑 프로토콜에 대한 견고한基础을 제공합니다.","es":"Habilita a los agentes a hacer cumplir normas de codificación consistentes y las mejores prácticas utilizando Nest Js y TypeScript, proporcionando una base sólida para las pautas del proyecto personalizadas y los protocolos de tipificación estricta.","fr":"Permet aux agents de faire respecter des normes de codage cohérentes et les meilleures pratiques en utilisant Nest Js et TypeScript, fournissant une base solide pour les directives de projet personnalisées et les protocoles de typage strict.","de":"Ermächtigt Agents, konsistente Codierungsstandards und Best Practices mithilfe von Nest Js und TypeScript durchzusetzen, und bietet eine solide Grundlage für benutzerdefinierte Projektleitlinien und strenge Typisierungsprotokolle.","pt":"Habilita os agentes a impor padrões de codificação consistentes e as melhores práticas usando Nest Js e TypeScript, fornecendo uma base sólida para diretrizes de projeto personalizadas e protocolos de digitação estrita.","ru":"Позволяет агентам обеспечивать соблюдение единых стандартов кодирования и передового опыта с использованием Nest Js и TypeScript, предоставляя прочную основу для пользовательских руководств по проекту и протоколов жесткой типизации.","ar":"تمكّن الوكلاء من فرض معايير التشفير المترابطة وأفضل الممارسات باستخدام Nest Js وTypeScript، وتوفير أساس قوي لمرشديات المشروع المخصصة وبروتوكولات الكتابة المشددة."},"useCases":{"en":["Defining custom project instructions","Enforcing strict typing conventions","Generating project guidelines for Nest Js applications"],"zh":["定义自定义项目指令","强制执行严格的类型约定","为Nest Js应用程序生成项目指南"],"ja":["カスタムプロジェクト指令を定義する","厳格な型付け規約を強制する","Nest Jsアプリケーションのプロジェクトガイドラインを生成する"],"ko":["사용자 지정 프로젝트 지침 정의","엄격한 타이핑 규칙 적용","Nest Js 애플리케이션에 대한 프로젝트 가이드라인 생성"],"es":["Definir instrucciones de proyecto personalizadas","Hacer cumplir convenciones de tipificación estricta","Generar pautas de proyecto para aplicaciones de Nest Js"],"fr":["Définir des instructions de projet personnalisées","Faire respecter les conventions de typage strict","Générer des directives de projet pour les applications Nest Js"],"de":["Benutzerdefinierte Projektanweisungen definieren","Strenge Typisierungskonventionen durchsetzen","Projektleitlinien für Nest Js-Anwendungen generieren"],"pt":["Definir instruções de projeto personalizadas","Impor convenções de digitação estrita","Gerar diretrizes de projeto para aplicações Nest Js"],"ru":["Определение пользовательских инструкций проекта","Обеспечение соблюдения жестких соглашений типизации","Генерация руководств по проекту для приложений Nest Js"],"ar":["تحديد تعليمات مشروع مخصصة","فرض اتفاقيات الكتابة المشددة","توليد إرشادات مشروع لتطبيقات Nest Js"]},"limitations":{"en":["Requires Nest Js and TypeScript setup","Limited to Backend App development"],"zh":["需要Nest Js和TypeScript设置","仅限后端应用开发"],"ja":["Nest JsとTypeScriptの設定が必要","バックエンドアプリ開発のみ"],"ko":["Nest Js 및 TypeScript 설정이 필요","백엔드 앱 개발만"],"es":["Requiere configuración de Nest Js y TypeScript","Limitado al desarrollo de aplicaciones de backend"],"fr":["Nécessite une configuration de Nest Js et TypeScript","Limité au développement d''applications de backend"],"de":["Benötigt Nest Js- und TypeScript-Setup","Begrenzt auf die Entwicklung von Backend-Anwendungen"],"pt":["Requer configuração do Nest Js e TypeScript","Limitado ao desenvolvimento de aplicativos Backend"],"ru":["Требует настройки Nest Js и TypeScript","Ограничен разработкой приложений Backend"],"ar":["يتطلب إعداد Nest Js وTypeScript","محدود بتطوير تطبيقات Backend"]},"version":4},"contentHash":"6532105588aa59594aa6d796188e8a27182295b02516c97eb4323ca8614edad7","qualityScore":38}');
