INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('carrizoja/Nest-Dating-Backend/Project Guidelines', 'Project Guidelines', 'carrizoja', 'Nest-Dating-Backend', 'community', 'Project Guidelines carrizoja Nest-Dating-Backend community Project Guidelines is a Backend App made with Nest Js and Typescript, providing a foundation for custom instructions and strict typing. It benefits developers working with Nest Js and Typescript. Project Guidelines是一套使用Nest Js和Typescript的后端应用开发指南，帮助开发者高效构建应用 Project Guidelinesは、Nest JsとTypescriptを使用してバックエンドアプリを開発するためのガイドラインです Project Guidelines는 Nest Js와 Typescript를 사용하여 백엔드 애플리케이션을 개발하기 위한 가이드라인입니다 Project Guidelines es una aplicación de backend creada con Nest Js y Typescript que sigue instrucciones personalizadas Project Guidelines est une application backend créée avec Nest Js et Typescript qui suit des instructions personnalisées Project Guidelines ist eine Backend-Anwendung, die mit Nest Js und Typescript erstellt wurde und benutzerdefinierte Anweisungen befolgt Um aplicativo de backend feito com Nest Js e Typescript, com diretrizes de projeto personalizadas Бэкенд-приложение, созданное с помощью Nest Js и Typescript, с настраиваемыми проектными рекомендациями تطبيق خلفي مصنوع مع Nest Js و Typescript ، مع إرشادات مشروع مخصصة how to use Project Guidelines what is Project Guidelines Project Guidelines alternative Project Guidelines vs Nest Js Project Guidelines install Project Guidelines setup guide Nest Js and Typescript development custom instruction implementation strict typing with Typescript Project Guidelines Nest Js Typescript 后端应用开发 技术指南 严格类型检查 自定义项目指南 命名约定 高效开发 Utilizes Nest Js for Backend App development Leverages Typescript for strict typing and code quality Allows for custom instructions and naming conventions Supports adherence to specific coding standards Enables developers to follow best practices with Typescript Project Guidelines is a technical framework for Backend Apps, utilizing Nest Js and Typescript for custom instruction implementation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kreuzberg-dev/html-to-markdown/model-routing', 'community', 'kreuzberg-dev', 'html-to-markdown', 'kreuzberg-dev/html-to-markdown', 'model-routing', 0, 0, 38, '2026-02-27T01:51:08.518Z', '2026-02-27T02:45:23.959Z', '20ca58f04b187057acbc2e581cad158c50f90fa739a2d22814e17dec276dc1f2', '{"id":"kreuzberg-dev/html-to-markdown/model-routing","name":"model-routing","description":{"zh":"model-routing是由Kreuzberg团队维护的高性能HTML到Markdown转换工具，完全兼容CommonMark标准。基于Rust核心构建，支持从56种以上文档格式中提取结构化数据，并提供流式解析器和内置OCR功能。","ja":"model-routingはKreuzbergチームがメンテナンスする高性能なHTML to Markdownコンバーターです。CommonMarkに完全準拠し、Rustコアを基盤に構築。56以上のドキュメント形式から構造化データを抽出し、ストリーミングパーサーと組み込みOCRを提供します。","ko":"model-routing은 Kreuzberg 팀이 유지보수하는 고성능 HTML to Markdown 변환기입니다. CommonMark 표준을 완전히 준수하며 Rust 코어로 구축되었습니다. 56가지 이상의 문서 형식에서 구조화된 데이터를 추출하고 스트리밍 파서와 내장 OCR 기능을 제공합니다.","es":"Model-routing es un convertidor de HTML a Markdown de alto rendimiento y compatible con CommonMark, mantenido por el equipo de Kreuzberg","fr":"Model-routing est un convertisseur HTML en Markdown haute performance et compatible CommonMark, maintenu par l''équipe de Kreuzberg","de":"Model-routing ist ein leistungsstarkes HTML-in-Markdown-Konvertierungs-Tool, das mit CommonMark kompatibel ist und vom Kreuzberg-Team gewartet wird","pt":"O model-routing é uma ferramenta de alto desempenho para conversão de HTML para Markdown, compatível com CommonMark e mantida pela equipe Kreuzberg","ru":"Model-routing - высокопроизводительный инструмент для преобразования HTML в Markdown, совместимый с CommonMark и поддерживаемый командой Kreuzberg","ar":"model-routing هي أداة عالية الأداء لتحويل HTML إلى Markdown، متوافقة مع CommonMark ومدعومة من فريق Kreuzberg","en":"High performance and CommonMark compliant HTML to Markdown converter. Maintained by the Kreuzberg team. Kreuzberg is a fast, polyglot document i