INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kreuzberg-dev/html-to-markdown/model-routing', 'model-routing', 'kreuzberg-dev', 'html-to-markdown', 'community', 'model-routing kreuzberg-dev html-to-markdown community model-routing是由Kreuzberg团队维护的高性能HTML到Markdown转换工具，完全兼容CommonMark标准。基于Rust核心构建，支持从56种以上文档格式中提取结构化数据，并提供流式解析器和内置OCR功能。 model-routingはKreuzbergチームがメンテナンスする高性能なHTML to Markdownコンバーターです。CommonMarkに完全準拠し、Rustコアを基盤に構築。56以上のドキュメント形式から構造化データを抽出し、ストリーミングパーサーと組み込みOCRを提供します。 model-routing은 Kreuzberg 팀이 유지보수하는 고성능 HTML to Markdown 변환기입니다. CommonMark 표준을 완전히 준수하며 Rust 코어로 구축되었습니다. 56가지 이상의 문서 형식에서 구조화된 데이터를 추출하고 스트리밍 파서와 내장 OCR 기능을 제공합니다. Model-routing es un convertidor de HTML a Markdown de alto rendimiento y compatible con CommonMark, mantenido por el equipo de Kreuzberg Model-routing est un convertisseur HTML en Markdown haute performance et compatible CommonMark, maintenu par l''équipe de Kreuzberg Model-routing ist ein leistungsstarkes HTML-in-Markdown-Konvertierungs-Tool, das mit CommonMark kompatibel ist und vom Kreuzberg-Team gewartet wird O model-routing é uma ferramenta de alto desempenho para conversão de HTML para Markdown, compatível com CommonMark e mantida pela equipe Kreuzberg Model-routing - высокопроизводительный инструмент для преобразования HTML в Markdown, совместимый с CommonMark и поддерживаемый командой Kreuzberg model-routing هي أداة عالية الأداء لتحويل HTML إلى Markdown، متوافقة مع CommonMark ومدعومة من فريق Kreuzberg High performance and CommonMark compliant HTML to Markdown converter. Maintained by the Kreuzberg team. Kreuzberg is a fast, polyglot document intelligence engine with a Rust core. It extracts structured data from 56+ document formats using streaming parsers and built-in OCR. model-routing使用教程 HTML转Markdown工具 CommonMark兼容转换器 Kreuzberg文档智能引擎 Rust核心HTML解析 文档OCR提取工具 model-routing安装指南 流式解析器实现 model-routing vs turndown 结构化数据提取工具 High performance and CommonMark compliant HTML to Markdown converter. Maintained by the Kreuzberg team. Kreuzberg is a fast, polyglot document intelligence engine with a Rust core. It extracts structured data from 56+ document formats using streaming parsers and built-in OCR.');
