INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('itmeGirish/BoardingMcp-Server/prayer-agent', 'prayer-agent', 'itmeGirish', 'BoardingMcp-Server', 'community', 'prayer-agent itmeGirish BoardingMcp-Server community The prayer-agent skill generates PRAYER_PACK.json files for Whatsp API, following strict rules and output contracts, benefiting developers and legal professionals. Prayer Agent 是一个 MCP 服务器，为 Whatsp API 提供技术支持，用于生成 PRAYER_PACK.json 文件 Prayer Agent は、Whatsp API 用の PRAYER_PACK.json ファイルを生成する MCP サーバーです Prayer Agent는 Whatsp API용 PRAYER_PACK.json 파일을 생성하는 MCP 서버입니다 Prayer Agent es un servidor MCP para la API de WhatSp que genera archivos PRAYER_PACK.json con reglas estrictas y lenguaje formal de tribunal. Prayer Agent est un serveur MCP pour l''API WhatSp qui génère des fichiers PRAYER_PACK.json avec des règles strictes et un langage formel de tribunal. Prayer Agent ist ein MCP-Server für die WhatSp-API, der Dateien im PRAYER_PACK.json-Format mit strengen Regeln und formalem Gerichtssprachgebrauch erstellt. O Prayer-Agent é um servidor MCP para a API WhatSp que gera PRAYER_PACK.json com base em regras rigorosas e linguagem formal de tribunal. ИИ Агент Prayer-Agent - это сервер MCP для API WhatSp, который генерирует PRAYER_PACK.json на основе строгих правил и формального языка суда. Prayer-Agent هو خادم MCP ل API WhatSp يولد PRAYER_PACK.json بناءً على قواعد صارمة و لغة محكمة رسمية. how to use prayer-agent prayer-agent setup guide prayer-agent vs Whatsp API prayer-agent install what is prayer-agent prayer-agent alternative prayer-agent MCP server PRAYER_PACK.json generation Whatsp API integration Prayer Agent MCP 服务器 Whatsp API PRAYER_PACK.json AI 工具 AI エージェント 法庭语言 技术集成 Generates PRAYER_PACK.json files with strict JSON output contracts Follows hard rules for prayer matching and relief requests Includes ''such other orders'' clause in output Uses formal court language and ''this Hon''ble Court'' phrasing Avoids aggressive accusations unless facts are present Supports Whatsp API integration via MCP server Prayer-agent is a MCP server skill for generating PRAYER_PACK.json files, adhering to specific technical standards and rules for Whatsp API integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HerbertGao/qsl-cardhub/openspec-onboard', 'community', 'HerbertGao', 'qsl-cardhub', 'HerbertGao/qsl-cardhub', 'openspec-onboard', 0, 0, 38, '2026-03-06T12:59:22.233Z', '2026-03-06T14:21:48.665Z', '8a664b397a911fbd23ff787ee95e303ff38b88747d70ee05f4eb55ef1e79048a', '{"id":"HerbertGao/qsl-cardhub/openspec-onboard","name":"openspec-onboard","description":{"en":"The openspec-onboard skill guides users through their first complete OpenSpec workflow cycle, providing a hands-on teaching experience. It benefits developers by explaining each step in the process.","zh":"OpenSpec-onboard技能引导用户完成第一个完整的OpenSpec工作流周期，包括初始化、任务选择、变更创建和实现","ja":"OpenSpec-onboardスキルは、ユーザーをOpenSpecの初期化からタスクの実装までのワークフローサイクルを通して導きます","ko":"OpenSpec-onboard 스킬은 사용자를 OpenSpec 초기화에서 작업 구현까지의 워크플로우 사이클을 통해 안내합니다","es":"El skill openspec-onboard te guía a través de un flujo de trabajo completo de OpenSpec, desde la idea hasta la implementación, utilizando tareas reales de tu código","fr":"Le skill openspec-onboard vous guide à travers un flux de travail complet OpenSpec, de l''idée à la mise en œuvre, en utilisant des tâches réelles de votre code","de":"Der Skill openspec-onboard führt Sie durch einen kompletten OpenSpec-Workflow, von der Idee bis zur Implementierung, unter Verwendung von realen Aufgaben aus Ihrem Code","pt":"O openspec-onboard é uma ferramenta que guia os usuários por um fluxo de trabalho completo de OpenSpec","ru":"openspec-onboard - это инструмент, который проводит пользователей через полный рабочий процесс OpenSpec","ar":"openspec-onboard هو أداة تقود المستخدمين خلال تدفق عمل كامل ل OpenSpec"},"seo":{"title":{"en":"openspec-onboard: Interactive Onboarding Setup Guide | AI...","zh":"OpenSpec入门指南：开启您的第一个工作流周期","ja":"OpenSpecのセットアップガイド：AIエージェントを使用した初めてのワークフローサイクル","ko":"OpenSpec 시작하기: 첫 번째 워크플로우 사이클을 위한 온보딩 가이드","es":"Guía de configuración de openspec-onboard: Implementación...","fr":"Guide de configuration d''openspec-onboard : Mise en œuvre...","de":"Einrichtungsleitfaden für openspec-onboard: Implementieru...","pt":"Guia de Configuração do openspec-onboard: Fluxo de Trabal...","ru":"ИИ Агенты: Руководство по настройке openspec-onboard","ar":"دليل إعداد openspec-onboard: تدفق عمل كامل"},"description":{"en":"Get started with openspec-onboard and learn how to complete a full OpenSpec workflow cycle with our interactive onboarding process - try it now!","zh":"通过OpenSpec-onboard技能，学习如何初始化OpenSpec、选择任务、创建变更、构建产出物和实现任务","ja":"OpenSpec-onboardスキルを使用して、OpenSpecの初期化からタスクの実装までのワークフローサイクルをマスターしましょう","ko":"OpenSpec-onboard 스킬을 통해 OpenSpec 초기화, 작업 선택, 변경 생성, 산출물 생성 및 작업 구현을 학습하세요","es":"Aprende a configurar openspec-onboard y a implementar flujos de trabajo de OpenSpec en tu proyecto con esta guía paso a paso","fr":"Découvrez comment configurer openspec-onboard et mettre en œuvre des flux de travail OpenSpec dans votre projet avec ce guide étape par étape","de":"Erfahren Sie, wie Sie openspec-onboard konfigurieren und OpenSpec-Workflows in Ihrem Projekt implementieren können, mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o openspec-onboard e execute um fluxo de trabalho completo em 15-20 minutos","ru":"Настройте openspec-onboard и выполните полный рабочий процесс за 15-20 минут с помощью ИИ Агентов","ar":"تعلم كيفية إعداد openspec-onboard وتنفيذ تدفق عمل كامل في 15-20 دقيقة"},"definition":{"en":"openspec-onboard is a skill that provides an interactive onboarding experience for OpenSpec, guiding users through a complete workflow cycle.","zh":"OpenSpec-onboard是指引用户完成第一个OpenSpec工作流周期的技能，涵盖初始化、任务选择、变更创建和实现等步骤","ja":"OpenSpec-onboardは、ユーザーをOpenSpecのワークフローサイクルを通して導くスキルであり、初期化、タスクの選択、変更の作成、実装などを含みます","ko":"OpenSpec-onboard는 사용자를 OpenSpec 워크플로우 사이클을 통해 안내하는 스킬로, 초기화, 작업 선택, 변경 생성 및 구현 등의 단계를 포함합니다","es":"openspec-onboard es un skill que te ayuda a configurar y implementar flujos de trabajo de OpenSpec en tu proyecto","fr":"openspec-onboard est un skill qui vous aide à configurer et à mettre en œuvre des flux de travail OpenSpec dans votre projet","de":"openspec-onboard ist ein Skill, der Ihnen hilft, OpenSpec-Workflows in Ihrem Projekt zu konfigurieren und zu implementieren","pt":"O que é openspec-onboard? É uma ferramenta de auxílio ao usuário para executar um fluxo de trabalho de OpenSpec","ru":"Что такое openspec-onboard? Это инструмент, помогающий пользователям выполнить рабочий процесс OpenSpec","ar":"ما هو openspec-onboard؟ هو أداة مساعدة للمستخدمين لتنفيذ تدفق عمل OpenSpec"},"features":{"en":["Checks OpenSpec initialization status using `openspec-cn status --json` command","Initializes OpenSpec project using `openspec-cn init` command if not already set up","Guides users through a 6-step workflow process, from idea to implementation","Creates a change (container for work) and builds output: proposal, specification, design, and task","Implements tasks and archives completed changes","Provides a ~15-20 minute interactive onboarding experience"],"zh":["初始化OpenSpec","选择真实任务","创建变更","构建产出物：提案、规格说明、设计、任务","实现任务","归档完成的变更"],"ja":["OpenSpecの初期化","実際のタスクの選択","変更の作成","成果物の構築：提案、仕様書、設計、タスク","タスクの実装","完了した変更のアーカイブ"],"ko":["OpenSpec 초기화","실제 작업 선택","변경 생성","산출물 생성：제안, 사양서, 설계, 작업","작업 구현","완료된 변경의 아카이빙"],"es":["Configuración de OpenSpec con el comando `openspec-cn init`","Creación de un cambio en tu código con el comando `openspec-cn status`","Implementación de un flujo de trabajo completo de OpenSpec, desde la idea hasta la implementación","Uso de tareas reales de tu código para ilustrar el flujo de trabajo","Exploración del problema y creación de un cambio","Implementación de la tarea y archivo del cambio completado"],"fr":["Configuration d''OpenSpec avec la commande `openspec-cn init`","Création d''un changement dans votre code avec la commande `openspec-cn status`","Mise en œuvre d''un flux de travail complet OpenSpec, de l''idée à la mise en œuvre","Utilisation de tâches réelles de votre code pour illustrer le flux de travail","Exploration du problème et création d''un changement","Mise en œuvre de la tâche et archivage du changement complet"],"de":["Konfiguration von OpenSpec mit dem Befehl `openspec-cn init`","Erstellung einer Änderung in Ihrem Code mit dem Befehl `openspec-cn status`","Implementierung eines kompletten OpenSpec-Workflows, von der Idee bis zur Implementierung","Verwendung von realen Aufgaben aus Ihrem Code, um den Workflow zu veranschaulichen","Untersuchung des Problems und Erstellung einer Änderung","Implementierung der Aufgabe und Archivierung der abgeschlossenen Änderung"],"pt":["Verificação de inicialização do OpenSpec","Criação de um contêiner de alteração","Construção de saídas: proposta, especificação, design e tarefa","Implementação de tarefas","Arquivamento de alterações concluídas"],"ru":["Проверка инициализации OpenSpec","Создание контейнера изменений","Построение выходных данных: предложение, спецификация, дизайн и задача","Реализация задач","Архивация завершенных изменений"],"ar":["التحقق من 초기ته OpenSpec","إنشاء حاوية للتغيير","بناء الإخراج: المقترح، المواصفات، التصميم والمهمة","تنفيذ المهام","أرشفة التغييرات المكتملة"]},"keywords":{"en":["how to use openspec-onboard","openspec-onboard setup guide","openspec-onboard vs openspec-cn","openspec-onboard install","what is openspec-onboard","openspec-onboard alternative","openspec-onboard tutorial","openspec-onboard workflow cycle","openspec-onboard interactive onboarding"],"zh":["OpenSpec入门","OpenSpec工作流","AI工具","代码库管理","变更管理","任务实现","OpenSpec初始化","OpenSpec技能"],"ja":["OpenSpecのセットアップ","OpenSpecワークフロー","AIエージェント","コードライブラリの管理","変更の管理","タスクの実装","OpenSpecの初期化","OpenSpecスキル"],"ko":["OpenSpec 시작하기","OpenSpec 워크플로우","AI 툴","코드 라이ブラ리의 관리","변경의 관리","작업의 구현","OpenSpec 초기화","OpenSpec 스킬"],"es":["openspec-onboard","OpenSpec","flujo de trabajo","configuración","implementación","tareas reales","código","desarrollo de software","herramientas de desarrollo","agentes de IA"],"fr":["openspec-onboard","OpenSpec","flux de travail","configuration","mise en œuvre","tâches réelles","code","développement de logiciels","outils de développement","agents d''IA"],"de":["openspec-onboard","OpenSpec","Workflow","Konfiguration","Implementierung","reale Aufgaben","Code","Software-Entwicklung","Entwicklertools","KI-Agents"],"pt":["openspec-onboard","fluxo de trabalho de OpenSpec","configuração do OpenSpec","ferramentas de auxílio ao usuário","desenvolvimento de software","CLI","bash"],"ru":["openspec-onboard","рабочий процесс OpenSpec","настройка OpenSpec","инструменты помощи пользователям","разработка программного обеспечения","ИИ Агенты","CLI","bash"],"ar":["openspec-onboard","تدفق عمل OpenSpec","إعداد OpenSpec","أدوات مساعدة للمستخدمين","تطوير البرمجيات","أدوات الذكاء الاصطناعي","CLI","bash"]}},"owner":"HerbertGao","repo":"qsl-cardhub","repoPath":"HerbertGao/qsl-cardhub","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.233Z","topics":[],"category":"community","skillMd":{"name":"openspec-onboard","description":"OpenSpec 引导式入门 - 通过讲解与在真实代码库中动手，走完一个完整的工作流周期。","version":"1.0","bodyPreview":"引导用户完成他们的第一个完整OpenSpec工作流周期。这是一个教学体验——你将在他们的代码库中完成实际工作，同时解释每个步骤。\n\n---\n\n## 准备阶段\n\n开始前，检查OpenSpec是否已初始化：\n\n```bash\nopenspec-cn status --json 2>&1 || echo \"NOT_INITIALIZED\"\n```\n\n**如果未初始化：**\n> OpenSpec尚未在此项目中设置。请先运行 `openspec-cn init`，然后返回 `/opsx:onboard`。\n\n如果未初始化，请在此停止。\n\n---\n\n## 阶段1：欢迎\n\n显示：\n\n```\n## 欢迎使用OpenSpec！\n\n我将引导您完成一个完整的变更周期——从想法到实现——使用您代码库中的真实任务。在此过程中，您将通过实践学习工作流程。\n\n**我们将要做的事情：**\n1. 在您的代码库中选择一个小的真实任务\n2. 简要探索问题\n3. 创建一个变更（我们工作的容器）\n4. 构建产出物：提案 → 规格说明 → 设计 → 任务\n5. 实现任务\n6. 归档完成的变更\n\n**时间：** ~15-20分钟","body":"引导用户完成他们的第一个完整OpenSpec工作流周期。这是一个教学体验——你将在他们的代码库中完成实际工作，同时解释每个步骤。\n\n---\n\n## 准备阶段\n\n开始前，检查OpenSpec是否已初始化：\n\n```bash\nopenspec-cn status --json 2>&1 || echo \"NOT_INITIALIZED\"\n```\n\n**如果未初始化：**\n> OpenSpec尚未在此项目中设置。请先运行 `openspec-cn init`，然后返回 `/opsx:onboard`。\n\n如果未初始化，请在此停止。\n\n---\n\n## 阶段1：欢迎\n\n显示：\n\n```\n## 欢迎使用OpenSpec！\n\n我将引导您完成一个完整的变更周期——从想法到实现——使用您代码库中的真实任务。在此过程中，您将通过实践学习工作流程。\n\n**我们将要做的事情：**\n1. 在您的代码库中选择一个小的真实任务\n2. 简要探索问题\n3. 创建一个变更（我们工作的容器）\n4. 构建产出物：提案 → 规格说明 → 设计 → 任务\n5. 实现任务\n6. 归档完成的变更\n\n**时间：** ~15-20分钟\n\n让我们开始寻找要处理的内容。\n```\n\n---\n\n## 阶段2：任务选择\n\n### 代码库分析\n\n扫描代码库寻找小的改进机会。寻找：\n\n1. **TODO/FIXME注释** - 在代码文件中搜索 `TODO`、`FIXME`、`HACK`、`XXX`\n2. **缺少错误处理** - 吞没错误的 `catch` 块，没有try-catch的风险操作\n3. **没有测试的函数** - 交叉引用 `src/` 和测试目录\n4. **类型问题** - TypeScript文件中的 `any` 类型（`: any`、`as any`）\n5. **调试产出物** - 非调试代码中的 `console.log`、`console.debug`、`debugger` 语句\n6. **缺少验证** - 没有验证的用户输入处理程序\n\n同时检查最近的git活动：\n```bash\ngit log --oneline -10 2>/dev/null || echo \"No git history\"\n```\n\n### 提出建议\n\n根据您的分析，提出3-4个具体建议：\n\n```\n## 任务建议\n\n基于扫描您的代码库，以下是一些好的入门任务：\n\n**1. [最有希望的任务]**\n   位置：`src/path/to/file.ts:42`\n   范围：~1-2个文件，~20-30行\n   为什么好：[简要原因]\n\n**2. [第二个任务]**\n   位置：`src/another/file.ts`\n   范围：~1个文件，~15行\n   为什么好：[简要原因]\n\n**3. [第三个任务]**\n   位置：[位置]\n   范围：[估计]\n   为什么好：[简要原因]\n\n**4. 其他内容？**\n   告诉我您想要处理什么。\n\n哪个任务让您感兴趣？（选择一个数字或描述您自己的）\n```\n\n**如果未找到任何内容：** 回退到询问用户想要构建什么：\n> 我在您的代码库中没有找到明显的快速改进机会。您一直想要添加或修复什么小东西？\n\n### 范围护栏\n\n如果用户选择或描述的内容太大（主要功能，多天工作）：\n\n```\n这是一个有价值的任务，但对于您的第一次OpenSpec体验来说可能太大了。\n\n对于学习工作流程，越小越好——它让您能够看到完整周期而不会陷入实现细节。\n\n**选项：**\n1. **切分成更小的部分** - [他们的任务]中最小的有用部分是什么？也许只是[具体切片]？\n2. **选择其他内容** - 其他建议之一，或不同的任务？\n3. **无论如何都做** - 如果您真的想处理这个，我们可以做。只是要知道需要更长时间。\n\n您更喜欢哪种？\n```\n\n如果用户坚持，让他们覆盖——这是一个软护栏。\n\n---\n\n## 阶段3：探索演示\n\n一旦选择了任务，简要演示探索模式：\n\n```\n在我们创建变更之前，让我快速向您展示**探索模式**——这是在承诺方向之前思考问题的方式。\n```\n\n花1-2分钟调查相关代码：\n- 阅读涉及的文件\n- 如果需要，绘制快速ASCII图表\n- 注意任何考虑事项\n\n```\n## 快速探索\n\n[您的简要分析——您发现了什么，任何考虑事项]\n\n┌─────────────────────────────────────────┐\n│   [可选：如果有帮助的ASCII图表]          │\n└─────────────────────────────────────────┘\n\n探索模式（`/opsx:explore`）用于这种思考——在实现之前进行调查。您可以在需要思考问题时随时使用它。\n\n现在让我们创建一个变更来保存我们的工作。\n```\n\n**暂停** - 等待用户确认后再继续。\n\n---\n\n## 阶段4：创建变更\n\n**解释：**\n```\n## 创建变更\n\nOpenSpec中的\"变更\"是围绕一项工作的所有思考和规划的容器。它位于 `openspec/changes/<name>/` 中，保存您的产出物——提案、规格说明、设计、任务。\n\n让我为我们的任务创建一个。\n```\n\n**执行：** 使用派生的kebab-case名称创建变更：\n```bash\nopenspec-cn new change \"<derived-name>\"\n```\n\n**显示：**\n```\n已创建：`openspec/changes/<name>/`\n\n文件夹结构：\n```\nopenspec/changes/<name>/\n├── proposal.md    ← 为什么我们要做这个（空，我们将填充它）\n├── design.md      ← 我们将如何构建它（空）\n├── specs/         ← 详细需求（空）\n└── tasks.md       ← 实现检查清单（空）\n```\n\n现在让我们填充第一个产出物——提案。\n```\n\n---\n\n## 阶段5：提案\n\n**解释：**\n```\n## 提案\n\n提案捕获**为什么**我们要进行此变更以及**什么**在高层级上涉及。这是工作的\"电梯演讲\"。\n\n我将根据我们的任务起草一个。\n```\n\n**执行：** 起草提案内容（暂时不保存）：\n\n```\n这是一个草案提案：\n\n---\n\n## 为什么\n\n[1-2句话解释问题/机会]\n\n## 什么变化\n\n[将要不同的要点]\n\n## 能力\n\n### 新能力\n- `<能力名称>`: [简要描述]\n\n### 修改的能力\n<!-- 如果修改现有行为 -->\n\n## 影响\n\n- `src/path/to/file.ts`: [什么变化]\n- [其他文件如果适用]\n\n---\n\n这能捕捉意图吗？我可以在保存前调整。\n```\n\n**暂停** - 等待用户批准/反馈。\n\n批准后，保存提案：\n```bash\nopenspec-cn instructions proposal --change \"<name>\" --json\n```\n然后将内容写入 `openspec/changes/<name>/proposal.md`。\n\n```\n提案已保存。这是您的\"为什么\"文档——您随时可以回来在理解发展时完善它。\n\n接下来：规格说明。\n```\n\n---\n\n## 阶段6：规格说明\n\n**解释：**\n```\n## 规格说明\n\n规格说明以精确、可测试的术语定义**什么**我们正在构建。它们使用需求/场景格式，使预期行为清晰明了。\n\n对于像这样的小任务，我们可能只需要一个规格说明文件。\n```\n\n**执行：** 创建规格说明文件：\n```bash\nmkdir -p openspec/changes/<name>/specs/<capability-name>\n```\n\n起草规格说明内容：\n\n```\n这是规格说明：\n\n---\n\n## 新增需求\n\n### 需求：<名称>\n\n<系统应该做什么的描述>\n\n#### 场景：<场景名称>\n\n- **当** <触发条件>\n- **那么** <预期结果>\n- **并且** <如果需要额外结果>\n\n---\n\n这种格式——当/那么/并且——使需求可测试。您可以将它们字面地读作测试用例。\n```\n\n保存到 `openspec/changes/<name>/specs/<capability>/spec.md`。\n\n---\n\n## 阶段7：设计\n\n**解释：**\n```\n## 设计\n\n设计捕获**如何**我们将构建它——技术决策、权衡、方法。\n\n对于小变更，这可能很简短。没关系——不是每个变更都需要深入的设计讨论。\n```\n\n**执行：** 起草design.md：\n\n```\n这是设计：\n\n---\n\n## 上下文\n\n[关于当前状态的简要上下文]\n\n## 目标/非目标\n\n**目标：**\n- [我们试图实现什么]\n\n**非目标：**\n- [明确超出范围的内容]\n\n## 决策\n\n### 决策1：[关键决策]\n\n[方法解释和理由]\n\n---\n\n对于小任务，这捕获了关键决策而不过度工程化。\n```\n\n保存到 `openspec/changes/<name>/design.md`。\n\n---\n\n## 阶段8：任务\n\n**解释：**\n```\n## 任务\n\n最后，我们将工作分解为实现任务——驱动应用阶段的复选框。\n\n这些应该小、清晰且逻辑顺序。\n```\n\n**执行：** 基于规格说明和设计生成任务：\n\n```\n这是实现任务：\n\n---\n\n## 1. [类别或文件]\n\n- [ ] 1.1 [具体任务]\n- [ ] 1.2 [具体任务]\n\n## 2. 验证\n\n- [ ] 2.1 [验证步骤]\n\n---\n\n每个复选框成为应用阶段的工作单元。准备好实现了吗？\n```\n\n**暂停** - 等待用户确认他们准备好实现。\n\n保存到 `openspec/changes/<name>/tasks.md`。\n\n---\n\n## 阶段9：应用（实现）\n\n**解释：**\n```\n## 实现\n\n现在我们实现每个任务，在过程中勾选它们。我将宣布每个任务，并偶尔注意规格说明/设计如何影响方法。\n```\n\n**执行：** 对于每个任务：\n\n1. 宣布：\"正在处理任务N：[描述]\"\n2. 在代码库中实现变更\n3. 自然地引用规格说明/设计：\"规格说明说X，所以我做Y\"\n4. 在tasks.md中标记完成：`- [ ]` → `- [x]`\n5. 简要状态：\"✓ 任务N完成\"\n\n保持叙述轻量——不要过度解释每一行代码。\n\n所有任务后：\n\n```\n## 实现完成\n\n所有任务完成：\n- [x] 任务1\n- [x] 任务2\n- [x] ...\n\n变更已实现！还有一个步骤——让我们归档它。\n```\n\n---\n\n## 阶段10：归档\n\n**解释：**\n```\n## 归档\n\n当变更完成时，我们归档它。这将把它从 `openspec/changes/` 移动到 `openspec/changes/archive/YYYY-MM-DD-<name>/`。\n\n归档的变更成为您项目的决策历史——您随时可以找到它们来理解为什么某物以某种方式构建。\n```\n\n**执行：**\n```bash\nopenspec-cn archive \"<name>\"\n```\n\n**显示：**\n```\n已归档到：`openspec/changes/archive/YYYY-MM-DD-<name>/`\n\n变更现在是您项目历史的一部分。代码在您的代码库中，决策记录被保留。\n```\n\n---\n\n## 阶段11：回顾与下一步\n\n```\n## 恭喜！\n\n您刚刚完成了一个完整的OpenSpec周期：\n\n1. **探索** - 思考问题\n2. **新建** - 创建变更容器\n3. **提案** - 捕获为什么\n4. **规格说明** - 详细定义什么\n5. **设计** - 决定如何\n6. **任务** - 分解为步骤\n7. **应用** - 实现工作\n8. **归档** - 保留记录\n\n同样的节奏适用于任何大小的变更——小修复或主要功能。\n\n---\n\n## 命令参考\n\n| 命令 | 做什么 |\n|---------|--------------|\n| `/opsx:explore` | 在工作之前/期间思考问题 |\n| `/opsx:new` | 开始新变更，逐步通过产出物 |\n| `/opsx:ff` | 快进：一次创建所有产出物 |\n| `/opsx:continue` | 继续处理现有变更 |\n| `/opsx:apply` | 实现变更中的任务 |\n| `/opsx:verify` | 验证实现是否匹配产出物 |\n| `/opsx:archive` | 归档完成的变更 |\n\n---\n\n## 下一步是什么？\n\n尝试 `/opsx:new` 或 `/opsx:ff` 在您实际想要构建的内容上。您现在掌握了节奏！\n```\n\n---\n\n## 优雅退出处理\n\n### 用户想要中途停止\n\n如果用户说他们需要停止、想要暂停或似乎不投入：\n\n```\n没问题！您的变更保存在 `openspec/changes/<name>/`。\n\n要在以后继续：\n- `/opsx:continue <name>` - 恢复产出物创建\n- `/opsx:apply <name>` - 跳转到实现（如果任务存在）\n\n工作不会丢失。随时回来。\n```\n\n优雅退出，不施加压力。\n\n### 用户只想要命令参考\n\n如果用户说他们只想看命令或跳过教程：\n\n```\n## OpenSpec快速参考\n\n| 命令 | 做什么 |\n|---------|--------------|\n| `/opsx:explore` | 思考问题（无代码更改） |\n| `/opsx:new <name>` | 开始新变更，逐步进行 |\n| `/opsx:ff <name>` | 快进：一次创建所有产出物 |\n| `/opsx:continue <name>` | 继续现有变更 |\n| `/opsx:apply <name>` | 实现任务 |\n| `/opsx:verify <name>` | 验证实现 |\n| `/opsx:archive <name>` | 完成后归档 |\n\n尝试 `/opsx:new` 开始您的第一个变更，或 `/opsx:ff` 如果您想快速移动。\n```\n\n优雅退出。\n\n---\n\n## 护栏\n\n- **遵循解释→执行→显示→暂停模式**在关键转换点（探索后、提案草案后、任务后、归档后）\n- **在实现期间保持叙述轻量**——教学而不说教\n- **不要跳过阶段**即使变更很小——目标是教学工作流程\n- **在标记点暂停等待确认**，但不要过度暂停\n- **优雅处理退出**——从不施压用户继续\n- **使用真实代码库任务**——不模拟或使用虚假示例\n- **温和调整范围**——引导向更小任务但尊重用户选择\n"},"lastSynced":"2026-03-06T14:21:48.665Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing guided OpenSpec workflow integration.","zh":"非常适合需要指导的OpenSpec工作流集成的开发代理。","ja":"OpenSpecワークフロー統合を必要とする開発エージェントに最適です。","ko":"OpenSpec 워크플로 통합을 필요로 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan integración de flujo de trabajo OpenSpec guiada.","fr":"Parfait pour les agents de développement nécessitant une intégration de workflow OpenSpec guidée.","de":"Perfekt für Entwicklungsmittel benötigende Agenten, die eine geleitete OpenSpec-Workflow-Integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de integração de fluxo de trabalho OpenSpec orientada.","ru":"Идеально подходит для агентов разработки, которым необходима интеграция рабочего процесса OpenSpec с руководством.","ar":"مثالي للوكلاء الناشئين الذين يحتاجون إلى إدماج سير عمل OpenSpec موجه."},"recommendation":{"en":"Empowers agents to navigate the OpenSpec workflow cycle, providing hands-on experience with openspec-cn initialization, status checks, and workflow steps like creating changes, building outputs, and implementing tasks, all within a code repository using bash commands and JSON outputs.","zh":"赋予代理导航OpenSpec工作流周期的能力，提供使用openspec-cn初始化、状态检查和工作流步骤（如创建更改、构建输出和实现任务）进行实践经验，所有这些都在使用bash命令和JSON输出的代码仓库中进行。","ja":"OpenSpecワークフロー周期をナビゲートするエージェントをEmpowerし、openspec-cnの初期化、ステータスチェック、およびワークフローのステップ（変更の作成、出力の構築、タスクの実装など）に関するハンドスオンエクスペリエンスを提供します。すべてのコードリポジトリ内でbashコマンドとJSON出力を使用して行われます。","ko":"OpenSpec 워크플로 사이클을 탐색할 수 있는 에이전트를 강화하여 openspec-cn 초기화, 상태 확인 및 워크플로우 단계(변경 사항 만들기, 출력 빌드, 작업 구현 등)에 대한 실践 경험을 제공하고 코드 저장소에서 bash 명령과 JSON 출력을 사용하여 모든 것을 처리합니다.","es":"Habilita a los agentes a navegar por el ciclo de flujo de trabajo OpenSpec, proporcionando experiencia práctica con la inicialización de openspec-cn, comprobaciones de estado y pasos de flujo de trabajo como la creación de cambios, la generación de resultados y la implementación de tareas, todo dentro de un repositorio de código utilizando comandos bash y resultados JSON.","fr":"Permet aux agents de naviguer dans le cycle de workflow OpenSpec, en fournissant une expérience pratique avec l''initialisation de openspec-cn, les vérifications d''état et les étapes de workflow comme la création de modifications, la construction de sorties et la mise en œuvre de tâches, le tout dans un référentiel de code en utilisant des commandes bash et des sorties JSON.","de":"Ermächtigt die Agenten, den OpenSpec-Workflow-Zyklus zu navigieren und bietet praktische Erfahrung mit der Initialisierung von openspec-cn, Statusprüfungen und Workflow-Schritten wie der Erstellung von Änderungen, der Erstellung von Ausgaben und der Implementierung von Aufgaben, alles innerhalb eines Code-Repositorys unter Verwendung von Bash-Befehlen und JSON-Ausgaben.","pt":"Habilita os agentes a navegar pelo ciclo de fluxo de trabalho OpenSpec, fornecendo experiência prática com inicialização openspec-cn, verificações de status e etapas de fluxo de trabalho, como criar alterações, construir saídas e implementar tarefas, tudo dentro de um repositório de código usando comandos bash e saídas JSON.","ru":"Наделяет агентов возможностью ориентироваться в цикле рабочего процесса OpenSpec, обеспечивая практический опыт с инициализацией openspec-cn, проверками статуса и шагами рабочего процесса, такими как создание изменений, сбор выводов и реализация задач, все в рамках репозитория кода с использованием команд bash и выходных данных JSON.","ar":"تمكّن الوكلاء من التنقل في دورة سير عمل OpenSpec، وتوفير خبرة عملية مع التهيئة openspec-cn، وفحوصات الحالة، وخطوات سير العمل، مثل إنشاء التغييرات، وبناء الإخراج، وتنفيذ المهام، وكل ذلك داخل مستودع الشفرة باستخدام أوامر bash وإخراج JSON."},"useCases":{"en":["Onboarding new developers to OpenSpec workflows","Guiding users through their first complete OpenSpec workflow cycle","Explaining each step of the OpenSpec process for better understanding"],"zh":["将新开发人员纳入OpenSpec工作流","引导用户完成他们的第一个完整OpenSpec工作流周期","解释OpenSpec流程的每个步骤以获得更好的理解"],"ja":["OpenSpecワークフローを使用した新しい開発者のオンボーディング","ユーザーを最初の完全なOpenSpecワークフロー周期に導く","OpenSpecプロセスの各ステップを説明してより良い理解を得る"],"ko":["OpenSpec 워크플로를 사용하는 새로운 개발자 온보딩","사용자를 첫 번째 완전한 OpenSpec 워크플로 사이클로 안내","OpenSpec 프로세스의 각 단계를 설명하여 더 나은 이해를 얻음"],"es":["Incorporación de nuevos desarrolladores a los flujos de trabajo OpenSpec","Guía a los usuarios a través de su primer ciclo de flujo de trabajo OpenSpec completo","Explicación de cada paso del proceso OpenSpec para una mejor comprensión"],"fr":["Intégration de nouveaux développeurs aux workflows OpenSpec","Guidage des utilisateurs à travers leur premier cycle de workflow OpenSpec complet","Explication de chaque étape du processus OpenSpec pour une meilleure compréhension"],"de":["Einarbeitung neuer Entwickler in OpenSpec-Workflows","Anleitung der Benutzer durch ihren ersten vollständigen OpenSpec-Workflow-Zyklus","Erklärung jedes Schritts im OpenSpec-Prozess für ein besseres Verständnis"],"pt":["Integração de novos desenvolvedores aos fluxos de trabalho OpenSpec","Orientação de usuários em seu primeiro ciclo de fluxo de trabalho OpenSpec completo","Explicação de cada etapa do processo OpenSpec para melhor compreensão"],"ru":["Внедрение новых разработчиков в рабочие процессы OpenSpec","Проведение пользователей через их первый полный цикл рабочего процесса OpenSpec","Объяснение каждого шага процесса OpenSpec для лучшего понимания"],"ar":["دمج المطورين الجدد في سير عمل OpenSpec","توجيه المستخدمين خلال دورتهم الأولى الكاملة من سير عمل OpenSpec","شرح كل خطوة من خطوات عملية OpenSpec لفهم أفضل"]},"limitations":{"en":["Requires openspec-cn initialization","Needs access to the code repository","Limited to guiding the first complete OpenSpec workflow cycle"],"zh":["需要openspec-cn初始化","需要访问代码仓库","仅限于指导第一次完整的OpenSpec工作流周期"],"ja":["openspec-cnの初期化が必要","コードリポジトリへのアクセスが必要","最初の完全なOpenSpecワークフロー周期のガイダンスのみ"],"ko":["openspec-cn 초기화 필요","코드 저장소에 대한 액세스 필요","첫 번째 완전한 OpenSpec 워크플로 사이클에 대한 안내만"],"es":["Requiere inicialización de openspec-cn","Necesita acceso al repositorio de código","Limitado a guiar el primer ciclo de flujo de trabajo OpenSpec completo"],"fr":["Nécessite l''initialisation de openspec-cn","Nécessite l''accès au référentiel de code","Limité à guider le premier cycle de workflow OpenSpec complet"],"de":["Benötigt die Initialisierung von openspec-cn","Benötigt den Zugriff auf das Code-Repository","Begrenzt auf die Anleitung des ersten vollständigen OpenSpec-Workflow-Zyklus"],"pt":["Exige inicialização openspec-cn","Necessita acesso ao repositório de código","Limitado a orientar o primeiro ciclo de fluxo de trabalho OpenSpec completo"],"ru":["Требует инициализации openspec-cn","Требует доступа к репозиторию кода","Ограничен руководством только первым полным циклом рабочего процесса OpenSpec"],"ar":["يتطلب تهيئة openspec-cn","يحتاج إلى الوصول إلى مستودع الشفرة","محدود بتوجيه الدورة الأولى الكاملة من سير عمل OpenSpec"]},"version":4},"contentHash":"8a664b397a911fbd23ff787ee95e303ff38b88747d70ee05f4eb55ef1e79048a","qualityScore":38}');
