INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Adrian-opo/multitool-app/Swift 6 Paradigm Shift Guide', 'Swift 6 Paradigm Shift Guide', 'Adrian-opo', 'multitool-app', 'community', 'Swift 6 Paradigm Shift Guide Adrian-opo multitool-app community The Swift 6 Paradigm Shift Guide helps developers transition to systems programming, covering language fundamentals, system architecture, and concurrency safety. It benefits developers working on embedded microcontrollers to distributed server clusters. Swift 6 Paradigm Shift Guide 提供了对 Swift 6 语言基础、系统架构和并发安全的全面分析 Swift 6 パラダイムシフトガイドは、Swift 6 の言語基礎、システムアーキテクチャ、並行性の安全性に関する包括的な分析を提供します Swift 6 패러다임 시프트 가이드는 Swift 6의 언어 기본, 시스템 아키텍처, 및 병렬성 안전성에 대한 종합적인 분석을 제공합니다 Swift 6 es una versión revolucionaria que marca la transición de un lenguaje de aplicación de alto nivel a un lenguaje de programación de sistemas verdadero Swift 6 est une version révolutionnaire qui marque la transition d''un langage d''application de haut niveau à un langage de programmation système véritable Swift 6 ist eine revolutionsäre Version, die den Übergang von einer High-Level-Anwendungsprache zu einer wahren Systemprogrammiersprache markiert O Swift 6 marca uma transição para uma linguagem de programação de sistemas verdadeira, com capacidades de concorrência e arquitetura de sistema Swift 6 представляет собой переход к真正шему системному языку программирования, с возможностями конкуренции и системной архитектуры Swift 6 ي代表 انتقالًا إلى لغة برمجة أنظمة حقيقية، مع إمكانيات تزامن وأrchitecture نظام how to use Swift 6 Paradigm Shift Guide Swift 6 Paradigm Shift Guide alternative Swift 6 Paradigm Shift Guide setup guide what is Swift 6 Paradigm Shift Guide Swift 6 Paradigm Shift Guide vs Swift 5 Swift 6 systems programming tutorial concurrency safety in Swift 6 Swift 6 language fundamentals Swift 6 system architecture Swift 6 系统编程语言 并发安全 语言基础 系统架构 API 稳定性 分布式服务器集群 AIエージェント Analyzes language fundamentals for systems programming Covers system architecture for distributed server clusters Ensures concurrency safety for embedded microcontrollers Provides a comprehensive guide for transitioning from high-level app development Supports development for the entire computing spectrum Explains the transition from API stability to systems programming Swift 6 Paradigm Shift Guide is a comprehensive analysis of Swift 6''s transition to a systems programming language, covering language fundamentals, system architecture, and concurrency safety.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sanity-io/next-sanity/tsdown', 'community', 'sanity-io', 'next-sanity', 'sanity-io/next-sanity', 'tsdown', 0, 0, 37, '2026-03-08T01:57:15.323Z', '2026-03-08T02:02:59.552Z', 'c34b99d8a834e767b8172198fda10c200f9d6b4643574daed76f9fa9bcf7be8b', '{"id":"sanity-io/next-sanity/tsdown","name":"tsdown","description":{"en":"tsdown is a next-generation TypeScript library bundler for Next.js, providing fast builds and seamless migration from tsup. It benefits developers seeking efficient bundling solutions.","zh":"tsdown 是一个基于 Rolldown 和 Oxc 的 TypeScript 库打包工具，提供快速构建和自动类型声明生成","ja":"tsdown は Rolldown と Oxc に基づく TypeScript ライブラリバンドラーで、高速ビルドと自動型宣言生成を提供","ko":"tsdown은 Rolldown과 Oxc 기반의 TypeScript 라이브러리 번들러로 빠른 빌드와 자동 타입 선언 생성을 제공","es":"tsdown es una biblioteca de bundling de TypeScript de próxima generación para Next.js, que ofrece builds rápidos y generación automática de .d.ts","fr":"tsdown est une bibliothèque de bundling de TypeScript de nouvelle génération pour Next.js, qui propose des builds rapides et une génération automatique de .d.ts","de":"tsdown ist eine Bibliothek der nächsten Generation für das Bundling von TypeScript für Next.js, die schnelle Builds und automatische .d.ts-Generierung bietet","pt":"O tsdown é uma biblioteca de bundler de TypeScript de próxima geração, construída sobre Rolldown e Oxc, que fornece builds rápidos e geração automática de .d.ts.","ru":"Tsdown — это библиотека следующего поколения для сборки TypeScript, построенная на Rolldown и Oxc, которая обеспечивает быстрые сборки и автоматическую генерацию .d.ts.","ar":"أداة tsdown هي مكتبة من الجيل التالي لمجمعات TypeScript، مبنية على Rolldown و Oxc، توفر بناء سريعًا وتوليدًا تلقائيًا لملفات .d.ts."},"seo":{"title":{"en":"tsdown: Next-Gen TypeScript Library Bundler Setup Guide |...","zh":"tsdown Setup Guide: Sanity Toolkit for Next.js","ja":"tsdown を使用した Next.js Sanity Toolkit のセットアップ","ko":"tsdown Next.js Sanity Toolkit 사용법","es":"Guía de configuración de tsdown para Next.js","fr":"Guide de mise en route de tsdown pour Next.js","de":"Einrichtungsanleitung für tsdown mit Next.js","pt":"Guia de Configuração do tsdown: Otimização de Builds para...","ru":"ИИ Агент tsdown: Руководство по Настройке для Разработчиков","ar":"إعداد أداة tsdown: دليل kullanım لتحسين الأداء في Next.js"},"description":{"en":"Unlock blazing-fast builds with tsdown, the ultimate Sanity toolkit for Next.js. Learn how to migrate from tsup and optimize your workflow today!","zh":"了解 tsdown 的功能和特点，优化 Next.js 项目的性能和开发效率","ja":"Next.js プロジェクトのパフォーマンスと開発効率を最適化するための tsdown の機能と特徴","ko":"Next.js 프로젝트 성능과 개발 효율을 최적화하는 tsdown 기능과 특징","es":"Aprende a utilizar tsdown, una herramienta de Sanity para Next.js, y mejora tus proyectos con builds rápidos y generación automática de .d.ts","fr":"Découvrez tsdown, un outil de Sanity pour Next.js, et améliorez vos projets avec des builds rapides et une génération automatique de .d.ts","de":"Erfahren Sie, wie Sie tsdown, ein Sanity-Tool für Next.js, verwenden können, und verbessern Sie Ihre Projekte mit schnellen Builds und automatischer .d.ts-Ge...","pt":"Aprenda a configurar o tsdown para builds rápidos e eficientes em projetos Next.js. Descubra como aproveitar suas funcionalidades para melhorar a produtividade.","ru":"Узнайте, как настроить tsdown для быстрых и эффективных сборок в проектах Next.js. Откройте для себя его возможности для повышения производительности.","ar":"تعلم كيفية ضبط أداة tsdown لتحقيق بناء سريع وفعال في مشاريع Next.js. اكتشف كيف تستفيد من ميزاتها لتحسين الإنتاجية."},"definition":{"en":"tsdown is a TypeScript library bundler built on Rolldown and Oxc, offering automatic .d.ts generation and smart dependency handling.","zh":"tsdown 是一个用于 Next.js 的 TypeScript 库打包工具","ja":"tsdown は Next.js 用の TypeScript ライブラリバンドラー","ko":"tsdown은 Next.js 용 TypeScript 라이브러리 번들러","es":"tsdown es una herramienta de Sanity para Next.js que se utiliza para el bundling de bibliotecas de TypeScript","fr":"tsdown est un outil de Sanity pour Next.js utilisé pour le bundling de bibliothèques de TypeScript","de":"tsdown ist ein Sanity-Tool für Next.js, das für das Bundling von TypeScript-Bibliotheken verwendet wird","pt":"O tsdown é uma ferramenta de bundler de TypeScript que oferece builds rápidos e geração automática de declarações de tipo.","ru":"Tsdown — это инструмент для сборки TypeScript, который предлагает быстрые сборки и автоматическую генерацию деклараций типов.","ar":"أداة tsdown هي أداة لمجمعات TypeScript التي توفر بناء سريعًا وتوليدًا تلقائيًا لبيانات الإعلان عن النوع."},"features":{"en":["Blazing-fast builds using Rolldown and Oxc","Automatic .d.ts generation for type declarations","Seamless migration from tsup","Supports Rolldown/Rollup/Unplugin plugins","Smart dependency handling for efficient bundling","Enables exports option for auto-generated package exports"],"zh":["基于 Rolldown 和 Oxc 的 TypeScript 库打包","提供快速构建和自动类型声明生成","支持 Rolldown/Rollup/Unplugin 插件","智能依赖处理","支持纯 ESM 包构建"],"ja":["Rolldown と Oxc に基づく TypeScript ライブラリバンドリング","高速ビルドと自動型宣言生成","Rolldown/Rollup/Unplugin プラグインのサポート","スマートな依存関係の処理","純 ESM パッケージの構築のサポート"],"ko":["Rolldown과 Oxc 기반의 TypeScript 라이브러리 번들링","빠른 빌드와 자동 타입 선언 생성","Rolldown/Rollup/Unplugin 플러그인 지원","스마트한 의존성 처리","순수 ESM 패키지 빌드 지원"],"es":["Builds rápidos con Rolldown y Oxc","Generación automática de .d.ts","Compatibilidad con plugins de Rolldown, Rollup y Unplugin","Manejo inteligente de dependencias","Soporte para la migración desde tsup"],"fr":["Builds rapides avec Rolldown et Oxc","Génération automatique de .d.ts","Compatibilité avec les plugins de Rolldown, Rollup et Unplugin","Gestion intelligente des dépendances","Support pour la migration depuis tsup"],"de":["Schnelle Builds mit Rolldown und Oxc","Automatische .d.ts-Generierung","Unterstützung für Rolldown-, Rollup- und Unplugin-Plugins","Intelligente Abhängigkeitsverwaltung","Unterstützung für die Migration von tsup"],"pt":["Builds rápidos com Rolldown e Oxc","Geração automática de .d.ts","Suporte a plugins de Rolldown, Rollup e Unplugin","Manipulação inteligente de dependências","Suporte à migração de tsup"],"ru":["Быстрые сборки с Rolldown и Oxc","Автоматическая генерация .d.ts","Поддержка плагинов Rolldown, Rollup и Unplugin","Умная обработка зависимостей","Поддержка миграции из tsup"],"ar":["بناء سريع مع Rolldown و Oxc","توليد تلقائي لملفات .d.ts","دعم ملحقات Rolldown و Rollup و Unplugin","تحكم ذكي في الإعتماديات","دعم الهجرة من tsup"]},"keywords":{"en":["how to use tsdown","tsdown vs tsup","tsdown setup guide","what is tsdown","tsdown install","next-gen TypeScript library bundler","Rolldown and Oxc integration","tsdown alternative","TypeScript library bundling best practices"],"zh":["tsdown","Next.js","TypeScript","Rolldown","Oxc","tsdown Setup","Next.js Sanity Toolkit","AIエージェント","JavaScript 开发工具"],"ja":["tsdown","Next.js","TypeScript","Rolldown","Oxc","tsdown セットアップ","Next.js Sanity Toolkit","AIエージェント","JavaScript 開発ツール"],"ko":["tsdown","Next.js","TypeScript","Rolldown","Oxc","tsdown 설정","Next.js Sanity Toolkit","AI 에이전트","JavaScript 개발 도구"],"es":["tsdown","Next.js","TypeScript","bundling","Sanity","Rolldown","Oxc","builds rápidos","generación automática de .d.ts"],"fr":["tsdown","Next.js","TypeScript","bundling","Sanity","Rolldown","Oxc","builds rapides","génération automatique de .d.ts"],"de":["tsdown","Next.js","TypeScript","bundling","Sanity","Rolldown","Oxc","schnelle Builds","automatische .d.ts-Generierung"],"pt":["tsdown","Next.js","TypeScript","bundler","builds rápidos","geração de .d.ts","Rolldown","Oxc","tsup"],"ru":["tsdown","Next.js","TypeScript","сборщик","быстрые сборки","генерация .d.ts","Rolldown","Oxc","tsup"],"ar":["tsdown","Next.js","TypeScript","مجمعات","بناء سريع","توليد .d.ts","Rolldown","Oxc","tsup"]}},"owner":"sanity-io","repo":"next-sanity","repoPath":"sanity-io/next-sanity","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.323Z","topics":[],"category":"community","skillMd":{"name":"tsdown","description":"tsdown fast TypeScript library bundler powered by Rolldown and Oxc. Use when bundling TypeScript libraries, configuring entry points, or generating .d.ts declaration files.","version":"2026.1.28","bodyPreview":"tsdown is a next-generation TypeScript library bundler built on Rolldown and Oxc. It provides blazing-fast builds, automatic `.d.ts` generation, and seamless migration from tsup. Supports Rolldown/Rollup/Unplugin plugins and features smart dependency handling.\n\n> The skill is based on tsdown v0.20.1, generated at 2026-01-28.\n\n**Anthony''s Preferences:**\n\n- Build pure-ESM packages, avoid CJS\n- Always enable `dts` option for type declarations\n- Enable `exports` option for auto-generated package exp","body":"tsdown is a next-generation TypeScript library bundler built on Rolldown and Oxc. It provides blazing-fast builds, automatic `.d.ts` generation, and seamless migration from tsup. Supports Rolldown/Rollup/Unplugin plugins and features smart dependency handling.\n\n> The skill is based on tsdown v0.20.1, generated at 2026-01-28.\n\n**Anthony''s Preferences:**\n\n- Build pure-ESM packages, avoid CJS\n- Always enable `dts` option for type declarations\n- Enable `exports` option for auto-generated package exports\n\n## Core\n\n| Topic         | Description                                       | Reference                                |\n| ------------- | ------------------------------------------------- | ---------------------------------------- |\n| Configuration | Config file setup, defineConfig, multiple configs | [core-config](references/core-config.md) |\n| CLI           | Command-line interface and options                | [core-cli](references/core-cli.md)       |\n| Entry Points  | Entry files, aliases, glob patterns               | [core-entry](references/core-entry.md)   |\n\n## Build Options\n\n| Topic             | Description                                            | Reference                                                        |\n| ----------------- | ------------------------------------------------------ | ---------------------------------------------------------------- |\n| Output            | Format (ESM/CJS/IIFE/UMD), directory, target, platform | [options-output](references/options-output.md)                   |\n| Declaration Files | .d.ts generation, isolatedDeclarations, sourcemaps     | [options-dts](references/options-dts.md)                         |\n| Dependencies      | External, noExternal, dependency bundling              | [options-dependencies](references/options-dependencies.md)       |\n| Package Exports   | Auto-generating exports, main, module fields           | [options-package-exports](references/options-package-exports.md) |\n\n## Features\n\n| Topic         | Description                            | Reference                                                    |\n| ------------- | -------------------------------------- | ------------------------------------------------------------ |\n| Optimization  | Tree shaking, minification, sourcemaps | [features-optimization](references/features-optimization.md) |\n| Shims         | CJS/ESM compatibility shims            | [features-shims](references/features-shims.md)               |\n| Unbundle Mode | Bundleless transpile-only builds       | [features-unbundle](references/features-unbundle.md)         |\n| Watch Mode    | Auto-rebuild on file changes           | [features-watch](references/features-watch.md)               |\n\n## Advanced\n\n| Topic            | Description                                | Reference                                                            |\n| ---------------- | ------------------------------------------ | -------------------------------------------------------------------- |\n| Plugins          | Rolldown, Unplugin, Rollup, Vite plugins   | [advanced-plugins](references/advanced-plugins.md)                   |\n| Hooks            | Build lifecycle hooks                      | [advanced-hooks](references/advanced-hooks.md)                       |\n| Programmatic API | Using tsdown from code                     | [advanced-programmatic](references/advanced-programmatic.md)         |\n| Rolldown Options | Customizing inputOptions and outputOptions | [advanced-rolldown-options](references/advanced-rolldown-options.md) |\n\n## Recipes\n\n| Topic             | Description                    | Reference                                              |\n| ----------------- | ------------------------------ | ------------------------------------------------------ |\n| Framework Support | Vue and React library bundling | [recipes-frameworks](references/recipes-frameworks.md) |\n| Migration         | Migrating from tsup            | [recipes-migration](references/recipes-migration.md)   |\n"},"lastSynced":"2026-03-08T02:02:59.552Z","agentAnalysis":{"suitability":{"en":"Ideal for Next.js Development Agents seeking efficient TypeScript library bundling and seamless migration from tsup.","zh":"适合寻求高效TypeScript库打包和无缝从tsup迁移的Next.js开发代理。","ja":"Next.js開発エージェントが効率的なTypeScriptライブラリバンドルとtsupからのシームレスな移行を求める場合に適しています。","ko":"Next.js 개발 에이전트가 효율적인 TypeScript 라이브러리 번들링과 tsup에서 무중단으로 마이그레이션하려는 경우 적합합니다.","es":"Ideal para agentes de desarrollo de Next.js que buscan una biblioteca de TypeScript eficiente y una migración sin problemas desde tsup.","fr":"Idéal pour les agents de développement Next.js qui recherchent un regroupement de bibliothèques TypeScript efficace et une migration en douceur depuis tsup.","de":"Ideal für Next.js-Entwicklungsagenten, die eine effiziente TypeScript-Bibliotheksbündelung und eine nahtlose Migration von tsup suchen.","pt":"Ideal para Agentes de Desenvolvimento Next.js que buscam uma biblioteca TypeScript eficiente e uma migração sem problemas do tsup.","ru":"Идеально подходит для агентов разработки Next.js, ищущих эффективную библиотеку TypeScript и беспроблемную миграцию с tsup.","ar":"مثالية للوكلاء النشطاء في تطوير Next.js الذين يبحثون عن إعداد مكتبة TypeScript فعالة وانتقال بدون مشاكل من tsup."},"recommendation":{"en":"Empowers agents to generate blazing-fast builds with automatic .d.ts generation, leveraging Rolldown and Oxc, and supporting Rolldown/Rollup/Unplugin plugins for smart dependency handling, while building pure-ESM packages and enabling auto-generated package exports with the ''exports'' option.","zh":"赋予代理生成极速构建的能力，具有自动的.d.ts生成，利用Rolldown和Oxc，并支持Rolldown/Rollup/Unplugin插件进行智能依赖处理，同时构建纯ESM包，并启用自动生成的包导出，使用''exports''选项。","ja":"エージェントが極速のビルドを生成する能力を付与し、自動の.d.ts生成を備え、RolldownとOxcを利用し、 Rolldown/Rollup/Unpluginプラグインをサポートしてスマートな依存関係の管理を行いながら、純粋なESMパッケージをビルドし、''exports''オプションを使用して自動生成されたパッケージのエクスポートを可能にします。","ko":"에이전트가 cực속의 빌드를 생성할 수 있는 능력을 부여하며, 자동의 .d.ts 생성을 지원하고, Rolldown과 Oxc를 활용하며, Rolldown/Rollup/Unplugin 플러그인을 지원하여 智能한 의존성 관리를 수행하며, 순수한 ESM 패키지를 빌드하고, ''exports'' 옵션을 사용하여 자동으로 생성된 패키지 내보내기 기능을 활성화합니다.","es":"Permite a los agentes generar compilaciones extremadamente rápidas con generación automática de .d.ts, aprovechando Rolldown y Oxc, y compatibilidad con plugins Rolldown/Rollup/Unplugin para un manejo inteligente de dependencias, al mismo tiempo que se crean paquetes puros ESM y se habilitan exportaciones de paquetes autogeneradas con la opción ''exports''.","fr":"Permet aux agents de générer des builds incroyablement rapides avec une génération automatique de .d.ts, en exploitant Rolldown et Oxc, et en prenant en charge les plugins Rolldown/Rollup/Unplugin pour une gestion intelligente des dépendances, tout en créant des packages ESM purs et en activant les exportations de packages autogénérées avec l''option ''exports''.","de":"Ermächtigt die Agenten, extrem schnelle Builds mit automatischer .d.ts-Generierung zu erstellen, indem sie Rolldown und Oxc nutzen und die Unterstützung von Rolldown/Rollup/Unplugin-Plugins für intelligentes Abhängigkeitsmanagement bereitstellen, während sie reine ESM-Pakete erstellen und autogenerierte Paketexporte mit der Option ''exports'' aktivieren.","pt":"Habilita os agentes a gerar compilações extremamente rápidas com geração automática de .d.ts, aproveitando Rolldown e Oxc, e suportando plugins Rolldown/Rollup/Unplugin para tratamento inteligente de dependências, ao mesmo tempo em que constrói pacotes puros-ESM e habilita exportações de pacotes automaticamente geradas com a opção ''exports''.","ru":"Наделяет агентов возможностью генерировать чрезвычайно быстрые сборки с автоматической генерацией .d.ts, используя Rolldown и Oxc, и поддерживая плагины Rolldown/Rollup/Unplugin для умного управления зависимостями, а также собирая чистые пакеты ESM и ermöglicht автоматически сгенерированные экспорты пакетов с опцией ''exports''.","ar":"تمكّن الوكلاء النشطاء من توليد بناء سريع للغاية مع توليد تلقائي ل .d.ts، مستفيدة من Rolldown و Oxc، ودعم إضافات Rolldown/Rollup/Unplugin لت扱ة ذكية للتحكم في التبعيات، وفي نفس الوقت بناء حزم ESM النقية وتفعيل تصدير الحزم التلقائي مع خيار ''exports''."},"useCases":{"en":["Migrating existing tsup configurations to tsdown for improved performance","Building optimized Next.js applications with fast builds and automatic type declarations","Managing dependencies efficiently using smart dependency handling and Rolldown/Rollup/Unplugin plugins"],"zh":["将现有的tsup配置迁移到tsdown以提高性能","使用快速构建和自动类型声明构建优化的Next.js应用程序","使用智能依赖处理和Rolldown/Rollup/Unplugin插件高效地管理依赖关系"],"ja":["既存のtsup設定をtsdownに移行してパフォーマンスを向上させる","高速ビルドと自動型宣言を使用して最適化されたNext.jsアプリケーションをビルドする","スマートな依存関係の管理とRolldown/Rollup/Unpluginプラグインを使用して依存関係を効率的に管理する"],"ko":["기존 tsup 설정을 tsdown으로 마이그레이션하여 성능을 개선하는 것","빠른 빌드와 자동 형 선언을 사용하여 최적화된 Next.js 애플리케이션을 빌드하는 것","スマート한 의존성 관리와 Rolldown/Rollup/Unplugin 플러그인을 사용하여 의존성을 효율적으로 관리하는 것"],"es":["Migrar configuraciones de tsup existentes a tsdown para mejorar el rendimiento","Crear aplicaciones de Next.js optimizadas con compilaciones rápidas y declaraciones de tipo automáticas","Gestionar dependencias de manera eficiente utilizando un manejo inteligente de dependencias y plugins Rolldown/Rollup/Unplugin"],"fr":["Migrer des configurations tsup existantes vers tsdown pour améliorer les performances","Créer des applications Next.js optimisées avec des builds rapides et des déclarations de type automatiques","Gérer les dépendances de manière efficace en utilisant une gestion intelligente des dépendances et des plugins Rolldown/Rollup/Unplugin"],"de":["Bestehende tsup-Konfigurationen auf tsdown migrieren, um die Leistung zu verbessern","Optimierte Next.js-Anwendungen mit schnellen Builds und automatischen Typdeklarationen erstellen","Abhängigkeiten effizient verwalten, indem ein intelligentes Abhängigkeitsmanagement und Rolldown/Rollup/Unplugin-Plugins verwendet werden"],"pt":["Migrar configurações existentes do tsup para o tsdown para melhorar o desempenho","Construir aplicações Next.js otimizadas com compilações rápidas e declarações de tipo automáticas","Gerenciar dependências de forma eficiente usando tratamento inteligente de dependência e plugins Rolldown/Rollup/Unplugin"],"ru":["Мигрировать существующие настройки tsup в tsdown для улучшения производительности","Создавать оптимизированные приложения Next.js с быстрыми сборками и автоматическими объявлениями типов","Эффективно управлять зависимостями, используя умное управление зависимостями и плагины Rolldown/Rollup/Unplugin"],"ar":["نقل الإعدادات الحالية من tsup إلى tsdown لتحسين الأداء","بناء تطبيقات Next.js المُختارة مع عمليات بناء سريعة وإعلانات أنواع تلقائية","إدارة التبعيات بفعالية باستخدام معالجة ذكية للتبعيات وإضافات Rolldown/Rollup/Unplugin"]},"limitations":{"en":["Requires tsdown v0.20.1 or compatible version","Specifically designed for Next.js and TypeScript library bundling"],"zh":["需要tsdown v0.20.1或兼容版本","专门为Next.js和TypeScript库打包设计"],"ja":["tsdown v0.20.1または互換バージョンが必要","Next.jsとTypeScriptライブラリバンドル専用に設計"],"ko":["tsdown v0.20.1 또는 호환 버전이 필요","Next.js와 TypeScript 라이브러리 번들링을 위한 전용 설계"],"es":["Requiere tsdown v0.20.1 o una versión compatible","Diseñado específicamente para Next.js y el regroupamento de bibliotecas de TypeScript"],"fr":["Nécessite tsdown v0.20.1 ou une version compatible","Conçu spécifiquement pour Next.js et le regroupement de bibliothèques TypeScript"],"de":["Benötigt tsdown v0.20.1 oder eine kompatible Version","Speziell für Next.js und die Bündelung von TypeScript-Bibliotheken konzipiert"],"pt":["Exige tsdown v0.20.1 ou versão compatível","Projetado especificamente para Next.js e empacotamento de bibliotecas TypeScript"],"ru":["Требует tsdown v0.20.1 или совместимой версии","Разработан специально для Next.js и упаковки библиотек TypeScript"],"ar":["يتطلب tsdown الإصدار 0.20.1 أو إصدارًا متوافقًا","صُمّم خصيصًا ل Next.js وضغط مكتبات TypeScript"]},"version":4},"contentHash":"c34b99d8a834e767b8172198fda10c200f9d6b4643574daed76f9fa9bcf7be8b","qualityScore":37}');
