INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sanity-io/next-sanity/tsdown', 'tsdown', 'sanity-io', 'next-sanity', 'community', 'tsdown sanity-io next-sanity community tsdown is a next-generation TypeScript library bundler for Next.js, providing fast builds and seamless migration from tsup. It benefits developers seeking efficient bundling solutions. tsdown 是一个基于 Rolldown 和 Oxc 的 TypeScript 库打包工具，提供快速构建和自动类型声明生成 tsdown は Rolldown と Oxc に基づく TypeScript ライブラリバンドラーで、高速ビルドと自動型宣言生成を提供 tsdown은 Rolldown과 Oxc 기반의 TypeScript 라이브러리 번들러로 빠른 빌드와 자동 타입 선언 생성을 제공 tsdown es una biblioteca de bundling de TypeScript de próxima generación para Next.js, que ofrece builds rápidos y generación automática de .d.ts tsdown est une bibliothèque de bundling de TypeScript de nouvelle génération pour Next.js, qui propose des builds rapides et une génération automatique de .d.ts tsdown ist eine Bibliothek der nächsten Generation für das Bundling von TypeScript für Next.js, die schnelle Builds und automatische .d.ts-Generierung bietet O tsdown é uma biblioteca de bundler de TypeScript de próxima geração, construída sobre Rolldown e Oxc, que fornece builds rápidos e geração automática de .d.ts. Tsdown — это библиотека следующего поколения для сборки TypeScript, построенная на Rolldown и Oxc, которая обеспечивает быстрые сборки и автоматическую генерацию .d.ts. أداة tsdown هي مكتبة من الجيل التالي لمجمعات TypeScript، مبنية على Rolldown و Oxc، توفر بناء سريعًا وتوليدًا تلقائيًا لملفات .d.ts. how to use tsdown tsdown vs tsup tsdown setup guide what is tsdown tsdown install next-gen TypeScript library bundler Rolldown and Oxc integration tsdown alternative TypeScript library bundling best practices tsdown Next.js TypeScript Rolldown Oxc tsdown Setup Next.js Sanity Toolkit AIエージェント JavaScript 开发工具 Blazing-fast builds using Rolldown and Oxc Automatic .d.ts generation for type declarations Seamless migration from tsup Supports Rolldown/Rollup/Unplugin plugins Smart dependency handling for efficient bundling Enables exports option for auto-generated package exports tsdown is a TypeScript library bundler built on Rolldown and Oxc, offering automatic .d.ts generation and smart dependency handling.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chrispangg/deepagentsdk/content-writer', 'community', 'chrispangg', 'deepagentsdk', 'chrispangg/deepagentsdk', 'content-writer', 0, 0, 37, '2026-03-03T01:58:23.453Z', '2026-03-03T03:33:53.689Z', '879faed0bbb5770dc73f2027b7637b607fa0a7c70d0e8f6eef03f2435dd02941', '{"id":"chrispangg/deepagentsdk/content-writer","name":"content-writer","description":{"zh":"content-writer是一个基于Vercel AI SDK v6构建的AI代理框架，帮助开发者快速集成AI功能到应用中，支持多种开发语言和平台。","ja":"content-writerは、Vercel AI SDK v6を基盤とするAIエージェントフレームワークで、開発者がアプリにAI機能を簡単に統合できるように設計されています。","ko":"content-writer는 Vercel AI SDK v6를 기반으로 한 AI 에이전트 프레임워크로, 개발자가 애플리케이션에 AI 기능을 쉽게 통합할 수 있도록 지원합니다.","es":"Content Writer es un framework de Deep Agent Harness construido con Vercel AI SDK v6 para desarrolladores","fr":"Content Writer est un framework de Deep Agent Harness construit avec Vercel AI SDK v6 pour les développeurs","de":"Content Writer ist ein Framework von Deep Agent Harness, entwickelt mit Vercel AI SDK v6 für Entwickler","pt":"O content-writer é um framework de agente de IA construído com Vercel''s AI SDK v6, projetado para automatizar e otimizar a criação de conteúdo técnico para desenvolvedores.","ru":"content-writer — это фреймворк для ИИ агентов, созданный на Vercel AI SDK v6, предназначенный для автоматизации и оптимизации создания технического контента для разработчиков.","ar":"content-writer هو إطار عمل لوكلاء الذكاء الاصطناعي مبني على Vercel AI SDK v6، مصمم لأتمتة وتحسين إنشاء المحتوى التقني للمطورين.","en":"A Deep Agent Harness framework built with Vercel''s AI SDK v6"},"seo":{"title":{"zh":"使用Vercel AI SDK v6构建AI代理框架content-writer","ja":"Vercel AI SDK v6で構築されたAIエージェントフレームワーク","ko":"Vercel AI SDK v6로 구축된 AI 에이전트 프레임워크","es":"Herramientas de AI: Content Writer con Vercel AI SDK","fr":"Outils d''IA: Content Writer avec Vercel AI SDK","de":"KI-Tools: Content Writer mit Vercel AI SDK","pt":"content-writer: Ferramenta de IA para Agentes de Conteúdo...","ru":"content-writer: ИИ Агенты для создания контента на Vercel...","ar":"content-writer: أداة الذكاء الاصطناعي لوكلاء المحتوى باست...","en":"content-writer"},"description":{"zh":"content-writer是一个基于Vercel AI SDK v6构建的AI代理框架，帮助开发者快速集成AI功能到应用中，支持多种开发语言和平台。","ja":"content-writerは、Vercel AI SDK v6を基盤とするAIエージェントフレームワークで、開発者がアプリにAI機能を簡単に統合できるように設計されています。","ko":"content-writer는 Vercel AI SDK v6를 기반으로 한 AI 에이전트 프레임워크로, 개발자가 애플리케이션에 AI 기능을 쉽게 통합할 수 있도록 지원합니다.","es":"Content Writer es un framework de Deep Agent Harness construido con Vercel AI SDK v6 para desarrolladores","fr":"Content Writer est un framework de Deep Agent Harness construit avec Vercel AI SDK v6 pour les développeurs","de":"Content Writer ist ein Framework von Deep Agent Harness, entwickelt mit Vercel AI SDK v6 für Entwickler","pt":"O content-writer é um framework de agente de IA construído com Vercel''s AI SDK v6, projetado para automatizar e otimizar a criação de conteúdo técnico para d...","ru":"content-writer — это фреймворк для ИИ агентов, созданный на Vercel AI SDK v6, предназначенный для автоматизации и оптимизации создания технического контента ...","ar":"content-writer هو إطار عمل لوكلاء الذكاء الاصطناعي مبني على Vercel AI SDK v6، مصمم لأتمتة وتحسين إنشاء المحتوى التقني للمطورين.","en":"A Deep Agent Harness framework built with Vercel''s AI SDK v6"},"definition":{"en":"A Deep Agent Harness framework built with Vercel''s AI SDK v6"},"features":{"zh":["基于Vercel AI SDK v6构建","支持React和Node.js集成","提供高效的AI代理开发工具","简化AI功能部署流程","兼容多种开发环境","开源且社区支持"],"ja":["Vercel AI SDK v6ベースの構築","ReactとNode.jsの統合サポート","効率的なAIエージェント開発ツール","AI機能のデプロイプロセス簡素化","多様な開発環境との互換性","オープンソースとコミュニティサポート"],"ko":["Vercel AI SDK v6 기반 구축","React 및 Node.js 통합 지원","효율적인 AI 에이전트 개발 도구","AI 기능 배포 프로세스 간소화","다양한 개발 환경 호환성","오픈 소스 및 커뮤니티 지원"],"es":["Integración con Vercel AI SDK v6","Desarrollo de aplicaciones de AI","Herramientas de contenido avanzadas","Compatibilidad con Node.js y React","CLI para desarrollo rápido"],"fr":["Intégration avec Vercel AI SDK v6","Développement d''applications d''IA","Outils de contenu avancés","Compatibilité avec Node.js et React","CLI pour développement rapide"],"de":["Integration mit Vercel AI SDK v6","Entwicklung von KI-Anwendungen","Erweiterte Inhalts-Tools","Kompatibilität mit Node.js und React","CLI für schnelles Entwicklung"],"pt":["Construído com Vercel AI SDK v6 para integração moderna","Framework Deep Agent Harness para automação de agentes de IA","Geração de conteúdo técnico otimizado para SEO","Suporte para modelos de linguagem avançados (LLMs)","Configuração simplificada com CLI e Node.js","Documentação completa para desenvolvedores"],"ru":["Построен на Vercel AI SDK v6 для современной интеграции","Фреймворк Deep Agent Harness для автоматизации ИИ агентов","Генерация технического контента с оптимизацией для SEO","Поддержка продвинутых языковых моделей (LLMs)","Упрощенная настройка с CLI и Node.js","Полная документация для разработчиков"],"ar":["مبني على Vercel AI SDK v6 للتكامل الحديث","إطار عمل Deep Agent Harness لأتمتة وكلاء الذكاء الاصطناعي","إنشاء محتوى تقني مُحسن لمحركات البحث (SEO)","دعم نماذج اللغة المتقدمة (LLMs)","إعداد مبسط باستخدام CLI وNode.js","توثيق شامل للمطورين"]},"keywords":{"zh":["AI代理框架","Vercel AI SDK使用指南","content-writer安装","AI工具集成","React AI代理","Node.js AI开发","content-writer vs其他框架","如何部署AI代理"],"ja":["AIエージェントフレームワーク","Vercel AI SDK使い方","content-writerインストール","AIツール統合","React AIエージェント","Node.js AI開発","content-writer対他のフレームワーク","AIエージェントデプロイ方法"],"ko":["AI 에이전트 프레임워크","Vercel AI SDK 사용법","content-writer 설치","AI 도구 통합","React AI 에이전트","Node.js AI 개발","content-writer 대안","AI 에이전트 배포 방법"],"es":["cómo usar Content Writer","qué es un agente de IA","alternativas a Content Writer","Content Writer vs otros frameworks","instalación de Content Writer","guía de configuración de Content Writer"],"fr":["comment utiliser Content Writer","qu''est-ce qu''un agent d''IA","alternatives à Content Writer","Content Writer vs autres frameworks","installation de Content Writer","guide de configuration de Content Writer"],"de":["wie man Content Writer verwendet","was ist ein KI-Agent","Alternativen zu Content Writer","Content Writer vs andere Frameworks","Installation von Content Writer","Konfigurationsanleitung für Content Writer"],"pt":["como usar content-writer","ferramentas de IA para conteúdo","Vercel AI SDK v6 tutorial","content-writer install","agentes de IA para desenvolvedores","automação de conteúdo técnico","content-writer vs outras ferramentas","Deep Agent Harness framework","setup content-writer guide","modelos de linguagem para geração de conteúdo"],"ru":["как использовать content-writer","ИИ инструменты для контента","Vercel AI SDK v6 руководство","content-writer установка","ИИ агенты для разработчиков","автоматизация технического контента","content-writer vs альтернативы","фреймворк Deep Agent Harness","настройка content-writer гайд","языковые модели для генерации контента"],"ar":["كيفية استخدام content-writer","أدوات الذكاء الاصطناعي للمحتوى","Vercel AI SDK v6 tutorial","تثبيت content-writer","وكلاء الذكاء الاصطناعي للمطورين","أتمتة المحتوى التقني","content-writer مقابل البدائل","إطار عمل Deep Agent Harness","دليل إعداد content-writer","نماذج اللغة لإنشاء المحتوى"]}},"owner":"chrispangg","repo":"deepagentsdk","repoPath":"chrispangg/deepagentsdk","stars":0,"forks":0,"updatedAt":"2026-03-03T01:58:23.453Z","topics":[],"category":"community","skillMd":{"name":"content-writer","description":"Writing content across different platforms and styles. This skill should be used when creating blog posts, LinkedIn posts, X/Twitter threads, technical documentation, or other written content. It intelligently selects the appropriate writing style based on the platform, audience, and content type, then applies that style consistently throughout the piece.","bodyPreview":"# Content Writer\n\n## Overview\n\nThis skill enables writing high-quality content across different platforms and audiences. It dynamically selects the appropriate writing style based on the task, then applies that style consistently. Available styles include deep technical blog posts, social media content (LinkedIn, X/Twitter), tutorials, and more.\n\n## Style Selection\n\nBefore writing, determine the appropriate style based on these factors:\n\n| Factor | Consider |\n|--------|----------|\n| **Platform**","body":"# Content Writer\n\n## Overview\n\nThis skill enables writing high-quality content across different platforms and audiences. It dynamically selects the appropriate writing style based on the task, then applies that style consistently. Available styles include deep technical blog posts, social media content (LinkedIn, X/Twitter), tutorials, and more.\n\n## Style Selection\n\nBefore writing, determine the appropriate style based on these factors:\n\n| Factor | Consider |\n|--------|----------|\n| **Platform** | Blog, LinkedIn, X/Twitter, documentation, newsletter |\n| **Audience** | Engineers, executives, general tech audience, developers |\n| **Depth** | Deep-dive technical, lightweight explainer, announcement |\n| **Tone** | Authoritative, conversational, promotional, educational |\n| **Length** | Long-form (2000+ words), medium (500-1500), short (<500), thread |\n\n### Style Decision Tree\n\n```\nIs this for social media?\n├─ Yes → LinkedIn or X/Twitter style\n│   ├─ Professional/B2B → LinkedIn Style\n│   └─ Tech community/casual → X/Twitter Style\n│\n└─ No → Is this a technical blog post?\n    ├─ Yes → What voice/style?\n    │   ├─ Karpathy-style (conversational, personal, pragmatic) → Karpathy Style\n    │   ├─ Opinion-forward analysis → Deep Technical Style\n    │   ├─ Lightweight explainer → Simplified Technical Style\n    │   └─ Tutorial/how-to → Tutorial Style\n    │\n    └─ No → What type?\n        ├─ Announcement → Announcement Style\n        ├─ Newsletter → Newsletter Style\n        └─ Documentation → Documentation Style\n```\n\n## Available Styles\n\n### 1. Karpathy Style (Conversational Technical)\n\n**Use when:** Writing technical content that feels personal and accessible. Best for blog posts about AI/ML, tutorials, or technical essays where you want the voice of an expert friend explaining things over coffee.\n\n**Characteristics:**\n\n- First-person, conversational tone (\"I''ve found that...\", \"Here''s what I learned...\")\n- Starts with personal experience or intriguing premise\n- Progressive complexity (simple → detailed)\n- Dry wit and occasional humor\n- Honest about limitations and failures\n- Pragmatic (\"It only has to be right more often than not\")\n- Numbered frameworks and structured approaches\n- Memorable, quotable lines\n\n**Load:** `references/karpathy-style.md` for comprehensive guidance\n\n**Core Philosophy:** \"Don''t be a hero. Start simple. Be patient.\"\n\n**Opening Hooks (choose one):**\n\n| Pattern | Example |\n|---------|---------|\n| Personal experience | \"I still remember when I trained my first recurrent network...\" |\n| Intriguing premise | \"We''re going to feed 2 million selfies to a neural network and have it tell us what makes a selfie good.\" |\n| Leaky abstraction | \"Neural nets are not ''off-the-shelf'' technology the second you deviate slightly from training an ImageNet classifier.\" |\n| Strong observation | \"Trees are solidified air.\" |\n\n**Example opening:**\n> \"I''ve trained a lot of neural networks over the years and I''ve come to find that the process isn''t nearly as simple as it seems. They are a leaky abstraction. Here''s what I''ve learned.\"\n\n**Tweet/X style (short-form):**\n- Pithy observations that compress insight\n- Strong statements (90% true, ignore counterexample police)\n- Unexpected connections between domains\n- Personal candor about struggles and discoveries\n\n### 2. Deep Technical Style (Opinion-Forward Analysis)\n\n**Use when:** Writing opinion-forward technical analysis about AI, LLMs, agents, or engineering topics. Best for content targeting senior engineers who want bold takes backed by evidence.\n\n**Characteristics:**\n\n- Contrarian, opinion-forward opening hooks\n- \"Do the simple thing first\" philosophy\n- Concrete examples with specific numbers\n- Takes clear positions and makes predictions\n- Varied sentence length, active voice\n\n**Load:** `references/deep-technical-style.md` for comprehensive guidance\n\n**Core Philosophy:** \"Do the simple thing first.\"\n\n- Embrace the black box: Focus on inputs/outputs, not internal mechanisms\n- Domain expertise over technical knowledge\n- Simplicity as virtue: Start simple, add complexity only when necessary\n- Opinion-forward: Take clear positions and make predictions boldly\n\n**Opening Hooks (choose one):**\n\n| Pattern | Example |\n|---------|---------|\n| Contrarian position | \"The death of prompt engineering has been greatly exaggerated.\" |\n| Practical pain point | \"So you need to hire someone to build your LLM multi-agent system...\" |\n| Challenge assumptions | \"If you''ve been stuffing thousands of tokens thinking ''more context = better''...\" |\n| Surprising simplicity | \"Claude Code isn''t built on a complex multi-agent swarm. It''s a single-threaded loop.\" |\n\n**Example opening:**\n> \"Most AI architectures are overengineered. A single-threaded loop often outperforms elaborate multi-agent orchestrations.\"\n\n### 3. LinkedIn Style\n\n**Use when:** Writing professional content for LinkedIn—thought leadership, announcements, industry insights.\n\n**Characteristics:**\n\n- Hook in first line (appears before \"see more\")\n- Short paragraphs (1-2 sentences each)\n- Line breaks between paragraphs for mobile readability\n- Personal angle or story\n- Call-to-action or question at the end\n- Strategic use of emojis (sparingly, professionally)\n- 1300 characters ideal, 3000 max\n\n**Structure:**\n\n```\n[Hook line that creates curiosity]\n\n[Personal context or story - 2-3 short paragraphs]\n\n[Key insight or lesson - bulleted if multiple points]\n\n[Call-to-action or engaging question]\n\n#relevanthashtags (3-5 max)\n```\n\n**Example:**\n\n> Most AI features never make it to production.\n>\n> Not because the models aren''t good enough.\n>\n> Because teams build for demos, not for users.\n>\n> After shipping 50+ AI features, here''s what actually matters:\n>\n> → Start with the simplest possible implementation\n> → Measure what users do, not what they say\n> → Treat AI like any other code: test it, monitor it, iterate\n>\n> What''s the biggest lesson you''ve learned shipping AI?\n\n### 4. X/Twitter Style\n\n**Use when:** Writing for X/Twitter—quick insights, hot takes, thread explainers, engagement posts.\n\n**Characteristics:**\n\n- Punchy, high-signal first tweet\n- No filler words\n- Threads: numbered, each tweet standalone valuable\n- Contrarian takes perform well\n- Code snippets or visuals boost engagement\n- 280 characters per tweet, threads typically 5-15 tweets\n\n**Thread structure:**\n\n```\n1/ [Bold claim or hook]\n\n2/ [Context or \"here''s why\"]\n\n3-N/ [Key points, one per tweet]\n\nN+1/ [Takeaway or call-to-action]\n\n[Optional: link to longer content]\n```\n\n**Example:**\n\n> Unpopular opinion: RAG is overengineered for most use cases.\n>\n> A well-crafted system prompt often outperforms a poorly designed RAG pipeline.\n>\n> Thread on when to use (and skip) RAG 🧵\n\n### 5. Simplified Technical Style\n\n**Use when:** Writing accessible technical content for broader audiences—explainers, introductions, \"what is X\" posts.\n\n**Characteristics:**\n\n- Start with the \"why it matters\" not the \"what it is\"\n- Analogies to familiar concepts\n- Avoid jargon or define it immediately\n- Progressive complexity (simple → detailed)\n- Concrete examples before abstract explanations\n\n**Example opening:**\n\n> Every time you ask ChatGPT a question, something interesting happens behind the scenes. The AI doesn''t just \"know\" the answer—it builds one, word by word, based on patterns it learned from millions of conversations.\n\n### 6. Tutorial Style\n\n**Use when:** Writing step-by-step guides, how-tos, implementation walkthroughs.\n\n**Characteristics:**\n\n- Clear prerequisites upfront\n- Numbered steps\n- Code blocks with comments\n- \"What you''ll learn\" summary\n- Troubleshooting section\n- Working example at the end\n\n**Structure:**\n\n```\n## What You''ll Build\n[One sentence + screenshot/diagram]\n\n## Prerequisites\n[Bulleted list]\n\n## Steps\n### Step 1: [Action verb]\n[Explanation + code]\n\n### Step 2: ...\n\n## Troubleshooting\n[Common issues + solutions]\n\n## Next Steps\n[Where to go from here]\n```\n\n### 7. Announcement Style\n\n**Use when:** Announcing features, releases, milestones, company news.\n\n**Characteristics:**\n\n- Lead with the news, not the backstory\n- What it is → Why it matters → How to use it\n- Keep it concise\n- Clear call-to-action\n- Links to more detailed content\n\n**Example:**\n\n> We just shipped streaming support for Deep Agent.\n>\n> Now you can see your agent''s thinking in real-time—tool calls, responses, everything—as it happens.\n>\n> Why it matters: Debugging agent loops is 10x easier when you can watch them run.\n>\n> Try it: `createDeepAgent({ model, onEvent: console.log })`\n\n## Writing Workflow\n\n### Step 1: Identify the Style\n\nAsk these questions:\n\n1. Where will this be published?\n2. Who is the primary audience?\n3. What action should readers take after reading?\n4. How much time will readers spend on this?\n\n### Step 2: Load Style Reference\n\nFor Deep Technical style, load `references/deep-technical-style.md` for detailed guidance including:\n\n- 7 opening hook patterns with examples\n- 5 argumentative structures\n- 10+ rhetorical techniques\n- 8 recurring themes to weave throughout\n- Sentence-level craft patterns\n- Pre-publication checklist\n\nFor other styles, refer to the characteristics above.\n\n### Step 3: Draft with Style Constraints\n\nApply the chosen style''s characteristics from the start. Don''t write generically then \"style\" it later—the style should inform structure, not just tone.\n\n### Step 4: Review Against Style Checklist\n\nEach style has implicit requirements. Before finalizing:\n\n**Karpathy Style:**\n\n- [ ] First-person, conversational voice?\n- [ ] Opens with personal experience or intriguing premise?\n- [ ] Honest about limitations (\"This might be wrong, but...\")?\n- [ ] Progressive complexity (simple → detailed)?\n- [ ] Contains dry wit or memorable lines?\n- [ ] Pragmatic advice, not theoretical?\n\n**Deep Technical Style:**\n\n- [ ] Contrarian or surprising opening?\n- [ ] Specific numbers/examples?\n- [ ] Clear position taken?\n- [ ] Explains \"why\" not just \"what\"?\n- [ ] Subheadings as mini-arguments?\n- [ ] Active voice throughout?\n\n**LinkedIn Style:**\n\n- [ ] Hook visible before \"see more\"?\n- [ ] Mobile-friendly spacing?\n- [ ] Personal angle included?\n- [ ] Ends with engagement prompt?\n\n**X/Twitter Style:**\n\n- [ ] First tweet standalone compelling?\n- [ ] Each tweet <280 chars?\n- [ ] No filler words?\n- [ ] Thread numbered clearly?\n\n## AI Slop Avoidance\n\n**Critical:** All content must avoid patterns that signal AI-generated text. Load `references/ai-slop-avoidance.md` for comprehensive guidance.\n\n### Quick Reference: Words to Ban\n\nNever use these overused AI words:\n\n| Category | Banned Words |\n|----------|--------------|\n| **Verbs** | delve, embark, unleash, harness, unlock, navigate, revolutionize, foster, elevate |\n| **Adjectives** | vibrant, bustling, intricate, pivotal, crucial, cutting-edge, robust, seamless, meticulous |\n| **Nouns** | tapestry, realm, landscape, paradigm, synergy, beacon, testament, game-changer |\n| **Phrases** | \"it''s important to note\", \"in today''s digital age\", \"dive into\", \"at its core\", \"a myriad of\" |\n\n### Quick Reference: Patterns to Avoid\n\n| Pattern | Problem | Fix |\n|---------|---------|-----|\n| **Em-dashes (—)** | Strong AI signal, ban entirely | Use commas, parentheses, periods (hyphens/en-dashes OK) |\n| Uniform sentences | All ~25-30 words | Mix 5-word punches with 40-word explanations |\n| Excessive hedging | \"might\", \"arguably\", \"perhaps\" | Take clear positions |\n| Immediate lists | Jump to bullets without narrative | Build tension first |\n| Perfect grammar | Zero typos feels robotic | Occasional imperfection is human |\n| Balanced both-sides | Artificial neutrality | Take a stance |\n\n### AI Slop Checklist (Apply to All Content)\n\n- [ ] Zero banned words from the list above?\n- [ ] **Zero em-dashes (—) in the entire piece?**\n- [ ] Sentence lengths vary dramatically (some <10 words, some >35)?\n- [ ] Contains specific names, numbers, dates?\n- [ ] Has personal voice or anecdotes?\n- [ ] Takes clear positions without excessive hedging?\n- [ ] Avoids \"In conclusion\" / \"To summarize\" closings?\n\n## Resources\n\n### references/\n\n- `karpathy-style.md` - Guide for writing in Andrej Karpathy''s conversational, pragmatic technical style with blog post patterns, tweet patterns, and recurring themes\n- `deep-technical-style.md` - Comprehensive guide for opinion-forward technical blog posts with detailed examples, rhetorical techniques, and pre-publication checklist\n- `ai-slop-avoidance.md` - Detailed guide to avoiding AI-generated content patterns\n\n## Extending This Skill\n\nTo add new writing styles:\n\n1. Analyze 5-10 examples of the target style\n2. Extract patterns: opening hooks, structure, tone, length constraints\n3. Create a reference file in `references/[style-name]-style.md`\n4. Add the style to the decision tree and Available Styles section\n5. Include a checklist for that style in the Review step\n"},"lastSynced":"2026-03-03T03:33:53.689Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Strategy Agents needing dynamic style adaptation across multiple platforms.","zh":"非常适合需要跨多个平台进行动态风格调整的内容策略代理。","ja":"複数のプラットフォームにわたる動的なスタイル適応を必要とするコンテンツ戦略エージェントに最適です。","ko":"다중 플랫폼에 걸친 동적 스타일 적용이 필요한 콘텐츠 전략 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Estrategia de Contenido que necesitan adaptación de estilo dinámica en múltiples plataformas.","fr":"Parfait pour les Agents de Stratégie de Contenu ayant besoin d''une adaptation de style dynamique sur plusieurs plateformes.","de":"Perfekt für Content-Strategie-Agents, die eine dynamische Stil-Anpassung auf mehreren Plattformen benötigen.","pt":"Perfeito para Agentes de Estratégia de Conteúdo que necessitam de adaptação de estilo dinâmico em várias plataformas.","ru":"Идеально подходит для агентов по стратегии контента, которым требуется динамическая адаптация стиля на нескольких платформах.","ar":"مثالي لوكلاء استراتيجية المحتوى الذين يحتاجون إلى تعديل أسلوب ديناميكي عبر منصات متعددة."},"recommendation":{"en":"Empowers agents to dynamically select and apply appropriate writing styles using Vercel''s AI SDK v6 framework, enabling consistent tone adaptation for technical blogs, social media content, and tutorial formats based on platform-specific requirements.","zh":"利用 Vercel 的 AI SDK v6 框架，使代理能够动态选择和应用适当的写作风格，从而根据特定平台的要求，为技术博客、社交媒体内容和教程格式实现一致的语调调整。","ja":"VercelのAI SDK v6フレームワークを使用して、エージェントが適切な書き方スタイルを動的に選択および適用できるようにし、プラットフォーム固有の要件に基づいて、技術ブログ、ソーシャルメディアコンテンツ、チュートリアル形式で一貫したトーン適応を可能にします。","ko":"Vercel의 AI SDK v6 프레임워크를 사용하여 에이전트가 적절한 작성 스타일을 동적으로 선택하고 적용할 수 있도록 하여, 플랫폼별 요구 사항에 따라 기술 블로그, 소셜 미디어 콘텐츠 및 튜토리얼 형식을 위한 일관된 어조 적용을 가능하게 합니다.","es":"Habilita a los agentes a seleccionar y aplicar dinámicamente estilos de escritura adecuados utilizando el framework de Vercel''s AI SDK v6, lo que permite una adaptación de tono coherente para blogs técnicos, contenido de redes sociales y formatos de tutoriales basados en requisitos específicos de la plataforma.","fr":"Permet aux agents de sélectionner et d''appliquer dynamiquement des styles d''écriture appropriés en utilisant le framework Vercel''s AI SDK v6, ce qui permet une adaptation de ton cohérente pour les blogs techniques, le contenu des réseaux sociaux et les formats de tutoriels basés sur les exigences spécifiques à la plateforme.","de":"Ermöglicht es Agents, geeignete Schreibstile dynamisch auszuwählen und anzuwenden, indem sie das Vercel''s AI SDK v6-Framework verwenden, was eine konsistente Tonanpassung für technische Blogs, soziale Medieninhalte und Tutorialformate ermöglicht, basierend auf plattformspezifischen Anforderungen.","pt":"Habilita os agentes a selecionar e aplicar dinamicamente estilos de escrita apropriados usando o framework Vercel''s AI SDK v6, permitindo adaptação de tom consistente para blogs técnicos, conteúdo de mídia social e formatos de tutorial com base em requisitos específicos de plataforma.","ru":"Позволяет агентам динамически выбирать и применять подходящие стили письма с использованием фреймворка Vercel''s AI SDK v6, обеспечивая последовательную адаптацию тона для технических блогов, контента социальных сетей и форматов уроков на основе требований конкретной платформы.","ar":"تمكّن الوكلاء من اختيار وتطبيق أساليب الكتابة المناسبة بشكل ديناميكي باستخدام إطار Vercel''s AI SDK v6، مما يتيح تعديل النبرة المتسقة للمدونات الفنية والوسائط الاجتماعية وأنماط الدرس بالاعتماد على متطلبات منصة معينة."},"useCases":{"en":["Generating platform-optimized social media content for LinkedIn and X/Twitter","Creating deep technical blog posts with consistent tone","Producing tutorial content with structured learning pathways","Adapting writing style dynamically based on audience analysis"],"zh":["为 LinkedIn 和 X/Twitter 生成平台优化的社交媒体内容","创建具有一致语调的深度技术博客文章","生成具有结构化学习路径的教程内容","基于受众分析动态调整写作风格"],"ja":["LinkedInおよびX/Twitter向けのプラットフォーム最適化されたソーシャルメディアコンテンツの生成","一貫したトーンを持つ深い技術ブログ記事の作成","構造化された学習パスを持つチュートリアルコンテンツの制作","オーディエンス分析に基づいた書き方スタイルの動的適応"],"ko":["LinkedIn 및 X/Twitter용 플랫폼 최적화 소셜 미디어 콘텐츠 생성","일관된 어조를 가진 심층 기술 블로그 게시물 작성","구조화된 학습 경로가 있는 튜토리얼 콘텐츠 제작","청중 분석을 기반으로 한 작성 스타일 동적 적용"],"es":["Generar contenido de redes sociales optimizado para la plataforma para LinkedIn y X/Twitter","Crear publicaciones de blog técnicas profundas con tono coherente","Producir contenido de tutoriales con rutas de aprendizaje estructuradas","Adaptar el estilo de escritura dinámicamente en función del análisis de la audiencia"],"fr":["Générer du contenu de réseaux sociaux optimisé pour la plateforme pour LinkedIn et X/Twitter","Créer des billets de blog techniques approfondis avec un ton cohérent","Produire du contenu de tutoriels avec des parcours d''apprentissage structurés","Adapter le style d''écriture de manière dynamique en fonction de l''analyse de l''audience"],"de":["Plattform-optimierten sozialen Medieninhalt für LinkedIn und X/Twitter generieren","Tiefgehende technische Blog-Beiträge mit konsistentem Ton erstellen","Tutorial-Inhalte mit strukturierten Lernwegen produzieren","Schreibstil dynamisch basierend auf der Zielgruppenanalyse anpassen"],"pt":["Geração de conteúdo de mídia social otimizado para plataforma para LinkedIn e X/Twitter","Criação de posts de blog técnicos profundos com tom consistente","Produção de conteúdo de tutorial com caminhos de aprendizado estruturados","Adaptação do estilo de escrita dinamicamente com base na análise de audiência"],"ru":["Генерация контента социальных сетей, оптимизированного для платформы для LinkedIn и X/Twitter","Создание глубоких технических блог-постов с последовательным тоном","Производство контента уроков с структурированными путями обучения","Динамическая адаптация стиля письма на основе анализа аудитории"],"ar":["توليد محتوى وسائط اجتماعية محسّن لمنصة لينكد إن و إكس/تويتر","إنشاء منشورات مدونة تقنية متعمقة ذات نبرة متسقة","إنتاج محتوى درس مع مسارات تعلم منسقة","تعديل أسلوب الكتابة بشكل ديناميكي بالاعتماد على تحليل الجمهور"]},"limitations":{"en":["Requires Vercel AI SDK v6 integration","Dependent on style selection framework accuracy","Platform-specific formatting constraints may apply"],"zh":["需要集成 Vercel AI SDK v6","依赖于风格选择框架的准确性","可能适用平台特定的格式约束"],"ja":["Vercel AI SDK v6の統合が必要","スタイル選択フレームワークの精度に依存","プラットフォーム固有のフォーマット制約が適用される場合あり"],"ko":["Vercel AI SDK v6 통합 필요","스타일 선택 프레임워크의 정확도에 의존","플랫폼별 형식 제약이 적용될 수 있음"],"es":["Requiere integración con Vercel AI SDK v6","Dependiente de la precisión del marco de selección de estilos","Es posible que se apliquen restricciones de formato específicas de la plataforma"],"fr":["Nécessite une intégration avec Vercel AI SDK v6","Dépend de la précision du cadre de sélection de styles","Des contraintes de formatage spécifiques à la plateforme peuvent s''appliquer"],"de":["Benötigt Vercel AI SDK v6-Integration","Abhängig von der Genauigkeit des Style-Auswahl-Frameworks","Plattformspezifische Formatierungsbeschränkungen können gelten"],"pt":["Requer integração com Vercel AI SDK v6","Depende da precisão do framework de seleção de estilo","Pode aplicar restrições de formatação específicas de plataforma"],"ru":["Требует интеграции с Vercel AI SDK v6","Зависит от точности фреймворка выбора стиля","Может применять ограничения форматирования, специфичные для платформы"],"ar":["يتطلب تكاملًا مع Vercel AI SDK v6","يعتمد على دقة إطار اختيار الأسلوب","يمكن أن يطبّق قيود تنسيق محددة بالمنصة"]},"version":3},"contentHash":"879faed0bbb5770dc73f2027b7637b607fa0a7c70d0e8f6eef03f2435dd02941","qualityScore":37}');
