INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chrispangg/deepagentsdk/content-writer', 'content-writer', 'chrispangg', 'deepagentsdk', 'community', 'content-writer chrispangg deepagentsdk community content-writer是一个基于Vercel AI SDK v6构建的AI代理框架，帮助开发者快速集成AI功能到应用中，支持多种开发语言和平台。 content-writerは、Vercel AI SDK v6を基盤とするAIエージェントフレームワークで、開発者がアプリにAI機能を簡単に統合できるように設計されています。 content-writer는 Vercel AI SDK v6를 기반으로 한 AI 에이전트 프레임워크로, 개발자가 애플리케이션에 AI 기능을 쉽게 통합할 수 있도록 지원합니다. Content Writer es un framework de Deep Agent Harness construido con Vercel AI SDK v6 para desarrolladores Content Writer est un framework de Deep Agent Harness construit avec Vercel AI SDK v6 pour les développeurs Content Writer ist ein Framework von Deep Agent Harness, entwickelt mit Vercel AI SDK v6 für Entwickler O content-writer é um framework de agente de IA construído com Vercel''s AI SDK v6, projetado para automatizar e otimizar a criação de conteúdo técnico para desenvolvedores. content-writer — это фреймворк для ИИ агентов, созданный на Vercel AI SDK v6, предназначенный для автоматизации и оптимизации создания технического контента для разработчиков. content-writer هو إطار عمل لوكلاء الذكاء الاصطناعي مبني على Vercel AI SDK v6، مصمم لأتمتة وتحسين إنشاء المحتوى التقني للمطورين. A Deep Agent Harness framework built with Vercel''s AI SDK v6 AI代理框架 Vercel AI SDK使用指南 content-writer安装 AI工具集成 React AI代理 Node.js AI开发 content-writer vs其他框架 如何部署AI代理 A Deep Agent Harness framework built with Vercel''s AI SDK v6');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RosenGray/sima/sima-form-edit-mode', 'community', 'RosenGray', 'sima', 'RosenGray/sima', 'sima-form-edit-mode', 0, 0, 37, '2026-03-04T13:07:01.821Z', '2026-03-04T14:39:01.883Z', 'd1fe0d753f1887b961de15563d7ca5e010ac6bf0840dbb258f1b133e154dcc15', '{"id":"RosenGray/sima/sima-form-edit-mode","name":"sima-form-edit-mode","description":{"zh":"Sima表单编辑模式是一种AI智能工具，帮助开发者高效编辑和管理表单","ja":"Simaフォーム編集モードは、開発者が効率的にフォームを編集および管理できるAIエージェントです","ko":"Sima 폼 편집 모드는 개발자가 효율적으로 폼을 편집 및 관리할 수 있는 AI 에이전트입니다","es":"Sima Form Edit Mode es una herramienta de AI que permite a los desarrolladores editar y personalizar formularios de manera eficiente","fr":"Sima Form Edit Mode est un outil d''IA qui permet aux développeurs d''éditer et de personnaliser des formulaires de manière efficace","de":"Sima Form Edit Mode ist ein KI-Tool, das es Entwicklern ermöglicht, Formulare effizient zu bearbeiten und anzupassen","pt":"A Sima Form Edit Mode é uma ferramenta de edição de formulários baseada em IA que melhora a experiência do usuário. Com recursos avançados de edição, essa ferramenta é ideal para desenvolvedores","ru":"Sima Форма Режим Редактирования - это инструмент для редактирования форм на основе ИИ, который улучшает опыт пользователя. С помощью продвинутых функций редактирования, этот инструмент идеален для разработчиков","ar":"سيما نموذج تحرير الوضع هي أداة تحرير النماذج التي تعتمد على الذكاء الاصطناعي لتحسين تجربة المستخدم. مع ميزات متقدمة للتحرير، هذه الأداة مثالية للمطورين","en":"Sima Board "},"seo":{"title":{"zh":"Sima表单编辑模式 - AI智能工具","ja":"Simaフォーム編集モード - AIエージェント","ko":"Sima 폼 편집 모드 - AI 에이전트","es":"Herramientas de AI: Sima Form Edit Mode","fr":"Outils d''IA: Sima Form Edit Mode","de":"KI-Tools: Sima Form Edit Mode","pt":"Sima Form Edit Mode: Ferramenta de Edição de Formulários ...","ru":"Sima Форма Режим Редактирования: ИИ Ин