INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RosenGray/sima/sima-form-edit-mode', 'sima-form-edit-mode', 'RosenGray', 'sima', 'community', 'sima-form-edit-mode RosenGray sima community Sima表单编辑模式是一种AI智能工具，帮助开发者高效编辑和管理表单 Simaフォーム編集モードは、開発者が効率的にフォームを編集および管理できるAIエージェントです Sima 폼 편집 모드는 개발자가 효율적으로 폼을 편집 및 관리할 수 있는 AI 에이전트입니다 Sima Form Edit Mode es una herramienta de AI que permite a los desarrolladores editar y personalizar formularios de manera eficiente Sima Form Edit Mode est un outil d''IA qui permet aux développeurs d''éditer et de personnaliser des formulaires de manière efficace Sima Form Edit Mode ist ein KI-Tool, das es Entwicklern ermöglicht, Formulare effizient zu bearbeiten und anzupassen A Sima Form Edit Mode é uma ferramenta de edição de formulários baseada em IA que melhora a experiência do usuário. Com recursos avançados de edição, essa ferramenta é ideal para desenvolvedores Sima Форма Режим Редактирования - это инструмент для редактирования форм на основе ИИ, который улучшает опыт пользователя. С помощью продвинутых функций редактирования, этот инструмент идеален для разработчиков سيما نموذج تحرير الوضع هي أداة تحرير النماذج التي تعتمد على الذكاء الاصطناعي لتحسين تجربة المستخدم. مع ميزات متقدمة للتحرير، هذه الأداة مثالية للمطورين Sima Board Sima表单编辑模式 AI智能工具 表单编辑 如何使用Sima Sima替代品 Sima安装 Sima设置指南 React表单编辑 Node.js表单管理 Sima Board ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kennethbigler/react-home/accessibility', 'community', 'kennethbigler', 'react-home', 'kennethbigler/react-home', 'accessibility', 0, 0, 37, '2026-03-04T13:07:01.882Z', '2026-03-04T14:53:56.294Z', '3871d3ef2064246d242bc0f01457987164c4cf2a41f509c0cb905628bf724d05', '{"id":"kennethbigler/react-home/accessibility","name":"accessibility","description":{"zh":"使用 ReactJS 创建无障碍首页，提升用户体验和搜索引擎优化","ja":"ReactJS でアクセシブルなホームページを作成して、ユーザーエクスペリエンスと SEO を向上させる","ko":"ReactJS로 접근성 있는 홈페이지를 만들고 사용자 경험과 검색 엔진 최적화를 향상시키는 방법","es":"Desarrolla aplicaciones web accesibles con ReactJS y herramientas de accesibilidad AI","fr":"Développez des applications web accessibles avec ReactJS et des outils d''accessibilité IA","de":"Entwickeln Sie zugängliche Webanwendungen mit ReactJS und Accessibility-AI-Tools","pt":"Desenvolva soluções de acessibilidade em ReactJS com nossas ferramentas de IA. Crie uma homepage acessível e melhore a experiência do usuário.","ru":"Разработайте решения для аксессуабилити на ReactJS с помощью наших ИИ Агентов. Создайте доступную главную страницу и улучшите пользовательский опыт.","ar":"قم بإنشاء حلول إمكانية الوصول في ReactJS باستخدام أدواتنا الذكية. أنشئ صفحة 主页 قابلة للوصول و تحسين تجربة المستخدم.","en":"Homepage created in ReactJS"},"seo":{"title":{"zh":"AI智能体 无障碍 ReactJS 首页","ja":"AIエージェント アクセシビリティ ReactJS ホームページ","ko":"AI 에이전트 접근성 ReactJS 홈ページ","es":"Herramientas de accesibilidad AI: ReactJS para desarrolla...","fr":"Outils d''accessibilité IA: Création de page d''accueil ave...","de":"Accessibility AI-Tools: Erstellung einer Homepage mit Rea...","pt":"Ferramentas de Acessibilidade: Desenvolvimento em ReactJS","ru":"ИИ Агенты для Аксессуабилити: Разработка на ReactJS","ar":"أدوات إمكانية الوصول: إنشاء صفحة 主页 باستخدام ReactJS","en":"accessibility"},"description":{"zh":"使用 ReactJS 创建无障碍首页，提升用户体验和搜索引擎优化","ja":"ReactJS でアクセシブルなホームページを作成して、ユーザーエクスペリエンスと SEO を向上させる","ko":"ReactJS로 접근성 있는 홈페이지를 만들고 사용자 경험과 검색 엔진 최적화를 향상시키는 방법","es":"Desarrolla aplicaciones web accesibles con ReactJS y herramientas de accesibilidad AI","fr":"Développez des applications web accessibles avec ReactJS et des outils d''accessibilité IA","de":"Entwickeln Sie zugängliche Webanwendungen mit ReactJS und Accessibility-AI-Tools","pt":"Desenvolva soluções de acessibilidade em ReactJS com nossas ferramentas de IA. Crie uma homepage acessível e melhore a experiência do usuário.","ru":"Разработайте решения для аксессуабилити на ReactJS с помощью наших ИИ Агентов. Создайте доступную главную страницу и улучшите пользовательский опыт.","ar":"قم بإنشاء حلول إمكانية الوصول في ReactJS باستخدام أدواتنا الذكية. أنشئ صفحة 主页 قابلة للوصول و تحسين تجربة المستخدم.","en":"Homepage created in ReactJS"},"definition":{"en":"Homepage created in ReactJS"},"features":{"zh":["使用 ReactJS 创建无障碍首页","支持多种屏幕阅读器","高对比度颜色方案","键盘导航支持","语义化 HTML 代码"],"ja":["ReactJS でアクセシブルなホームページを作成","複数のスクリーンリーダーに対応","高コントラストカラー_scheme","キーボードナビゲーション対応","セマンティック HTML コード"],"ko":["ReactJS로 접근성 있는 홈페이지를 만들기","다수의 스크린 리더 지원","고대비 색상 체계","키보드 내비게이션 지원","의미론적 HTML 코드"],"es":["Creación de sitios web accesibles con ReactJS","Implementación de herramientas de accesibilidad AI","Mejora de la experiencia del usuario","Cumplimiento de estándares de accesibilidad","Integración con tecnologías de asistencia"],"fr":["Création de sites web accessibles avec ReactJS","Mise en œuvre d''outils d''accessibilité IA","Amélioration de l''expérience utilisateur","Respect des normes d''accessibilité","Intégration avec des technologies d''assistance"],"de":["Erstellung von zugänglichen Webseiten mit ReactJS","Implementierung von Accessibility-AI-Tools","Verbesserung der Benutzererfahrung","Einhaltung von Accessibility-Standards","Integration mit Assistenztechnologien"],"pt":["Desenvolvimento de soluções de acessibilidade em ReactJS","Criação de homepage acessível","Melhoria da experiência do usuário","Integração com ferramentas de IA","Compatibilidade com dispositivos móveis"],"ru":["Разработка решений для аксессуабилити на ReactJS","Создание доступной главной страницы","Улучшение пользовательского опыта","Интеграция с ИИ Агентами","Совместимость с мобильными устройствами"],"ar":["إنشاء حلول إمكانية الوصول في ReactJS","إنشاء صفحة 主页 قابلة للوصول","تحسين تجربة المستخدم","التكامل مع أدوات الذكاء الاصطناعي","التوافق مع الأجهزة المحمولة"]},"keywords":{"zh":["如何使用 ReactJS 创建无障碍首页","什么是无障碍","ReactJS 无障碍教程","无障碍 ReactJS 示例","ReactJS 安装","ReactJS 设置指南","ReactJS 替代方案","ReactJS vs Angular"],"ja":["ReactJS でアクセシブルなホームページを作成する方法","AIエージェントとは","ReactJS アクセシビリティチュートリアル","アクセシブルな ReactJS サンプル","ReactJS インストール","ReactJS 設定ガイド","ReactJS の代替","ReactJS vs Angular"],"ko":["ReactJS로 접근성 있는 홈페이지를 만들기","AI 에이전트란","ReactJS 접근성 튜토리얼","접근성 있는 ReactJS 샘플","ReactJS 설치","ReactJS 설정 가이드","ReactJS 대안","ReactJS vs Angular"],"es":["herramientas de accesibilidad AI","ReactJS para desarrolladores","creación de sitios web accesibles","mejora de la experiencia del usuario","cumplimiento de estándares de accesibilidad","alternativas a herramientas de accesibilidad","guía de instalación de herramientas de accesibilidad","configuración de herramientas de accesibilidad"],"fr":["outils d''accessibilité IA","ReactJS pour développeurs","création de sites web accessibles","amélioration de l''expérience utilisateur","respect des normes d''accessibilité","alternatives aux outils d''accessibilité","guide d''installation des outils d''accessibilité","configuration des outils d''accessibilité"],"de":["Accessibility-AI-Tools","ReactJS für Entwickler","Erstellung von zugänglichen Webseiten","Verbesserung der Benutzererfahrung","Einhalten von Accessibility-Standards","Alternativen zu Accessibility-Tools","Installationsanleitung für Accessibility-Tools","Konfiguration von Accessibility-Tools"],"pt":["como criar soluções de acessibilidade em ReactJS","ferramentas de IA para acessibilidade","desenvolvimento de aplicativos acessíveis","ReactJS para acessibilidade","acessibilidade em dispositivos móveis","guia de instalação de ferramentas de acessibilidade"],"ru":["как создать решения для аксессуабилити на ReactJS","ИИ Агенты для аксессуабилити","разработка доступных приложений","ReactJS для аксессуабилити","аксессуабилити на мобильных устройствах","руководство по установке инструментов аксессуабилити"],"ar":["كيفية إنشاء حلول إمكانية الوصول في ReactJS","أدوات الذكاء الاصطناعي لإمكانية الوصول","إنشاء تطبيقات قابلة للوصول","ReactJS لإمكانية الوصول","إمكانية الوصول على الأجهزة المحمولة","دليل تثبيت أدوات إمكانية الوصول"]}},"owner":"kennethbigler","repo":"react-home","repoPath":"kennethbigler/react-home","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.882Z","topics":[],"category":"community","skillMd":{"name":"accessibility","description":"WCAG 2.2 Level AA accessibility standards for React components. Ensures semantic HTML, keyboard navigation, ARIA usage, color contrast, form labels, and screen reader support.","bodyPreview":"# Web Accessibility Standards\n\n## Core Principles (WCAG 2.2)\n\nAll code must follow [WCAG 2.2 Level AA](https://www.w3.org/TR/WCAG22/) standards:\n\n1. **Perceivable** - Information must be presentable to all users\n2. **Operable** - UI components must be operable by all users\n3. **Understandable** - Information and operation must be clear\n4. **Robust** - Content must work with current and future technologies\n\n## Essential Requirements\n\n### 1. Semantic HTML First\n\nAlways use native HTML elements bef","body":"# Web Accessibility Standards\n\n## Core Principles (WCAG 2.2)\n\nAll code must follow [WCAG 2.2 Level AA](https://www.w3.org/TR/WCAG22/) standards:\n\n1. **Perceivable** - Information must be presentable to all users\n2. **Operable** - UI components must be operable by all users\n3. **Understandable** - Information and operation must be clear\n4. **Robust** - Content must work with current and future technologies\n\n## Essential Requirements\n\n### 1. Semantic HTML First\n\nAlways use native HTML elements before custom implementations:\n\n```tsx\n// ✅ GOOD: Native semantics\n<button onClick={handleClick}>Submit</button>\n<a href=\"/page\">Navigate</a>\n<input type=\"checkbox\" />\n\n// ❌ BAD: Custom elements without semantics\n<div onClick={handleClick}>Submit</div>\n<span onClick={navigate}>Navigate</span>\n```\n\n### 2. Text Alternatives\n\nAll non-text content must have text alternatives:\n\n```tsx\n// ✅ GOOD: Descriptive alt text\n<img src=\"/chart.png\" alt=\"Sales increased 25% in Q4 2024\" />\n\n// ✅ GOOD: Empty alt for decorative images\n<img src=\"/decoration.png\" alt=\"\" />\n\n// ✅ GOOD: Icon buttons with labels\n<button aria-label=\"Close dialog\">\n  <IconClose aria-hidden=\"true\" />\n</button>\n\n// ❌ BAD: Missing alt text\n<img src=\"/chart.png\" />\n```\n\n### 3. Keyboard Accessibility\n\nAll interactive elements must be keyboard accessible:\n\n**Required keyboard support:**\n- `Tab`/`Shift+Tab` - Navigate between elements\n- `Enter` - Activate buttons/links\n- `Space` - Activate buttons/checkboxes\n- `Escape` - Close modals/dialogs\n- Arrow keys - Navigate menus/tabs/lists\n\n```tsx\n// ✅ GOOD: Keyboard accessible\n<button onClick={handleClick}>Click me</button>\n\n// ❌ BAD: Not keyboard accessible\n<div onClick={handleClick}>Click me</div>\n```\n\n### 4. Visible Focus Indicators\n\nAll interactive elements must have visible focus indicators:\n\n```css\n/* ✅ GOOD: Visible focus indicator */\nbutton:focus-visible {\n  outline: 2px solid #0066CC;\n  outline-offset: 2px;\n}\n\n/* ❌ BAD: Removing focus outline */\nbutton:focus {\n  outline: none;\n}\n```\n\n### 5. Color and Contrast\n\n**WCAG AA Requirements:**\n- Normal text (< 18pt): 4.5:1 minimum\n- Large text (≥ 18pt or bold 14pt): 3:1 minimum\n- UI components: 3:1 minimum\n\n```tsx\n// ❌ BAD: Color is only indicator\n<span style={{ color: ''red'' }}>Error occurred</span>\n\n// ✅ GOOD: Icon + text + color\n<span style={{ color: ''red'' }}>\n  <IconError aria-hidden=\"true\" />\n  Error: Invalid email address\n</span>\n```\n\n### 6. Form Accessibility\n\nAll form inputs must have associated labels:\n\n```tsx\n// ✅ GOOD: Proper form structure\n<label htmlFor=\"email\">\n  Email Address\n  <span aria-label=\"required\">*</span>\n</label>\n<input\n  id=\"email\"\n  type=\"email\"\n  required\n  aria-required=\"true\"\n  aria-invalid={!!error}\n  aria-describedby={error ? \"email-error\" : undefined}\n/>\n{error && (\n  <div id=\"email-error\" role=\"alert\">\n    {error}\n  </div>\n)}\n\n// ❌ BAD: Placeholder as label\n<input type=\"email\" placeholder=\"Email Address\" />\n```\n\n### 7. Heading Hierarchy\n\nUse proper heading levels without skipping:\n\n```tsx\n// ✅ GOOD: Logical hierarchy\n<h1>Page Title</h1>\n  <h2>Section 1</h2>\n    <h3>Subsection 1.1</h3>\n  <h2>Section 2</h2>\n\n// ❌ BAD: Skipping levels\n<h1>Page Title</h1>\n<h4>Section</h4>  // Skipped h2, h3\n```\n\n### 8. ARIA Usage\n\nUse ARIA only when native HTML is insufficient:\n\n```tsx\n// Common ARIA patterns\n<button\n  aria-expanded={isOpen}\n  aria-controls=\"menu-id\"\n>\n  Menu\n</button>\n\n<div\n  role=\"dialog\"\n  aria-modal=\"true\"\n  aria-labelledby=\"dialog-title\"\n>\n  <h2 id=\"dialog-title\">Dialog Title</h2>\n</div>\n\n<div role=\"alert\">Critical error occurred</div>\n<div role=\"status\" aria-live=\"polite\">Loading complete</div>\n```\n\n### 9. Focus Management\n\nManage focus for dynamic content:\n\n```tsx\n// ✅ GOOD: Modal with focus management\nconst Modal = ({ isOpen, onClose, title }) => {\n  const modalRef = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    if (!isOpen) return;\n\n    const previousFocus = document.activeElement;\n    modalRef.current?.querySelector(''button'')?.focus();\n\n    const handleEscape = (e: KeyboardEvent) => {\n      if (e.key === ''Escape'') onClose();\n    };\n\n    document.addEventListener(''keydown'', handleEscape);\n\n    return () => {\n      document.removeEventListener(''keydown'', handleEscape);\n      (previousFocus as HTMLElement)?.focus();\n    };\n  }, [isOpen, onClose]);\n\n  return (\n    <div ref={modalRef} role=\"dialog\" aria-modal=\"true\">\n      <h2>{title}</h2>\n      <button onClick={onClose}>Close</button>\n    </div>\n  );\n};\n```\n\n### 10. Dynamic Content Announcements\n\nAnnounce dynamic content changes to screen readers:\n\n```tsx\n// Status messages (polite - wait for user)\n<div role=\"status\" aria-live=\"polite\">\n  {statusMessage}\n</div>\n\n// Error alerts (assertive - interrupt)\n<div role=\"alert\" aria-live=\"assertive\">\n  {errorMessage}\n</div>\n```\n\n## Common Patterns\n\n### Screen Reader Only Text\n\n```tsx\nconst srOnly: React.CSSProperties = {\n  position: ''absolute'',\n  width: ''1px'',\n  height: ''1px'',\n  padding: ''0'',\n  margin: ''-1px'',\n  overflow: ''hidden'',\n  clip: ''rect(0, 0, 0, 0)'',\n  whiteSpace: ''nowrap'',\n  border: ''0'',\n};\n\n<button>\n  <IconTrash />\n  <span style={srOnly}>Delete item</span>\n</button>\n```\n\n### Skip Links\n\n```tsx\n<a href=\"#main-content\" className=\"skip-link\">\n  Skip to main content\n</a>\n<header>...</header>\n<main id=\"main-content\">...</main>\n```\n\n### Accessible Tables\n\n```tsx\n<table>\n  <caption>Sales Data Q4 2024</caption>\n  <thead>\n    <tr>\n      <th scope=\"col\">Month</th>\n      <th scope=\"col\">Revenue</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th scope=\"row\">October</th>\n      <td>$50,000</td>\n    </tr>\n  </tbody>\n</table>\n```\n\n## Top 10 Mistakes to Avoid\n\n1. **Missing alt text** on images\n2. **Using `<div>` or `<span>` instead of `<button>`** for actions\n3. **Missing form labels** (using placeholder instead)\n4. **Removing focus outline** without replacement\n5. **Skipping heading levels** (h1 → h4)\n6. **Insufficient color contrast** (< 4.5:1)\n7. **Color as only indicator** (no icon/text)\n8. **No keyboard access** to interactive elements\n9. **Not announcing dynamic content** changes\n10. **Icon buttons without labels** or aria-label\n\n## Testing Checklist\n\n### Automated Testing\n- Use axe-core, Lighthouse, or WAVE browser extensions\n- Add automated tests with jest-axe or similar tools\n\n### Manual Testing\n- [ ] Tab through all interactive elements\n- [ ] All elements reachable by keyboard\n- [ ] Focus visible on all elements\n- [ ] Enter/Space activates buttons\n- [ ] Escape closes modals\n- [ ] Works at 200% zoom\n- [ ] Color contrast meets WCAG AA\n- [ ] Test with screen reader (VoiceOver/NVDA/JAWS)\n\n## Resources\n\n- **WCAG 2.2 Guidelines**: https://www.w3.org/TR/WCAG22/\n- **WCAG Quick Reference**: https://www.w3.org/WAI/WCAG22/quickref/\n- **ARIA Authoring Practices**: https://www.w3.org/WAI/ARIA/apg/\n- **WebAIM**: https://webaim.org/\n- **MDN Accessibility**: https://developer.mozilla.org/en-US/docs/Web/Accessibility\n\n## Best Practices Summary\n\n### ✅ Always Do\n1. Use semantic HTML first\n2. Provide text alternatives\n3. Ensure keyboard accessibility\n4. Maintain sufficient color contrast\n5. Manage focus for dynamic content\n6. Use proper heading hierarchy\n7. Label all form inputs\n8. Test with assistive technology\n\n### ❌ Never Do\n1. Remove focus outline without replacement\n2. Use color as only indicator\n3. Create keyboard traps\n4. Skip heading levels\n5. Use placeholder as label\n6. Make non-interactive elements clickable\n7. Rely solely on automated testing\n8. Add ARIA when native HTML works\n"},"lastSynced":"2026-03-04T14:53:56.294Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing to ensure WCAG 2.2 compliance in web development projects.","zh":"非常适合需要确保Web开发项目符合WCAG 2.2标准的Frontend Agent。","ja":"Web開発プロジェクトにおいてWCAG 2.2準拠を確保する必要があるFrontend Agentに最適です。","ko":"웹 개발 프로젝트에서 WCAG 2.2 준수를 보장해야 하는 프론트엔드 에이전트에게 완벽합니다.","es":"Perfecto para Agentes Frontend que necesitan garantizar el cumplimiento de WCAG 2.2 en proyectos de desarrollo web.","fr":"Parfait pour les Agents Frontend ayant besoin de garantir la conformité WCAG 2.2 dans les projets de développement web.","de":"Perfekt für Frontend Agents, die die Einhaltung von WCAG 2.2 in Webentwicklungsprojekten sicherstellen müssen.","pt":"Perfeito para Agentes Frontend que precisam garantir a conformidade com a WCAG 2.2 em projetos de desenvolvimento web.","ru":"Идеально подходит для агентов Frontend, которым необходимо обеспечить соответствие требованиям WCAG 2.2 в проектах веб-разработки.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى ضمان مطابقة WCAG 2.2 في مشاريع تطوير الويب."},"recommendation":{"en":"Empowers agents to create accessible web interfaces using semantic HTML, following WCAG 2.2 Level AA standards, and ensuring perceivable, operable, understandable, and robust content for all users, leveraging technologies like ReactJS.","zh":"赋能Agent使用语义化HTML创建可访问的Web界面，遵循WCAG 2.2 Level AA标准，并利用ReactJS等技术，确保所有用户都能获得可感知、可操作、可理解且稳健的内容。","ja":"セマンティックHTMLを使用してアクセシブルなWebインターフェースを作成し、WCAG 2.2 Level AA標準に従い、ReactJSなどの技術を活用して、すべてのユーザーにとって知覚可能、操作可能、理解可能、かつ堅牢なコンテンツを保証するようにAgentを支援します。","ko":"의미론적 HTML을 사용하여 접근 가능한 웹 인터페이스를 생성하고, WCAG 2.2 Level AA 표준을 준수하며, ReactJS와 같은 기술을 활용하여 모든 사용자를 위한 인지 가능하고, 작동 가능하며, 이해 가능하고, 강력한 콘텐츠를 보장하도록 에이전트를 지원합니다.","es":"Empodera a los agentes para crear interfaces web accesibles utilizando HTML semántico, siguiendo los estándares WCAG 2.2 Nivel AA, y garantizando contenido perceptible, operable, comprensible y robusto para todos los usuarios, aprovechando tecnologías como ReactJS.","fr":"Permet aux agents de créer des interfaces web accessibles en utilisant du HTML sémantique, en suivant les normes WCAG 2.2 Niveau AA, et en garantissant un contenu perceptible, utilisable, compréhensible et robuste pour tous les utilisateurs, en tirant parti de technologies comme ReactJS.","de":"Ermächtigt Agents, zugängliche Weboberflächen mit semantischem HTML zu erstellen, indem sie den WCAG 2.2 Level AA-Standards folgen und wahrnehmbare, bedienbare, verständliche und robuste Inhalte für alle Benutzer sicherstellen, unter Nutzung von Technologien wie ReactJS.","pt":"Habilita os agentes a criar interfaces web acessíveis usando HTML semântico, seguindo os padrões do nível AA da WCAG 2.2, e garantindo conteúdo perceptível, operável, compreensível e robusto para todos os usuários, aproveitando tecnologias como o ReactJS.","ru":"Наделяет агентов возможностью создавать доступные веб-интерфейсы с использованием семантического HTML, следуя стандартам уровня AA WCAG 2.2, и обеспечивающих воспринимаемый, управляемый, понятный и надежный контент для всех пользователей, используя технологии seperti ReactJS.","ar":"يمنح الوكلاء القدرة على إنشاء واجهات ويب قابلة للوصول باستخدام HTML الدلالي ، متبعة معايير المستوى AA من WCAG 2.2 ، وضمان المحتوى القابل للتصور والتشغيل والفهم والمتين لجميع المستخدمين ، واستخدام تقنيات مثل ReactJS."},"useCases":{"en":["Implementing accessible navigation menus for screen readers","Generating semantic HTML templates for new web pages","Validating color contrast and font sizes for visually impaired users"],"zh":["为屏幕阅读器实施可访问的导航菜单","为新网页生成语义化HTML模板","为视障用户验证颜色对比度和字体大小"],"ja":["スクリーンリーダー向けのアクセシブルなナビゲーションメニューの実装","新しいWebページのためのセマンティックHTMLテンプレートの生成","視覚障害ユーザーのための色コントラストとフォントサイズの検証"],"ko":["스크린 리더를 위한 접근성 탐색 메뉴 구현","새 웹 페이지를 위한 의미론적 HTML 템플릿 생성","시각 장애 사용자를 위한 색상 대비 및 글꼴 크기 검증"],"es":["Implementar menús de navegación accesibles para lectores de pantalla","Generar plantillas de HTML semántico para nuevas páginas web","Validar el contraste de color y los tamaños de fuente para usuarios con discapacidad visual"],"fr":["Mettre en œuvre des menus de navigation accessibles pour les lecteurs d''écran","Générer des modèles de HTML sémantique pour de nouvelles pages web","Valider le contraste des couleurs et les tailles de police pour les utilisateurs malvoyants"],"de":["Implementierung zugänglicher Navigationsmenüs für Screenreader","Generieren semantischer HTML-Vorlagen für neue Webseiten","Validieren von Farbkontrast und Schriftgrößen für sehbehinderte Benutzer"],"pt":["Implementação de menus de navegação acessíveis para leitores de tela","Geração de modelos de HTML semântico para novas páginas da web","Validação do contraste de cores e tamanhos de fonte para usuários com deficiência visual"],"ru":["Реализация доступных меню навигации для программ чтения с экрана","Генерация семантических шаблонов HTML для новых веб-страниц","Проверка контраста цветов и размеров шрифта для пользователей с нарушением зрения"],"ar":["تنفيذ قوائم التنقل القابلة للوصول لبرامج قراءة الشاشة","إنشاء قوالب HTML الدلالية للصفحات الويب الجديدة","التحقق من توافق الألوان وأحجام الخطوط للمستخدمين ذوي الإعاقة البصرية"]},"limitations":{"en":["Requires knowledge of HTML and CSS","Limited to web development projects","Must adhere to WCAG 2.2 guidelines"],"zh":["需要具备HTML和CSS知识","仅限于Web开发项目","必须遵守WCAG 2.2指南"],"ja":["HTMLとCSSの知識が必要","Web開発プロジェクトに限定される","WCAG 2.2ガイドラインに従う必要がある"],"ko":["HTML 및 CSS 지식 필요","웹 개발 프로젝트로 제한됨","WCAG 2.2 가이드라인을 준수해야 함"],"es":["Requiere conocimientos de HTML y CSS","Limitado a proyectos de desarrollo web","Debe adherirse a las pautas de WCAG 2.2"],"fr":["Nécessite une connaissance du HTML et du CSS","Limité aux projets de développement web","Doit respecter les directives WCAG 2.2"],"de":["Erfordert Kenntnisse in HTML und CSS","Beschränkt auf Webentwicklungsprojekte","Muss an die WCAG 2.2-Richtlinien halten"],"pt":["Exige conhecimento de HTML e CSS","Limitado a projetos de desenvolvimento web","Deve aderir às diretrizes da WCAG 2.2"],"ru":["Требует знания HTML и CSS","Ограничен проектами веб-разработки","Должен соответствовать руководящим принципам WCAG 2.2"],"ar":["يتطلب معرفة HTML و CSS","محدود بمشاريع تطوير الويب","يجب الالتزام بدلائل WCAG 2.2"]},"version":3},"contentHash":"3871d3ef2064246d242bc0f01457987164c4cf2a41f509c0cb905628bf724d05","qualityScore":37}');
