INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BauplanLabs/case-study-intella/wap-ingestion', 'wap-ingestion', 'BauplanLabs', 'case-study-intella', 'community', 'wap-ingestion BauplanLabs case-study-intella community wap-ingestion是一种使用WAP工作流程进行遥测分析的AI智能代理，案例研究使用Intella和Bauplan wap-ingestionは，WAPワークフローを使用したテレメトリ分析のためのAIエージェントです。IntellaとBauplanを使用したケーススタディ wap-ingestion은 WAP 워크플로우를 사용한 텔레메트리 분석을 위한 AI 에이전트입니다. 인텔라와 바우플랜을 사용한 사례 연구 WAP Ingestion es una herramienta de AI que utiliza el flujo de trabajo WAP para analizar telemetría en Bauplan. Este caso de estudio con Intella muestra su eficacia WAP Ingestion est un outil d''IA qui utilise le flux de travail WAP pour analyser la télémétrie sur Bauplan. Cette étude de cas avec Intella démontre son efficacité WAP Ingestion ist ein KI-Tool, das den WAP-Workflow zur Analyse von Telemetrie in Bauplan verwendet. Dieser Fallstudie mit Intella zeigt seine Effektivität A WAP Ingestion é uma ferramenta de IA que utiliza o workflow Bauplan para análise de telemetria com Intella WAP Ingestion - это ИИ инструмент, использующий рабочий процесс Bauplan для анализа телеметрии с Intella لواب إنجيستن هي أداة ذكاء اصطناعي تستخدم تدفق العمل باوبلان لتحليل التелеметري مع إنترللا A case study with Intella using WAP workflow on Bauplan for telemetry analysis 如何使用wap-ingestion wap-ingestion是什么 Intella替代品 wap-ingestion安装 wap-ingestion设置指南 AI智能代理 WAP工作流程 遥测分析 A case study with Intella using WAP workflow on Bauplan for telemetry analysis');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('udecode/plate/kieran-python-reviewer', 'community', 'udecode', 'plate', 'udecode/plate', 'kieran-python-reviewer', 15986, 958, 36, '2026-03-05T10:09:36Z', '2026-03-06T06:24:00.495Z', '529e07ebdf3d836d516e1563361638b1b20a7a52f40b3e6a38e6ca75fb512856', '{"id":"udecode/plate/kieran-python-reviewer","name":"kieran-python-reviewer","description":{"en":"The kieran-python-reviewer skill provides AI-powered code reviews for Python developers, ensuring adherence to strict conventions and quality standards. It benefits developers working with FastAPI and other Python frameworks.","zh":"kieran-python-reviewer是一个基于AI的Python代码审查工具，利用Rich-text editor和MCP技术","ja":"kieran-python-reviewerはAIエージェントを使用したPythonコードレビュー工具で、Rich-text editorとMCP技術を活用する","ko":"kieran-python-reviewer는 AI를 기반으로 하는 파이썬 코드 리뷰 도구로 Rich-text editor와 MCP 기술을 활용합니다","es":"kieran-python-reviewer es un agente de revisión de código Python que utiliza tecnologías de edición de texto enriquecido y MCP para garantizar la calidad del código","fr":"kieran-python-reviewer est un agent de révision de code Python qui utilise des technologies de texte enrichi et MCP pour garantir la qualité du code","de":"kieran-python-reviewer ist ein Agent zur Überprüfung von Python-Code, der reiche Text-Editing-Technologien und MCP verwendet, um die Code-Qualität zu gewährleisten","pt":"O kieran-python-reviewer é uma ferramenta de revisão de código Python com AI, MCP e shadcn/ui, que ajuda a melhorar a qualidade do código","ru":"kieran-python-reviewer - это инструмент проверки кода Python с ИИ, MCP и shadcn/ui, который помогает улучшить качество кода","ar":"kieran-python-reviewer هو أداة مراجعة كود بايثون بالذكاء الاصطناعي، MCP و shadcn/ui، التي تساعد على تحسين جودة الكود"},"seo":{"title":{"en":"kieran-python-reviewer: AI-Powered Code Review for Python...","zh":"kieran-python-reviewer_SETUP GUIDE: AI代码审查工具","ja":"kieran-python-reviewer設定ガイド: AIエージェントによるPythonコードレビュー","ko":"kieran-python-reviewer설치 가이드: AI를 이용한 파이썬 코드 리뷰 도구","es":"Guía de configuración de kieran-python-reviewer para revi...","fr":"Guide de configuration de kieran-python-reviewer pour la ...","de":"Einrichtungsleitfaden für kieran-python-reviewer zur Über...","pt":"Guia de Configuração do kieran-python-reviewer: Ferrament...","ru":"Настройка kieran-python-reviewer: ИИ Агент для проверки к...","ar":"دليل إعداد kieran-python-reviewer: أداة مراجعة كود بايثون..."},"description":{"en":"Discover how kieran-python-reviewer streamlines Python code quality with AI-driven reviews. Learn how to integrate this skill into your development workflow ...","zh":"使用kieran-python-reviewer实现AI驱动的Python代码审查，确保您的代码质量和安全性","ja":"kieran-python-reviewerを使用してAIエージェントによるPythonコードレビューを実現し、コードの品質とセキュリティを確保する","ko":"kieran-python-reviewer를 사용하여 AI 기반의 파이썬 코드 리뷰를 구현하고 코드의 품질과 보안을 확보하세요","es":"Aprende a configurar kieran-python-reviewer para mejorar la calidad de tu código Python con MCP, shadcn/ui y tecnologías de edición de texto enriquecido","fr":"Découvrez comment configurer kieran-python-reviewer pour améliorer la qualité de votre code Python avec MCP, shadcn/ui et technologies de texte enrichi","de":"Erfahren Sie, wie Sie kieran-python-reviewer einrichten, um die Qualität Ihres Python-Codes mit MCP, shadcn/ui und reichem Text-Editing zu verbessern","pt":"Aprenda a configurar o kieran-python-reviewer, uma ferramenta de revisão de código Python com AI, MCP e shadcn/ui, para melhorar a qualidade do seu código","ru":"Узнайте, как настроить kieran-python-reviewer, инструмент проверки кода Python с ИИ, MCP и shadcn/ui, для улучшения качества вашего кода","ar":"تعرف على كيفية إعداد kieran-python-reviewer، أداة مراجعة كود بايثون بالذكاء الاصطناعي، MCP و shadcn/ui، لتحسين جودة كودك"},"definition":{"en":"kieran-python-reviewer is a rich-text editor skill that utilizes AI, MCP, and shadcn/ui to review Python code, applying strict quality checks and conventions.","zh":"kieran-python-reviewer是一种AI驱动的Python代码审查工具，用于检查和改进代码质量","ja":"kieran-python-reviewerはAIエージェントを使用したPythonコードレビュー工具の一種で、コードの品質をチェックして改良する","ko":"kieran-python-reviewer는 AI 기반의 파이썬 코드 리뷰 도구의 일종으로 코드의 품질을 확인하고 개선합니다","es":"kieran-python-reviewer es un agente de revisión de código que aplica convenciones y controles de calidad de Python","fr":"kieran-python-reviewer est un agent de révision de code qui applique des conventions et des contrôles de qualité Python","de":"kieran-python-reviewer ist ein Agent zur Überprüfung von Code, der Python-Konventionen und Qualitätskontrollen anwendet","pt":"O kieran-python-reviewer é uma ferramenta de revisão de código Python que utiliza AI e outras tecnologias para garantir a qualidade do código","ru":"kieran-python-reviewer - это инструмент проверки кода Python, использующий ИИ и другие технологии для обеспечения качества кода","ar":"kieran-python-reviewer هو أداة مراجعة كود بايثون تستخدم الذكاء الاصطناعي وتكنولوجيا أخرى لضمان جودة الكود"},"features":{"en":["Applies strict Python conventions using AI-driven reviews","Supports integration with FastAPI endpoints for automated code checks","Utilizes shadcn/ui for a rich-text editing experience","Employs MCP for enhanced code analysis and review capabilities","Compatible with Slate and TypeScript for seamless development workflows","Enables automated code reviews for improved quality and standards compliance"],"zh":["支持Rich-text editor","集成MCP技术","使用shadcn/ui组件","支持Slate和TypeScript","提供AI驱动的代码审查功能"],"ja":["Rich-text editorをサポート","MCP技術を統合","shadcn/uiコンポーネントを使用","SlateとTypeScriptをサポート","AIエージェントによるコードレビュー機能を提供"],"ko":["Rich-text editor 지원","MCP 기술 통합","shadcn/ui 컴포넌트 사용","Slate와 TypeScript 지원","AI 기반의 코드 리뷰 기능 제공"],"es":["Revisión de código Python con tecnologías de edición de texto enriquecido","Integración con MCP para garantizar la calidad del código","Compatibilidad con shadcn/ui para una mejor experiencia de usuario","Soporte para React y TypeScript","Capacidad de revisión de código con comentarios y sugerencias"],"fr":["Révision de code Python avec des technologies de texte enrichi","Intégration avec MCP pour garantir la qualité du code","Compatibilité avec shadcn/ui pour une meilleure expérience utilisateur","Prise en charge de React et TypeScript","Capacité de révision de code avec commentaires et suggestions"],"de":["Überprüfung von Python-Code mit reichen Text-Editing-Technologien","Integration mit MCP zur Gewährleistung der Code-Qualität","Kompatibilität mit shadcn/ui für eine bessere Benutzererfahrung","Unterstützung für React und TypeScript","Fähigkeit zur Überprüfung von Code mit Kommentaren und Vorschlägen"],"pt":["Revisão de código Python com AI","Integração com MCP e shadcn/ui","Suporte a FastAPI","Análise de código com Slate e TypeScript","Interface de usuário intuitiva com React"],"ru":["Проверка кода Python с ИИ","Интеграция с MCP и shadcn/ui","Поддержка FastAPI","Анализ кода с Slate и TypeScript","Интуитивный интерфейс пользователя на React"],"ar":["مراجعة كود بايثون بالذكاء الاصطناعي","التكامل مع MCP و shadcn/ui","دعم FastAPI","تحليل الكود مع Slate و TypeScript","واجهة مستخدم直관ية مع React"]},"keywords":{"en":["how to use kieran-python-reviewer","kieran-python-reviewer setup guide","kieran-python-reviewer alternative","kieran-python-reviewer vs pycodechecker","install kieran-python-reviewer","kieran-python-reviewer for FastAPI development","AI-powered Python code review","MCP code analysis","shadcn/ui integration","Slate and TypeScript support"],"zh":["kieran-python-reviewer","AI代码审查","Python代码质量","Rich-text editor","MCP技术","shadcn/ui","Slate","TypeScript","AI工具"],"ja":["kieran-python-reviewer","AIエージェント","Pythonコードレビュー","Rich-text editor","MCP技術","shadcn/ui","Slate","TypeScript","AIエージェント工具"],"ko":["kieran-python-reviewer","AI 기반의 코드 리뷰","파이썬 코드 품질","Rich-text editor","MCP 기술","shadcn/ui","Slate","TypeScript","AI 도구"],"es":["kieran-python-reviewer","revisión de código Python","MCP","shadcn/ui","edición de texto enriquecido","React","TypeScript","herramientas de desarrollo de software","agentes de revisión de código"],"fr":["kieran-python-reviewer","révision de code Python","MCP","shadcn/ui","texte enrichi","React","TypeScript","outils de développement de logiciels","agents de révision de code"],"de":["kieran-python-reviewer","Überprüfung von Python-Code","MCP","shadcn/ui","reiche Text-Editing","React","TypeScript","Software-Entwicklungstools","Code-Überprüfungsagenten"],"pt":["kieran-python-reviewer","ferramenta de revisão de código python","ai para desenvolvimento","mcp","shadcn/ui","fastapi","slate","typescript","react"],"ru":["kieran-python-reviewer","инструмент проверки кода python","ИИ для разработки","mcp","shadcn/ui","fastapi","slate","typescript","react"],"ar":["kieran-python-reviewer","أداة مراجعة كود بايثون","الذكاء الاصطناعي للبرمجة","mcp","shadcn/ui","fastapi","slate","typescript","react"]}},"owner":"udecode","repo":"plate","repoPath":"udecode/plate","stars":15986,"forks":958,"updatedAt":"2026-03-05T10:09:36Z","topics":["ai","mcp","react","shadcn-ui","slate","typescript","wysiwyg"],"category":"community","skillMd":{"name":"kieran-python-reviewer","description":"Reviews Python code with an extremely high quality bar for Pythonic patterns, type safety, and maintainability. Use after implementing features, modifying code, or creating new Python modules.","bodyPreview":"<examples>\n<example>\nContext: The user has just implemented a new FastAPI endpoint.\nuser: \"I''ve added a new user registration endpoint\"\nassistant: \"I''ve implemented the registration endpoint. Now let me have Kieran review this code to ensure it meets our quality standards.\"\n<commentary>\nSince new endpoint code was written, use the kieran-python-reviewer agent to apply Kieran''s strict Python conventions and quality checks.\n</commentary>\n</example>\n<example>\nContext: The user has refactored an exi","body":"<examples>\n<example>\nContext: The user has just implemented a new FastAPI endpoint.\nuser: \"I''ve added a new user registration endpoint\"\nassistant: \"I''ve implemented the registration endpoint. Now let me have Kieran review this code to ensure it meets our quality standards.\"\n<commentary>\nSince new endpoint code was written, use the kieran-python-reviewer agent to apply Kieran''s strict Python conventions and quality checks.\n</commentary>\n</example>\n<example>\nContext: The user has refactored an existing service class.\nuser: \"Please refactor the EmailService class to handle attachments\"\nassistant: \"I''ve refactored the EmailService to handle attachments.\"\n<commentary>\nAfter modifying existing code, especially services, use kieran-python-reviewer to ensure the changes meet Kieran''s high bar for code quality.\n</commentary>\nassistant: \"Let me have Kieran review these changes to the EmailService.\"\n</example>\n<example>\nContext: The user has created new utility functions.\nuser: \"Create a data validation module\"\nassistant: \"I''ve created the data validation module.\"\n<commentary>\nNew modules should be reviewed by kieran-python-reviewer to check Pythonic patterns, type hints, and best practices.\n</commentary>\nassistant: \"I''ll have Kieran review this module to ensure it follows our conventions.\"\n</example>\n</examples>\n\nYou are Kieran, a super senior Python developer with impeccable taste and an exceptionally high bar for Python code quality. You review all code changes with a keen eye for Pythonic patterns, type safety, and maintainability.\n\nYour review approach follows these principles:\n\n## 1. EXISTING CODE MODIFICATIONS - BE VERY STRICT\n\n- Any added complexity to existing files needs strong justification\n- Always prefer extracting to new modules/classes over complicating existing ones\n- Question every change: \"Does this make the existing code harder to understand?\"\n\n## 2. NEW CODE - BE PRAGMATIC\n\n- If it''s isolated and works, it''s acceptable\n- Still flag obvious improvements but don''t block progress\n- Focus on whether the code is testable and maintainable\n\n## 3. TYPE HINTS CONVENTION\n\n- ALWAYS use type hints for function parameters and return values\n- 🔴 FAIL: `def process_data(items):`\n- ✅ PASS: `def process_data(items: list[User]) -> dict[str, Any]:`\n- Use modern Python 3.10+ type syntax: `list[str]` not `List[str]`\n- Leverage union types with `|` operator: `str | None` not `Optional[str]`\n\n## 4. TESTING AS QUALITY INDICATOR\n\nFor every complex function, ask:\n\n- \"How would I test this?\"\n- \"If it''s hard to test, what should be extracted?\"\n- Hard-to-test code = Poor structure that needs refactoring\n\n## 5. CRITICAL DELETIONS & REGRESSIONS\n\nFor each deletion, verify:\n\n- Was this intentional for THIS specific feature?\n- Does removing this break an existing workflow?\n- Are there tests that will fail?\n- Is this logic moved elsewhere or completely removed?\n\n## 6. NAMING & CLARITY - THE 5-SECOND RULE\n\nIf you can''t understand what a function/class does in 5 seconds from its name:\n\n- 🔴 FAIL: `do_stuff`, `process`, `handler`\n- ✅ PASS: `validate_user_email`, `fetch_user_profile`, `transform_api_response`\n\n## 7. MODULE EXTRACTION SIGNALS\n\nConsider extracting to a separate module when you see multiple of these:\n\n- Complex business rules (not just \"it''s long\")\n- Multiple concerns being handled together\n- External API interactions or complex I/O\n- Logic you''d want to reuse across the application\n\n## 8. PYTHONIC PATTERNS\n\n- Use context managers (`with` statements) for resource management\n- Prefer list/dict comprehensions over explicit loops (when readable)\n- Use dataclasses or Pydantic models for structured data\n- 🔴 FAIL: Getter/setter methods (this isn''t Java)\n- ✅ PASS: Properties with `@property` decorator when needed\n\n## 9. IMPORT ORGANIZATION\n\n- Follow PEP 8: stdlib, third-party, local imports\n- Use absolute imports over relative imports\n- Avoid wildcard imports (`from module import *`)\n- 🔴 FAIL: Circular imports, mixed import styles\n- ✅ PASS: Clean, organized imports with proper grouping\n\n## 10. MODERN PYTHON FEATURES\n\n- Use f-strings for string formatting (not % or .format())\n- Leverage pattern matching (Python 3.10+) when appropriate\n- Use walrus operator `:=` for assignments in expressions when it improves readability\n- Prefer `pathlib` over `os.path` for file operations\n\n## 11. CORE PHILOSOPHY\n\n- **Explicit > Implicit**: \"Readability counts\" - follow the Zen of Python\n- **Duplication > Complexity**: Simple, duplicated code is BETTER than complex DRY abstractions\n- \"Adding more modules is never a bad thing. Making modules very complex is a bad thing\"\n- **Duck typing with type hints**: Use protocols and ABCs when defining interfaces\n- Follow PEP 8, but prioritize consistency within the project\n\nWhen reviewing code:\n\n1. Start with the most critical issues (regressions, deletions, breaking changes)\n2. Check for missing type hints and non-Pythonic patterns\n3. Evaluate testability and clarity\n4. Suggest specific improvements with examples\n5. Be strict on existing code modifications, pragmatic on new isolated code\n6. Always explain WHY something doesn''t meet the bar\n\nYour reviews should be thorough but actionable, with clear examples of how to improve the code. Remember: you''re not just finding problems, you''re teaching Python excellence.\n"},"lastSynced":"2026-03-06T06:24:00.495Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing strict Python convention adherence and quality checks for FastAPI frameworks.","zh":"非常适合需要严格遵守Python约定和质量检查的代码审查代理，特别适用于FastAPI框架。","ja":"Pythonの規約と品質チェックを厳密に遵守する必要があるコードレビューエージェントに最適です。特にFastAPIフレームワークに適しています。","ko":"严格한 Python 규약과 품질 확인이 필요한 코드 리뷰 에이전트에게 적합하며, 특히 FastAPI 프레임워크에 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan adherirse estrictamente a las convenciones de Python y realizar controles de calidad para frameworks de FastAPI.","fr":"Parfait pour les Agents de Révision de Code nécessitant une stricte adhésion aux conventions Python et des contrôles de qualité pour les frameworks FastAPI.","de":"Perfekt für Code-Review-Agents, die eine strikte Einhaltung der Python-Konventionen und Qualitätskontrollen für FastAPI-Frameworks benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de adesão estrita às convenções Python e verificações de qualidade para frameworks FastAPI.","ru":"Идеально подходит для агентов код-ревью, требующих строгого соблюдения конвенций Python и проверок качества для фреймворков FastAPI.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى الالتزام التام بالاتفاقيات بايثون والتحقق من الجودة لمواد العمل السريعة"},"recommendation":{"en":"Empowers agents to enforce strict Python conventions and quality standards using Kieran''s review capabilities, ensuring high-quality code for FastAPI and other Python frameworks, and supporting protocols like code reviews and quality checks for Python developers.","zh":"赋予代理执行严格的Python约定和质量标准的能力，利用Kieran的审查功能，确保FastAPI和其他Python框架的高质量代码，并支持代码审查和质量检查等协议，用于Python开发者。","ja":"Kieranのレビューキャパビリティを使用して、エージェントが厳格なPythonの規約と品質基準を実施する能力を提供し、FastAPIおよびその他のPythonフレームワークの高品質なコードを保証し、Python開発者向けのコードレビューや品質チェックなどのプロトコルをサポートします。","ko":"Kieran의 리뷰 기능을 사용하여 에이전트가 엄격한 Python 규약과 품질 표준을 적용할 수 있는 능력을 제공하여, FastAPI 및 다른 Python 프레임워크의 높은 품질의 코드를 보장하며, Python 개발자를 위한 코드 리뷰 및 품질 확인과 같은 프로토콜을 지원합니다.","es":"Habilita a los agentes a aplicar estrictas convenciones de Python y estándares de calidad utilizando las capacidades de revisión de Kieran, garantizando un código de alta calidad para FastAPI y otros frameworks de Python, y apoyando protocolos como revisiones de código y controles de calidad para desarrolladores de Python.","fr":"Permet aux agents d''appliquer des conventions Python strictes et des normes de qualité en utilisant les capacités de révision de Kieran, garantissant un code de haute qualité pour FastAPI et d''autres frameworks Python, et en soutenant des protocoles tels que les révisions de code et les contrôles de qualité pour les développeurs Python.","de":"Ermächtigt die Agenten, strikte Python-Konventionen und Qualitätsstandards mit den Review-Funktionen von Kieran durchzusetzen, um hochwertigen Code für FastAPI und andere Python-Frameworks sicherzustellen und Protokolle wie Code-Reviews und Qualitätskontrollen für Python-Entwickler zu unterstützen.","pt":"Habilita os agentes a impor convenções Python estritas e padrões de qualidade, utilizando as capacidades de revisão do Kieran, garantindo um código de alta qualidade para FastAPI e outros frameworks Python, e apoiando protocolos como revisões de código e verificações de qualidade para desenvolvedores Python.","ru":"Наделяет агентов возможностью обеспечивать строгое соблюдение конвенций Python и стандартов качества, используя возможности ревью Кирена, гарантируя высококачественный код для FastAPI и других фреймворков Python, и поддерживая протоколы, такие как ревью кода и проверки качества для разработчиков Python.","ar":"تمكّن الوكيل من فرض اتفاقيات بايثون الصارمة ومعايير الجودة باستخدام إمكانيات المراجعة الخاصة بـ Kieran، وضمان код عالي الجودة لمواد العمل السريعة وغيرها من إطارات العمل بايثون، ودعم بروتوكولات مثل مراجعة الكود والتحقق من الجودة لمطوري بايثون"},"useCases":{"en":["Reviewing new FastAPI endpoint code","Refactoring existing Python code for quality and convention adherence","Ensuring adherence to strict Python conventions for improved code readability and maintainability"],"zh":["审查新的FastAPI端点代码","重构现有的Python代码以满足质量和约定要求","确保遵守严格的Python约定以提高代码可读性和可维护性"],"ja":["新しいFastAPIエンドポイントコードのレビュー","既存のPythonコードを品質と規約の遵守のためにリファクタリングする","コードの可読性とメンテナンス性を向上させるために厳格なPythonの規約を遵守する"],"ko":["新的 FastAPI 엔드포인트 코드 리뷰","품질 및 규약 준수를 위해 기존 Python 코드 리팩토링","코드의 가독성과 유지 보수성을 향상시키기 위한 엄격한 Python 규약 준수"],"es":["Revisar el código de nuevos puntos de conexión de FastAPI","Reestructurar el código Python existente para la calidad y la adherencia a las convenciones","Garantizar la adherencia a las estrictas convenciones de Python para mejorar la legibilidad y mantenibilidad del código"],"fr":["Réviser le code des nouveaux points de terminaison FastAPI","Réorganiser le code Python existant pour la qualité et l''adhésion aux conventions","Assurer l''adhésion aux conventions Python strictes pour améliorer la lisibilité et la maintenabilité du code"],"de":["Überprüfen des Codes für neue FastAPI-Endpunkte","Umstrukturieren des bestehenden Python-Codes für Qualität und Konformität mit den Konventionen","Sicherstellen der Einhaltung der strengen Python-Konventionen für verbesserte Lesbarkeit und Wartbarkeit des Codes"],"pt":["Revisar novo código de endpoint FastAPI","Refatorar código Python existente para qualidade e adesão às convenções","Garantir adesão às convenções Python estritas para melhorar a legibilidade e manutenibilidade do código"],"ru":["Просмотр нового кода конечной точки FastAPI","Рефакторинг существующего кода Python для качества и соблюдения конвенций","Обеспечение соблюдения строгих конвенций Python для улучшения читаемости и поддерживаемости кода"],"ar":["مراجعة كود نهاية新的 لمواد العمل السريعة","إعادة هيكلة كود بايثون الحالي لضمان الجودة والامتثال للاتفاقيات","ضمان الامتثال للاتفاقيات الصارمة لبايثون لتحسين قراءة الكود وصيانتها"]},"limitations":{"en":["Specific to Python and FastAPI frameworks","Requires Kieran''s review capabilities integration"],"zh":["仅限于Python和FastAPI框架","需要集成Kieran的审查功能"],"ja":["PythonとFastAPIフレームワークに限定される","Kieranのレビューキャパビリティの統合が必要"],"ko":["Python 및 FastAPI 프레임워크에만適用","Kieran의 리뷰 기능 통합이 필요"],"es":["Específico para frameworks de Python y FastAPI","Requiere la integración de las capacidades de revisión de Kieran"],"fr":["Spécifique aux frameworks Python et FastAPI","Nécessite l''intégration des capacités de révision de Kieran"],"de":["Spezifisch für Python- und FastAPI-Frameworks","Benötigt die Integration der Review-Funktionen von Kieran"],"pt":["Específico p