INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('snyk/snyk-intellij-plugin/commit', 'commit', 'snyk', 'snyk-intellij-plugin', 'community', 'commit snyk snyk-intellij-plugin community ide-plugin intellij intellij-plugin snyk Commit 工作流程是使用 Snyk Vulnerability Scanner 实现代码安全检查的自动化流程 Commit ワークフローは、Snyk Vulnerability Scanner を使用したコードのセキュリティチェックの自動化された流れです Commit 워크플로우는 Snyk Vulnerability Scanner를 사용하여 코드 보안 검사를 자동화하는 과정입니다 El commit es un workflow que prepara, verifica y confirma cambios de código siguiendo los estándares del proyecto con Snyk Le commit est un workflow qui prépare, vérifie et confirme les modifications de code suivant les normes du projet avec Snyk Der Commit ist ein Workflow, der Codeänderungen vorbereitet, überprüft und bestätigt, indem er die Projektstandards mit Snyk einhält O commit é uma habilidade que prepara, verifica e compromete alterações de código seguindo os padrões do projeto com o Snyk Vulnerability Scanner Коммит - это навык, который готовит, проверяет и фиксирует изменения кода в соответствии со стандартами проекта с помощью Snyk Vulnerability Scanner и ИИ Агентов Commit هو مهارة تقوم بإعداد وفرز وتسجيل تغييرات الكود وفقًا لمعايير المشروع باستخدام Snyk Vulnerability Scanner وأدوات الذكاء الاصطناعي Snyk Vulnerability Scanner for IDEs based on the IntelliJ platform Commit 工作流程 Snyk Vulnerability Scanner IntelliJ 平台 IDE 插件 代码安全检查 自动化测试 TDD 预提交检查 代码修复 Snyk Vulnerability Scanner for IDEs based on the IntelliJ platform');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MatrixReligio/ProductVideoCreator/bgm', 'community', 'MatrixReligio', 'ProductVideoCreator', 'MatrixReligio/ProductVideoCreator', 'bgm', 20, 5, 36, '2026-02-23T13:33:33Z', '2026-03-06T06:41:28.816Z', '49542862c661f257a1e186e18e470dc75c60d8b6553a22427c9888bae1ab6efe', '{"id":"MatrixReligio/ProductVideoCreator/bgm","name":"bgm","description":{"en":"The bgm skill generates automated product introduction videos using Remotion, Playwright, and edge-tts, benefiting developers and marketers. It provides a toolkit for creating engaging videos with various music styles and sources.","zh":"bgm背景音乐技能是使用Remotion、Playwright和edge-tts自动化产品介绍视频生成的AI Agent Skills工具包","ja":"bgmは、Remotion、Playwright、edge-ttsを使用してAIエージェントの背景音楽生成を自動化するAI Agent Skillsツールキットです","ko":"bgm 배경음악 스킬은 Remotion, Playwright 및 edge-tts를 사용하여 자동 제품 소개 비디오 생성을 자동화하는 AI 에이전트 스킬 툴킷입니다","es":"bgm es una herramienta de automatización para la creación de videos de introducción de productos con Remotion, Playwright y edge-tts","fr":"bgm est un outil d''automatisation pour la création de vidéos de présentation de produits avec Remotion, Playwright et edge-tts","de":"bgm ist ein Automatisierungstool für die Erstellung von Produktvideos mit Remotion, Playwright und edge-tts","pt":"O BGM é uma ferramenta de geração automática de vídeos de introdução de produtos que utiliza Remotion, Playwright e edge-tts","ru":"ИИ Агент BGM - это инструмент для автоматического создания видео-интродукций продуктов, использующий Remotion, Playwright и edge-tts","ar":"BGM هي أداة لإنشاء فيديوهات تلقائية لتقديم المنتجات باستخدام Remotion و Playwright و edge-tts"},"seo":{"title":{"en":"bgm: Automated Video Generation Setup Guide | AI Agent Skill","zh":"bgm 背景音乐技能设置指南","ja":"bgm AIエージェントの背景音楽生成ガイド","ko":"bgm 배경음악 스킬 설정 가이드","es":"Guía de configuración de bgm para videos de introducción ...","fr":"Configurer bgm pour les vidéos de présentation de produit...","de":"Einrichtungsleitfaden für bgm zur automatisierten Produkt...","pt":"Guia de Configuração do BGM: Geração Automática de Vídeos...","ru":"Настройка ИИ Агента BGM: Автоматическое Создание Видео с ...","ar":"دليل إعداد BGM: إنشاء فيديوهات تلقائي مع Remotion و Playw..."},"description":{"en":"Discover how to leverage bgm for automated product intro video creation with Remotion, Playwright, and edge-tts. Get started now!","zh":"使用Remotion、Playwright和edge-tts自动化产品介绍视频生成，了解bgm背景音乐技能的优势","ja":"Remotion、Playwright、edge-ttsを使用してAIエージェントの背景音楽生成を自動化するbgmの利点を学ぶ","ko":"Remotion, Playwright 및 edge-tts를 사용하여 배경음악 스킬 bgm의 자동 제품 소개 비디오 생성을 자동화하는 방법","es":"Aprende a utilizar bgm con Remotion, Playwright y edge-tts para crear videos de introducción de productos personalizados","fr":"Découvrez comment utiliser bgm avec Remotion, Playwright et edge-tts pour créer des vidéos de présentation de produits sur mesure","de":"Erfahren Sie, wie Sie bgm mit Remotion, Playwright und edge-tts verwenden, um maßgeschneiderte Produktvideos zu erstellen","pt":"Aprenda a configurar o BGM para geração automática de vídeos de introdução de produtos com Remotion, Playwright e edge-tts","ru":"Узнайте, как настроить ИИ Агента BGM для автоматического создания видео-интродукций продуктов с Remotion, Playwright и edge-tts","ar":"تعرف على كيفية إعداد BGM لإنشاء فيديوهات تلقائية لتقديم المنتجات مع Remotion و Playwright و edge-tts"},"definition":{"en":"bgm is an AI agent skill for automated product introduction video generation with Remotion, Playwright, and edge-tts, utilizing free music sources like Pixabay Music and Free Music Archive.","zh":"bgm背景音乐技能是用于自动化产品介绍视频生成的AI Agent Skills工具包，使用Remotion、Playwright和edge-tts","ja":"bgmは、AIエージェントの背景音楽生成を自動化するためにRemotion、Playwright、edge-ttsを使用するAI Agent Skillsツールキットです","ko":"bgm 배경음악 스킬은 Remotion, Playwright 및 edge-tts를 사용하여 자동 제품 소개 비디오 생성을 자동화하는 AI 에이전트 스킬 툴킷입니다","es":"bgm es una herramienta de AI que utiliza Remotion y edge-tts para generar videos de introducción de productos automatizados","fr":"bgm est un outil d''IA qui utilise Remotion et edge-tts pour générer des vidéos de présentation de produits automatisées","de":"bgm ist ein AI-Tool, das Remotion und edge-tts verwendet, um automatisierte Produktvideos zu generieren","pt":"O que é BGM? É uma ferramenta de geração automática de vídeos de introdução de produtos","ru":"Что такое ИИ Агент BGM? Это инструмент для автоматического создания видео-интродукций продуктов","ar":"ما هو BGM؟ هو أداة لإنشاء فيديوهات تلقائية لتقديم المنتجات"},"features":{"en":["Utilizes Remotion for video generation","Leverages Playwright for automated browser interactions","Integrates edge-tts for text-to-speech functionality","Supports various music sources like Pixabay Music and Free Music Archive","Allows for music style selection based on video type, such as Epic and Corporate","Provides a recommendation for free music sources, including Pixabay Music"],"zh":["使用Remotion、Playwright和edge-tts自动化产品介绍视频生成","支持Pixabay Music、Free Music Archive、Uppbeat和Mixkit等免费音乐来源","可选择Epic、Cinematic、Corporate、Upbeat等音乐风格","支持关键词搜索，例如\"epic cinematic\"、\"technology\"等","推荐Pixabay Music作为无需署名的商用免费音乐来源"],"ja":["Remotion、Playwright、edge-ttsを使用してAIエージェントの背景音楽生成を自動化する","Pixabay Music、Free Music Archive、Uppbeat、Mixkitなどの無料音楽ソースをサポートする","Epic、Cinematic、Corporate、Upbeatなどの音楽スタイルを選択する","キーワード検索をサポートする、例えば\"epic cinematic\"、\"technology\"など","Pixabay Musicを無署名の商用無料音楽ソースとしてお勧めする"],"ko":["Remotion, Playwright 및 edge-tts를 사용하여 자동 제품 소개 비디오 생성을 자동화하는 기능","Pixabay Music, Free Music Archive, Uppbeat 및 Mixkit 등의 무료 음악 소스를 지원하는 기능","Epic, Cinematic, Corporate, Upbeat 등의 음악 스타일을 선택할 수 있는 기능","키워드 검색을 지원하는 기능, 예를 들어 \"epic cinematic\", \"technology\" 등","Pixabay Music를 무자격의 thương mại 무료 음악 소스로 추천하는 기능"],"es":["Generación automática de videos de introducción de productos con Remotion","Integración con Playwright para la automatización de tareas","Uso de edge-tts para la síntesis de voz","Selección de música de fondo con Pixabay Music y otros proveedores","Personalización de estilos de música para diferentes tipos de videos"],"fr":["Génération automatisée de vidéos de présentation de produits avec Remotion","Intégration avec Playwright pour l''automatisation de tâches","Utilisation d''edge-tts pour la synthèse vocale","Sélection de musique de fond avec Pixabay Music et d''autres fournisseurs","Personnalisation de styles de musique pour différents types de vidéos"],"de":["Automatisierte Erstellung von Produktvideos mit Remotion","Integration mit Playwright für die Automatisierung von Aufgaben","Verwendung von edge-tts für die Sprachsynthese","Auswahl von Hintergrundmusik mit Pixabay Music und anderen Anbietern","Anpassung von Musikstilen für verschiedene Videotypen"],"pt":["Geração automática de vídeos de introdução de produtos","Utiliza Remotion para renderização de vídeo","Utiliza Playwright para automação de navegador","Suporte a edge-tts para texto-a-voz","Fontes de música gratuitas, incluindo Pixabay Music e Free Music Archive"],"ru":["Автоматическое создание видео-интродукций продуктов","Использует Remotion для рендеринга видео","Использует Playwright для автоматизации браузера","Поддержка edge-tts для текста-в-говор","Бесплатные музыкальные источники, включая Pixabay Music и Free Music Archive"],"ar":["إنشاء فيديوهات تلقائية لتقديم المنتجات","استخدام Remotion لتحويل الفيديو","استخدام Playwright للتحكم التلقائي في المتصفح","دعم edge-tts لنص-إلى-كلام","مصادر موسيقية مجانية، بما في ذلك Pixabay Music و Free Music Archive"]},"keywords":{"en":["how to use bgm","bgm alternative","bgm setup guide","what is bgm","bgm vs Remotion","automated video generation","edge-tts integration","Playwright automation","free music sources for videos"],"zh":["bgm背景音乐技能","AI Agent Skills","Remotion","Playwright","edge-tts","自动化产品介绍视频生成","免费音乐来源","音乐风格选择","关键词搜索"],"ja":["bgm AIエージェント","AI Agent Skills","Remotion","Playwright","edge-tts","AIエージェントの背景音楽生成","無料音楽ソース","音楽スタイル選択","キーワード検索"],"ko":["bgm 배경음악 스킬","AI 에이전트 스킬","Remotion","Playwright","edge-tts","자동 제품 소개 비디오 생성","무료 음악 소스","음악 스타일 선택","키워드 검색"],"es":["bgm","Remotion","Playwright","edge-tts","generación automática de videos","introducción de productos","herramientas de AI","automatización de tareas","síntesis de voz"],"fr":["bgm","Remotion","Playwright","edge-tts","génération automatisée de vidéos","présentation de produits","outils d''IA","automatisation de tâches","synthèse vocale"],"de":["bgm","Remotion","Playwright","edge-tts","automatisierte Videoproduktion","Produktpräsentation","AI-Tools","Automatisierung von Aufgaben","Sprachsynthese"],"pt":["BGM","geração automática de vídeos","Remotion","Playwright","edge-tts","vídeos de introdução de produtos","ferramentas de AI","desenvolvimento de vídeo"],"ru":["ИИ Агент BGM","автоматическое создание видео","Remotion","Playwright","edge-tts","видео-интродукции продуктов","инструменты ИИ","разработка видео"],"ar":["BGM","إنشاء فيديوهات تلقائي","Remotion","Playwright","edge-tts","فيديوهات تقديم المنتجات","أدوات الذكاء الاصطناعي","تطوير الفيديو"]}},"owner":"MatrixReligio","repo":"ProductVideoCreator","repoPath":"MatrixReligio/ProductVideoCreator","stars":20,"forks":5,"updatedAt":"2026-02-23T13:33:33Z","topics":[],"category":"community","skillMd":{"name":"bgm","description":"为视频添加背景音乐。支持免版权音乐来源、音量混合、淡入淡出效果。当需要为视频添加背景音乐、调整音乐与配音音量平衡时使用。","bodyPreview":"# 背景音乐技能\n\n## 免版权音乐来源\n\n| 来源 | 网址 | 特点 |\n|------|------|------|\n| Pixabay Music | https://pixabay.com/music/ | 完全免费，无需署名 |\n| Free Music Archive | https://freemusicarchive.org/ | CC 授权，部分需署名 |\n| Uppbeat | https://uppbeat.io/ | 免费版每月限量 |\n| Mixkit | https://mixkit.co/free-stock-music/ | 完全免费 |\n\n**推荐**: Pixabay Music (无需署名，商用免费)\n\n## 音乐风格选择\n\n| 视频类型 | 推荐风格 | 关键词搜索 |\n|----------|----------|------------|\n| 科技历程 | Epic, Cinematic | \"epic cinematic\", \"technology\" |\n| 产品介绍 | Corporate, Upbeat | \"corporate\",","body":"# 背景音乐技能\n\n## 免版权音乐来源\n\n| 来源 | 网址 | 特点 |\n|------|------|------|\n| Pixabay Music | https://pixabay.com/music/ | 完全免费，无需署名 |\n| Free Music Archive | https://freemusicarchive.org/ | CC 授权，部分需署名 |\n| Uppbeat | https://uppbeat.io/ | 免费版每月限量 |\n| Mixkit | https://mixkit.co/free-stock-music/ | 完全免费 |\n\n**推荐**: Pixabay Music (无需署名，商用免费)\n\n## 音乐风格选择\n\n| 视频类型 | 推荐风格 | 关键词搜索 |\n|----------|----------|------------|\n| 科技历程 | Epic, Cinematic | \"epic cinematic\", \"technology\" |\n| 产品介绍 | Corporate, Upbeat | \"corporate\", \"business\" |\n| 教程视频 | Ambient, Soft | \"ambient\", \"background\" |\n| 发布会 | Inspiring, Motivational | \"inspiring\", \"motivational\" |\n| 创意内容 | Modern, Electronic | \"modern\", \"electronic\" |\n\n## FFmpeg 音频混合\n\n### 基础混合（配音优先）\n\n```bash\n# 将 BGM 与配音混合，BGM 音量降低\n# 配音密集时推荐 volume=0.05，配音稀疏时可用 0.08-0.10\nffmpeg -i voiceover.mp3 -i bgm.mp3 \\\n  -filter_complex \"[1:a]volume=0.05[bgm];[0:a][bgm]amix=inputs=2:duration=first[out]\" \\\n  -map \"[out]\" mixed_audio.mp3\n```\n\n### 带淡入淡出效果\n\n```bash\n# BGM 淡入3秒，淡出3秒\nffmpeg -i voiceover.mp3 -i bgm.mp3 \\\n  -filter_complex \"\n    [1:a]volume=0.05,afade=t=in:st=0:d=3,afade=t=out:st=82:d=3[bgm];\n    [0:a][bgm]amix=inputs=2:duration=first[out]\n  \" \\\n  -map \"[out]\" mixed_audio.mp3\n```\n\n### 完整音频处理流程\n\n```bash\n# 1. 处理 BGM（循环、淡入淡出、降低音量）\nffmpeg -stream_loop -1 -i bgm_original.mp3 \\\n  -t 85 \\\n  -af \"volume=0.05,afade=t=in:st=0:d=3,afade=t=out:st=82:d=3\" \\\n  bgm_processed.mp3\n\n# 2. 混合配音和 BGM\nffmpeg -i voiceover.mp3 -i bgm_processed.mp3 \\\n  -filter_complex \"[0:a][1:a]amix=inputs=2:duration=first[out]\" \\\n  -map \"[out]\" final_audio.mp3\n\n# 3. 音量标准化\nffmpeg -i final_audio.mp3 \\\n  -af \"loudnorm=I=-16:TP=-1.5:LRA=11\" \\\n  final_audio_normalized.mp3\n```\n\n## 音量平衡建议\n\n### 核心原则\n\n**配音清晰度优先**：BGM 必须作为\"背景\"存在，绝不能盖过配音。人声频率(85-255Hz基频 + 泛音)与 BGM 重叠时尤其需要注意。\n\n| 音频类型 | 相对音量 | 说明 |\n|----------|----------|------|\n| 配音 | 1.0 (100%) | 主音频，保持原音量 |\n| BGM（有密集配音） | **0.05-0.08** | 确保配音清晰可辨 |\n| BGM（有稀疏配音） | 0.08-0.12 | 配音间隙较多时 |\n| BGM（无配音段落） | 0.15-0.25 | 片头/片尾/转场 |\n| BGM（纯音乐段落） | 0.30-0.50 | 无配音时可提高 |\n\n### 音量选择决策树\n\n```\n视频有配音吗？\n├── 是 → 配音密度高吗（>70%时间有语音）？\n│   ├── 是 → BGM volume = 0.05-0.06 (推荐 0.05)\n│   └── 否 → BGM volume = 0.08-0.10\n└── 否 → BGM volume = 0.25-0.40\n```\n\n### 测试方法\n\n在正式渲染前，截取30秒包含配音的片段测试：\n```bash\n# 快速测试不同音量\nfor vol in 0.04 0.05 0.06 0.08; do\n  ffmpeg -y -i bgm.mp3 -i voiceover.mp3 \\\n    -filter_complex \"[0:a]volume=$vol[bgm];[1:a][bgm]amix=inputs=2[out]\" \\\n    -map \"[out]\" -t 30 test_vol_$vol.mp3\ndone\n```\n\n### 动态音量控制（高级）\n\n```bash\n# 配音出现时自动降低 BGM（侧链压缩效果）\nffmpeg -i voiceover.mp3 -i bgm.mp3 \\\n  -filter_complex \"\n    [0:a]asplit=2[vo][vo_sidechain];\n    [1:a]volume=0.3[bgm];\n    [bgm][vo_sidechain]sidechaincompress=threshold=0.02:ratio=8:attack=50:release=500[bgm_ducked];\n    [vo][bgm_ducked]amix=inputs=2:duration=first[out]\n  \" \\\n  -map \"[out]\" ducked_audio.mp3\n```\n\n## 智能 BGM 长度计算\n\n### 问题：无脑循环的弊端\n\n简单的 `-stream_loop -1` 会导致：\n- BGM 在非自然位置截断\n- 音乐节奏与视频内容不匹配\n- 循环接缝处听感不自然\n\n### 解决方案：场景感知的 BGM 选择\n\n#### 策略 1: 选择合适长度的音乐\n\n**优先选择**时长接近或略长于视频的 BGM：\n\n| 视频时长 | 推荐 BGM 时长 | 策略 |\n|----------|---------------|------|\n| < 60s | 60-90s | 单曲裁剪 |\n| 60-120s | 90-180s | 单曲裁剪 + 淡出 |\n| 120-300s | 180-360s | 单曲或精心设计的接缝 |\n| > 300s | 多首拼接 | 场景转换处切换 |\n\n#### 策略 2: 基于场景结构计算\n\n```python\n# 场景时间配置\nSCENES = {\n    \"opening\": {\"start\": 0, \"duration\": 8},    # 片头\n    \"scene1\": {\"start\": 8, \"duration\": 14},    # 场景1\n    \"scene2\": {\"start\": 22, \"duration\": 16},   # 场景2\n    \"scene3\": {\"start\": 38, \"duration\": 14},   # 场景3\n    \"scene4\": {\"start\": 52, \"duration\": 20},   # 场景4\n    \"closing\": {\"start\": 72, \"duration\": 13},  # 片尾\n}\n\ndef calculate_bgm_strategy(scenes: dict, bgm_duration: float, video_duration: float):\n    \"\"\"\n    计算 BGM 使用策略\n\n    Returns:\n        dict: 包含 trim_end, need_loop, loop_point 等信息\n    \"\"\"\n    if bgm_duration >= video_duration:\n        # BGM 够长，直接裁剪\n        return {\n            \"strategy\": \"single_trim\",\n            \"trim_end\": video_duration,\n            \"need_loop\": False\n        }\n\n    # BGM 不够长，找最佳循环点（场景边界）\n    scene_boundaries = sorted([s[\"start\"] for s in scenes.values()])\n\n    # 找到最接近 BGM 时长的场景边界\n    best_loop_point = min(\n        scene_boundaries,\n        key=lambda x: abs(x - bgm_duration) if x <= bgm_duration else float(''inf'')\n    )\n\n    return {\n        \"strategy\": \"scene_aware_loop\",\n        \"loop_point\": best_loop_point,\n        \"bgm_duration\": bgm_duration,\n        \"loops_needed\": math.ceil(video_duration / best_loop_point)\n    }\n```\n\n#### 策略 3: 动态音量适配场景\n\n不同场景使用不同 BGM 音量：\n\n```python\n# 场景音量配置\nSCENE_VOLUMES = {\n    \"opening\": 0.15,    # 片头无配音，音量较高\n    \"scene1\": 0.05,     # 有配音场景\n    \"scene2\": 0.05,\n    \"scene3\": 0.05,\n    \"scene4\": 0.05,\n    \"closing\": 0.12,    # 片尾配音较少\n}\n\ndef generate_volume_filter(scenes: dict, volumes: dict, fps: int = 30):\n    \"\"\"生成 FFmpeg 音量自动化滤镜\"\"\"\n    points = []\n    for name, scene in scenes.items():\n        start_frame = scene[\"start\"] * fps\n        vol = volumes.get(name, 0.05)\n        points.append(f\"volume=enable=''between(t,{scene[''start'']},{scene[''start'']+scene[''duration'']})'':volume={vol}\")\n\n    return \",\".join(points)\n```\n\n### FFmpeg 场景感知混合\n\n```bash\n# 使用 aeval 实现场景动态音量\n# 片头(0-8s): 0.15, 正片(8-72s): 0.05, 片尾(72-85s): 0.12\n\nffmpeg -i voiceover.mp3 -i bgm.mp3 \\\n  -filter_complex \"\n    [1:a]volume=''if(lt(t,8),0.15,if(lt(t,72),0.05,0.12))'':eval=frame,\n    afade=t=in:st=0:d=3,\n    afade=t=out:st=82:d=3[bgm];\n    [0:a][bgm]amix=inputs=2:duration=first[out]\n  \" \\\n  -map \"[out]\" mixed_audio.mp3\n```\n\n### 最佳实践\n\n1. **优先选择时长合适的 BGM**：避免循环，选择 >= 视频时长的音乐\n2. **如果必须循环**：在场景转换处设置循环点，而非音乐结尾\n3. **场景边界淡入淡出**：循环接缝处使用交叉淡化\n4. **动态音量**：片头片尾可略高，配音密集段落降低\n\n---\n\n## Remotion 动态音量控制 (推荐)\n\n除了使用 FFmpeg 预处理，还可以在 Remotion 中直接实现动态音量控制。这种方式更灵活，便于调试。\n\n### 基础用法：场景感知音量\n\n```tsx\nimport { Audio, staticFile, useCurrentFrame, useVideoConfig } from \"remotion\";\nimport { SCENES } from \"./config/scenes\";\n\n// 场景音量配置\nconst SCENE_VOLUMES = {\n  opening: 0.15,   // 片头无配音，音量较高\n  scene1: 0.05,    // 有配音场景\n  scene2: 0.05,\n  scene3: 0.05,\n  scene4: 0.05,\n  closing: 0.12,   // 片尾配音较少\n};\n\n// 动态音量函数\nconst getDynamicVolume = (frame: number, fps: number): number => {\n  const currentTime = frame / fps;\n\n  // 遍历场景找到当前所在场景\n  for (const [sceneName, scene] of Object.entries(SCENES)) {\n    const sceneEnd = scene.start + scene.duration;\n    if (currentTime >= scene.start && currentTime < sceneEnd) {\n      return SCENE_VOLUMES[sceneName as keyof typeof SCENE_VOLUMES] ?? 0.05;\n    }\n  }\n  return 0.05; // 默认音量\n};\n\n// 在组件中使用\nexport const VideoWithDynamicBGM: React.FC = () => {\n  const { fps } = useVideoConfig();\n\n  return (\n    <>\n      {/* 配音 - 固定音量 */}\n      <Audio src={staticFile(\"audio/voiceover.mp3\")} volume={1} />\n\n      {/* BGM - 动态音量 */}\n      <Audio\n        src={staticFile(\"audio/bgm.mp3\")}\n        volume={(frame) => getDynamicVolume(frame, fps)}\n      />\n    </>\n  );\n};\n```\n\n### 进阶用法：平滑过渡\n\n```tsx\nimport { interpolate } from \"remotion\";\n\nconst getSmoothVolume = (frame: number, fps: number): number => {\n  const currentTime = frame / fps;\n\n  // 片头 (0-8s): 0.15 -> 片头结束前0.5s开始降低\n  if (currentTime < 7.5) return 0.15;\n  if (currentTime < 8) {\n    return interpolate(currentTime, [7.5, 8], [0.15, 0.05]);\n  }\n\n  // 正片 (8-71.5s): 0.05\n  if (currentTime < 71.5) return 0.05;\n\n  // 正片结束 -> 片尾 (71.5-72s): 平滑过渡到 0.12\n  if (currentTime < 72) {\n    return interpolate(currentTime, [71.5, 72], [0.05, 0.12]);\n  }\n\n  // 片尾 (72-85s): 0.12\n  return 0.12;\n};\n```\n\n### 组件模板\n\n```tsx\n// components/DynamicBGM.tsx\nimport React from \"react\";\nimport { Audio, staticFile, useVideoConfig } from \"remotion\";\n\ninterface DynamicBGMProps {\n  /** BGM 文件路径 (相对于 public/) */\n  src: string;\n  /** 场景音量配置 */\n  sceneVolumes: Record<string, number>;\n  /** 场景时间配置 */\n  scenes: Record<string, { start: number; duration: number }>;\n  /** 是否启用平滑过渡 (默认 true) */\n  smoothTransition?: boolean;\n  /** 过渡时长 (秒, 默认 0.5) */\n  transitionDuration?: number;\n}\n\nexport const DynamicBGM: React.FC<DynamicBGMProps> = ({\n  src,\n  sceneVolumes,\n  scenes,\n  smoothTransition = true,\n  transitionDuration = 0.5,\n}) => {\n  const { fps } = useVideoConfig();\n\n  const getVolume = (frame: number): number => {\n    const currentTime = frame / fps;\n\n    for (const [sceneName, scene] of Object.entries(scenes)) {\n      const sceneEnd = scene.start + scene.duration;\n      if (currentTime >= scene.start && currentTime < sceneEnd) {\n        return sceneVolumes[sceneName] ?? 0.05;\n      }\n    }\n    return 0.05;\n  };\n\n  return (\n    <Audio\n      src={staticFile(src)}\n      volume={(frame) => getVolume(frame)}\n    />\n  );\n};\n```\n\n### FFmpeg vs Remotion 对比\n\n| 方面 | FFmpeg 预处理 | Remotion 动态控制 |\n|------|--------------|------------------|\n| 调试便捷性 | ⚠️ 需重新处理音频 | ✅ 实时预览 |\n| 灵活性 | ⚠️ 固定一次 | ✅ 随时调整 |\n| 渲染性能 | ✅ 无额外开销 | ⚠️ 微小开销 |\n| 文件大小 | ⚠️ 预混合体积大 | ✅ 分离存储 |\n| 推荐场景 | 最终交付 | 开发调试 |\n\n**建议工作流**：\n1. 开发阶段使用 Remotion 动态控制快速调试\n2. 确定最终参数后，使用 FFmpeg 预处理生成交付版本\n\n---\n\n## Python 脚本模板\n\n```python\n#!/usr/bin/env python3\n\"\"\"\n背景音乐处理脚本\n\"\"\"\n\nimport subprocess\nfrom pathlib import Path\n\ndef process_bgm(\n    bgm_path: str,\n    voiceover_path: str,\n    output_path: str,\n    video_duration: float,\n    bgm_volume: float = 0.05,  # 默认低音量，确保配音清晰\n    fade_duration: float = 3.0\n):\n    \"\"\"\n    处理背景音乐并与配音混合\n\n    Args:\n        bgm_path: BGM 文件路径\n        voiceover_path: 配音文件路径\n        output_path: 输出文件路径\n        video_duration: 视频总时长（秒）\n        bgm_volume: BGM 相对音量 (0.0-1.0)\n        fade_duration: 淡入淡出时长（秒）\n    \"\"\"\n    fade_out_start = video_duration - fade_duration\n\n    # 构建 filter_complex\n    filter_complex = f\"\"\"\n        [1:a]aloop=loop=-1:size=2e+09,atrim=0:{video_duration},\n        volume={bgm_volume},\n        afade=t=in:st=0:d={fade_duration},\n        afade=t=out:st={fade_out_start}:d={fade_duration}[bgm];\n        [0:a][bgm]amix=inputs=2:duration=first[out]\n    \"\"\".replace(\"\\n\", \"\").replace(\"  \", \"\")\n\n    cmd = [\n        \"ffmpeg\", \"-y\",\n        \"-i\", voiceover_path,\n        \"-i\", bgm_path,\n        \"-filter_complex\", filter_complex,\n        \"-map\", \"[out]\",\n        output_path\n    ]\n\n    subprocess.run(cmd, check=True)\n    print(f\"✓ 混合音频输出: {output_path}\")\n\ndef normalize_audio(input_path: str, output_path: str):\n    \"\"\"音量标准化到 -16 LUFS\"\"\"\n    cmd = [\n        \"ffmpeg\", \"-y\",\n        \"-i\", input_path,\n        \"-af\", \"loudnorm=I=-16:TP=-1.5:LRA=11\",\n        output_path\n    ]\n    subprocess.run(cmd, check=True)\n    print(f\"✓ 标准化输出: {output_path}\")\n\n# 使用示例\nif __name__ == \"__main__\":\n    process_bgm(\n        bgm_path=\"public/audio/bgm_epic.mp3\",\n        voiceover_path=\"public/audio/synced_voiceover.mp3\",\n        output_path=\"public/audio/mixed_audio.mp3\",\n        video_duration=85,\n        bgm_volume=0.05,  # 配音密集时推荐 0.05\n        fade_duration=3.0\n    )\n\n    normalize_audio(\n        input_path=\"public/audio/mixed_audio.mp3\",\n        output_path=\"public/audio/final_audio.mp3\"\n    )\n```\n\n## Remotion 集成\n\n在 Remotion 组件中使用混合后的音频：\n\n```tsx\nimport { Audio, staticFile } from \"remotion\";\n\nexport const FinalVideo: React.FC = () => {\n  return (\n    <>\n      {/* 使用混合后的音频（配音 + BGM） */}\n      <Audio src={staticFile(\"audio/final_audio.mp3\")} volume={1} />\n\n      {/* 或者分开控制 */}\n      <Audio src={staticFile(\"audio/synced_voiceover.mp3\")} volume={1} />\n      <Audio\n        src={staticFile(\"audio/bgm.mp3\")}\n        volume={(f) => {\n          // 淡入淡出控制\n          const fps = 30;\n          if (f < 3 * fps) return (f / (3 * fps)) * 0.12;\n          if (f > 82 * fps) return ((85 * fps - f) / (3 * fps)) * 0.12;\n          return 0.12;\n        }}\n      />\n    </>\n  );\n};\n```\n\n## 工作流程\n\n```\n1. 确定视频风格 → 选择音乐关键词\n2. 从免版权网站下载 BGM\n3. 处理 BGM（循环/裁剪到视频时长）\n4. 添加淡入淡出效果\n5. 与配音混合（配音优先）\n6. 音量标准化\n7. 集成到视频\n```\n\n## 常见问题\n\n| 问题 | 解决方案 |\n|------|----------|\n| BGM 太响干扰配音 | 降低 volume 到 0.04-0.06（配音密集时推荐 0.05） |\n| BGM 不够长 | 优先选择更长的音乐；必须循环时在场景边界处接缝 |\n| 淡入淡出太突然 | 增加 fade_duration 到 4-5 秒 |\n| 混合后音量不一致 | 使用 loudnorm 滤镜标准化 |\n| 风格不匹配 | 重新选择更合适的 BGM |\n| 循环接缝明显 | 使用交叉淡化或在场景转换处设置循环点 |\n"},"lastSynced":"2026-03-06T06:41:28.816Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Generation Agents needing automated product introduction videos with customizable background music.","zh":"非常适合需要自动化产品介绍视频并可自定义背景音乐的媒体生成代理。","ja":"自動化された製品紹介動画をバックグラウンドミュージックをカスタマイズできるメディア生成エージェントに最適です。","ko":"자동화된 제품 소개 비디오를 배경 음악을 사용자 지정할 수 있는 미디어 생성 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Generación de Medios que necesitan videos de introducción de productos automatizados con música de fondo personalizable.","fr":"Parfait pour les Agents de Génération de Médias ayant besoin de vidéos d''introduction de produits automatisées avec de la musique de fond personnalisable.","de":"Perfekt für Media-Generation-Agents, die automatisierte Produkt-Einführungs-Videos mit anpassbarer Hintergrundmusik benötigen.","pt":"Perfeito para Agentes de Geração de Mídia que precisam de vídeos de introdução de produtos automatizados com música de fundo personalizável.","ru":"Идеально подходит для агентов генерации медиа, которым требуются автоматизированные видеоролики с введением продукта и настраиваемой фоновой музыкой.","ar":"مثالي للوكلاء الذين يحتاجون إلى مقاطع فيديو تلقائية لتقديم المنتجات مع موسيقى خلفية قابلة للتعديل."},"recommendation":{"en":"Empowers agents to generate engaging videos using Remotion, Playwright, and edge-tts, with access to various music styles and sources like Pixabay Music, Free Music Archive, and Uppbeat, utilizing protocols for seamless integration.","zh":"赋予代理使用Remotion、Playwright和edge-tts生成引人入胜的视频的能力，提供各种音乐风格和来源，如Pixabay Music、Free Music Archive和Uppbeat，并利用协议实现无缝集成。","ja":"Remotion、Playwright、edge-ttsを使用して魅力的な動画を生成するエージェントの能力を提供し、様々な音楽スタイルやPixabay Music、Free Music Archive、Uppbeatなどの音楽ソースへのアクセスを提供し、プロトコルを使用してシームレスな統合を実現します。","ko":"Remotion, Playwright 및 edge-tts를 사용하여 매력적인 비디오를 생성할 수 있는 에이전트의 능력을 제공하며, 다양한 음악 스타일 및 Pixabay Music, Free Music Archive 및 Uppbeat와 같은 음악 소스에 대한 액세스를 제공하며, 프로토콜을 사용하여 무결점 통합을 구현합니다.","es":"Habilita a los agentes a generar videos atractivos utilizando Remotion, Playwright y edge-tts, con acceso a varios estilos y fuentes de música como Pixabay Music, Free Music Archive y Uppbeat, utilizando protocolos para una integración sin problemas.","fr":"Permet aux agents de générer des vidéos engageantes en utilisant Remotion, Playwright et edge-tts, avec un accès à divers styles et sources de musique comme Pixabay Music, Free Music Archive et Uppbeat, en utilisant des protocoles pour une intégration sans rupture.","de":"Ermöglicht es Agenten, ansprechende Videos mit Remotion, Playwright und edge-tts zu generieren, mit Zugang zu verschiedenen Musikstilen und -quellen wie Pixabay Music, Free Music Archive und Uppbeat, unter Verwendung von Protokollen für eine nahtlose Integration.","pt":"Habilita os agentes a gerar vídeos atraentes usando Remotion, Playwright e edge-tts, com acesso a vários estilos e fontes de música, como Pixabay Music, Free Music Archive e Uppbeat, utilizando protocolos para integração sem problemas.","ru":"Позволяет агентам создавать привлекательные видеоролики с помощью Remotion, Playwright и edge-tts, имея доступ к различным стилям и источникам музыки, таким как Pixabay Music, Free Music Archive и Uppbeat, используя протоколы для бесперебойной интеграции.","ar":"تمكين الوكلاء من generar فيديوهات جذابة باستخدام Remotion و Playwright و edge-tts ، مع الوصول إلى أنواع ومصادر موسيقية مختلفة مثل Pixabay Music و Free Music Archive و Uppbeat ، باستخدام بروتوكولات للتكامل السلس."},"useCases":{"en":["Automating product introduction video creation with epic cinematic music","Generating corporate videos with upbeat background tracks","Customizing video music styles using keyword searches like ''technology'' and ''corporate''"],"zh":["使用史诗电影音乐自动化产品介绍视频创建","使用活泼的背景音轨生成企业视频","使用关键词搜索如''技术''和''企业''来自定义视频音乐风格"],"ja":["エピックな映画音楽で自動化された製品紹介動画の作成","アップビートなバックグラウンドトラックで企業動画を生成する","キーワード検索を使用して動画の音楽スタイルをカスタマイズする、例えば''技術''と''企業''"],"ko":["에픽한 영화 음악으로 자동화된 제품 소개 비디오 생성","활기찬 배경 트랙으로 기업 비디오 생성","키워드 검색을 사용하여 비디오 음악 스타일을 사용자 지정하기, 예를 들어 ''기술'' 및 ''기업''"],"es":["Automatizar la creación de videos de introducción de productos con música cinematográfica épica","Generar videos corporativos con pistas de fondo animadas","Personalizar estilos de música de video mediante búsquedas de palabras clave como ''tecnología'' y ''corporativo''"],"fr":["Automatiser la création de vidéos d''introduction de produits avec de la musique cinématique épique","Générer des vidéos d''entreprise avec des pistes de fond animées","Personnaliser les styles de musique de vidéo en utilisant des recherches de mots clés comme ''technologie'' et ''entreprise''"],"de":["Automatisieren der Erstellung von Produkt-Einführungs-Videos mit epischer Kinomusik","Erstellen von Unternehmensvideos mit aufmunternden Hintergrundspuren","Anpassen von Videomusikstilen unter Verwendung von Schlüsselwort-Suchen wie ''Technologie'' und ''Unternehmen''"],"pt":["Automatizar a criação de vídeos de introdução de produtos com música cinematográfica épica","Gerar vídeos corporativos com faixas de fundo animadas","Personalizar estilos de música de vídeo usando pesquisas de palavras-chave como ''tecnologia'' e ''corporativo''"],"ru":["Автоматизировать создание видеороликов с введением продукта с эпической кинематографической музыкой","Генерировать корпоративные видеоролики с оживленными фоновой музыкой","Настроить стили музыки для видео, используя поиск по ключевым словам, таким как ''технология'' и ''корпоративный''"],"ar":["الاستفادة من مقاطع فيديو تلقائية لتقديم المنتجات مع موسيقى سينمائية ملحمية","generar فيديوهات الشركات مع مسارات خلفية حيوية","تخصيص أنماط الموسيقى في مقاطع الفيديو باستخدام عمليات البحث بالكلمات الرئيسية مثل ''التكنولوجيا'' و ''الشركات''"]},"limitations":{"en":["Requires Remotion, Playwright, and edge-tts setup","Limited to free music sources with potential attribution requirements","Dependent on internet connection for music source access"],"zh":["需要Remotion、Playwright和edge-tts的设置","仅限于免费音乐来源，可能需要归属要求","依赖于互联网连接以访问音乐来源"],"ja":["Remotion、Playwright、edge-ttsの設定が必要","無料の音楽ソースのみに限定され、帰属要件が必要になる可能性がある","音楽ソースへのアクセスにはインターネット接続が必要"],"ko":["Remotion, Playwright 및 edge-tts 설정이 필요합니다.","무료 음악 소스만으로 제한되며, 속성 요구 사항이 필요할 수 있습니다.","음악 소스에 액세스하려면 인터넷 연결이 필요합니다."],"es":["Requiere configuración de Remotion, Playwright y edge-tts","Limitado a fuentes de música gratuitas con posibles requisitos de atribución","Dependiente de la conexión a Internet para acceder a las fuentes de música"],"fr":["Nécessite une configuration de Remotion, Playwright et edge-tts","Limité aux sources de musique gratuites avec des exigences d''attribution potentielles","Dépend de la connexion Internet pour accéder aux sources de musique"],"de":["Benötigt Remotion-, Playwright- und edge-tts-Setup","Begrenzt auf kostenlose Musikquellen mit möglichen Attributionsanforderungen","Abhängig von der Internetverbindung für den Zugriff auf Musikquellen"],"pt":["Requer configuração do Remotion, Playwright e edge-tts","Limitado a fontes de música gratuitas com potenciais requisitos de atribuição","Dependente da conexão com a internet para acesso às fontes de música"],"ru":["Требует настройки Remotion, Playwright и edge-tts","Ограничен бесплатными источниками музыки с потенциальными требованиями атрибуции","Зависит от подключения к интернету для доступа к источникам музыки"],"ar":["يتطلب التهيئة Remotion و Playwright و edge-tts","محدود بمصادر الموسيقى المجانية مع متطلبات потенسية للتعريف","يعتمد على الاتصال بالإنترنت للوصول إلى مصادر الموسيقى"]},"version":4},"contentHash":"49542862c661f257a1e186e18e470dc75c60d8b6553a22427c9888bae1ab6efe","qualityScore":36}');
