INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MatrixReligio/ProductVideoCreator/bgm', 'bgm', 'MatrixReligio', 'ProductVideoCreator', 'community', 'bgm MatrixReligio ProductVideoCreator community The bgm skill generates automated product introduction videos using Remotion, Playwright, and edge-tts, benefiting developers and marketers. It provides a toolkit for creating engaging videos with various music styles and sources. bgm背景音乐技能是使用Remotion、Playwright和edge-tts自动化产品介绍视频生成的AI Agent Skills工具包 bgmは、Remotion、Playwright、edge-ttsを使用してAIエージェントの背景音楽生成を自動化するAI Agent Skillsツールキットです bgm 배경음악 스킬은 Remotion, Playwright 및 edge-tts를 사용하여 자동 제품 소개 비디오 생성을 자동화하는 AI 에이전트 스킬 툴킷입니다 bgm es una herramienta de automatización para la creación de videos de introducción de productos con Remotion, Playwright y edge-tts bgm est un outil d''automatisation pour la création de vidéos de présentation de produits avec Remotion, Playwright et edge-tts bgm ist ein Automatisierungstool für die Erstellung von Produktvideos mit Remotion, Playwright und edge-tts O BGM é uma ferramenta de geração automática de vídeos de introdução de produtos que utiliza Remotion, Playwright e edge-tts ИИ Агент BGM - это инструмент для автоматического создания видео-интродукций продуктов, использующий Remotion, Playwright и edge-tts BGM هي أداة لإنشاء فيديوهات تلقائية لتقديم المنتجات باستخدام Remotion و Playwright و edge-tts how to use bgm bgm alternative bgm setup guide what is bgm bgm vs Remotion automated video generation edge-tts integration Playwright automation free music sources for videos bgm背景音乐技能 AI Agent Skills Remotion Playwright edge-tts 自动化产品介绍视频生成 免费音乐来源 音乐风格选择 关键词搜索 Utilizes Remotion for video generation Leverages Playwright for automated browser interactions Integrates edge-tts for text-to-speech functionality Supports various music sources like Pixabay Music and Free Music Archive Allows for music style selection based on video type, such as Epic and Corporate Provides a recommendation for free music sources, including Pixabay Music bgm is an AI agent skill for automated product introduction video generation with Remotion, Playwright, and edge-tts, utilizing free music sources like Pixabay Music and Free Music Archive.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('METR/inspect-action/debug-stuck-eval', 'community', 'METR', 'inspect-action', 'METR/inspect-action', 'debug-stuck-eval', 20, 9, 36, '2026-03-03T00:16:18Z', '2026-03-06T06:41:54.945Z', 'a0053ae6c485921d3887151903fe3b6a1d2845f2a7a3dfe65716ebb7da20b9fb', '{"id":"METR/inspect-action/debug-stuck-eval","name":"debug-stuck-eval","description":{"en":"The debug-stuck-eval skill helps AI developers troubleshoot stuck evaluations by running UK AISI''s Inspect in the Cloud, providing a quick checklist for verification, status checks, and log analysis. It benefits developers working with AI evaluations and inspections.","zh":"本文介绍如何使用 UK AISI 的 Inspect 在云端调试卡住的评估，包括设置、故障排除和 API 测试","ja":"本文では、UK AISI の Inspect を使用してクラウドで評価をデバッグする方法について説明します。設定、トラブルシューティング、API テストなどを含みます","ko":"이 문서는 클라우드에서 eval이 중단된 경우 디버깅하는 방법에 대해 설명합니다. 설정, 문제 해결 및 API 테스트 등이 포함됩니다","es":"El skill debug-stuck-eval permite a los desarrolladores depurar evaluaciones atascadas en UK AISI''s Inspect en la nube","fr":"Le skill debug-stuck-eval permet aux développeurs de dépanner les évaluations bloquées dans Inspect d''UK AISI dans le cloud","de":"Das Skill debug-stuck-eval ermöglicht es Entwicklern, Bewertungen in UK AISI''s Inspect in der Cloud zu debuggen","pt":"O debug-stuck-eval é uma ferramenta de depuração para avaliações de IA que executa o Inspect na nuvem, fornecendo relatórios de status e logs.","ru":"Debug-stuck-eval - это отладчик для оценок ИИ, который запускает Inspect в облаке, предоставляя отчеты о статусе и журналах.","ar":"debug-stuck-eval هو أداة تصحيح لأvaluations الذكاء الاصطناعي التي تعمل Inspect في السحابة، وتقدم تقارير الحالة وسجلات"},"seo":{"title":{"en":"debug-stuck-eval: Troubleshooting Guide for AI Agents | A...","zh":"调试卡住的评估：UK AISI Inspect 在云端运行指南","ja":"評価が止まった場合のデバッグ：UK AISI Inspect をクラウドで実行する方法","ko":"eval이 중단된 경우 디버깅: UK AISI Inspect 클라우드 실행 가이드","es":"Guía de configuración de debug-stuck-eval para AI Agents","fr":"Guide de dépannage de debug-stuck-eval pour les outils d''IA","de":"Einrichtungsleitfaden für debug-stuck-eval in KI-Agents","pt":"Guia de Configuração do debug-stuck-eval: Ferramentas de ...","ru":"Настройка debug-stuck-eval: ИИ Агенты для Отладки","ar":"دليل إعداد debug-stuck-eval: أدوات ذكاء اصطناعي للتصحيح"},"description":{"en":"Stuck with evals? Learn how to debug and resolve issues with UK AISI''s Inspect in the Cloud using debug-stuck-eval. Get started now and optimize your AI work...","zh":"了解如何使用 UK AISI 的 Inspect 在云端调试卡住的评估，通过 Hawk CLI 实现评估设置和故障排除","ja":"UK AISI の Inspect を使用してクラウドで評価をデバッグする方法を学びます。Hawk CLI を使用して評価を設定し、トラブルシューティングを行うことができます","ko":"클라우드에서 eval이 중단된 경우 디버깅하는 방법을 알아보세요. UK AISI의 Inspect와 Hawk CLI를 사용하여 평가를 설정하고 문제를 해결합니다","es":"Aprende a solucionar problemas de evaluación atascada con debug-stuck-eval y UK AISI''s Inspect en la nube","fr":"Découvrez comment résoudre les problèmes d''évaluation bloquée avec debug-stuck-eval et Inspect d''UK AISI dans le cloud","de":"Erfahren Sie, wie Sie Bewertungsprobleme mit debug-stuck-eval und UK AISI''s Inspect in der Cloud beheben","pt":"Aprenda a configurar e usar o debug-stuck-eval para depurar avaliações de IA com o Inspect na nuvem","ru":"Узнайте, как настроить и использовать debug-stuck-eval для отладки оценок ИИ с Inspect в облаке","ar":"تعلم كيفية تكوين واستخدام debug-stuck-eval لتصحيح تقييمات الذكاء الاصطناعي مع Inspect في السحابة"},"definition":{"en":"debug-stuck-eval is a skill that enables developers to troubleshoot and debug stuck evaluations using UK AISI''s Inspect in the Cloud, leveraging commands like hawk auth and hawk status.","zh":"debug-stuck-eval 是一个 AI 代理技能，用于在云端运行 UK AISI 的 Inspect 以调试卡住的评估","ja":"debug-stuck-eval は、クラウドで UK AISI の Inspect を実行して評価をデバッグする AI エージェント スキルです","ko":"debug-stuck-eval은 클라우드에서 UK AISI의 Inspect를 실행하여 eval이 중단된 경우 디버깅하는 AI 에이전트 스킬입니다","es":"debug-stuck-eval es un skill que ayuda a solucionar problemas de evaluación atascada en entornos de nube","fr":"debug-stuck-eval est un skill qui aide à résoudre les problèmes d''évaluation bloquée dans les environnements cloud","de":"debug-stuck-eval ist ein Skill, der bei der Lösung von Bewertungsproblemen in Cloud-Umgebungen hilft","pt":"O debug-stuck-eval é uma ferramenta de depuração para avaliações de IA","ru":"Debug-stuck-eval - это отладчик для оценок ИИ","ar":"debug-stuck-eval هو أداة تصحيح لأvaluations الذكاء الاصطناعي"},"features":{"en":["Verifies authentication using `hawk auth access-token` command","Retrieves evaluation set ID from users and checks status using `hawk status`","Provides JSON reports with pod state, logs, and metrics","Supports log viewing and follow mode using `hawk logs` and `hawk logs -f`","Lists samples with completion status using `hawk list samples`","Enables direct API testing for troubleshooting retries and errors"],"zh":["使用 Hawk CLI 进行评估设置和故障排除","检查评估状态和日志","查看样本完成状态","查找错误模式","直接测试 API"],"ja":["Hawk CLI を使用して評価を設定し、トラブルシューティングを行う","評価の状態とログを確認する","サンプルの完了状況を表示する","エラーパターンを探す","API を直接テストする"],"ko":["Hawk CLI를 사용하여 평가를 설정하고 문제를 해결한다","평가 상태와 로그를 확인한다","샘플 완성 상태를 표시한다","오류 패턴을 찾는다","API를 직접 테스트한다"],"es":["Verificación de autenticación con `hawk auth access-token`","Obtención de ID de conjunto de evaluación con `hawk status <eval-set-id>`","Visualización de registros con `hawk logs <eval-set-id>`","Lista de muestras con `hawk list samples <eval-set-id>`","Búsqueda de patrones de error en los registros"],"fr":["Vérification de l''authentification avec `hawk auth access-token`","Obtention de l''ID de l''ensemble d''évaluation avec `hawk status <eval-set-id>`","Affichage des journaux avec `hawk logs <eval-set-id>`","Liste des échantillons avec `hawk list samples <eval-set-id>`","Recherche de modèles d''erreur dans les journaux"],"de":["Authentifizierungsprüfung mit `hawk auth access-token`","Abrufen der Bewertungs-ID mit `hawk status <eval-set-id>`","Anzeige der Protokolle mit `hawk logs <eval-set-id>`","Liste der Proben mit `hawk list samples <eval-set-id>`","Suche nach Fehlern in den Protokollen"],"pt":["Verificação de autenticação com `hawk auth`","Obtenção de ID de conjunto de avaliação","Verificação de status com `hawk status`","Exibição de logs com `hawk logs`","Listagem de amostras com `hawk list samples`","Teste de API direto"],"ru":["Проверка аутентификации с помощью `hawk auth`","Получение ID набора оценок","Проверка статуса с помощью `hawk status`","Отображение журналов с помощью `hawk logs`","Перечисление образцов с помощью `hawk list samples`","Прямое тестирование API"],"ar":["التحقق من مصادقة مع `hawk auth`","الحصول على معرف مجموعة التقييم","التحقق من الحالة باستخدام `hawk status`","عرض السجلات باستخدام `hawk logs`","قائمة العينات باستخدام `hawk list samples`","اختبار واجهة برمجة التطبيقات مباشرة"]},"keywords":{"en":["how to use debug-stuck-eval","debug-stuck-eval setup guide","debug-stuck-eval alternative","debug-stuck-eval vs hawk","what is debug-stuck-eval","debug-stuck-eval install","debug-stuck-eval troubleshooting","UK AISI Inspect in the Cloud","AI evaluation debugging","hawk auth and status commands"],"zh":["AI 代理","UK AISI Inspect","云端调试","评估设置","故障排除","Hawk CLI","API 测试"],"ja":["AI エージェント","UK AISI Inspect","クラウド デバッグ","評価設定","トラブルシューティング","Hawk CLI","API テスト"],"ko":["AI 에이전트","UK AISI Inspect","클라우드 디버깅","평가 설정","문제 해결","Hawk CLI","API 테스트"],"es":["debug-stuck-eval","AI Agents","evaluación atascada","UK AISI''s Inspect","nube","depuración","evaluación","autenticación","registros"],"fr":["debug-stuck-eval","outils d''IA","évaluation bloquée","Inspect d''UK AISI","cloud","dépannage","évaluation","authentification","journaux"],"de":["debug-stuck-eval","KI-Agents","Bewertungsprobleme","UK AISI''s Inspect","Cloud","Debuggen","Bewertung","Authentifizierung","Protokolle"],"pt":["debug-stuck-eval","ferramentas de IA","depuração de avaliações de IA","Inspect na nuvem","hawk auth","hawk status","hawk logs","avalieções de IA"],"ru":["debug-stuck-eval","ИИ Агенты","отладка оценок ИИ","Inspect в облаке","hawk auth","hawk status","hawk logs","оценки ИИ"],"ar":["debug-stuck-eval","أدوات الذكاء الاصطناعي","تصحيح تقييمات الذكاء الاصطناعي","Inspect في السحابة","hawk auth","hawk status","hawk logs","تقييمات الذكاء الاصطناعي"]}},"owner":"METR","repo":"inspect-action","repoPath":"METR/inspect-action","stars":20,"forks":9,"updatedAt":"2026-03-03T00:16:18Z","topics":["ai","ai-evaluation","elicitation","evals","inspect"],"category":"community","skillMd":{"name":"debug-stuck-eval","description":"Debug stuck Hawk/Inspect AI evaluations. Use when user mentions stuck eval, eval not progressing, eval hanging, samples not completing, eval set frozen, runner stuck, 500 errors in eval, retry loop, eval timeout, or asks why an evaluation isnt finishing.","bodyPreview":"## Quick Checklist\n\n1. **Verify auth**: `hawk auth access-token > /dev/null || echo \"Run ''hawk login'' first\"`\n2. **Get eval-set-id** from user\n3. **Check status**: `hawk status <eval-set-id>` - JSON report with pod state, logs, metrics\n4. **View logs**: `hawk logs <eval-set-id>` or `hawk logs -f` for follow mode\n5. **List samples**: `hawk list samples <eval-set-id>` - see completion status\n6. **Look for error patterns** (see below)\n7. **Test API directly** if logs show retries without clear erro","body":"## Quick Checklist\n\n1. **Verify auth**: `hawk auth access-token > /dev/null || echo \"Run ''hawk login'' first\"`\n2. **Get eval-set-id** from user\n3. **Check status**: `hawk status <eval-set-id>` - JSON report with pod state, logs, metrics\n4. **View logs**: `hawk logs <eval-set-id>` or `hawk logs -f` for follow mode\n5. **List samples**: `hawk list samples <eval-set-id>` - see completion status\n6. **Look for error patterns** (see below)\n7. **Test API directly** if logs show retries without clear errors\n\n## Error Patterns\n\n| Log Pattern | Meaning | Resolution |\n|-------------|---------|------------|\n| `[uuid task/id/epoch model] Retrying request to /responses` | OpenAI SDK retry with sample context | Test API directly with curl to see real error |\n| `[uuid task/id/epoch model] -> model retry N ... [ErrorType code]` | Inspect retry with error summary | Check error type; use curl for full details |\n| `500 - Internal server error` | API issue | Download buffer, find failing request, test through middleman AND directly to provider |\n| `400 - invalid_request_error` | Token/context limit exceeded | Check message count and model context window |\n| `Pod UID mismatch` | Sandbox pod was killed and restarted | No fix needed—sample errored out, Inspect will retry |\n| Empty output, `pending: true` | API returned malformed response | Restart eval (buffer resumes) |\n| OOMKilled in pod status | Memory exhaustion | Increase pod memory limits |\n\n## Key Techniques\n\n1. **Retry messages have sample context** - All retry messages include a `[sample_uuid task/sample_id/epoch model]` prefix. Inspect''s own retries also include a compact error summary suffix like `[RateLimitError 429 rate_limit_exceeded]`. The OpenAI SDK''s internal retry messages still don''t show the actual error — use curl for full details.\n2. **FAIL-OK patterns are fine** - Alternating failures and successes mean the eval IS progressing. Only worry about consistent FAIL-FAIL-FAIL patterns.\n3. **Use S3 for buffer access** - Download `.buffer/` from S3 rather than accessing the runner pod directly.\n4. **Read .eval files with inspect_ai** - Use `from inspect_ai.log import read_eval_log` instead of manually extracting zips.\n\n## Test API Directly\n\nMiddleman is the auth proxy. If middleman fails but direct provider calls work, it''s a middleman issue.\n\n```bash\nTOKEN=$(hawk auth access-token)\n\n# Test through middleman\ncurl --max-time 300 -X POST https://middleman.internal.metr.org/anthropic/v1/messages \\\n  -H \"Authorization: Bearer $TOKEN\" -H \"Content-Type: application/json\" \\\n  -d ''{\"model\": \"claude-sonnet-4-20250514\", \"max_tokens\": 100, \"messages\": [{\"role\": \"user\", \"content\": \"Say hello\"}]}''\n\n# Test OpenAI-compatible\ncurl --max-time 300 -X POST https://middleman.internal.metr.org/openai/v1/chat/completions \\\n  -H \"Authorization: Bearer $TOKEN\" -H \"Content-Type: application/json\" \\\n  -d ''{\"model\": \"gpt-4o\", \"messages\": [{\"role\": \"user\", \"content\": \"Say hello\"}], \"max_tokens\": 100}''\n```\n\n## Recovery\n\n```bash\n# Delete stuck eval and restart\nhawk delete <eval-set-id>\nhawk eval-set <config.yaml>\n```\n\nThe sample buffer in S3 allows Inspect to resume from where it left off (unless you use `--no-resume`).\n\n## HTTP Retry Count\n\nTask progress logs include \"HTTP retries: X\". High retry counts indicate API instability even while tasks complete.\n\n**Severity:** Retry count × wait time = stuck duration. E.g., 45 retries × 1800s = 22+ hours stuck.\n\n## More Details\n\nSee `docs/debugging-stuck-evals.md` for:\n- Sample buffer SQL queries\n- Detailed API testing examples\n- Escalation checklist\n\n## References\n\n- [Inspect AI Model Providers](https://inspect.aisi.org.uk/providers.html) - Model configuration\n- [Inspect AI Eval Logs](https://inspect.aisi.org.uk/eval-logs.html) - .eval file format\n\n## Filing Issues\n\n- **Middleman**: https://github.com/metr-middleman/middleman-server/issues\n- **Hawk**: Linear issue on Evals Execution team\n- **Inspect AI**: https://github.com/UKGovernmentBEIS/inspect_ai/issues\n"},"lastSynced":"2026-03-06T06:41:54.945Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Development Agents requiring advanced troubleshooting capabilities for stuck evaluations, particularly those working with UK AISI''s Inspect in the Cloud.","zh":"适用于需要高级故障排除能力的AI开发代理，特别是那些使用UK AISI的Inspect in the Cloud的代理。","ja":"UK AISIのInspect in the Cloudを使用するものを含め、詰まった評価のための高度なトラブルシューティング能力を必要とするAI開発エージェントに適しています。","ko":"UK AISI의 Inspect in the Cloud를 사용하는 것을 포함하여 고급 트러블슈팅 기능이 필요한 AI 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo de IA que requieren capacidades de solución de problemas avanzadas para evaluaciones atascadas, particularmente aquellos que trabajan con Inspect in the Cloud de UK AISI.","fr":"Idéal pour les agents de développement d''IA nécessitant des capacités de dépannage avancées pour les évaluations bloquées, en particulier ceux qui travaillent avec Inspect in the Cloud de UK AISI.","de":"Ideal für AI-Entwicklungsagenten, die erweiterte Fehlersuche-Funktionen für feststeckende Bewertungen benötigen, insbesondere solche, die mit UK AISI''s Inspect in the Cloud arbeiten.","pt":"Ideal para Agentes de Desenvolvimento de IA que exigem capacidades avançadas de solução de problemas para avaliações presas, particularmente aqueles que trabalham com o Inspect in the Cloud da UK AISI.","ru":"Идеально для агентов разработки ИИ, требующих продвинутых возможностей по устранению неполадок для застрявших оценок, особенно тех, кто работает с Inspect in the Cloud от UK AISI.","ar":"مثالي لعميل تطوير الذكاء الاصطناعي الذين يحتاجون إلى إمكانيات متقدمة لتعديل الأخطاء في التقييمات المعطلة، خاصة أولئك الذين يعملون مع التفتيش السحابي في UK AISI."},"recommendation":{"en":"Empowers agents to rapidly diagnose and resolve stuck evaluations by leveraging hawk auth, status checks, and log analysis, utilizing JSON reports and metrics to inform the debugging process.","zh":"通过利用hawk auth、状态检查和日志分析，使用JSON报告和指标来告知调试过程，从而使代理能够快速诊断和解决卡住的评估。","ja":"hawk auth、ステータスチェック、ログ分析を利用して、JSONレポートとメトリクスを使用してデバッグプロセスに情報を提供することで、エージェントが詰まった評価を迅速に診断して解決できるようにします。","ko":"hawk auth, 상태 확인 및 로그 분석을 활용하여 JSON 보고서 및 메트릭을 사용하여 디버깅 과정을 정보를 제공함으로써 에이전트가 걸린 평가를 신속하게 진단 및 해결 할 수 있도록 합니다.","es":"Habilita a los agentes a diagnosticar y resolver rápidamente evaluaciones atascadas aprovechando hawk auth, verificaciones de estado y análisis de registros, utilizando informes y métricas JSON para informar el proceso de depuración.","fr":"Permet aux agents de diagnostiquer et de résoudre rapidement les évaluations bloquées en exploitant hawk auth, les vérifications d''état et l''analyse des journaux, en utilisant des rapports et des métriques JSON pour éclairer le processus de débogage.","de":"Ermächtigt Agenten, steckengebliebene Bewertungen schnell zu diagnostizieren und zu lösen, indem sie hawk auth, Statusprüfungen und Log-Analyse nutzen und JSON-Berichte und -Metriken verwenden, um den Debugging-Prozess zu informieren.","pt":"Habilita os agentes a diagnosticar e resolver rapidamente avaliações presas, utilizando hawk auth, verificações de status e análise de logs, utilizando relatórios JSON e métricas para informar o processo de depuração.","ru":"Наделяет агентов возможностью быстро диагностировать и решать застрявшие оценки, используя hawk auth, проверки статуса и анализ логов, используя отчеты JSON и метрики для информирования процесса отладки.","ar":"يمنح الوكيل القدرة على تشخيص وتصحيح التقييمات المعطلة بسرعة، من خلال استخدام hawk auth، وفرضات حالة، وتحليل السجلات، واستخدام تقارير JSON والأرقام الإحصائية لإعلام عملية التصحيح."},"useCases":{"en":["Debugging stuck evaluations in AI model inspections","Verifying authentication and authorization for AI services","Analyzing logs and metrics to identify error patterns in AI evaluations"],"zh":["AI 모델 검사에서卡住的评估의 디버깅","AI 서비스의 인증 및 권한 확인","AI 평가에서 오류 패턴을 식별하기 위한 로그 및 메트릭 분석"],"ja":["AIモデル検査での詰まった評価のデバッグ","AIサービスの認証および認可の検証","AI評価でのエラーパターンの識別のためのログおよびメトリクスの分析"],"ko":["AI 모델 검사에서 걸린 평가의 디버깅","AI 서비스의 인증 및 권한 확인","AI 평가에서 오류 패턴을 식별하기 위한 로그 및 메트릭 분석"],"es":["Depuración de evaluaciones atascadas en inspecciones de modelos de IA","Verificación de autenticación y autorización para servicios de IA","Análisis de registros y métricas para identificar patrones de error en evaluaciones de IA"],"fr":["Débogage des évaluations bloquées dans les inspections de modèles d''IA","Vérification de l''authentification et de l''autorisation pour les services d''IA","Analyse des journaux et des métriques pour identifier les modèles d''erreur dans les évaluations d''IA"],"de":["Fehlersuche bei feststeckenden Bewertungen in IA-Modell-Inspektionen","Überprüfung der Authentifizierung und Autorisierung für IA-Dienste","Analyse von Protokollen und Metriken zur Identifizierung von Fehlern in IA-Bewertungen"],"pt":["Depuração de avaliações presas em inspeções de modelos de IA","Verificação de autenticação e autorização para serviços de IA","Análise de logs e métricas para identificar padrões de erros em avaliações de IA"],"ru":["Отладка застрявших оценок при осмотре моделей ИИ","Проверка аутентификации и авторизации для сервисов ИИ","Анализ логов и метрик для выявления ошибок в оценках ИИ"],"ar":["تصحيح التقييمات المعطلة في عمليات فحص أنماط الذكاء الاصطناعي","التحقق من مصادقة وتصريح الخدمات الذكية","تحليل السجلات والأرقام الإحصائية للكشف عن أنماط الأخطاء في تقييمات الذكاء الاصطناعي"]},"limitations":{"en":["Requires hawk auth access-token","Dependent on UK AISI''s Inspect in the Cloud infrastructure","Limited to troubleshooting evaluations, not general AI model development"],"zh":["需要hawk auth访问令牌","依赖于UK AISI的Inspect in the Cloud基础设施","仅限于故障排除评估，不适用于一般的AI模型开发"],"ja":["hawk authアクセストークンが必要","UK AISIのInspect in the Cloudインフラストラクチャに依存","トラブルシューティング評価のみに限定され、一般的なAIモデル開発には不適"],"ko":["hawk auth 액세스 토큰이 필요","UK AISI의 Inspect in the Cloud 인프라에 의존","트러블슈팅 평가만 해당되며 일반적인 AI 모델 개발에는 부적합"],"es":["Requiere acceso con token de autenticación hawk","Dependiente de la infraestructura de Inspect in the Cloud de UK AISI","Limitado a la solución de problemas de evaluaciones, no al desarrollo general de modelos de IA"],"fr":["Nécessite un jeton d''accès d''authentification hawk","Dépend de l''infrastructure d''Inspect in the Cloud de UK AISI","Limité au dépannage des évaluations, et non au développement général de modèles d''IA"],"de":["Benötigt Zugriff auf hawk-Authentifizierungszugangstoken","Abhängig von der Infrastruktur von UK AISI''s Inspect in the Cloud","Begrenzt auf Fehlersuche bei Bewertungen, nicht auf die allgemeine Entwicklung von IA-Modellen"],"pt":["Exige acesso ao token de autenticação hawk","Dependente da infraestrutura do Inspect in the Cloud da UK AISI","Limitado à solução de problemas de avaliações, não ao desenvolvimento geral de modelos de IA"],"ru":["Требует доступа к токену аутентификации hawk","Зависит от инфраструктуры Inspect in the Cloud от UK AISI","Ограничен устранением неполадок оценок, а не общим развитием моделей ИИ"],"ar":["يتطلب الوصول إلى رمز مصادقة hawk","يعتمد على بنية التحتية للتفتيش السحابي في UK AISI","محدود بتصحيح الأخطاء في التقييمات، وليس بالتطوير العام لأنماط الذكاء الاصطناعي"]},"version":4},"contentHash":"a0053ae6c485921d3887151903fe3b6a1d2845f2a7a3dfe65716ebb7da20b9fb","qualityScore":36}');
