INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('METR/inspect-action/debug-stuck-eval', 'debug-stuck-eval', 'METR', 'inspect-action', 'community', 'debug-stuck-eval METR inspect-action community ai ai-evaluation elicitation evals inspect The debug-stuck-eval skill helps AI developers troubleshoot stuck evaluations by running UK AISI''s Inspect in the Cloud, providing a quick checklist for verification, status checks, and log analysis. It benefits developers working with AI evaluations and inspections. 本文介绍如何使用 UK AISI 的 Inspect 在云端调试卡住的评估，包括设置、故障排除和 API 测试 本文では、UK AISI の Inspect を使用してクラウドで評価をデバッグする方法について説明します。設定、トラブルシューティング、API テストなどを含みます 이 문서는 클라우드에서 eval이 중단된 경우 디버깅하는 방법에 대해 설명합니다. 설정, 문제 해결 및 API 테스트 등이 포함됩니다 El skill debug-stuck-eval permite a los desarrolladores depurar evaluaciones atascadas en UK AISI''s Inspect en la nube Le skill debug-stuck-eval permet aux développeurs de dépanner les évaluations bloquées dans Inspect d''UK AISI dans le cloud Das Skill debug-stuck-eval ermöglicht es Entwicklern, Bewertungen in UK AISI''s Inspect in der Cloud zu debuggen O debug-stuck-eval é uma ferramenta de depuração para avaliações de IA que executa o Inspect na nuvem, fornecendo relatórios de status e logs. Debug-stuck-eval - это отладчик для оценок ИИ, который запускает Inspect в облаке, предоставляя отчеты о статусе и журналах. debug-stuck-eval هو أداة تصحيح لأvaluations الذكاء الاصطناعي التي تعمل Inspect في السحابة، وتقدم تقارير الحالة وسجلات how to use debug-stuck-eval debug-stuck-eval setup guide debug-stuck-eval alternative debug-stuck-eval vs hawk what is debug-stuck-eval debug-stuck-eval install debug-stuck-eval troubleshooting UK AISI Inspect in the Cloud AI evaluation debugging hawk auth and status commands AI 代理 UK AISI Inspect 云端调试 评估设置 故障排除 Hawk CLI API 测试 Verifies authentication using `hawk auth access-token` command Retrieves evaluation set ID from users and checks status using `hawk status` Provides JSON reports with pod state, logs, and metrics Supports log viewing and follow mode using `hawk logs` and `hawk logs -f` Lists samples with completion status using `hawk list samples` Enables direct API testing for troubleshooting retries and errors debug-stuck-eval is a skill that enables developers to troubleshoot and debug stuck evaluations using UK AISI''s Inspect in the Cloud, leveraging commands like hawk auth and hawk status.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('futuresearch/everyrow-sdk/deploy-mcp', 'community', 'futuresearch', 'everyrow-sdk', 'futuresearch/everyrow-sdk', 'deploy-mcp', 17, 2, 36, '2026-03-02T12:01:38Z', '2026-03-06T06:42:44.367Z', 'e1bb3f611236218905ec43f60e90ba27995cad0f9012cb122ec279faee5849fa', '{"id":"futuresearch/everyrow-sdk/deploy-mcp","name":"deploy-mcp","description":{"en":"The deploy-mcp skill automates the deployment of MCP servers, benefiting AI agent developers. It supports quick deployment to staging and production environments.","zh":"Deploy-MCP 是一个自动化部署 MCP 服务器的工具，支持从主分支或功能分支部署","ja":"Deploy-MCP は、MCP サーバーの自動化デプロイを支援するツールです。メインブランチまたは機能ブランチからのデプロイをサポートしています","ko":"Deploy-MCP는 MCP 서버의 자동화 배포를 지원하는 도구입니다. 메인 브랜치 또는 기능 브랜치에서 배포를 지원합니다","es":"Deploy-mcp es una herramienta para desplegar servidores MCP para agentes de AI, compatible con Claude y Claude Code","fr":"Deploy-mcp est un outil pour déployer des serveurs MCP pour les agents d''IA, compatible avec Claude et Claude Code","de":"Deploy-mcp ist ein Tool zum Bereitstellen von MCP-Servern für KI-Agents, kompatibel mit Claude und Claude Code","pt":"O deploy-mcp é uma ferramenta para implantar servidores MCP. Ele fornece comandos para configurar e executar tarefas de staging e produção.","ru":"Deploy-mcp - это инструмент для развертывания серверов MCP. Он предоставляет команды для настройки и выполнения задач стадии и производственного окружения.","ar":"deploy-mcp هو أداة لنشر خوادم MCP. يوفر أوامر لتنفيذ مهام لمرحلة الإعداد والانتاج."},"seo":{"title":{"en":"deploy-mcp: Automated Deployment Setup Guide | AI Agent S...","zh":"Deploy-MCP 设置指南：AI 研究团队自动化部署","ja":"Deploy-MCP セットアップガイド：AI エージェントの自動化デプロイ","ko":"Deploy-MCP 설정 가이드: AI 에이전트 자동화 배포","es":"Guía de configuración de deploy-mcp para agentes de AI","fr":"Déploiement de deploy-mcp pour les agents d''IA","de":"Einrichtungsleitfaden für deploy-mcp für KI-Agents","pt":"Guia de Configuração do deploy-mcp: Implantação de Servid...","ru":"Руководство по настройке deploy-mcp: Развертывание сервер...","ar":"دليل إعداد deploy-mcp: نشر خوادم MCP"},"description":{"en":"Discover how to streamline your AI agent deployment with deploy-mcp. Learn how to automate staging and production environments with ease.","zh":"学习如何使用 Deploy-MCP 设置 AI 研究团队，自动化部署 MCP 服务器，提高开发效率","ja":"Deploy-MCP を使用して AI エージェントを自動化デプロイし、開発効率を向上させる方法を学びます","ko":"Deploy-MCP를 사용하여 AI 에이전트를 자동화 배포하고 개발 효율을 향상시키는 방법을 알아보세요","es":"Aprende a desplegar deploy-mcp para mejorar el rendimiento de tus agentes de AI con Claude y Claude Code","fr":"Découvrez comment déployer deploy-mcp pour améliorer les performances de vos agents d''IA avec Claude et Claude Code","de":"Erfahren Sie, wie Sie deploy-mcp für die Leistungsverbesserung Ihrer KI-Agents mit Claude und Claude Code bereitstellen","pt":"Aprenda a implantar servidores MCP com o deploy-mcp. Veja como configurar e executar comandos para staging e produção.","ru":"Узнайте, как развернуть серверы MCP с помощью deploy-mcp. См. как настроить и выполнить команды для стадии и производственного окружения.","ar":"تعلم كيفية نشر خوادم MCP باستخدام deploy-mcp. انظر كيفية تنظیم وتنفيذ أوامر لمرحلة الإعداد والانتاج."},"definition":{"en":"deploy-mcp is a skill that automates the deployment of MCP servers using GitHub workflows and supports pandas-dataframe for data analysis.","zh":"Deploy-MCP 是一个用于自动化部署 MCP 服务器的工具，支持 CLI 命令","ja":"Deploy-MCP は、MCP サーバーの自動化デプロイを支援するツールです。CLI コマンドをサポートしています","ko":"Deploy-MCP는 MCP 서버의 자동화 배포를 지원하는 도구입니다. CLI 명령을 지원합니다","es":"Deploy-mcp es una herramienta de despliegue de servidores MCP para agentes de AI","fr":"Deploy-mcp est un outil de déploiement de serveurs MCP pour les agents d''IA","de":"Deploy-mcp ist ein Tool zum Bereitstellen von MCP-Servern für KI-Agents","pt":"O deploy-mcp é uma ferramenta de implantação de servidores MCP que utiliza comandos CLI para configurar e executar tarefas.","ru":"Deploy-mcp - это инструмент развертывания серверов MCP, который использует команды CLI для настройки и выполнения задач.","ar":"deploy-mcp هو أداة نشر خوادم MCP التي تستخدم أوامر CLI لتنفيذ مهام."},"features":{"en":["Supports automated deployment to staging and production environments using GitHub workflows","Utilizes pandas-dataframe for efficient data analysis and filtering","Enables quick deployment from main branch or feature branches using specific commands","Allows for simultaneous deployment to both staging and production environments","Leverages semantic analysis and ranking for improved AI agent performance","Integrates with Claude and Claude-code for enhanced AI capabilities"],"zh":["支持从主分支或功能分支部署","自动化部署 MCP 服务器","支持 CLI 命令","支持 staging 和 production 环境","支持 pandas-dataframe 和 semantic-analysis"],"ja":["メインブランチまたは機能ブランチからのデプロイをサポート","MCP サーバーの自動化デプロイ","CLI コマンドをサポート","staging と production 環境をサポート","pandas-dataframe と semantic-analysis をサポート"],"ko":["메인 브랜치 또는 기능 브랜치에서 배포를 지원","MCP 서버의 자동화 배포","CLI 명령을 지원","staging 과 production 환경을 지원","pandas-dataframe 와 semantic-analysis 를 지원"],"es":["Compatibilidad con Claude y Claude Code","Despliegue de servidores MCP para agentes de AI","Soporte para pandas DataFrame","Análisis semántico y filtrado","Despliegue en entornos de staging y producción"],"fr":["Compatibilité avec Claude et Claude Code","Déploiement de serveurs MCP pour les agents d''IA","Prise en charge de pandas DataFrame","Analyse sémantique et filtrage","Déploiement dans les environnements de staging et de production"],"de":["Kompatibilität mit Claude und Claude Code","Bereitstellung von MCP-Servern für KI-Agents","Unterstützung für pandas DataFrame","Semantische Analyse und Filterung","Bereitstellung in Staging- und Produktionsumgebungen"],"pt":["Suporte a implantação em staging e produção","Utilização de comandos CLI para configurar e executar tarefas","Compatibilidade com branches de recursos","Integração com o GitHub Workflow","Suporte a pandas-dataframe e semantic-analysis","Utilização de filtering e ranking para análise de dados"],"ru":["Поддержка развертывания в стадии и производственном окружении","Использование команд CLI для настройки и выполнения задач","Совместимость с ветками функций","Интеграция с GitHub Workflow","Поддержка pandas-dataframe и semantic-analysis","Использование filtering и ranking для анализа данных"],"ar":["دعم نشر في مرحلة الإعداد والانتاج","استخدام أوامر CLI لتنفيذ مهام","توافق مع فروع الميزات","دمج مع GitHub Workflow","دعم pandas-dataframe و semantic-analysis","استخدام filtering و ranking لتحليل البيانات"]},"keywords":{"en":["how to use deploy-mcp","deploy-mcp setup guide","deploy-mcp alternative","deploy-mcp vs Claude","deploy-mcp install","automated deployment with GitHub workflows","pandas-dataframe for AI agents","semantic analysis for AI agents","what is deploy-mcp","deploy-mcp tutorial"],"zh":["Deploy-MCP","AI 研究团队","自动化部署","MCP 服务器","CLI 命令","pandas-dataframe","semantic-analysis","AI 工具","AI 平台"],"ja":["Deploy-MCP","AI エージェント","自動化デプロイ","MCP サーバー","CLI コマンド","pandas-dataframe","semantic-analysis","AI ツール","AI プラットフォーム"],"ko":["Deploy-MCP","AI 에이전트","자동화 배포","MCP 서버","CLI 명령","pandas-dataframe","semantic-analysis","AI 도구","AI 플랫폼"],"es":["agentes de AI","despliegue de servidores MCP","Claude","Claude Code","pandas DataFrame","análisis semántico","filtrado","despliegue en la nube"],"fr":["agents d''IA","déploiement de serveurs MCP","Claude","Claude Code","pandas DataFrame","analyse sémantique","filtrage","déploiement dans le cloud"],"de":["KI-Agents","Bereitstellung von MCP-Servern","Claude","Claude Code","pandas DataFrame","semantische Analyse","Filterung","Bereitstellung in der Cloud"],"pt":["deploy-mcp","implantação de servidores MCP","configuração de staging e produção","comandos CLI","branches de recursos","GitHub Workflow","pandas-dataframe","semantic-analysis","filtragem de dados","classificação de dados"],"ru":["deploy-mcp","развертывание серверов MCP","настройка стадии и производственного окружения","команды CLI","ветки функций","GitHub Workflow","pandas-dataframe","semantic-analysis","фильтрация данных","ранжирование данных"],"ar":["deploy-mcp","نشر خوادم MCP","إعداد مرحلة الإعداد والانتاج","أوامر CLI","فروع الميزات","GitHub Workflow","pandas-dataframe","semantic-analysis","ترشيح البيانات","تصنيف البيانات"]}},"owner":"futuresearch","repo":"everyrow-sdk","repoPath":"futuresearch/everyrow-sdk","stars":17,"forks":2,"updatedAt":"2026-03-02T12:01:38Z","topics":["claude","claude-code","filtering","llm-agents","pandas-dataframe","ranking","semantic-analysis"],"category":"community","skillMd":{"name":"deploy-mcp","description":"Deploy the everyrow MCP server to staging or production on GKE. Use when the user wants to deploy, redeploy, roll back, scale replicas, or check deployment status. Triggers on deploy, redeploy, staging, production, rollout, scale, replicas.","bodyPreview":"# Deploying the MCP Server\n\n## Quick Deploy\n\n### Staging (from main)\n\n```bash\ngh workflow run \"Deploy MCP Server\" -f branch=main -f deploy_staging=true\n```\n\n### Production (from main)\n\n```bash\ngh workflow run \"Deploy MCP Server\" -f branch=main -f deploy_production=true\n```\n\n### Both environments\n\n```bash\ngh workflow run \"Deploy MCP Server\" -f branch=main -f deploy_staging=true -f deploy_production=true\n```\n\n### From a feature branch\n\n```bash\ngh workflow run \"Deploy MCP Server\" -f branch=feat/my-","body":"# Deploying the MCP Server\n\n## Quick Deploy\n\n### Staging (from main)\n\n```bash\ngh workflow run \"Deploy MCP Server\" -f branch=main -f deploy_staging=true\n```\n\n### Production (from main)\n\n```bash\ngh workflow run \"Deploy MCP Server\" -f branch=main -f deploy_production=true\n```\n\n### Both environments\n\n```bash\ngh workflow run \"Deploy MCP Server\" -f branch=main -f deploy_staging=true -f deploy_production=true\n```\n\n### From a feature branch\n\n```bash\ngh workflow run \"Deploy MCP Server\" -f branch=feat/my-branch -f deploy_staging=true\n```\n\n## Monitoring a Deploy\n\n```bash\n# Watch the workflow run\ngh run list --workflow=\"Deploy MCP Server\" --limit 3\ngh run watch <run-id>\n\n# Check pod rollout\nkubectl rollout status deploy/everyrow-mcp-staging -n everyrow-mcp-staging --timeout=5m\n\n# Verify pods are running\nkubectl get pods -n everyrow-mcp-staging -o wide\n```\n\n## How It Works\n\nThe GitHub Actions workflow (`.github/workflows/deploy-mcp.yaml`) does:\n\n1. **Checks** — ruff lint + pytest on the target branch\n2. **Build & push** — Docker image to GAR, tagged with short SHA (+ `latest` on main)\n3. **Deploy** — Helm upgrade with layered values:\n   - `values.yaml` — base config\n   - `values.staging.yaml` — staging overrides (MCP_SERVER_URL, REDIS_DB, replicaCount, host)\n   - `values.secrets.staging.yaml` — SOPS-decrypted secrets (Supabase, API keys)\n\nThe deploy uses `--atomic` so it auto-rolls back on failure.\n\n## Scaling Replicas\n\n### Via Helm values (persistent)\n\nEdit `everyrow-mcp/deploy/chart/values.staging.yaml`:\n```yaml\nreplicaCount: 2  # Change this\n```\nCommit, push, and redeploy.\n\n### Via kubectl (temporary, resets on next deploy)\n\n```bash\n# Staging\nkubectl scale deploy everyrow-mcp-staging -n everyrow-mcp-staging --replicas=3\n\n# Take offline\nkubectl scale deploy everyrow-mcp-staging -n everyrow-mcp-staging --replicas=0\n```\n\n## Environments\n\n| Environment | Namespace | Host | Redis DB |\n|---|---|---|---|\n| Staging | `everyrow-mcp-staging` | `mcp-staging.everyrow.io` | 14 |\n| Production | `everyrow-mcp` | `mcp.everyrow.io` | (default in values.yaml) |\n\nBoth environments hit the **same production EveryRow API** — there is no staging API.\n\n## Updating Secrets\n\n```bash\n# View current secrets\nsops -d everyrow-mcp/deploy/chart/secrets.staging.enc.yaml\n\n# Update a value\nsops --set ''[\"secrets\"][\"data\"][\"KEY_NAME\"] \"new-value\"'' everyrow-mcp/deploy/chart/secrets.staging.enc.yaml\n```\n\nCommit the encrypted file and redeploy.\n\n## Key Files\n\n| File | Purpose |\n|------|---------|\n| `.github/workflows/deploy-mcp.yaml` | CI/CD workflow (checks → build → deploy) |\n| `everyrow-mcp/deploy/chart/values.yaml` | Base Helm values |\n| `everyrow-mcp/deploy/chart/values.staging.yaml` | Staging overrides |\n| `everyrow-mcp/deploy/chart/secrets.enc.yaml` | Production secrets (SOPS) |\n| `everyrow-mcp/deploy/chart/secrets.staging.enc.yaml` | Staging secrets (SOPS) |\n| `everyrow-mcp/deploy/Dockerfile` | Server container image |\n\n## Gotchas\n\n- **Branch protection on main**: Can''t push directly — create a PR and merge first, then deploy from main.\n- **SOPS decryption requires GCP IAM**: Run `gcloud auth application-default login` if decryption fails.\n- **Concurrent deploys**: Workflow uses `cancel-in-progress: false` — if a deploy is running, the next one queues.\n- **Atomic rollback**: `--atomic` means a failed deploy auto-reverts to the previous release. Check `helm history` if this happens.\n"},"lastSynced":"2026-03-06T06:42:44.367Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing streamlined MCP server deployment to staging and production environments.","zh":"非常适合需要将MCP服务器部署到暂存和生产环境的DevOps代理的简化流程。","ja":"DevOpsエージェントがMCPサーバーのステージング環境とプロダクション環境へのデプロイを簡素化する必要がある場合に最適です。","ko":"DevOps 에이전트가 MCP 서버를 스테이징 및 프로덕션 환경에 배포할 때 간소화된 프로세스가 필요한 경우에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan una implementación de servidor MCP optimizada para entornos de staging y producción.","fr":"Parfait pour les agents DevOps ayant besoin d''un déploiement de serveur MCP rationalisé vers les environnements de staging et de production.","de":"Perfekt für DevOps-Agents, die eine optimierte MCP-Server-Bereitstellung in Staging- und Produktionsumgebungen benötigen.","pt":"Perfeito para Agentes DevOps que precisam de implantação de servidor MCP simplificada para ambientes de staging e produção.","ru":"Идеально подходит для агентов DevOps, которым требуется упрощенная установка сервера MCP в среды подготовки и производства.","ar":"مثالي لعميل DevOps الذين يحتاجون إلى نشر خادم MCP مبسط إلى بيئات الإعداد والانتاج."},"recommendation":{"en":"Empowers agents to automate MCP server deployment using GitHub workflows, supporting quick deployment to staging and production environments via commands like ''gh workflow run'' with parameters such as ''-f branch=main'' and ''-f deploy_staging=true'' or ''-f deploy_production=true''.","zh":"赋予代理人使用GitHub工作流自动化MCP服务器部署的能力，支持通过命令（如''gh workflow run''，参数如''-f branch=main''和''-f deploy_staging=true''或''-f deploy_production=true''）快速将服务器部署到暂存和生产环境。","ja":"エージェントがGitHubワークフローを使用してMCPサーバーのデプロイを自動化できるようにし、コマンド（例：''gh workflow run''、パラメータとして''-f branch=main''および''-f deploy_staging=true''または''-f deploy_production=true''）を使用してステージング環境とプロダクション環境への迅速なデプロイをサポートします。","ko":"에이전트가 GitHub 워크플ロー를 사용하여 MCP 서버 배포를 자동화할 수 있도록 하며, ''gh workflow run''과 같은 명령어(예: ''-f branch=main'' 및 ''-f deploy_staging=true'' 또는 ''-f deploy_production=true''와 같은 매개변수)를 사용하여 스테이징 및 프로덕션 환경으로의 빠른 배포를 지원합니다.","es":"Habilita a los agentes a automatizar la implementación de servidores MCP utilizando flujos de trabajo de GitHub, lo que admite una implementación rápida en entornos de staging y producción mediante comandos como ''gh workflow run'' con parámetros como ''-f branch=main'' y ''-f deploy_staging=true'' o ''-f deploy_production=true''.","fr":"Permet aux agents d''automatiser le déploiement de serveurs MCP en utilisant des flux de travail GitHub, ce qui prend en charge un déploiement rapide vers les environnements de staging et de production via des commandes comme ''gh workflow run'' avec des paramètres tels que ''-f branch=main'' et ''-f deploy_staging=true'' ou ''-f deploy_production=true''.","de":"Ermöglicht es Agents, die Bereitstellung von MCP-Servern mithilfe von GitHub-Workflows zu automatisieren, was eine schnelle Bereitstellung in Staging- und Produktionsumgebungen über Befehle wie ''gh workflow run'' mit Parametern wie ''-f branch=main'' und ''-f deploy_staging=true'' oder ''-f deploy_production=true'' ermöglicht.","pt":"Habilita os agentes a automatizar a implantação do servidor MCP usando fluxos de trabalho do GitHub, com suporte ao deploy rápido para ambientes de staging e produção via comandos como ''gh workflow run'' com parâmetros como ''-f branch=main'' e ''-f deploy_staging=true'' ou ''-f deploy_production=true''.","ru":"Позволяет агентам автоматизировать установку сервера MCP с помощью рабочих процессов GitHub, поддерживая быструю установку в среды подготовки и производства с помощью команд, таких как ''gh workflow run'' с параметрами, такими как ''-f branch=main'' и ''-f deploy_staging=true'' или ''-f deploy_production=true''.","ar":"يُمكن للعميل من خلالها تفويض الوكيل لتشغيل خادم MCP آلياً باستخدام سير عمل جيت هب، مع دعم لنشر سريع إلى بيئات الإعداد والإنتاج عبر أوامر مثل ''gh workflow run'' مع معاملات مثل ''-f branch=main'' و ''-f deploy_staging=true'' أو ''-f deploy_production=true''."},"useCases":{"en":["Automating MCP server deployment to staging environments","Deploying MCP servers to production environments from feature branches","Streamlining deployment processes for MCP servers using GitHub workflows"],"zh":["自动将MCP服务器部署到暂存环境","从功能分支将MCP服务器部署到生产环境","使用GitHub工作流简化MCP服务器的部署过程"],"ja":["ステージング環境へのMCPサーバーの自動デプロイ","機能ブランチからのMCPサーバーのプロダクション環境へのデプロイ","GitHubワークフローを使用したMCPサーバーのデプロイプロセスの簡素化"],"ko":["MCP 서버를 스테이징 환경으로 자동 배포하기","기능 분기에서 MCP 서버를 프로덕션 환경으로 배포하기","GitHub 워크플ロー 사용하여 MCP 서버 배포 프로세스 간소화"],"es":["Automatizar la implementación de servidores MCP en entornos de staging","Implementar servidores MCP en entornos de producción desde ramas de características","Optimizar los procesos de implementación para servidores MCP utilizando flujos de trabajo de GitHub"],"fr":["Automatiser le déploiement de serveurs MCP dans des environnements de staging","Déployer des serveurs MCP dans des environnements de production à partir de branches de fonctionnalité